}
local GTA_ROLES_URL = "https://raw.githubusercontent.com/gta244adm/Gta-hub-pro/refs/heads/main/GTA%20HUB%20C%20e%20DV"
local GTA_BLACKLIST_URL = "https://raw.githubusercontent.com/gta244adm/Gta-hub-pro/refs/heads/main/Black%20list"

-- 22 cargos. noKey = libera sem key. immune = ninguém do script pode mirar nele.
