local GTA_ROLE_BY_ID, GTA_ROLE_ORDER = {}, {}
for i, r in ipairs(_G.GTA_ROLE_DEFS) do GTA_ROLE_BY_ID[r.id] = r; GTA_ROLE_ORDER[r.id] = i end

local function GTA_Http(url)
    local body
    pcall(function() body = game:HttpGet(url .. "?t=" .. math.floor(os.time())) end)
    if not body or body == "" then
        pcall(function()
            local req = request or http_request or (syn and syn.request)
            local r = req and req({Url = url, Method = "GET"})
            body = r and r.Body
        end)
    end
    return (type(body) == "string" and body ~= "") and body or nil
end

-- nome -> {TAG = true, ...} (só tags que existem no catálogo; D e DEV são imunes)
-- IMPORTANTE: no Roblox, _G não é o mesmo ambiente do identificador "solto" do script
-- (_G.x = y não faz "x" bare funcionar nesse mesmo script). Por isso é local + exposta nas duas formas.
local function GTA_ParseRoles(body)
    local out = {}
    if type(body) ~= "string" then return out end
    for line in body:gmatch("[^\r\n]+") do
        if not line:match("^%s*#") then
            local n, rest = line:match("^%s*([%w_]+)%s*[:%s%[]?%s*(.-)%s*$")
            if n and rest and rest ~= "" then
                local tags = {}
                for tag in rest:gmatch("%a[%a%d]*") do
                    tag = tag:upper()
                    if tag == "DV" then tag = "DEV" end  -- nome antigo do cargo no arquivo do GitHub
                    if GTA_ROLE_BY_ID[tag] then tags[tag] = true end
                end
                if next(tags) then out[n:lower()] = tags end
            end
        end
    end
    return out
end
_G.GTA_ParseRoles = GTA_ParseRoles

function _G.GTA_MergeLocalRoles(roles)
    for k, list in pairs(_G.GTA_LOCAL_ROLES or {}) do
        k = tostring(k):lower()
        roles[k] = roles[k] or {}
        for _, tag in ipairs(list) do
            tag = tostring(tag):upper()
            if GTA_ROLE_BY_ID[tag] then roles[k][tag] = true end
        end
    end
    return roles
end

local function GTA_ParseBlacklist(body)
    local out = {}
    if type(body) ~= "string" then return out end
    for line in body:gmatch("[^\r\n]+") do
        if not line:match("^%s*#") then
            local k = line:match("^%s*([^|]+)")
            if k then k = k:gsub("%s+$", ""):lower(); if k ~= "" then out[k] = true end end
        end
    end
    return out
end

do  -- blacklist: trava o script pra sempre (sem rodar nada) se o player tiver na lista
    local Plrs = game:GetService("Players")
    local lp = Plrs.LocalPlayer
    local body = GTA_Http(GTA_BLACKLIST_URL)
    local bl = GTA_ParseBlacklist(body)
    local banned = bl[lp.Name:lower()] or bl[tostring(lp.UserId)]
    if banned then
        local sg = Instance.new("ScreenGui")
        sg.Name, sg.ResetOnSpawn, sg.IgnoreGuiInset, sg.DisplayOrder = "GTA_Banned", false, true, 99999
        pcall(function() sg.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
        if not sg.Parent then sg.Parent = lp:WaitForChild("PlayerGui") end
        local bg = Instance.new("Frame", sg)
        bg.Size, bg.BackgroundColor3, bg.BackgroundTransparency = UDim2.fromScale(1, 1), Color3.new(0, 0, 0), 0
        local l = Instance.new("TextLabel", bg)
        l.Size, l.Position, l.AnchorPoint = UDim2.fromOffset(360, 80), UDim2.fromScale(0.5, 0.5), Vector2.new(0.5, 0.5)
        l.BackgroundTransparency, l.Text, l.TextWrapped = 1, "GTA HUB\nvocê foi banido de usar esse script", true
        l.TextColor3, l.Font, l.TextSize = Color3.fromRGB(255, 70, 70), Enum.Font.GothamBold, 18
        return  -- para o script inteiro aqui, nada mais carrega
    end
end

_G.GTA_ROLES_BODY = GTA_Http(GTA_ROLES_URL)
_G.GTA_ROLES_PRELOAD = _G.GTA_MergeLocalRoles(GTA_ParseRoles(_G.GTA_ROLES_BODY))
do
    local lp = game:GetService("Players").LocalPlayer
    local pre = _G.GTA_ROLES_PRELOAD
    local my = (lp.Name:lower() == GTA_OWNER_NAME) and {D = true} or (pre[lp.Name:lower()] or pre[tostring(lp.UserId)] or {})
    local n = 0 for _ in pairs(pre) do n = n + 1 end
    local mine = {} for tag in pairs(my) do mine[#mine + 1] = tag end
    _G.GTA_ROLES_DIAG = string.format("user=%s id=%s | arquivo=%s | entradas=%d | meus cargos=%s",
        lp.Name, tostring(lp.UserId), _G.GTA_ROLES_BODY and (#_G.GTA_ROLES_BODY .. " bytes") or "NAO CARREGOU", n,
        #mine > 0 and table.concat(mine, ",") or "NENHUM")
    print("[GTA Roles] " .. _G.GTA_ROLES_DIAG)
    local exempt = my.D or false
    for tag in pairs(my) do
        local def = GTA_ROLE_BY_ID[tag]
        if def and def.noKey then exempt = true end
    end
    _G.GTA_ROLE_EXEMPT = exempt
    _G.GTA_MY_ROLES = my
end

-- Abas Proteção+ e RGB: "usuário normal" = sem nenhum cargo no catálogo (arquivo de cargos do GitHub).
-- Quem tem qualquer cargo vê e usa as duas abas; o dono (D) entra sempre, mesmo com o GitHub fora do ar.
-- Pra liberar só pro dono, troque o corpo por:  return type(_G.GTA_MY_ROLES) == "table" and _G.GTA_MY_ROLES.D == true
_G.GTA_FULL_ACCESS_TAGS = {"D", "CO", "ADM", "SADM", "DEV"}
function _G.GTA_FullAccess()
    local lp = game:GetService("Players").LocalPlayer
    if lp and lp.Name:lower() == GTA_OWNER_NAME then return true end
    local my = _G.GTA_MY_ROLES
    if type(my) ~= "table" then return false end
    for _, tag in ipairs(_G.GTA_FULL_ACCESS_TAGS) do if my[tag] then return true end end
    return false
end

function _G.GTA_CanUseRestricted()
    if _G.GTA_FullAccess and _G.GTA_FullAccess() then return true end
    return type(_G.GTA_MY_ROLES) == "table" and next(_G.GTA_MY_ROLES) ~= nil
end

-- ============================================================
-- GTA KEY SYSTEM (keys rotativas lidas do teu GitHub)
-- Arquivo de keys (uma por linha):  GTA-XXXX-XXXX-XXXX | 2026-11-20 18:00 | 0
--   campo 2 = validade em UTC (AAAA-MM-DD HH:MM) ou 0 = não expira; campo 3 = UserId travado (0 = qualquer um)
-- Trocar de key = editar o arquivo no GitHub (tirar a linha velha, pôr a nova). Gerador: GTA_KeyGen.py
-- ============================================================
local GTA_KEY_ENABLED = false  -- versão sem key: a tela de key nunca aparece
local GTA_KEY_URL = "https://raw.githubusercontent.com/gta244adm/Gta-hub-pro/refs/heads/main/GTA%20HUB%20KEYS"  -- FILL: cria esse arquivo no repo
local GTA_KEY_GET_LINK = "https://lootlabs.gg/s/FILL_SEU_LINK_AQUI"   -- FILL: link da tua campanha no Lootlabs (ela entrega a key no final)
local GTA_KEY_FILE = "GTAHub_Key.txt"
local GTA_KEY_RECHECK = 120   -- segundos entre conferências com o servidor durante o jogo
local GTA_KEY_OFFLINE_GRACE = 6 * 3600  -- se o GitHub cair, key já validada vale por mais 6h
if GTA_KEY_ENABLED then
    local Players, TS = game:GetService("Players"), game:GetService("TweenService")
    local lp = Players.LocalPlayer
    local function now() local ok, t = pcall(function() return workspace:GetServerTimeNow() end) return (ok and t) or os.time() end
    local function utc(y, m, d, hh, mm)
        y = (m <= 2) and (y - 1) or y
        local era = math.floor(y / 400)
        local yoe = y - era * 400
        local doy = math.floor((153 * (m + (m > 2 and -3 or 9)) + 2) / 5) + d - 1
        local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
        return (era * 146097 + doe - 719468) * 86400 + hh * 3600 + mm * 60
    end
    local function norm(k) return (tostring(k or ""):gsub("%s", "")):upper() end
    local function fetch()
        local body
        pcall(function() body = game:HttpGet(GTA_KEY_URL .. "?t=" .. math.floor(os.time())) end)
        if not body or body == "" then
            pcall(function()
                local req = request or http_request or (syn and syn.request)
                local r = req and req({Url = GTA_KEY_URL, Method = "GET"})
                body = r and r.Body
            end)
        end
        if type(body) ~= "string" or body == "" then return nil end
        local list = {}
        for line in body:gmatch("[^\r\n]+") do
            local k, e, u = line:match("^%s*([^|]+)|?%s*([^|]*)|?%s*([^|]*)")
            if k and norm(k) ~= "" and not line:match("^%s*#") then
                local exp = 0
                local y, mo, d, hh, mi = tostring(e):match("(%d+)-(%d+)-(%d+)%s+(%d+):(%d+)")
                if y then exp = utc(tonumber(y), tonumber(mo), tonumber(d), tonumber(hh), tonumber(mi))
                else local n = tonumber((tostring(e):gsub("%s", ""))); if n and n > 1e9 then exp = n end end
                list[norm(k)] = {exp = exp, uid = tonumber((tostring(u):gsub("%s", ""))) or 0}
            end
        end
        return list
    end
    local function check(list, key)  -- true, msg | false, motivo
        local e = list[norm(key)]
        if not e then return false, "key inválida ou já trocada" end
        if e.exp ~= 0 and now() >= e.exp then return false, "key expirada" end
        if e.uid ~= 0 and e.uid ~= lp.UserId then return false, "essa key é de outra conta" end
        return true, (e.exp == 0) and "key permanente" or ("válida por mais " .. math.floor((e.exp - now()) / 60) .. " min")
    end
    local function saved()
        if type(readfile) ~= "function" then return nil end
        local ok, r = pcall(readfile, GTA_KEY_FILE)
        if not ok or type(r) ~= "string" then return nil end
        local k, t = r:match("^([^\n]+)\n?(%d*)")
        return k, tonumber(t) or 0
    end
    local function save(key) if type(writefile) == "function" then pcall(writefile, GTA_KEY_FILE, norm(key) .. "\n" .. math.floor(os.time())) end end

    local function gate(reason)  -- mostra a tela de key e só volta quando uma key válida for digitada
        local sg = Instance.new("ScreenGui")
        sg.Name, sg.ResetOnSpawn, sg.IgnoreGuiInset, sg.DisplayOrder = "GTA_KeyGate", false, true, 99999
        pcall(function() sg.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
        if not sg.Parent then sg.Parent = lp:WaitForChild("PlayerGui") end
        local bg = Instance.new("Frame", sg)
        bg.Size, bg.BackgroundColor3, bg.BackgroundTransparency, bg.Active = UDim2.fromScale(1, 1), Color3.new(0, 0, 0), 0.25, true
        local box = Instance.new("Frame", bg)
        box.Size, box.Position, box.AnchorPoint = UDim2.fromOffset(340, 210), UDim2.fromScale(0.5, 0.5), Vector2.new(0.5, 0.5)
        box.BackgroundColor3, box.BorderSizePixel = Color3.fromRGB(18, 10, 10), 0
        Instance.new("UICorner", box).CornerRadius = UDim.new(0, 12)
        local st = Instance.new("UIStroke", box); st.Color, st.Thickness = Color3.fromRGB(200, 25, 25), 2
        local function lbl(txt, y, size, col, font)
            local l = Instance.new("TextLabel", box)
            l.BackgroundTransparency, l.Size, l.Position = 1, UDim2.new(1, -24, 0, size + 4), UDim2.fromOffset(12, y)
            l.Text, l.TextSize, l.TextColor3, l.Font, l.TextWrapped = txt, size, col, font or Enum.Font.GothamBold, true
            return l
        end
        lbl("GTA HUB  •  KEY", 12, 20, Color3.fromRGB(255, 70, 70))
        local info = lbl(reason or "cole sua key pra entrar", 42, 13, Color3.fromRGB(210, 190, 190), Enum.Font.Gotham)
        local tb = Instance.new("TextBox", box)
        tb.Size, tb.Position, tb.PlaceholderText = UDim2.new(1, -24, 0, 38), UDim2.fromOffset(12, 78), "GTA-XXXX-XXXX-XXXX"
        tb.BackgroundColor3, tb.TextColor3, tb.Text, tb.Font, tb.TextSize, tb.ClearTextOnFocus = Color3.fromRGB(32, 18, 18), Color3.new(1, 1, 1), "", Enum.Font.Code, 16, false
        Instance.new("UICorner", tb).CornerRadius = UDim.new(0, 8)
        local function btn(txt, x, w, col)
            local b = Instance.new("TextButton", box)
            b.Size, b.Position, b.Text = UDim2.new(w, -8, 0, 36), UDim2.new(x, 12, 0, 128), txt
            b.BackgroundColor3, b.TextColor3, b.Font, b.TextSize = col, Color3.new(1, 1, 1), Enum.Font.GothamBold, 14
            Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
            return b
        end
        local go = btn("Verificar", 0, GTA_KEY_GET_LINK ~= "" and 0.5 or 1, Color3.fromRGB(190, 25, 25))
        if GTA_KEY_GET_LINK ~= "" then
            local gk = btn("Pegar key (Lootlabs)", 0.5, 0.5, Color3.fromRGB(60, 40, 40))
            gk.MouseButton1Click:Connect(function()
                local copied = false
                if setclipboard then copied = pcall(setclipboard, GTA_KEY_GET_LINK) end
                info.Text, info.TextColor3 = copied and "link do Lootlabs copiado! cola no navegador e segue os passos" or "não consegui copiar; o link tá no console (F9)", copied and Color3.fromRGB(90, 220, 120) or Color3.fromRGB(255, 160, 60)
                if not copied then print("[GTA HUB] Lootlabs: " .. GTA_KEY_GET_LINK) end
            end)
        end
        lbl("a key é trocada de tempos em tempos", 176, 11, Color3.fromRGB(150, 120, 120), Enum.Font.Gotham)
        local done, busy = false, false
        local function try()
            if busy then return end
            busy = true; info.Text, info.TextColor3 = "verificando...", Color3.fromRGB(210, 190, 190)
            local list = fetch()
            if not list then info.Text, info.TextColor3 = "sem conexão com o servidor de keys", Color3.fromRGB(255, 160, 60)
            else
                local ok, msg = check(list, tb.Text)
                if ok then save(tb.Text); info.Text, info.TextColor3 = msg, Color3.fromRGB(90, 220, 120); task.wait(0.6); done = true
                else info.Text, info.TextColor3 = msg, Color3.fromRGB(255, 90, 90) end
            end
            busy = false
        end
        go.MouseButton1Click:Connect(try)
        tb.FocusLost:Connect(function(enter) if enter then try() end end)
        while not done do task.wait(0.15) end
        sg:Destroy()
    end

    local function validNow()  -- confere a key salva; true = pode usar
        local k, at = saved()
        if not k then return false, "cole sua key pra entrar" end
        local list = fetch()
        if not list then
            if at and at > 0 and os.time() - at < GTA_KEY_OFFLINE_GRACE then return true end
            return false, "sem conexão com o servidor de keys"
        end
        local ok, msg = check(list, k)
        if ok then save(k) return true end
        return false, msg .. ", cole a key nova"
    end

    if _G.GTA_ROLE_EXEMPT then
        _G.GTA_KEY_OK = true  -- dono/staff/VIP etc: cargo libera, sem key
    else
        local ok, why = validNow()
        if not ok then gate(why) end
        _G.GTA_KEY_OK = true
        task.spawn(function()  -- key trocada/expirada durante o jogo: a tela volta e trava até colar a nova
            while task.wait(GTA_KEY_RECHECK) do
                local v, w = validNow()
                if not v and w and not w:find("sem conexão") then _G.GTA_KEY_OK = false; gate("sua key foi trocada: " .. w); _G.GTA_KEY_OK = true end
            end
        end)
    end
end

