-- CONFIG DA TELA DE LOADING (mude aqui)
-- ============================================================
local GTA_LOADING_SECONDS = 20                         -- tempo TOTAL até abrir o menu (loading + erro + desconectado + troll). 0 = sem loading
local GTA_SHARINGAN_IMAGE = "rbxassetid://104083038838148"  -- imagem do Sharingan
local GTA_LOADING_SPIN_SPEED = 600                     -- graus por segundo do giro
local GTA_TROLL_ONCE = true                            -- true: o erro/desconectado/troll só aparece na 1ª vez (depois só o loading)
local GTA_LOADING_TITLE = "GTA Hub"
local GTA_LOADING_TEXT = "Carregando..."

local GTA_SHARINGAN_B64 = ""
local GTA_SharinganCache
local function GTA_GetSharinganAsset()
    if GTA_SharinganCache ~= nil then return GTA_SharinganCache or nil end
    GTA_SharinganCache = false
    if type(writefile) ~= "function" or type(getcustomasset) ~= "function" then return nil end
    local ok, res = pcall(function()
        local A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local map = {}
        for i = 1, #A do map[A:byte(i)] = i - 1 end
        local out, buf, bits = {}, 0, 0
        local data = GTA_SHARINGAN_B64:gsub("=", "")
        for i = 1, #data do
            buf = buf * 64 + map[data:byte(i)]; bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local div = 2 ^ bits
                local byte = math.floor(buf / div)
                out[#out + 1] = string.char(byte)
                buf = buf - byte * div
            end
        end
        local bytes = table.concat(out)
        local path = "GTAHub_Sharingan.png"
        writefile(path, bytes)
        return getcustomasset(path)
    end)
    if ok and type(res) == "string" and res ~= "" then GTA_SharinganCache = res; return res end
    return nil
end

