do
    local function mk(cls, parent, props)
        local o = Instance.new(cls)
        for k, v in pairs(props or {}) do o[k] = v end
        o.Parent = parent
        return o
    end
    local function frame(parent, props) props = props or {}; props.BorderSizePixel = 0; if props.BackgroundTransparency == nil then props.BackgroundTransparency = 0 end; return mk("Frame", parent, props) end
    local function round(f) mk("UICorner", f, {CornerRadius = UDim.new(1, 0)}); return f end
    local function dot(parent, px, color, transp, x, y)
        return round(frame(parent, {Size = UDim2.new(0, px, 0, px), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, x or 95, 0, y or 95), BackgroundColor3 = color, BackgroundTransparency = transp or 0}))
    end
    local function ring(parent, px, color, thick, transp, x, y)
        local f = round(frame(parent, {Size = UDim2.new(0, px, 0, px), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, x or 95, 0, y or 95), BackgroundTransparency = 1}))
        local s = mk("UIStroke", f, {Color = color, Thickness = thick or 2, Transparency = transp or 0})
        return f, s
    end
    local function rot(parent, px) return frame(parent, {Size = UDim2.new(0, px or 190, 0, px or 190), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, 95, 0, 95), BackgroundTransparency = 1}) end
    local function seg(parent, color, transp)
        return frame(parent, {Size = UDim2.new(0, 2, 0, 2), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = color, BackgroundTransparency = transp or 0})
    end
    local function setSeg(f, th, x1, y1, x2, y2)
        local dx, dy = x2 - x1, y2 - y1
        f.Size = UDim2.new(0, math.sqrt(dx * dx + dy * dy) + 1, 0, th)
        f.Position = UDim2.new(0, (x1 + x2) / 2, 0, (y1 + y2) / 2)
        f.Rotation = math.deg(math.atan2(dy, dx))
    end
    local function clamp(v, a, b) return math.max(a, math.min(b, v)) end
    local C = Color3.fromRGB
    local B, A = GTA_LS.build, GTA_LS.accent
    local added = {}
    local function add(name, accent, fn) B[name] = fn; A[name] = accent; added[#added + 1] = name end

    add("Núcleo", C(255, 90, 60), function(h)
