        local spin = rot(h)
        local rays = {}
        for k = 0, 11 do
            local cont = rot(h); cont.Rotation = k * 30; cont.Parent = spin
            rays[k + 1] = frame(cont, {Size = UDim2.new(0, 4, 0, 20), AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 0.5, -46), BackgroundColor3 = c})
        end
        local glow = dot(h, 60, c, 0.7); local core = dot(h, 34, Color3.fromRGB(255, 235, 200), 0)
        return function(t)
            spin.Rotation = t * 60
            for k, r in ipairs(rays) do r.Size = UDim2.new(0, 4, 0, 14 + (math.sin(t * 4 + k) * 0.5 + 0.5) * 22) end
            local p = math.sin(t * 5) * 0.5 + 0.5
            core.Size = UDim2.new(0, 28 + p * 10, 0, 28 + p * 10); glow.Size = UDim2.new(0, 56 + p * 30, 0, 56 + p * 30)
        end
    end)

