        for i = 1, N do gl[i] = seg(h, c, 0.75); ln[i] = seg(h, Color3.new(1, 1, 1):Lerp(c, 0.35), 0) end
        local function ecg(u)
            local function g(m, w) local d = (u - m) / w; return math.exp(-d * d) end
            return 0.1 * g(0.2, 0.035) - 0.14 * g(0.42, 0.012) + 1.0 * g(0.46, 0.012) - 0.32 * g(0.5, 0.014) + 0.24 * g(0.72, 0.05)
        end
        return function(t)
            local px, py
            for i = 0, N do
                local x = i / N * 190
                local u = (x / 190 * 1.5 - t * 0.6) % 1
                local y = 118 - ecg(u) * 78
                if px then
                    setSeg(gl[i], 7, px, py, x, y); setSeg(ln[i], 2, px, py, x, y)
                    local a = i / N
                    ln[i].BackgroundTransparency = 0.85 - a * 0.85; gl[i].BackgroundTransparency = 1 - a * 0.3
