        for i, v in ipairs(lats) do lat[i] = {ring(h, 10, c, 1, v == 0 and 0.1 or 0.45), v} end
        local scan = frame(h, {Size = UDim2.new(0, 100, 0, 2), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.2})
        local orbit = rot(h); orbit.Rotation = -24
