        local sat = dot(orbit, 9, Color3.new(1, 1, 1), 0)
        local satGlow = dot(orbit, 18, c, 0.6)
        for _, corner in ipairs({{4, 4}, {186, 4}, {4, 186}, {186, 186}}) do
            local sx, sy = corner[1] < 95 and 1 or -1, corner[2] < 95 and 1 or -1
            frame(h, {Size = UDim2.new(0, 14, 0, 2), Position = UDim2.new(0, corner[1] - (sx < 0 and 14 or 0), 0, corner[2] - (sy < 0 and 2 or 0)), BackgroundColor3 = c})
            frame(h, {Size = UDim2.new(0, 2, 0, 14), Position = UDim2.new(0, corner[1] - (sx < 0 and 2 or 0), 0, corner[2] - (sy < 0 and 14 or 0)), BackgroundColor3 = c})
        end
