                local w = 2 * math.sqrt(math.max(0, R * R - y * y))
                l[1].Size = UDim2.new(0, math.max(2, w), 0, math.max(2, w * 0.22))
                l[1].Position = UDim2.new(0, 95, 0, 95 + y)
            end
            local sy = math.sin(t * 1.6) * R * 0.95
            scan.Position = UDim2.new(0, 95, 0, 95 + sy)
            scan.Size = UDim2.new(0, 2 * math.sqrt(math.max(1, R * R - sy * sy)), 0, 2)
            local a = t * 2.2
            sat.Position = UDim2.new(0, 95 + math.cos(a) * 88, 0, 95 + math.sin(a) * 22)
            satGlow.Position = sat.Position
        end
    end)

    add("Círculo Mágico", C(220, 120, 255), function(h)
