        return function(t)
            outer.Rotation = t * 14; runes.Rotation = -t * 22
            sqA.Rotation = -t * 38; sqB.Rotation = 45 - t * 38
            local base = t * 0.45
            local V = {}
            for i = 0, 5 do local a = base + i * math.pi / 3; V[i] = {95 + math.cos(a) * 80, 95 + math.sin(a) * 80} end
            local pairsList = {{0, 2}, {2, 4}, {4, 0}, {1, 3}, {3, 5}, {5, 1}}
            for i, pr in ipairs(pairsList) do
                local a, b = V[pr[1]], V[pr[2]]
                setSeg(lines[i][1], 2, a[1], a[2], b[1], b[2]); setSeg(lines[i][2], 6, a[1], a[2], b[1], b[2])
            end
            local k = math.sin(t * 4) * 0.5 + 0.5
            glow.Size = UDim2.new(0, 26 + k * 16, 0, 26 + k * 16); core.Size = UDim2.new(0, 12 + k * 5, 0, 12 + k * 5)
            for _, s in ipairs(sparks) do
                local q = (t * 0.35 + s[2]) % 1
                s[1].Position = UDim2.new(0, 95 + math.cos(s[3] + t) * q * 70, 0, 95 + math.sin(s[3] + t) * q * 70)
                s[1].BackgroundTransparency = q
            end
        end
    end)

