        local lbl = txt(h, {Size = UDim2.new(1, 0, 0, 20), Position = UDim2.new(0, 0, 0, 8), Text = "FIREWALL", Font = Enum.Font.GothamBold, TextSize = 16, TextColor3 = c})
        local st = txt(h, {Size = UDim2.new(1, 0, 0, 16), Position = UDim2.new(0, 0, 0, 150), Text = "", TextSize = 12, TextColor3 = Color3.new(1, 1, 1)})
