    end)

    add("Senha", C(90, 255, 120), function(h)
        local c = A["Senha"]
        txt(h, {Size = UDim2.new(1, 0, 0, 20), Position = UDim2.new(0, 0, 0, 22), Text = "BRUTE FORCE", Font = Enum.Font.GothamBold, TextSize = 15, TextColor3 = c})
        local slots = {}
        local chars = "ABCDEFGHJKLMNPQRSTUVWXYZ0123456789#$%&"
        for i = 1, 8 do
            local f = frame(h, {Size = UDim2.new(0, 18, 0, 30), Position = UDim2.new(0, 11 + (i - 1) * 21, 0, 70), BackgroundColor3 = C(0, 25, 5)})
            mk("UIStroke", f, {Color = c, Thickness = 1.5})
            slots[i] = txt(f, {Size = UDim2.new(1, 0, 1, 0), Text = "?", TextSize = 20, TextColor3 = c, Font = Enum.Font.Code})
        end
        local code = {}
        for i = 1, 8 do local k = math.random(1, #chars); code[i] = chars:sub(k, k) end
        local status = txt(h, {Size = UDim2.new(1, 0, 0, 20), Position = UDim2.new(0, 0, 0, 118), Text = "", TextSize = 14, TextColor3 = Color3.new(1, 1, 1)})
        local bucket = -1
        return function(t)
            local ct = t % 7
            local locked = math.min(8, math.floor(ct / 0.7))
            local b = math.floor(t * 18)
            for i = 1, 8 do
                if i <= locked then slots[i].Text = code[i]; slots[i].TextColor3 = Color3.new(1, 1, 1)
                elseif b ~= bucket then local k = math.random(1, #chars); slots[i].Text = chars:sub(k, k); slots[i].TextColor3 = c end
            end
            bucket = b
            if locked >= 8 then status.Text = "ACCESS GRANTED"; status.TextColor3 = C(120, 255, 140)
            else status.Text = "tentando... " .. math.floor(ct / 5.6 * 100) .. "%"; status.TextColor3 = Color3.new(1, 1, 1) end
        end
    end)

    add("Rede de Nós", C(120, 255, 200), function(h)
        local c = A["Rede de Nós"]
        local N = 11
        local nodes, edges = {}, {}
        for i = 1, N do nodes[i] = {dot(h, 9, c, 0), 0.3 + math.random() * 0.5, math.random() * 6.28, 30 + math.random() * 50, 30 + math.random() * 50} end
        for i = 1, N do edges[#edges + 1] = {i, i % N + 1}; edges[#edges + 1] = {i, (i + 2) % N + 1} end
        for _, e in ipairs(edges) do e[3] = seg(h, c, 0.55) end
        local packet = dot(h, 7, Color3.new(1, 1, 1), 0)
        local pos = {}
        return function(t)
            for i, n in ipairs(nodes) do
                local x, y = 95 + math.cos(t * n[2] + n[3]) * n[4] * 1.3, 95 + math.sin(t * n[2] * 1.3 + n[3]) * n[5] * 1.2
                pos[i] = {x, y}; n[1].Position = UDim2.new(0, x, 0, y)
            end
            for _, e in ipairs(edges) do local a, b = pos[e[1]], pos[e[2]]; setSeg(e[3], 1, a[1], a[2], b[1], b[2]) end
            local ei = (math.floor(t * 1.6) % #edges) + 1
            local e, f = edges[ei], (t * 1.6) % 1
            local a, b = pos[e[1]], pos[e[2]]
            packet.Position = UDim2.new(0, a[1] + (b[1] - a[1]) * f, 0, a[2] + (b[2] - a[2]) * f)
        end
