    add("Traceroute", C(255, 200, 60), function(h)
        local c = A["Traceroute"]
        local pts = {{20, 150}, {55, 105}, {100, 135}, {130, 80}, {165, 100}, {170, 40}}
        local lines, nodes, labs = {}, {}, {}
        for i = 1, #pts - 1 do lines[i] = seg(h, c, 0.6); setSeg(lines[i], 2, pts[i][1], pts[i][2], pts[i + 1][1], pts[i + 1][2]) end
        for i, p in ipairs(pts) do
            nodes[i] = ring(h, 14, c, 2, 0, p[1], p[2])
            labs[i] = txt(h, {Size = UDim2.new(0, 70, 0, 12), AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0, p[1], 0, p[2] + 9), Text = "hop " .. i, TextSize = 10, TextColor3 = c})
        end
        local pkt = dot(h, 9, Color3.new(1, 1, 1), 0)
        local wave, ws = ring(h, 10, c, 2, 0.3)
        return function(t)
            local seq = (t * 0.9) % (#pts - 1 + 0.6)
            local i = math.min(#pts - 1, math.floor(seq) + 1)
            local f = clamp(seq - (i - 1), 0, 1)
            if seq >= #pts - 1 then f = 1 end
            local a, b = pts[i], pts[i + 1]
            pkt.Position = UDim2.new(0, a[1] + (b[1] - a[1]) * f, 0, a[2] + (b[2] - a[2]) * f)
            local k = (t * 0.9) % 1
            wave.Position = UDim2.new(0, b[1], 0, b[2]); wave.Size = UDim2.new(0, 14 + k * 30, 0, 14 + k * 30)
            if ws then ws.Transparency = 0.2 + k * 0.8 end
            for j, l in ipairs(labs) do l.Text = (j <= i) and ("hop " .. j .. "  " .. (8 + j * 11 + math.floor(t * 3) % 5) .. "ms") or ("hop " .. j) end
        end
    end)

