    add("Caveira", C(215, 255, 215), function(h)
        local c = A["Caveira"]
        local map = {"....#####....", "..#########..", ".###########.", "###..###..###", "##...###...##", "##...###...##", "###..###..###", ".###########.",
            "..####.####..", "...#######...", "...#.#.#.#...", "...#.#.#.#...", "....#####...."}
        local cells = {}
        for r, row in ipairs(map) do for k = 1, #row do
            if row:sub(k, k) == "#" then
                cells[#cells + 1] = {frame(h, {Size = UDim2.new(0, 11, 0, 11), BackgroundColor3 = c}), k, r}
            end
        end end
        local eyes = {dot(h, 12, C(255, 30, 30), 0), dot(h, 12, C(255, 30, 30), 0)}
        local bucket, shift, shiftRow = -1, 0, 0
        return function(t)
            local b = math.floor(t * 5)
            if b ~= bucket then bucket = b; if math.random() < 0.35 then shift = math.random(-9, 9); shiftRow = math.random(1, 13) else shift = 0 end end
            local jaw = math.abs(math.sin(t * 7)) * 5
            for _, cl in ipairs(cells) do
                local x = 23 + (cl[2] - 1) * 11 + ((cl[3] == shiftRow or cl[3] == shiftRow + 1) and shift or 0)
                local y = 12 + (cl[3] - 1) * 11 + (cl[3] >= 10 and jaw or 0)
                cl[1].Position = UDim2.new(0, x, 0, y)
                cl[1].BackgroundColor3 = (shift ~= 0 and cl[3] == shiftRow) and C(255, 60, 60) or c
            end
            local k = math.sin(t * 6) * 0.5 + 0.5
            eyes[1].Position = UDim2.new(0, 23 + 3.5 * 11 + 5, 0, 12 + 4.5 * 11); eyes[2].Position = UDim2.new(0, 23 + 8.5 * 11 + 5, 0, 12 + 4.5 * 11)
            for _, e in ipairs(eyes) do e.BackgroundTransparency = 0.6 - k * 0.6; e.Size = UDim2.new(0, 8 + k * 6, 0, 8 + k * 6) end
        end
    end)

