    add("Osciloscópio", C(90, 255, 120), function(h)
        local c = A["Osciloscópio"]
        for i = 1, 7 do frame(h, {Size = UDim2.new(1, 0, 0, 1), Position = UDim2.new(0, 0, 0, i * 23.7), BackgroundColor3 = c, BackgroundTransparency = 0.88}) end
        for i = 1, 7 do frame(h, {Size = UDim2.new(0, 1, 1, 0), Position = UDim2.new(0, i * 23.7, 0, 0), BackgroundColor3 = c, BackgroundTransparency = 0.88}) end
        local N = 60
        local g1, g2, ln = {}, {}, {}
        for i = 1, N do g1[i] = seg(h, c, 0.85); g2[i] = seg(h, c, 0.65); ln[i] = seg(h, Color3.new(1, 1, 1):Lerp(c, 0.3), 0) end
        local function f(x, t) return 95 + math.sin(x * 0.06 + t * 4) * 34 + math.sin(x * 0.17 - t * 6.5) * 14 + math.sin(x * 0.41 + t * 11) * 5 end
        return function(t)
            local px, py, qy
            for i = 0, N do
                local x = i / N * 190
                local y, y2 = f(x, t), f(x, t - 0.06)
                if px then
                    setSeg(g1[i], 8, px, py, x, y); setSeg(g2[i], 3, px, qy, x, y2); setSeg(ln[i], 2, px, py, x, y)
                end
                px, py, qy = x, y, y2
            end
        end
    end)

