    add("Hex Dump", C(100, 255, 140), function(h)
        local c = A["Hex Dump"]
        h.ClipsDescendants = true
        local rows, lines = {}, {}
        local hl = frame(h, {Size = UDim2.new(1, 0, 0, 16), BackgroundColor3 = c, BackgroundTransparency = 0.82})
        for i = 1, 11 do
            rows[i] = txt(h, {Size = UDim2.new(1, -4, 0, 16), Position = UDim2.new(0, 3, 0, (i - 1) * 17), Text = "", TextSize = 11, TextColor3 = c, TextXAlignment = Enum.TextXAlignment.Left})
            lines[i] = ""
        end
        local addr = 4096
        local function newLine()
            addr = addr + 8
            local o = {}
            for k = 1, 6 do o[k] = hexs(2) end
            return string.format("%04X  %s  %s", addr % 65536, table.concat(o, " "), hexs(2) .. ".." .. hexs(1))
        end
        for i = 1, 11 do lines[i] = newLine() end
        local bucket = -1
        return function(t)
            local b = math.floor(t * 7)
            if b ~= bucket then
                bucket = b
                table.remove(lines, 1); lines[#lines + 1] = newLine()
                for i = 1, 11 do rows[i].Text = lines[i]; rows[i].TextTransparency = 0.45 - (i / 11) * 0.45 end
            end
            hl.Position = UDim2.new(0, 0, 0, (math.floor(t * 2.2) % 11) * 17)
        end
    end)

    add("Descriptografia", C(120, 255, 200), function(h)
        local c = A["Descriptografia"]
        local plain = {"GTA HUB SYSTEM", "AUTENTICANDO...", "ACESSO PERMITIDO"}
        local cols = {}
        local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%&*"
        txt(h, {Size = UDim2.new(1, 0, 0, 16), Position = UDim2.new(0, 0, 0, 24), Text = "DECRYPTING...", TextSize = 12, TextColor3 = c, Font = Enum.Font.GothamBold})
        for li, s in ipairs(plain) do
            cols[li] = {}
            local x0 = 95 - (#s * 9) / 2
            for k = 1, #s do
                cols[li][k] = txt(h, {Size = UDim2.new(0, 9, 0, 18), Position = UDim2.new(0, x0 + (k - 1) * 9, 0, 56 + (li - 1) * 32), Text = " ", TextSize = 15, TextColor3 = c})
            end
        end
        local bucket = -1
        return function(t)
            local ct = t % 8
            local b = math.floor(t * 20)
            for li, s in ipairs(plain) do
                for k = 1, #s do
                    local lockAt = 0.4 + (li - 1) * 1.6 + k * 0.12
                    local lab = cols[li][k]
                    if ct >= lockAt then lab.Text = s:sub(k, k); lab.TextColor3 = Color3.new(1, 1, 1)
                    elseif b ~= bucket then local r = math.random(1, #chars); lab.Text = chars:sub(r, r); lab.TextColor3 = c end
                end
            end
            bucket = b
        end
    end)

    -- ===================== TEMA GALÁXIA (15) =====================
    local function starfield(h, n, maxSize)
        local st = {}
        for i = 1, n do st[i] = {dot(h, 1 + math.random() * (maxSize or 2), Color3.new(1, 1, 1), 0.4, math.random(2, 188), math.random(2, 188)), math.random() * 6.28, 1 + math.random() * 2} end
        return function(t) for _, s in ipairs(st) do s[1].BackgroundTransparency = 0.85 - (math.sin(t * s[3] + s[2]) * 0.5 + 0.5) * 0.8 end end
    end
    local function gradient(f, seq, rotation)
        local g = Instance.new("UIGradient"); g.Color = seq; g.Rotation = rotation or 0; g.Parent = f; return g
    end

    add("Nebulosa", C(255, 120, 220), function(h)
        local twinkle = starfield(h, 34, 2)
        local cols = {C(255, 90, 200), C(130, 80, 255), C(70, 150, 255), C(255, 140, 90), C(200, 70, 255), C(80, 220, 255)}
        local blobs = {}
        for i = 1, 11 do
            local sz = 70 + math.random() * 60
            blobs[i] = {dot(h, sz, cols[(i % #cols) + 1], 0.86), math.random() * 6.28, 0.2 + math.random() * 0.4, 20 + math.random() * 30, sz}
        end
        local core = dot(h, 10, Color3.new(1, 1, 1), 0.1); local cg = dot(h, 36, C(255, 200, 240), 0.8)
        return function(t)
            twinkle(t)
            for _, b in ipairs(blobs) do
                b[1].Position = UDim2.new(0, 95 + math.cos(t * b[3] + b[2]) * b[4], 0, 95 + math.sin(t * b[3] * 1.3 + b[2]) * b[4])
                local k = b[5] + math.sin(t * 0.8 + b[2]) * 10
                b[1].Size = UDim2.new(0, k, 0, k)
            end
            local k = 30 + math.sin(t * 2.5) * 6
            cg.Size = UDim2.new(0, k, 0, k)
        end
    end)

    add("Meteoros", C(255, 210, 140), function(h)
        local twinkle = starfield(h, 26, 2)
        local ms = {}
        for i = 1, 6 do
            local m = {heads = dot(h, 5, Color3.new(1, 1, 1), 0), tails = {}, off = math.random(), sp = 0.35 + math.random() * 0.4, y0 = math.random(-20, 150), len = 34 + math.random() * 24}
            for k = 1, 5 do m.tails[k] = seg(h, C(255, 220, 160), 0.2 + k * 0.15) end
            ms[i] = m
        end
        local planet = dot(h, 90, C(40, 30, 70), 0, 150, 210); dot(h, 94, C(120, 90, 200), 0.8, 150, 210)
        return function(t)
