                local hx, hy = -20 + q * 240, m.y0 + q * 150
                m.heads.Position = UDim2.new(0, hx, 0, hy)
                m.heads.BackgroundTransparency = clamp((q - 0.85) * 6, 0, 1)
                for k, tl in ipairs(m.tails) do
                    local a, b = (k - 1) / 5, k / 5
                    setSeg(tl, 3 - k * 0.4, hx - a * m.len * 1.4, hy - a * m.len * 0.6, hx - b * m.len * 1.4, hy - b * m.len * 0.6)
                end
            end
        end
    end)

    add("Hiperespaço", C(200, 230, 255), function(h)
        local st = {}
        for i = 1, 70 do st[i] = {seg(h, Color3.new(1, 1, 1), 0), math.random() * 6.283, math.random(), 0.5 + math.random() * 0.9} end
        local glow = dot(h, 50, C(120, 180, 255), 0.85)
