                local r0 = math.max(0, r1 - (4 + q * q * 46))
                local ca, sa = math.cos(s[2]), math.sin(s[2])
                setSeg(s[1], 1 + q * 2, 95 + ca * r0, 95 + sa * r0, 95 + ca * r1, 95 + sa * r1)
                s[1].BackgroundTransparency = clamp(1 - q * 2.2, 0, 1) * 0 + (q < 0.1 and (0.1 - q) * 10 or 0)
            end
            local k = 44 + math.sin(t * 6) * 8
            glow.Size = UDim2.new(0, k, 0, k)
        end
    end)

    add("Eclipse", C(255, 230, 170), function(h)
        local twinkle = starfield(h, 20, 2)
        local rays = {}
        for k = 0, 35 do
            local cont = rot(h); cont.Rotation = k * 10
            rays[k + 1] = frame(cont, {Size = UDim2.new(0, 2, 0, 20), AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 0.5, -42), BackgroundColor3 = C(255, 235, 190), BackgroundTransparency = 0.7})
            rays[k + 1].Parent.Rotation = k * 10
        end
        local halo = dot(h, 130, C(255, 210, 120), 0.9); local halo2 = dot(h, 100, C(255, 230, 160), 0.8)
        local sun = dot(h, 80, C(255, 244, 214), 0)
