            local align = clamp(1 - math.abs(mx) / 40, 0, 1)
            for i, r in ipairs(rays) do r.BackgroundTransparency = 0.8 - align * 0.7 + math.sin(t * 3 + i) * 0.05; r.Size = UDim2.new(0, 2, 0, 14 + align * 24 + (i % 4) * 4) end
            halo.BackgroundTransparency = 0.95 - align * 0.3; halo2.BackgroundTransparency = 0.9 - align * 0.3
            diamond.Position = UDim2.new(0, 95 + 40, 0, 95); diamond.BackgroundTransparency = 1 - clamp((align - 0.7) * 3.3, 0, 1)
        end
    end)

