            for i, cell in ipairs(cells) do
                if i <= locked then
                    cell.Text = pw:sub(i, i); cell.TextColor3 = Color3.new(1, 1, 1); cell.BackgroundColor3 = C(0, 90, 30)
                else
                    if b ~= bucket then local k = math.random(1, #pool); cell.Text = pool:sub(k, k) end
                    cell.TextColor3 = c; cell.BackgroundColor3 = C(0, 30, 10)
                end
            end
            bucket = b
            bar.Size = UDim2.new(clamp(locked / 10, 0, 1), 0, 1, 0)
            if locked >= 10 then status.Text = (math.floor(t * 4) % 2 == 0) and "ACESSO LIBERADO" or ""; status.TextColor3 = Color3.new(1, 1, 1)
            else status.Text = "forca bruta: " .. (math.floor(t * 9371) % 99999) .. " tent/s"; status.TextColor3 = c end
        end
    end)

