    local function starfield(h, n, minS, maxS)
        local st = {}
        for i = 1, n do st[i] = {dot(h, minS + math.random() * (maxS - minS), Color3.new(1, 1, 1), 0.3, math.random(2, 188), math.random(2, 188)), math.random() * 6.28, 1 + math.random() * 2} end
        return function(t) for _, s in ipairs(st) do s[1].BackgroundTransparency = 0.75 - (math.sin(t * s[3] + s[2]) * 0.5 + 0.5) * 0.7 end end
    end

