        local glow = dot(h, 30, c, 0.7)
        return function(t)
            for _, s in ipairs(ss) do
                local q = (t * 0.75 * s[4] + s[3]) % 1
                local r1 = q * q * 105 + 3
                local r2 = r1 + 3 + q * q * 70
                local ca, sa = math.cos(s[2]), math.sin(s[2])
                setSeg(s[1], 1 + q * 2, 95 + ca * r1, 95 + sa * r1, 95 + ca * r2, 95 + sa * r2)
                s[1].BackgroundTransparency = 1 - clamp(q * 2.2, 0, 1)
            end
            local k = 26 + math.sin(t * 6) * 5
            glow.Size = UDim2.new(0, k, 0, k)
        end
    end)

