-- escolhe o estilo: preferência salva (dropdown) > GTA_LOADING_STYLE > aleatório sem repetir
local function GTA_PickLoadingStyle(record)
    local function readf(name)
        local raw
        if type(readfile) == "function" then local ok, r = pcall(readfile, name); if ok and type(r) == "string" and #r > 0 then raw = r end end
        return raw
    end
    local choice = GTA_LOADING_STYLE
    pcall(function() if getgenv().GTAHubLoadStyle then choice = getgenv().GTAHubLoadStyle end end)
    local f = readf("GTAHub_LoadStyle.txt")
    if f then choice = f:gsub("%s+$", "") end
    if choice ~= "Aleatório" and GTA_LS.build[choice] then return choice end
    if not GTA_LS.seeded then GTA_LS.seeded = true; pcall(function() math.randomseed(os.time() + math.floor(os.clock() * 1000)) end) end
    local hist = {used = {}, last = nil}
    local raw = readf("GTAHub_LoadHistory.json")
    if not raw then pcall(function() raw = getgenv().GTAHubLoadHistory end) end
    if type(raw) == "string" then
        local ok, d = pcall(function() return game:GetService("HttpService"):JSONDecode(raw) end)
        if ok and type(d) == "table" and type(d.used) == "table" then hist = d end
    end
    local usedSet = {}
    for _, n in ipairs(hist.used) do usedSet[n] = true end
    local pool = {}
    for _, n in ipairs(GTA_LS.names) do if not usedSet[n] and n ~= hist.last then pool[#pool + 1] = n end end
    if #pool == 0 then   -- todos já apareceram: começa um ciclo novo (sem repetir o último)
        hist.used = {}
        for _, n in ipairs(GTA_LS.names) do if n ~= hist.last then pool[#pool + 1] = n end end
    end
    local pick = pool[math.random(1, #pool)]
    if record then
        hist.used[#hist.used + 1] = pick; hist.last = pick
        local ok, json = pcall(function() return game:GetService("HttpService"):JSONEncode(hist) end)
        if ok then
            pcall(function() getgenv().GTAHubLoadHistory = json end)
            if type(writefile) == "function" then pcall(writefile, "GTAHub_LoadHistory.json", json) end
        end
    end
    return pick
end

local function GTA_ShowLoading(opts)
    opts = opts or {}
    if GTA_LOADING_SECONDS <= 0 and not opts.preview then return end
    local parentGui = (type(gethui) == "function" and select(2, pcall(gethui))) or game:GetService("CoreGui")
    if typeof(parentGui) ~= "Instance" then parentGui = game:GetService("CoreGui") end
    pcall(function() local o = parentGui:FindFirstChild("GTAHub_Loading"); if o then o:Destroy() end end)
    local sg = Instance.new("ScreenGui")
    sg.Name = "GTAHub_Loading"; sg.ResetOnSpawn = false; sg.IgnoreGuiInset = true; sg.DisplayOrder = 100000
    pcall(function() sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling end)
    if not pcall(function() sg.Parent = parentGui end) then return end
    local RS, TS = game:GetService("RunService"), game:GetService("TweenService")

    -- tempos: o total é GTA_LOADING_SECONDS (loading + erro + "desconectado" + troll)
    local T_ERR, T_DISC, T_TROLL = 2.2, 3.6, 2.4
    local T_LOAD = math.max(3, GTA_LOADING_SECONDS - (T_ERR + T_DISC + T_TROLL))
    if opts.seconds then T_LOAD = opts.seconds end
    -- já viu o troll antes? (arquivo + memória)
    local SEEN_FILE = "GTAHub_TrollSeen.txt"
    local trollSeen = false
    if GTA_TROLL_ONCE then
        pcall(function() if getgenv().GTAHubTrollSeen then trollSeen = true end end)
        if not trollSeen and type(isfile) == "function" then pcall(function() if isfile(SEEN_FILE) then trollSeen = true end end) end
    end
    if opts.noTroll then trollSeen = true end
    local function markSeen()
        pcall(function() getgenv().GTAHubTrollSeen = true end)
        if type(writefile) == "function" then pcall(writefile, SEEN_FILE, "1") end
    end

    local bg = Instance.new("Frame")
    bg.Size = UDim2.new(1, 0, 1, 0); bg.BackgroundColor3 = Color3.new(0, 0, 0); bg.BorderSizePixel = 0; bg.Active = true; bg.Parent = sg
    local holder = Instance.new("Frame")
    holder.BackgroundTransparency = 1; holder.AnchorPoint = Vector2.new(0.5, 0.5); holder.Position = UDim2.new(0.5, 0, 0.44, 0)
    holder.Size = UDim2.new(0, 190, 0, 190); holder.Parent = bg
    local styleName = opts.style
    if not styleName or not GTA_LS.build[styleName] then styleName = GTA_PickLoadingStyle(not opts.preview) end
    local okS, upd = pcall(GTA_LS.build[styleName], holder)
    if not okS then upd = nil end
    local accent = GTA_LS.accent[styleName] or Color3.fromRGB(235, 25, 25)
    local title = Instance.new("TextLabel")
    title.BackgroundTransparency = 1; title.AnchorPoint = Vector2.new(0.5, 0); title.Position = UDim2.new(0.5, 0, 0.44, 115)
    title.Size = UDim2.new(0, 360, 0, 34); title.Text = GTA_LOADING_TITLE; title.Font = Enum.Font.GothamBlack
    title.TextSize = 28; title.TextColor3 = accent; title.Parent = bg
    local sub = Instance.new("TextLabel")
    sub.BackgroundTransparency = 1; sub.AnchorPoint = Vector2.new(0.5, 0); sub.Position = UDim2.new(0.5, 0, 0.44, 150)
    sub.Size = UDim2.new(0, 460, 0, 20); sub.Text = GTA_LOADING_TEXT; sub.Font = Enum.Font.Gotham
    sub.TextSize = 14; sub.TextColor3 = Color3.fromRGB(170, 170, 170); sub.Parent = bg
    local barBg = Instance.new("Frame")
    barBg.AnchorPoint = Vector2.new(0.5, 0); barBg.Position = UDim2.new(0.5, 0, 0.44, 182); barBg.Size = UDim2.new(0, 260, 0, 6)
    barBg.BackgroundColor3 = Color3.fromRGB(30, 30, 30); barBg.BorderSizePixel = 0; barBg.Parent = bg
    Instance.new("UICorner", barBg).CornerRadius = UDim.new(1, 0)
    local bar = Instance.new("Frame")
    bar.Size = UDim2.new(0, 0, 1, 0); bar.BackgroundColor3 = accent; bar.BorderSizePixel = 0; bar.Parent = barBg
    Instance.new("UICorner", bar).CornerRadius = UDim.new(1, 0)

    local STYLES = {"GTA HUB", "GTA Hub", "gta hub", "Gta HuB"}
    local state = {phase = "load", t0 = os.clock(), spin = true}
    local conn
    conn = RS.RenderStepped:Connect(function()
        local t = os.clock() - state.t0
        if state.spin and upd then upd(t) end
        if state.phase == "load" then
            bar.Size = UDim2.new(math.min(1, t / T_LOAD), 0, 1, 0)
            title.Text = STYLES[(math.floor(t / 0.4) % #STYLES) + 1]   -- maiúsculo/minúsculo mudando
            sub.Text = GTA_LOADING_TEXT:gsub("%.+$", "") .. string.rep(".", math.floor(t * 2) % 4)
            if math.random() < 0.012 then   -- falhinhas rápidas durante o loading
                title.TextTransparency = 0.6
                task.delay(0.08, function() title.TextTransparency = 0 end)
            end
        end
    end)

    local function shake(dur, amt)
        local base, te = holder.Position, os.clock()
        while os.clock() - te < dur do
            holder.Position = base + UDim2.new(0, math.random(-amt, amt), 0, math.floor(math.random(-amt, amt) * 0.7))
            title.Position = UDim2.new(0.5, math.floor(math.random(-amt, amt) * 0.6), 0.44, 115)
            title.Text = STYLES[math.random(1, #STYLES)]
            title.TextTransparency = (math.random() < 0.35) and 0.7 or 0
            bg.BackgroundColor3 = (math.random() < 0.3) and Color3.fromRGB(70, 0, 0) or Color3.new(0, 0, 0)
            task.wait(0.04)
        end
        holder.Position = base; title.Position = UDim2.new(0.5, 0, 0.44, 115); title.TextTransparency = 0
        bg.BackgroundColor3 = Color3.new(0, 0, 0)
    end

    task.spawn(function()
        pcall(function()
            task.wait(T_LOAD)
            if not trollSeen then
            markSeen()
            -- 1) ERRO falso
            state.phase = "error"; state.spin = false
            bar.Size = UDim2.new(1, 0, 1, 0); bar.BackgroundColor3 = Color3.fromRGB(255, 0, 0)
            sub.TextColor3 = Color3.fromRGB(255, 70, 70); sub.Text = "ERRO: falha ao carregar o módulo (0x8F2A)"
            shake(T_ERR, 9)
            title.Text = "GTA HUB"
            -- 2) "DESCONECTADO" falso (parece a tela do Roblox)
            state.phase = "disc"
            holder.Visible = false; title.Visible = false; sub.Visible = false; barBg.Visible = false
            local dim = Instance.new("Frame")
            dim.Size = UDim2.new(1, 0, 1, 0); dim.BackgroundColor3 = Color3.new(0, 0, 0); dim.BackgroundTransparency = 0.35; dim.BorderSizePixel = 0; dim.Parent = bg
            local box = Instance.new("Frame")
            box.AnchorPoint = Vector2.new(0.5, 0.5); box.Position = UDim2.new(0.5, 0, 0.5, 0); box.Size = UDim2.new(0, 420, 0, 190)
            box.BackgroundColor3 = Color3.fromRGB(57, 59, 61); box.BorderSizePixel = 0; box.Parent = dim
            Instance.new("UICorner", box).CornerRadius = UDim.new(0, 8)
            local dt = Instance.new("TextLabel")
            dt.BackgroundTransparency = 1; dt.Position = UDim2.new(0, 0, 0, 12); dt.Size = UDim2.new(1, 0, 0, 32)
            dt.Text = "Desconectado"; dt.Font = Enum.Font.GothamBold; dt.TextSize = 22; dt.TextColor3 = Color3.new(1, 1, 1); dt.Parent = box
            local dm = Instance.new("TextLabel")
            dm.BackgroundTransparency = 1; dm.Position = UDim2.new(0, 20, 0, 52); dm.Size = UDim2.new(1, -40, 0, 70)
            dm.Text = "Você foi desconectado do servidor.\n(Código de erro: 277)"; dm.TextWrapped = true
            dm.Font = Enum.Font.Gotham; dm.TextSize = 16; dm.TextColor3 = Color3.fromRGB(215, 215, 215); dm.Parent = box
            local function mkBtn(txt, x, col)
                local b = Instance.new("TextButton")
                b.Size = UDim2.new(0, 170, 0, 40); b.Position = UDim2.new(0, x, 1, -56); b.BackgroundColor3 = col
                b.Text = txt; b.Font = Enum.Font.GothamBold; b.TextSize = 16; b.TextColor3 = Color3.new(1, 1, 1); b.AutoButtonColor = false
                b.Parent = box; Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
            end
            mkBtn("Reconectar", 20, Color3.fromRGB(80, 82, 85)); mkBtn("Sair", 230, Color3.fromRGB(80, 82, 85))
            task.wait(T_DISC)
            -- 3) TROLL
            state.phase = "troll"
            box.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
            dt.Text = "TROLL 😂"; dt.TextSize = 34; dt.TextColor3 = Color3.fromRGB(255, 60, 60); dt.Size = UDim2.new(1, 0, 0, 60)
            dm.Text = "Você não foi desconectado, era só uma zoeira!\nAbrindo o menu..."; dm.Position = UDim2.new(0, 20, 0, 80)
            for _, c in ipairs(box:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
            task.wait(T_TROLL)
            end
            -- fade out
            local info = TweenInfo.new(0.6)
            TS:Create(bg, info, {BackgroundTransparency = 1}):Play()
            for _, d in ipairs(bg:GetDescendants()) do
                if d:IsA("TextLabel") or d:IsA("TextButton") then TS:Create(d, info, {TextTransparency = 1}):Play() end
                if d:IsA("Frame") then TS:Create(d, info, {BackgroundTransparency = 1}):Play() end
                if d:IsA("ImageLabel") then TS:Create(d, info, {ImageTransparency = 1}):Play() end
            end
            task.wait(0.7)
        end)
        pcall(function() conn:Disconnect() end)
        pcall(function() sg:Destroy() end)
    end)
    task.delay((opts.seconds or GTA_LOADING_SECONDS) + 8, function() pcall(function() conn:Disconnect() end); pcall(function() sg:Destroy() end) end)
end

pcall(GTA_ShowLoading)
