    -- ===== GTA: fusão de abas duplicadas + remoção de funções duplicadas =====
    do
        local D = {cache = {}, seen = {}}
        D.tabmap = {
            house = "casas", ["car/boat/bike"] = "carro", ["toggle core"] = "carro",
            you = "local player", ["local"] = "local player", teleport = "teleportes",
            fun = "itens", ["música"] = "audio all", skin = "avatar", nomes = "avatar",
            people = "troll players", troll = "troll players", scripts = "scripts universais",
        }
        D.groups = {
            {"anti sit"}, {"spectar player", "spectate player", "view"}, {"auto unban"}, {"telekinesis"},
            {"nome rgb", "rgb name"}, {"rgb bio", "bio rgb"}, {"infinite jump", "pulo infinito"},
            {"gravidade", "gravity"}, {"velocidade do player", "speedwalk"}, {"tamanho do pulo", "jumppower"},
            {"copiar avatar", "copy selected player"}, {"car rgb", "rgb car"},
            {"get all items", "pegar todos os itens"}, {"fling ball all", "fling all by ball"},
            {"shutdown servidor"}, {"radio song id", "enter music id"}, {"play song", "play boombox music"},
        }
        D.gmap = {}
        for gi, g in ipairs(D.groups) do for _, n in ipairs(g) do D.gmap[n] = gi end end
        D.stub = setmetatable({}, {__index = function() return function() end end})
        -- aba "fantasma" pra abas restritas: aceita qualquer chamada (AddToggle, AddSection...) e não cria nada na UI
        D.inert = (function()
            local o = {}
            return setmetatable(o, {__index = function() return function() return o end end, __call = function() return o end})
        end)()
        -- ===== SAVE: lembra toggles/sliders/textos/dropdowns entre execuções (GTAHub_Save.json) =====
        D.sv = {data = {}, auto = true, load = true, cnt = {}, objs = {}, loaded = false, file = "GTAHub_Save.json", pend = false}
        local SV, HS = D.sv, game:GetService("HttpService")
        function SV.read()
            if SV.loaded then return end
            SV.loaded = true
            pcall(function()
                if isfile and readfile and isfile(SV.file) then
                    local t = HS:JSONDecode(readfile(SV.file))
                    if type(t) == "table" then
                        if type(t.data) == "table" then SV.data = t.data end
                        SV.auto = t.auto ~= false
                        SV.load = t.load ~= false
                    end
                end
            end)
        end
        function SV.flush()
            pcall(function()
                if writefile then writefile(SV.file, HS:JSONEncode({auto = SV.auto, load = SV.load, data = SV.data})) end
            end)
        end
        function SV.queue()
            if SV.pend or not SV.auto then return end
            SV.pend = true
            task.delay(1.5, function() SV.pend = false SV.flush() end)
        end
        function SV.clear() SV.data = {} SV.flush() end
        function SV.apply()  -- aplica o save nos controles que já existem
            for key, e in pairs(SV.objs) do
                local v = SV.data[key]
                if v ~= nil then
                    pcall(function()
                        if e.m == "AddSlider" then e.obj:Set(v, true)
                        elseif e.m == "AddDropdown" then if not e.obj.Has or e.obj:Has(v) then e.obj:Set(v) end
                        else e.obj:Set(v) end
                    end)
                end
            end
        end
        rawset(_G, "GTA_SV", SV)
        function D.norm(s)
            s = tostring(s or "")
            s = s:gsub("%b[]", ""):gsub("%b()", ""):gsub("%*.-%*", ""):gsub("「", ""):gsub("」", "")
            s = s:gsub("%p", " "):lower():gsub("%s+", " "):gsub("^ ", ""):gsub(" $", "")
            return s
        end
        function D.tabkey(s)
            s = tostring(s or ""):gsub("「", ""):gsub("」", ""):gsub("%+", ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
            return s
        end
        function D.wrap(tab, tkey)
            for _, m in ipairs({"AddButton", "AddToggle", "AddDropdown", "AddSlider", "AddTextBox"}) do
                local raw = tab[m]
                if raw then
                    tab[m] = function(self, cfg, ...)
                        local nm = type(cfg) == "table" and (cfg[1] or cfg.Name or cfg.Title)
                        if type(nm) == "string" then
                            local g = D.gmap[D.norm(nm)]
                            if g then
                                if D.seen[g] then return D.stub end
                                D.seen[g] = true
                            end
                            if type(cfg.Callback) == "function" then
                                local cb = cfg.Callback
                                cfg.Callback = function(...)
                                    local ok, e = pcall(cb, ...)
                                    if not ok then warn("[GTA Hub] " .. nm .. ": " .. tostring(e)) end
                                end
                            end
                        end
                        if m == "AddDropdown" and type(nm) == "string" and type(cfg.Callback) == "function" then
                            local l0 = D.norm(nm)
                            if l0:find("player", 1, true) or l0:find("jogador", 1, true) or l0:find("alvo", 1, true) then
                                local inner = cfg.Callback
                                cfg.Callback = function(v, ...)
                                    local PL = rawget(_G, "GTA_PL")
                                    if PL and PL.noteSel then pcall(PL.noteSel, v) end
                                    return inner(v, ...)
                                end
                            end
                        end
                        local svkey
                        if (m == "AddToggle" or m == "AddSlider" or m == "AddTextBox" or m == "AddDropdown")
                            and type(nm) == "string" and type(cfg.Callback) == "function"
                            and nm:sub(1, 5) ~= "Save:" and not cfg.MultiSelect then
                            local l = D.norm(nm)
                            local isPl = m == "AddDropdown" and (l:find("player", 1, true) or l:find("jogador", 1, true) or l:find("alvo", 1, true))
                            if not isPl then
                                local SV = D.sv
                                SV.read()
                                local base = tostring(tkey) .. "|" .. m .. "|" .. l
                                SV.cnt[base] = (SV.cnt[base] or 0) + 1
                                svkey = base .. "#" .. SV.cnt[base]
                                local saved = SV.data[svkey]
                                if SV.load and saved ~= nil then
                                    if m == "AddToggle" and type(saved) == "boolean" then
                                        cfg.Default = saved
                                        if cfg[2] ~= nil then cfg[2] = saved end
                                    elseif m == "AddSlider" and type(saved) == "number" then
                                        cfg.Default = saved
                                        if cfg[5] ~= nil then cfg[5] = saved end
                                    elseif m == "AddTextBox" and type(saved) == "string" and saved ~= "" then
                                        cfg.Default = saved
                                        if cfg[2] ~= nil then cfg[2] = saved end
                                    elseif m == "AddDropdown" and type(saved) == "string" then
                                        local opts, found = cfg.Options or cfg[2] or {}, false
                                        for _, ov in pairs(opts) do if ov == saved then found = true end end
                                        if found then
                                            cfg.Default = saved
                                            if cfg[3] ~= nil then cfg[3] = saved end
                                        end
                                    end
                                end
                                local born, inner, key = tick(), cfg.Callback, svkey
                                cfg.Callback = function(v, ...)
                                    local tv = type(v)
                                    if tick() - born > 0.6 and (tv == "boolean" or tv == "number" or tv == "string") then
                                        SV.data[key] = v
                                        SV.queue()
                                    end
                                    return inner(v, ...)
                                end
                            end
                        end
                        local obj = raw(self, cfg, ...)
                        if svkey then D.sv.objs[svkey] = {m = m, obj = obj} end
                        if m == "AddDropdown" and type(nm) == "string" then
                            local l = D.norm(nm)
                            if l:find("player", 1, true) or l:find("jogador", 1, true) or l:find("alvo", 1, true) then
                                local PL = rawget(_G, "GTA_PL")
                                if PL and PL.register then pcall(PL.register, obj) end
                            end
                        end
                        return obj
                    end
                end
            end
        end
        function Window:MakeTab(paste, Configs)
            local cfg = (type(paste) == "table" and paste) or Configs
            local key = D.tabkey(cfg and (cfg[1] or cfg.Title or cfg.Name))
            key = D.tabmap[key] or key
            if (key == "rgb" or key:sub(1, 5) == "prote") then  -- abas restritas: sem cargo, a aba nem é criada
                local canUse = _G.GTA_CanUseRestricted
                if not (canUse and canUse()) then return D.inert end
            end
            if D.cache[key] then return D.cache[key] end
            local t = Window:MakeTabRaw(paste, Configs)
            D.wrap(t, key)
            D.cache[key] = t
            return t
        end
    end

    CloseButton.Activated:Connect(Window.CloseBtn)
    MinimizeButton.Activated:Connect(Window.MinimizeBtn)
    return Window
end

end -- fim do escopo da redzlib (reduz locais da funcao principal)
local UserInputService = game:GetService("UserInputService")
local CoreGui = game:GetService("CoreGui")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local Hub = {Toggles = {}, Sliders = {}}
-- ================================================================
-- WRAPPER DE UI (compatível com as chamadas existentes no script)
-- ================================================================
local UI = {}
local MainGui
local ActiveWindow

local function resolveMainGui()
    local gui = CoreGui:FindFirstChild("GTA Hub V5")
        or CoreGui:FindFirstChild("GTA Hub")
        or CoreGui:FindFirstChild("Hub")
        or CoreGui:FindFirstChildWhichIsA("ScreenGui")
    MainGui = gui
    Hub.MainGui = gui
    Hub.Container = gui
    return gui
end

local function getTabContainer(tab)
    return tab and (tab.Cont or tab.Container or tab.Frame or tab)
end

function UI:CreateWindow(options)
    options = options or {}
    local title = options.Name or options.Title or "GTA Hub"
    local subtitle = options.SubTitle or options.Subtitle or options.MiniText or ""
    ActiveWindow = redzlib:MakeWindow({
        Name = title,
        SubTitle = subtitle,
        SaveFolder = false
    })
    task.wait()
    resolveMainGui()
    Hub.UI = UI
    return self
end

Hub.TabNames = setmetatable({}, {__mode = "k"})
Hub.Ctl = {}      -- lista ordenada de controles salvos pela aba CONFIG
Hub.CtlIndex = {}
local CTL_SKIP = {["GRÁFICOS+"] = true, ["CONFIG"] = true} -- gráficos têm arquivo próprio; todo o resto é salvo
local function registerCtl(tab, name, kind, default)
    local tn = Hub.TabNames[tab]
    if not tn or CTL_SKIP[tn] then return nil end
    local key = tn .. "|" .. name
    local rec = Hub.CtlIndex[key]
    if rec then rec.default = default; return rec end
    rec = {key = key, tab = tn, name = name, kind = kind, default = default, value = default}
    Hub.Ctl[#Hub.Ctl + 1] = rec
    Hub.CtlIndex[key] = rec
    return rec
end
local function ctlChanged(rec, v)
    if not rec then return end
    rec.value = v
    if Hub.CfgReady and not Hub.CfgRestoring then
        rec.touched = true
        if Hub.CfgChanged then Hub.CfgChanged(rec) end
    end
end

function UI:AddTab(name, icon)
    if not ActiveWindow then return nil end
    local tab = ActiveWindow:MakeTab({Title = name, Icon = icon})
    Hub.TabNames[tab] = name
    return tab
end

function UI:AddToggle(tab, name, default, callback)
    local t = getTabContainer(tab)
    if not t then return nil end
    Hub.Toggles[name] = Hub.Toggles[name] or {}
    Hub.Toggles[name].Value = default and true or false
    local rec = registerCtl(tab, name, "toggle", default and true or false)

    local function onChange(v)
        Hub.Toggles[name].Value = v and true or false
        ctlChanged(rec, v and true or false)
        if callback then
            callback(v and true or false)
        end
        if Hub.QueueToggleNotice then Hub:QueueToggleNotice(name, v and true or false) end
    end

    local obj = tab:AddToggle({
        Name = name,
        Default = default and true or false,
        Callback = onChange
    })

    Hub.Toggles[name].Set = function(v)
        if obj and obj.Set then
            obj:Set(v and true or false)
        else
            onChange(v and true or false)
        end
    end
    if rec then rec.set = function(v) if obj and obj.Set then obj:Set(v and true or false) else onChange(v and true or false) end end end
    return obj
end

function UI:AddSlider(tab, name, options, callback)
    local t = getTabContainer(tab)
    if not t then return nil end
    options = options or {}
    local min = tonumber(options.Min) or tonumber(options.MinValue) or 0
    local max = tonumber(options.Max) or tonumber(options.MaxValue) or 100
    local default = tonumber(options.Default) or min
    local increase = tonumber(options.Increase) or 1

    Hub.Sliders[name] = Hub.Sliders[name] or {}
    Hub.Sliders[name].Value = default
    local rec = registerCtl(tab, name, "slider", default)
    if rec then rec.min = min; rec.max = max end

    local function onChange(v)
        local num = tonumber(v)
        if num == nil then return end
        Hub.Sliders[name].Value = num
        ctlChanged(rec, num)
        if callback then
            callback(num)
        end
    end

    local obj = tab:AddSlider({
        Name = name,
        MinValue = min,
        MaxValue = max,
        Increase = increase,
        Default = default,
        Callback = onChange
    })

    Hub.Sliders[name].Set = function(v, instant)
        local num = tonumber(v)
        if num == nil then return end
        if obj and obj.Set then
            obj:Set(num, instant and true or nil)
        else
            onChange(num)
        end
    end
    if rec then rec.set = function(v) if obj and obj.Set then obj:Set(tonumber(v), true) end end end
    return obj
end

function UI:AddButton(tab, name, callback)
    if not getTabContainer(tab) then return nil end
    return tab:AddButton({
        Name = name,
        Callback = callback
    })
end

function UI:AddDropdown(tab, name, items, default, callback)
    if not getTabContainer(tab) then return nil end
    local rec = registerCtl(tab, name, "dropdown", default)
    local obj = tab:AddDropdown({
        Name = name,
        Options = items or {},
        Default = default,
        Callback = function(v, ...)
            if type(v) == "string" then ctlChanged(rec, v) end
            if callback then return callback(v, ...) end
        end
    })
    if rec then
        rec.options = items
        rec.set = function(v)
            if obj and obj.Select then obj:Select(v) end
        end
    end
    return obj
end

function UI:AddTextbox(tab, name, default, callback)
    local container = getTabContainer(tab)
    if not container then return nil end
    local rec = registerCtl(tab, name, "textbox", tonumber(default) or default)

    local frame = Instance.new("Frame")
    frame.Size = UDim2.new(1, -6, 0, 36)
    frame.BackgroundColor3 = Color3.fromRGB(24, 24, 30)
    frame.BackgroundTransparency = 0.12
    frame.BorderSizePixel = 0
    frame.Parent = container
    Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 7)

    local label = Instance.new("TextLabel")
    label.Size = UDim2.new(0, 110, 1, 0)
    label.Position = UDim2.new(0, 8, 0, 0)
    label.BackgroundTransparency = 1
    label.Text = name
    label.TextColor3 = Color3.new(1, 1, 1)
    label.Font = Enum.Font.Gotham
    label.TextSize = 12
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.Parent = frame

    local box = Instance.new("TextBox")
    box.Size = UDim2.new(0, 90, 0, 24)
    box.Position = UDim2.new(1, -98, 0.5, -12)
    box.BackgroundColor3 = Color3.fromRGB(45, 45, 54)
    box.TextColor3 = Color3.new(1, 1, 1)
    box.Font = Enum.Font.Gotham
    box.TextSize = 11
    box.ClearTextOnFocus = false
    box.Text = tostring(default or "")
    box.Parent = frame
    Instance.new("UICorner", box).CornerRadius = UDim.new(0, 5)

    Hub.Sliders[name] = Hub.Sliders[name] or {}
    local currentValue = tonumber(default) or default

    local function apply(val)
        local num = tonumber(val)
        if num == nil then
            box.Text = tostring(currentValue or default or "")
            return
        end
        currentValue = num
        box.Text = tostring(num)
        Hub.Sliders[name].Value = num
        ctlChanged(rec, num)
        if callback then
            callback(num)
        end
    end

    box.FocusLost:Connect(function()
        apply(box.Text)
    end)

    Hub.Sliders[name].Value = currentValue
    Hub.Sliders[name].Set = function(v)
        apply(v)
    end
    if rec then rec.set = function(v) apply(v) end end

    return frame
end

function UI:AddTextInput(tab, name, default, callback)
    local container = getTabContainer(tab)
    if not container then return nil end
    local rec = registerCtl(tab, name, "text", tostring(default or ""))
    local frame = Instance.new("Frame")
    frame.Size = UDim2.new(1, -6, 0, 36)
    frame.BackgroundColor3 = Color3.fromRGB(24, 24, 30)
    frame.BackgroundTransparency = 0.12
    frame.BorderSizePixel = 0
    frame.Parent = container
    Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 7)
    local label = Instance.new("TextLabel")
    label.Size = UDim2.new(0, 110, 1, 0)
    label.Position = UDim2.new(0, 8, 0, 0)
    label.BackgroundTransparency = 1
    label.Text = name
    label.TextColor3 = Color3.new(1, 1, 1)
    label.Font = Enum.Font.Gotham
    label.TextSize = 12
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.Parent = frame
    local box = Instance.new("TextBox")
    box.Size = UDim2.new(1, -130, 0, 24)
    box.Position = UDim2.new(0, 120, 0.5, -12)
    box.BackgroundColor3 = Color3.fromRGB(45, 45, 54)
    box.TextColor3 = Color3.new(1, 1, 1)
    box.PlaceholderText = "digite aqui"
    box.Font = Enum.Font.Gotham
    box.TextSize = 11
    box.ClearTextOnFocus = false
    box.Text = tostring(default or "")
    box.Parent = frame
    Instance.new("UICorner", box).CornerRadius = UDim.new(0, 5)
    box:GetPropertyChangedSignal("Text"):Connect(function()
        ctlChanged(rec, box.Text)
        if callback then callback(box.Text) end
    end)
    box.FocusLost:Connect(function()
        if callback then callback(box.Text) end
    end)
    local api = {Frame = frame, Box = box}
    function api:Set(v) box.Text = tostring(v or ""); ctlChanged(rec, box.Text); if callback then callback(box.Text) end end
    if rec then rec.set = function(v) api:Set(v) end end
    function api:Get() return box.Text end
    return api
end

function UI:AddSection(tab, name)
    if not getTabContainer(tab) then return nil end
    if tab.AddSection then
        return tab:AddSection(name)
