function UI:Notify(title, text, dur)
    if ActiveWindow and ActiveWindow.MakeNotify then
        return ActiveWindow:MakeNotify({
            Title = title,
            Text = text,
            Time = dur or 3
        })
    end
    warn(("[%s] %s"):format(tostring(title), tostring(text)))
end

-- Mensagens ao ligar/desligar (agrupa várias mudanças em uma única mensagem)
Hub.NotifyToggles = true
Hub.NoticeReady = false
Hub.QuietToggles = {ESP = true, ["Comparar com visual original"] = true}
local noticeQueue, noticeScheduled = {}, false
function Hub:QueueToggleNotice(name, enabled)
    if not Hub.NoticeReady or not Hub.NotifyToggles or (Hub.Bulk or 0) > 0 or Hub.QuietToggles[name] then return end
    noticeQueue[#noticeQueue + 1] = {name, enabled}
    if noticeScheduled then return end
    noticeScheduled = true
    task.delay(0.3, function()
        noticeScheduled = false
        local queue = noticeQueue
        noticeQueue = {}
        if #queue == 1 then
            UI:Notify(queue[1][1], queue[1][2] and "Ativado ✅" or "Desativado ⛔", 1.8)
        elseif #queue > 1 then
            UI:Notify("Sistema", #queue .. " ajustes alterados.", 2)
        end
    end)
end

-- ================================================================
-- GTA HUB | BROOKHAVEN RP  (conteúdo do script + UI GTA)
-- ================================================================
local Libary = redzlib
local GTA_PL = {list = {}}
do
    local Plrs = game:GetService("Players")
    -- cargos: {["nome"] = {TAG = true, ...}}. Pré-carregado antes da key (ver topo do script); dono sempre entra, mesmo offline.
    GTA_PL.roles = _G.GTA_ROLES_PRELOAD or {}
    GTA_PL.roles["gtasa244adm21"] = GTA_PL.roles["gtasa244adm21"] or {}
    GTA_PL.roles["gtasa244adm21"].D = true
    local ROLE_BY_ID, ROLE_ORDER = {}, {}
    for i, r in ipairs(_G.GTA_ROLE_DEFS or {}) do ROLE_BY_ID[r.id] = r; ROLE_ORDER[r.id] = i end
    function GTA_PL.tagsOf(p)
        local n = typeof(p) == "Instance" and p.Name or tostring(p or "")
        local byId = typeof(p) == "Instance" and p:IsA("Player") and GTA_PL.roles[tostring(p.UserId)] or nil
        return GTA_PL.roles[n:lower()] or byId or {}
    end
    function GTA_PL.hasRole(p, tag) return GTA_PL.tagsOf(p)[tag] == true end
    function GTA_PL.rolesOf(p)  -- lista ordenada pelo catálogo, do cargo mais alto pro mais baixo
        local out = {}
        for tag in pairs(GTA_PL.tagsOf(p)) do out[#out + 1] = tag end
        table.sort(out, function(a, b) return (ROLE_ORDER[a] or 999) < (ROLE_ORDER[b] or 999) end)
        return out
    end
    function GTA_PL.roleOf(p)  -- compat: só o cargo mais alto
        local r = GTA_PL.rolesOf(p)
        return r[1]
    end
    function GTA_PL.isImmune(p) for tag in pairs(GTA_PL.tagsOf(p)) do if ROLE_BY_ID[tag] and ROLE_BY_ID[tag].immune then return true end end return false end
    -- ===== PROTECAO EM CAMADAS (quem pode mirar em quem) =====
    -- Dono [D] e Desenvolvedor [DEV]: somem de TODO seletor e ninguém mira neles.
    -- Admin (CO, ADM, SADM): some para jogador normal; D/DEV podem mirar em admin.
    -- Para liberar admin x admin: GTA_PL.ADMIN_CAN_TARGET_ADMIN = true
    -- Tentou mesmo assim (clicou, escolheu, digitou o nome completo): kick no PROPRIO client de quem tentou.
    GTA_PL.ADMIN_CAN_TARGET_ADMIN = false
    GTA_PL.KICK_REASON = "Tentou matar um admin"
    function GTA_PL.isOwner(p) return GTA_PL.isImmune(p) end
    _G.GTA_PL_TOAST = function(...) if GTA_PL.toast then return GTA_PL.toast(...) end end
    function GTA_PL.isAdmin(p)
        for tag in pairs(GTA_PL.tagsOf(p)) do if ROLE_BY_ID[tag] and ROLE_BY_ID[tag].admin then return true end end
        return false
    end
    function GTA_PL.canTarget(viewer, target)
        if typeof(target) ~= "Instance" then return true end
        if viewer == target then return true end
        if GTA_PL.isOwner(target) then return false end
        if GTA_PL.isAdmin(target) then
            if GTA_PL.isOwner(viewer) then return true end
            return GTA_PL.ADMIN_CAN_TARGET_ADMIN == true and GTA_PL.isAdmin(viewer)
        end
        return true
    end
    function GTA_PL.canHit(p) return GTA_PL.canTarget(Plrs.LocalPlayer, p) end
    function GTA_PL.filter(list)
        local out = {}
        for _, p in ipairs(list) do if GTA_PL.canHit(p) then out[#out + 1] = p end end
        return out
    end
    function GTA_PL.punishSelf(reason)  -- so afeta o PROPRIO client de quem tentou: nunca mexe na sessao de outro player
        if GTA_PL._punished then return end
        GTA_PL._punished = true
        _G.GTA_KEY_OK = false
        pcall(function() if GTA_PL.toast then GTA_PL.toast(GTA_PL.KICK_REASON .. " (" .. tostring(reason) .. ")", Color3.fromRGB(255, 40, 40)) end end)
        task.spawn(function()
            task.wait(1.2)
            local lp = Plrs.LocalPlayer
            pcall(function() lp:Kick(GTA_PL.KICK_REASON) end)
            task.wait(3)
            if lp.Parent then  -- Kick bloqueado pelo executor: sai do servidor
                local ok = pcall(function() game:GetService("TeleportService"):Teleport(game.PlaceId, lp) end)
                if not ok then pcall(function() game:Shutdown() end) end
            end
        end)
    end
    function GTA_PL.violation(target, how)
        local lp = Plrs.LocalPlayer
        if GTA_PL.isAdmin(lp) and not GTA_PL.isOwner(target) then  -- admin x admin: so bloqueia
            pcall(function() if GTA_PL.toast then GTA_PL.toast("admin nao pode mirar em outro admin", Color3.fromRGB(220, 80, 80)) end end)
            return
        end
        GTA_PL.punishSelf(how or "mirou em protegido")
    end
    function GTA_PL.guardPlayer(p)  -- true = pode seguir; false = bloqueado (e kick se for caso)
        if typeof(p) ~= "Instance" or not p:IsA("Player") then return true end
        if GTA_PL.canHit(p) then return true end
        GTA_PL.violation(p, "tentou mirar em " .. p.Name)
        return false
    end
    function GTA_PL.guardName(n)
        if type(n) ~= "string" or n == "" then return true end
        return GTA_PL.guardPlayer(Plrs:FindFirstChild(n))
    end
    function GTA_PL.checkTyped(q)  -- digitou o nome COMPLETO (nick ou display) de um protegido
        q = tostring(q or ""):lower()
        if q == "" then return end
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p ~= Plrs.LocalPlayer and not GTA_PL.canHit(p) and (p.Name:lower() == q or p.DisplayName:lower() == q) then
                GTA_PL.violation(p, "digitou o nome de " .. p.Name)
                return
            end
        end
    end
    function GTA_PL.names(includeSelf, leaving)
        local t = {}
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p ~= leaving and (includeSelf or p ~= Plrs.LocalPlayer) and (p == Plrs.LocalPlayer or GTA_PL.canHit(p)) then t[#t + 1] = p.Name end
        end
        table.sort(t)
        return t
    end
    GTA_PL.sel = {}
    function GTA_PL.register(dd, includeSelf)  -- todo seletor de player: atualiza sozinho + entra na seleção global
        if not (dd and dd.Refresh) then return end
        for _, e in ipairs(GTA_PL.list) do if e.dd == dd then return end end
        GTA_PL.list[#GTA_PL.list + 1] = {dd = dd, self = includeSelf or false}
        GTA_PL.sel[#GTA_PL.sel + 1] = dd
        pcall(dd.Refresh, dd, GTA_PL.names(includeSelf or false))
    end
    function GTA_PL.track(dd, includeSelf)  -- registra um dropdown de players pra atualizar sozinho
        if dd and dd.Refresh then
            local known = false
            for _, e in ipairs(GTA_PL.list) do if e.dd == dd then known = true end end
            if not known then
                GTA_PL.list[#GTA_PL.list + 1] = {dd = dd, self = includeSelf}
                GTA_PL.sel[#GTA_PL.sel + 1] = dd
                pcall(dd.Refresh, dd, GTA_PL.names(includeSelf or false))
            end
        end
    end
    function GTA_PL.selectAll(name)  -- escolhe o player em TODOS os seletores que têm ele na lista
        local n = 0
        for _, dd in ipairs(GTA_PL.sel) do
            if dd.Has and dd:Has(name) and pcall(dd.Set, dd, name) then n = n + 1 end
        end
        return n
    end
    function GTA_PL.find(q)  -- nome rápido: parte do nick ou do display name
        q = tostring(q or ""):lower()
        if q == "" then return nil end
        GTA_PL.checkTyped(q)
        local best
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p ~= Plrs.LocalPlayer and GTA_PL.canHit(p) then
                local a, b = p.Name:lower(), p.DisplayName:lower()
                if a == q or b == q then return p.Name end
                if not best and (a:find(q, 1, true) or b:find(q, 1, true)) then best = p.Name end
            end
        end
        return best
    end
    local function note(m) pcall(function() redzlib:MakeNotify({Title = "GTA Hub", Text = m, Time = 2}) end) end
    function GTA_PL.pick(name)
        if not name then note("Player não encontrado") return end
        local p = Plrs:FindFirstChild(name)
        if p and not GTA_PL.canHit(p) then
            GTA_PL.violation(p, "tentou selecionar " .. name)
            return
        end
        GTA_PL.selectAll(name)
        note("Selecionado: " .. ((_G.GTA_PLabel and _G.GTA_PLabel(name)) or tostring(name)))
    end
    local TOOL = "Select Player (GTA)"
    function GTA_PL.giveSelectTool()
        local lp = Plrs.LocalPlayer
        local bp = lp:FindFirstChildOfClass("Backpack")
        if not bp or bp:FindFirstChild(TOOL) or (lp.Character and lp.Character:FindFirstChild(TOOL)) then return end
        local tool = Instance.new("Tool")
        tool.Name, tool.RequiresHandle, tool.CanBeDropped, tool.ToolTip = TOOL, false, false, "clique num player pra selecionar"
        tool.Activated:Connect(function()
            local node, plr = lp:GetMouse().Target, nil
            while node and node ~= workspace do
                plr = Plrs:GetPlayerFromCharacter(node)
                if plr then break end
                node = node.Parent
            end
            if plr and plr ~= lp then GTA_PL.pick(plr.Name) end
        end)
        tool.Parent = bp
    end
    function GTA_PL.setSelectTool(on)
        GTA_PL.toolOn = on
        local lp = Plrs.LocalPlayer
        if on then
            GTA_PL.giveSelectTool()
        else
            for _, c in ipairs({lp:FindFirstChildOfClass("Backpack"), lp.Character}) do
                local t = c and c:FindFirstChild(TOOL)
                if t then t:Destroy() end
            end
        end
    end
    Plrs.LocalPlayer.CharacterAdded:Connect(function()
        if GTA_PL.toolOn then task.wait(1) GTA_PL.giveSelectTool() end
    end)
    function GTA_PL.refreshAll(leaving)
        for _, e in ipairs(GTA_PL.list) do pcall(e.dd.Refresh, e.dd, GTA_PL.names(e.self, leaving)) end
    end
    Plrs.PlayerAdded:Connect(function() GTA_PL.refreshAll() end)
    Plrs.PlayerRemoving:Connect(function(p) GTA_PL.refreshAll(p) end)
    task.spawn(function() while task.wait(5) do GTA_PL.refreshAll() end end)  -- reconciliação de segurança
end
rawset(_G, "GTA_PL", GTA_PL)

-- ================================================================
-- GTA ROLES: Dev [D] / Colaborador [C] (lista lida do GitHub do GTA) + nome/bio automáticos
-- ================================================================
do
    local Plrs = game:GetService("Players")
    local lp = Plrs.LocalPlayer
    local kRolesUrl = "https://raw.githubusercontent.com/gta244adm/Gta-hub-pro/refs/heads/main/GTA%20HUB%20C%20e%20DV"
    local LABEL = {}
    for _, r in ipairs(_G.GTA_ROLE_DEFS or {}) do LABEL[r.id] = r.label end
    GTA_PL.cfg = GTA_PL.cfg or {}
    GTA_PL.identityOn = true
    local function reFindRP(clean)
        local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
        if RE then for _, c in ipairs(RE:GetChildren()) do if (c.Name:gsub("%d", "")) == clean then return c end end end
    end
    function GTA_PL.myRole() return GTA_PL.roleOf(lp) end
    function GTA_PL.identity()
        local tags = GTA_PL.rolesOf(lp)
        local top = tags[1]
        local name = "[GTA HUB]" .. (top and (" [" .. top .. "]") or "")
        local bio = (top == "D") and "[DONO DO SCRIPT]" or (top and ("[" .. (LABEL[top] or top):upper() .. "]")) or "[USUÁRIO]"
        return name, bio
    end
    function GTA_PL.applyIdentity()
        local r = reFindRP("RPNameText")
        if not r then return false end
        local name, bio = GTA_PL.identity()
        pcall(function() r:FireServer("RolePlayName", name) end)
        task.wait(0.3)
        pcall(function() r:FireServer("RolePlayBio", bio) end)
        return true
    end
    local function refreshRoles(body)
        if type(body) == "string" then
            local fresh = _G.GTA_MergeLocalRoles(_G.GTA_ParseRoles(body))
            fresh["gtasa244adm21"] = fresh["gtasa244adm21"] or {}
            fresh["gtasa244adm21"].D = true
            GTA_PL.roles = fresh
            local mine = fresh[lp.Name:lower()] or fresh[tostring(lp.UserId)]
            if mine then _G.GTA_MY_ROLES = mine end
        end
        GTA_PL.rolesLoaded = true
        pcall(function() if GTA_PL.refreshAll then GTA_PL.refreshAll() end end)
    end
    task.spawn(function()
        if not GTA_PL.rolesLoaded then refreshRoles(game and nil) end  -- já veio do preload; só marca carregado
        GTA_PL.rolesLoaded = true
        task.wait(1)
        if GTA_PL.identityOn then GTA_PL.applyIdentity() end
        local role = GTA_PL.myRole()
        if role and GTA_PL.toast then
            GTA_PL.toast("GTA HUB: " .. (LABEL[role] or role) .. " [" .. role .. "]", Color3.fromRGB(255, 210, 0))
        elseif GTA_PL.toast then
            GTA_PL.toast("GTA HUB: nenhum cargo achado. " .. tostring(_G.GTA_ROLES_DIAG), Color3.fromRGB(255, 80, 80))
        end
        while task.wait(180) do  -- recarrega os cargos de tempos em tempos (cargo novo/removido durante o jogo)
            local body
            pcall(function() body = game:HttpGet(kRolesUrl .. "?t=" .. math.floor(os.time())) end)
            if body then refreshRoles(body) end
        end
    end)
end
do
    local Plrs = game:GetService("Players")
    local TS = game:GetService("TweenService")
    GTA_PL.cfg = {notify = false, remember = false}
    GTA_PL.lastSel, GTA_PL.lost = nil, nil

    -- ===== O QUE TAVA LIGADO NO ALVO: religa sozinho quando o alvo lembrado volta =====
    -- Cada função em cima de um alvo se anota aqui quando VOCÊ liga (markUse) e se apaga quando VOCÊ desliga (unmarkUse).
    -- Parada automática (alvo saiu, terminou) NÃO apaga a anotação: é isso que permite religar no retorno.
    GTA_PL.uses = {}
    function GTA_PL.markUse(key, plr, start)
        if type(key) ~= "string" or typeof(plr) ~= "Instance" or type(start) ~= "function" then return end
        GTA_PL.uses[key] = {name = plr.Name, id = plr.UserId, start = start}
    end
    function GTA_PL.unmarkUse(key) GTA_PL.uses[key] = nil end
    function GTA_PL.clearUses() GTA_PL.uses = {} end
    function GTA_PL.retargetUses(plr)  -- as funções seguem o alvo atual: trocou de alvo, a anotação troca junto
        for _, u in pairs(GTA_PL.uses) do u.name, u.id = plr.Name, plr.UserId end
    end
    function GTA_PL.resumeUses(p)  -- liga de novo tudo que estava ligado no player p (usa os mesmos start da UI, então passa pelo guardPlayer)
        local list = {}
        for key, u in pairs(GTA_PL.uses) do
            if u.id == p.UserId or u.name == p.Name then list[#list + 1] = {key = key, start = u.start} end
        end
        if #list == 0 then return 0 end
        pcall(function() if GTA_PL.PS and GTA_PL.PS.setTarget then GTA_PL.PS.setTarget(p) end end)
        task.spawn(function()
            for _, u in ipairs(list) do
                if p.Parent and GTA_PL.uses[u.key] then
                    local ok, e = pcall(u.start)
                    if not ok then warn("[GTA Hub] religar " .. u.key .. ": " .. tostring(e)) end
                    task.wait(0.4)
                end
            end
        end)
        return #list
    end

    function GTA_PL.noteSel(v)  -- chamado por todo seletor de player quando você escolhe alguém
        if type(v) ~= "string" or v == "" then return end
        if GTA_PL.lost and GTA_PL.lost.name ~= v then GTA_PL.lost = nil end  -- trocou de alvo: esquece o que saiu
        local p = Plrs:FindFirstChild(v)
        GTA_PL.lastSel = {name = v, id = p and p.UserId or nil}
    end

    -- aviso próprio (ScreenGui separada): aparece mesmo com a UI do hub fechada
    local gui, box
    function GTA_PL.toast(text, color)
        pcall(function()
            if not gui or not gui.Parent then
                gui = Instance.new("ScreenGui")
                gui.Name, gui.ResetOnSpawn, gui.DisplayOrder, gui.IgnoreGuiInset = "GTA_Toasts", false, 2147483000, true
                local okp, par = pcall(function() return gethui() end)
                if not okp or not par then par = game:GetService("CoreGui") end
                if not pcall(function() gui.Parent = par end) or not gui.Parent then
                    gui.Parent = Plrs.LocalPlayer:WaitForChild("PlayerGui")
                end
                box = Instance.new("Frame")
                box.BackgroundTransparency = 1
                box.AnchorPoint, box.Position, box.Size = Vector2.new(1, 0), UDim2.new(1, -10, 0, 10), UDim2.new(0, 290, 1, -20)
                box.Parent = gui
                local lay = Instance.new("UIListLayout")
                lay.Padding, lay.HorizontalAlignment = UDim.new(0, 6), Enum.HorizontalAlignment.Right
                lay.Parent = box
            end
            local fr = Instance.new("Frame")
            fr.Size, fr.BackgroundColor3, fr.BackgroundTransparency = UDim2.new(0, 280, 0, 34), Color3.fromRGB(20, 20, 26), 0.1
            local c = Instance.new("UICorner") c.CornerRadius = UDim.new(0, 8) c.Parent = fr
            local st = Instance.new("UIStroke") st.Color, st.Thickness = color or Color3.fromRGB(180, 180, 200), 1.2 st.Parent = fr
            local tl = Instance.new("TextLabel")
            tl.BackgroundTransparency, tl.Size, tl.Position = 1, UDim2.new(1, -16, 1, 0), UDim2.new(0, 8, 0, 0)
            tl.Font, tl.TextSize, tl.TextColor3, tl.TextWrapped = Enum.Font.GothamMedium, 12, Color3.fromRGB(240, 240, 245), true
            tl.TextXAlignment, tl.Text = Enum.TextXAlignment.Left, text
            tl.Parent = fr
            fr.Parent = box
            task.delay(4, function()
                pcall(function()
                    TS:Create(fr, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
                    TS:Create(tl, TweenInfo.new(0.3), {TextTransparency = 1}):Play()
                    TS:Create(st, TweenInfo.new(0.3), {Transparency = 1}):Play()
                end)
                task.wait(0.35)
                pcall(function() fr:Destroy() end)
            end)
        end)
    end

    local GREEN, RED, YEL = Color3.fromRGB(90, 220, 120), Color3.fromRGB(235, 80, 90), Color3.fromRGB(255, 200, 70)
    Plrs.PlayerAdded:Connect(function(p)
        if GTA_PL.cfg.notify then GTA_PL.toast("+ " .. p.DisplayName .. " (@" .. p.Name .. ") entrou", GREEN) end
        local L = GTA_PL.lost
        if GTA_PL.cfg.remember and L and (p.UserId == L.id or p.Name == L.name) then
            GTA_PL.lost = nil
            task.delay(1.5, function()  -- espera os dropdowns atualizarem a lista
                pcall(GTA_PL.refreshAll)
                GTA_PL.selectAll(p.Name)
                GTA_PL.lastSel = {name = p.Name, id = p.UserId}
                GTA_PL.toast("Alvo " .. p.Name .. " voltou: selecionado de novo", YEL)
                local nBack = 0
                pcall(function() nBack = GTA_PL.resumeUses(p) or 0 end)
                if nBack > 0 then GTA_PL.toast("Religando " .. nBack .. " função(ões) no " .. p.Name, GREEN) end
            end)
        end
    end)
    Plrs.PlayerRemoving:Connect(function(p)
        if GTA_PL.cfg.notify then GTA_PL.toast("- " .. p.DisplayName .. " (@" .. p.Name .. ") saiu", RED) end
        local S = GTA_PL.lastSel
        if GTA_PL.cfg.remember and S and S.name == p.Name then
            GTA_PL.lost = {name = p.Name, id = p.UserId}
            GTA_PL.toast("Alvo " .. p.Name .. " saiu: lembrando dele", YEL)
        end
    end)
end
function redzlib:MakeNotification(c)  -- compat com chamadas antigas (Name/Content/Time)
    c = c or {}
    return redzlib:MakeNotify({Title = c.Name or c.Title or "GTA Hub", Text = c.Content or c.Text or "", Time = c.Time or 5})
end

-- ================================================================
-- FREE CAM (nativa, substitui o blob ofuscado do link)
-- ================================================================
local GTA_FreeCam = {on = false, speed = 40}
do
    local UIS = game:GetService("UserInputService")
    local RS = game:GetService("RunService")
    local CAS = game:GetService("ContextActionService")
    local LP = game:GetService("Players").LocalPlayer
    local conn, saved, pitch, yaw, pos
    local KEYS = {Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D, Enum.KeyCode.Q, Enum.KeyCode.E, Enum.KeyCode.Space, Enum.KeyCode.LeftShift}
    local function hrp() return LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") end
    function GTA_FreeCam.set(on)
        on = on and true or false
        if on == GTA_FreeCam.on then return end
        local cam = workspace.CurrentCamera
        if on then
            GTA_FreeCam.on = true
            saved = {type = cam.CameraType, subject = cam.CameraSubject, anchored = hrp() and hrp().Anchored or false}
            local rx, ry = cam.CFrame:ToOrientation()
            pitch, yaw, pos = math.deg(rx), math.deg(ry), cam.CFrame.Position
            if hrp() then hrp().Anchored = true end
            pcall(function()
                CAS:BindActionAtPriority("GTAFreeCamSink", function() return Enum.ContextActionResult.Sink end, false, Enum.ContextActionPriority.High.Value + 1, unpack(KEYS))
            end)
            conn = RS.RenderStepped:Connect(function(dt)
                cam = workspace.CurrentCamera
                cam.CameraType = Enum.CameraType.Scriptable
                local rmb = UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
                UIS.MouseBehavior = rmb and Enum.MouseBehavior.LockCurrentPosition or Enum.MouseBehavior.Default
                if rmb then
                    local d = UIS:GetMouseDelta()
                    yaw = yaw - d.X * 0.25
                    pitch = math.clamp(pitch - d.Y * 0.25, -89, 89)
                end
                local rot = CFrame.Angles(0, math.rad(yaw), 0) * CFrame.Angles(math.rad(pitch), 0, 0)
                local mv = Vector3.new(0, 0, 0)
                if UIS:IsKeyDown(Enum.KeyCode.W) then mv = mv + Vector3.new(0, 0, -1) end
                if UIS:IsKeyDown(Enum.KeyCode.S) then mv = mv + Vector3.new(0, 0, 1) end
                if UIS:IsKeyDown(Enum.KeyCode.A) then mv = mv + Vector3.new(-1, 0, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.D) then mv = mv + Vector3.new(1, 0, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.E) or UIS:IsKeyDown(Enum.KeyCode.Space) then mv = mv + Vector3.new(0, 1, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.Q) then mv = mv + Vector3.new(0, -1, 0) end
                local sp = GTA_FreeCam.speed * (UIS:IsKeyDown(Enum.KeyCode.LeftShift) and 3 or 1)
                pos = pos + (rot * mv) * sp * dt
                cam.CFrame = CFrame.new(pos) * rot
            end)
        else
            GTA_FreeCam.on = false
            if conn then conn:Disconnect(); conn = nil end
            pcall(function() CAS:UnbindAction("GTAFreeCamSink") end)
            UIS.MouseBehavior = Enum.MouseBehavior.Default
            if saved then
                cam.CameraType = saved.type or Enum.CameraType.Custom
                if saved.subject then cam.CameraSubject = saved.subject end
                if hrp() then hrp().Anchored = saved.anchored end
            end
        end
    end
end

-- ================================================================
-- CAMADA DE COMPAT: API do pacote XY (Orion-like) -> UI GTA
-- ================================================================
local GTA_XY = {}
do
    local function clean(s)
        s = tostring(s or "")
        s = s:gsub("「", ""):gsub("」", "")
        return (s:gsub("^%s+", ""):gsub("%s+$", ""))
    end
    local function copy(c)
        local n = {}
        for k, v in pairs(c or {}) do n[k] = v end
        return n
    end
    local ICONS = {Carnival = "🎡", You = "🧍", Fun = "🎉", House = "🏠", ["Car/Boat/Bike"] = "🚗", Teleport = "🌀", ["Toggle Core"] = "⚙", People = "👥", ESP = "👁", Skin = "🎭", Troll = "😈"}
    local function wrapTab(tab)
        local P = {}
        function P:AddSection(c)
            return tab:AddSection({Name = clean(type(c) == "table" and (c.Name or c[1]) or c)})
        end
        function P:AddParagraph(a, b)
            if type(a) == "table" then
                return tab:AddParagraph({clean(a.Title or a.Name or a[1]), tostring(a.Content or a.Text or a[2] or "")})
            end
            return tab:AddParagraph({clean(a), tostring(b or "")})
        end
        function P:AddLabel(a)
            return tab:AddParagraph({clean(type(a) == "table" and (a.Name or a[1]) or a), ""})
        end
        function P:AddButton(c)
            local n = copy(c); n.Name = clean(n.Name or n[1])
            return tab:AddButton(n)
        end
        function P:AddToggle(c)
            local n = copy(c); n.Name = clean(n.Name or n[1]); n.Default = (c.Default == true)
            return tab:AddToggle(n)
        end
        function P:AddDropdown(c)
            local n = copy(c); n.Name = clean(n.Name or n[1])
            local ready, cb = false, c.Callback
            n.Callback = function(...)
                if not ready then return end   -- ignora o disparo de criação (Default nil)
                if cb then return cb(...) end
            end
            local obj = tab:AddDropdown(n)
            ready = true
            return obj
        end
        function P:AddTextbox(c)
            local n = copy(c); n.Name = clean(n.Name or n[1]); n.ClearText = c.TextDisappear
            return tab:AddTextBox(n)
        end
        P.AddTextBox = P.AddTextbox
        function P:AddSlider(c)
            local n = copy(c); n.Name = clean(n.Name or n[1]); n.Increase = c.Increment or c.Increase or 1
            return tab:AddSlider(n)
        end
        return setmetatable(P, {__index = function(_, k) return tab[k] end})
    end
    function GTA_XY.window()
        local W = {}
        function W:MakeTab(c)
            local name = clean(c.Name or c.Title or c[1])
            return wrapTab(ActiveWindow:MakeTab({Title = name, Icon = ICONS[name] or "•"}))
        end
        return W
    end
    GTA_XY.lib = {
        MakeNotification = function(_, c) return redzlib:MakeNotification(c) end,
        Init = function() end,
    }
end


-- ================================================================
-- PROP SWALLOW (by GTA | robotic GG): props com o teu nome orbitam você ou um alvo e vão pro void quando ele senta
-- ================================================================
GTA_PL.PS = {}
-- PREVISÃO AUTOMÁTICA (igual ao Fling Ball: posição do alvo + velocidade/1.5), usada por todos os props/barco que seguem um player
function GTA_PL.predictLead(root)
    if not root then return Vector3.new() end
    local ps = GTA_PL.PS
    if ps and ps.autoPredict == false then return Vector3.new() end
    local v = root.AssemblyLinearVelocity
    if v.Magnitude < 1 then return Vector3.new() end  -- parado: sem previsão
    local lead = v / 1.5
    if lead.Magnitude > 80 then lead = lead.Unit * 80 end  -- limite de segurança (lag/fling do alvo)
    return lead
end
do
    local PS = GTA_PL.PS
    local Players = game:GetService("Players")
    local LP = Players.LocalPlayer
    local RS = game:GetService("RunService")
    local UIS = game:GetService("UserInputService")
    local CoreGui = game:GetService("CoreGui")
    local kScanInterval, kGatherTime, kAppearRadius, kReleaseTime = 2.0, 8.0, 18, 2.6
    local kOrbitRadius, kOrbitRadiusVar, kOrbitSpeed, kOrbitSpeedVar, kOrbitHeightVar = 2.6, 1.2, 2.0, 1.0, 2.6
    local kSelfHeightOffset, kVoidY, kVoidSpread, kVoidSpinSpeed = -3.2, -600, 14, 28
    local kVoidTrembleSpeed, kVoidTrembleAmp = 999191991919199199, 0.22
    local kPredictLead, kPredictSmoothing, kPredictMaxLead, kNetworkRate = 0.12, 12, 6, 1 / 20
    local smoothedVel = Vector3.new(0, 0, 0)
    PS.autoPredict = true  -- previsão automática: lead = ping + base, suaviza a velocidade do alvo
    local function leadFor(root, dt)
        return GTA_PL.predictLead(root)
    end
    PS.mode, PS.target = "OFF", nil
    PS.park = "VOID"  -- onde os props ficam quando o alvo senta: VOID | FRONT (na tua frente, sem girar) | TOP (topo do mapa, girando)
    local kTopY, kTopSpin, kFlingSpin = 2500, 55, 80  -- rad/s reais (~9 e ~13 voltas/s); os números gigantes que vc mandou perdem precisão em double, isso aqui É o "muito rápido" de verdade
    -- Fling (PS.mode == "FLING"): enquanto o alvo não senta, segue ele girando; quando senta, faz TWEEN (não TP) pro destino do Fling (ver kFling* abaixo).
    -- FLING (V4): vai pro destino por TP DIRETO (sem Tween). O Tween só existe nos "pulos" pros lados em volta do destino, girando nos 3 eixos.
    -- Config única: tudo que é número do Fling mora aqui.
    local kFlingTweenSpeed = 1991919191919          -- studs/s do Tween dos lados
    local kFlingSpinSpeed  = 1991919191919          -- rad/s do giro (X, Y e Z)
    local kFlingGoalX      = 298292929939599273972973937297492826836384629639638369363926392628639263837383638363933936373637  -- destino X (os números que você mandou)
    local kFlingGoalY      = 1992919299292882937282836917272928268283743983838383893929282882828282828288292992982322333333292828929282  -- destino Y (altura)
    local kFlingGoalZ      = 192992929299191919191  -- destino Z (mantido como estava)
    local kFlingPosMax     = 3e38   -- CFrame/Vector3 são float32 (máx ~3.4e38): X e Y que você mandou passam disso (~1e95 e ~1e107) e virariam inf/NaN, então a posição ENVIADA é limitada a ±3e38 (o mais longe possível)
    local kFlingSideRadius = 1e13  -- NÃO calibrado: alcance dos pulos pros lados. Em coordenadas grandes o float32 só enxerga passos enormes, então menos que isso não aparece
    PS.flingGen = 0  -- muda a cada setMode: faz cada prop recomeçar o Fling (TP pro destino)
    -- Motor único do Fling (usado pelo botão Fling do Troll e pela Bola V2): s em DOUBLE de propósito
    -- (Vector3 é float32: a magnitude dessas distâncias estoura float32 e vira inf/NaN; a conta em number não).
    function PS.flingNewState()
        local s = { x = kFlingGoalX, y = kFlingGoalY, z = kFlingGoalZ, ax = 0, ay = math.pi / 3, az = 2 * math.pi / 3 }  -- TP direto pro destino
        s.tx, s.ty, s.tz = s.x, s.y, s.z
        return s
    end
    function PS.flingAdvance(s, dt)
        dt = math.clamp(dt or 0, 0, 0.1)
        local dx, dy, dz = s.tx - s.x, s.ty - s.y, s.tz - s.z
        local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
        local step = kFlingTweenSpeed * dt
        if dist ~= dist then
            s.x, s.y, s.z = kFlingGoalX, kFlingGoalY, kFlingGoalZ
            s.tx, s.ty, s.tz = s.x, s.y, s.z
        elseif dist <= step then  -- chegou no ponto do lado: escolhe outro lado
            s.x, s.y, s.z = s.tx, s.ty, s.tz
            s.tx = kFlingGoalX + (math.random() * 2 - 1) * kFlingSideRadius
            s.ty = kFlingGoalY + (math.random() * 2 - 1) * kFlingSideRadius
            s.tz = kFlingGoalZ + (math.random() * 2 - 1) * kFlingSideRadius
        else  -- Tween linear até o ponto do lado
            local k = step / dist
            s.x, s.y, s.z = s.x + dx * k, s.y + dy * k, s.z + dz * k
        end
        local tau, sp = 2 * math.pi, (kFlingSpinSpeed * dt) % (2 * math.pi)
        s.ax, s.ay, s.az = (s.ax + sp) % tau, (s.ay + sp) % tau, (s.az + sp) % tau
        local function f32(v) return math.clamp(v, -kFlingPosMax, kFlingPosMax) end
        return CFrame.new(f32(s.x), f32(s.y), f32(s.z)) * CFrame.Angles(s.ax, s.ay, s.az)
    end
    local props, lastScan, connected = {}, 0, false
    local function myRoot() return LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") end
    local function parkStep(d, dt, kind, spin)
        local r = myRoot()
        if not r then return end
        if kind == "FRONT" then
            d.pos = (r.CFrame * CFrame.new(0, 0, -5)).Position
            local _, ry = r.CFrame:ToOrientation()
            d.angle = ry
        elseif kind == "TOP" then
            d.pos = Vector3.new(r.Position.X, kTopY, r.Position.Z)
            d.angle = (d.angle + (spin or kTopSpin) * dt) % (2 * math.pi)  -- acumula com wrap, nunca perde precisão
        end
    end
    local ui = {}

    local function getRemote(inst)
        if inst:IsA("BasePart") or inst:IsA("Model") then return inst:FindFirstChild("SetCurrentCFrame") end
    end
    local function currentPos(inst)
        if inst:IsA("Model") then
            local ok, cf = pcall(function() return inst:GetPivot() end)
            if ok and cf then return cf.Position end
            if inst.PrimaryPart then return inst.PrimaryPart.Position end
        elseif inst:IsA("BasePart") then
            return inst.Position
        end
    end
    local function scanProps()
        local wanted = "Prop" .. LP.Name
        for _, v in ipairs(workspace:GetDescendants()) do
            if not props[v] and v.Name:find(wanted, 1, true) then
                local remote = getRemote(v)
                local pos = remote and currentPos(v)
                if remote and pos then
                    props[v] = {
                        remote = remote, phase = "VOID", phaseStart = tick(), phaseFrom = pos, pos = pos,
                        angle = math.random() * math.pi * 2,
                        radius = kOrbitRadius + math.random() * kOrbitRadiusVar,
                        speed = (kOrbitSpeed + math.random() * kOrbitSpeedVar) * (math.random() < 0.5 and -1 or 1),
                        heightOff = (math.random() - 0.5) * kOrbitHeightVar,
                        voidAngle = math.random() * math.pi * 2, voidRadius = math.random() * kVoidSpread,
                        lastNet = 0,
                    }
                end
            end
        end
    end
    local function stepProp(d, t, dt, shouldShow, center, hardTP)
        if shouldShow and center then
            if d.phase == "VOID" then
                d.phase, d.phaseStart, d.phaseFrom = (hardTP and "ORBIT" or "GATHER"), t, d.pos
                if not hardTP then
                    d.startRadius = kAppearRadius
                    d.startHeight = (math.random() - 0.5) * kOrbitHeightVar
                    d.angle = math.random() * math.pi * 2
                end
            end
        elseif d.phase == "ORBIT" or d.phase == "GATHER" then
            d.phase, d.phaseStart, d.phaseFrom = "RELEASE", t, d.pos
            local vc = center or d.pos
            d.releaseTarget = Vector3.new(vc.X + math.cos(d.voidAngle) * d.voidRadius, kVoidY, vc.Z + math.sin(d.voidAngle) * d.voidRadius)
            if hardTP then  -- modo alvo: vai pro void na hora (TP), sem descer em espiral
                d.phase = "VOID"
                d.pos = d.releaseTarget
            end
        end
        if d.phase == "VOID" then d.angle = d.angle + kVoidSpinSpeed * dt else d.angle = d.angle + d.speed * dt end
        if center and d.phase == "GATHER" then
            local p = math.clamp((t - d.phaseStart) / kGatherTime, 0, 1)
            local ease = 1 - (1 - p) * (1 - p)
            local r = d.startRadius + (d.radius - d.startRadius) * ease
            local h = d.startHeight + (d.heightOff - d.startHeight) * ease
            d.pos = center + Vector3.new(math.cos(d.angle) * r, h, math.sin(d.angle) * r)
            if p >= 1 then d.phase = "ORBIT" end
        elseif center and d.phase == "ORBIT" then
            d.pos = center + Vector3.new(math.cos(d.angle) * d.radius, d.heightOff, math.sin(d.angle) * d.radius)
        elseif d.phase == "RELEASE" and d.releaseTarget then
            local p = math.clamp((t - d.phaseStart) / kReleaseTime, 0, 1)
            local wobble = Vector3.new(math.cos(d.angle), 0, math.sin(d.angle)) * (d.radius * (1 - p) * 0.6)
            d.pos = d.phaseFrom:Lerp(d.releaseTarget, p) + wobble
            if p >= 1 then d.phase = "VOID" d.pos = d.releaseTarget end
        end
        if d.phase == "VOID" then
            local tt = t * kVoidTrembleSpeed
            d.pos = d.pos + Vector3.new(math.sin(tt) * kVoidTrembleAmp, math.sin(tt * 1.3) * kVoidTrembleAmp, math.cos(tt * 0.7) * kVoidTrembleAmp)
        end
    end
    local function connect()
        if connected then return end
        connected = true
        RS.Heartbeat:Connect(function(dt)
            local t = tick()
            if PS.mode ~= "OFF" and t - lastScan > kScanInterval then lastScan = t scanProps() end
            local center, shouldShow, hardTP = nil, false, false
            local predPos  -- posição prevista do alvo (vale pra TARGET, SEAT e FLING)
            do
                local ptr = PS.target and PS.target.Character and PS.target.Character:FindFirstChild("HumanoidRootPart")
                if ptr then predPos = ptr.Position + leadFor(ptr, dt) else smoothedVel = Vector3.new() end
            end
            local seatSeated = false
            if (PS.mode == "SEAT" or PS.mode == "FLING") and PS.target then
                local h = PS.target.Character and PS.target.Character:FindFirstChildOfClass("Humanoid")
                seatSeated = h ~= nil and h.Sit
                if PS.mode == "FLING" and seatSeated then PS.flingUp = true end
                if PS.mode == "SEAT" then
                    if seatSeated then PS.standSince = nil
                    elseif PS.hadSeat then
                        PS.standSince = PS.standSince or t
                        if t - PS.standSince > 1.5 then GTA_PL.unmarkUse("mode") PS.setMode("OFF") end  -- terminou: levantou e já foi pro void
                    end
                end
            end
            if PS.mode == "SELF" then
                local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                if root then center, shouldShow = root.Position + Vector3.new(0, kSelfHeightOffset, 0), true end
            elseif PS.mode == "TARGET" and PS.target then
                local char = PS.target.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local root = char and char:FindFirstChild("HumanoidRootPart")
                shouldShow = hum ~= nil and hum.Health > 0 and not hum.Sit
                hardTP = true
                if shouldShow and root then
                    center = predPos or root.Position
                end
            end
            local tracked = 0
            for inst, d in pairs(props) do
                if not inst.Parent then
                    props[inst] = nil
                else
                    tracked = tracked + 1
                    d.flingFast = false
                    if PS.mode == "FLING" then
                        if PS.flingUp then
                            d.phase = "VOID"
                            if d.flingGen ~= PS.flingGen or not d.fs then  -- começou o Fling: TP direto pro destino
                                d.flingGen = PS.flingGen
                                d.fs = PS.flingNewState(d.pos)
                            end
                            d.flingCF = PS.flingAdvance(d.fs, dt)  -- TP direto pro destino + Tween só nos lados, girando nos 3 eixos
                            d.flingFast = true
                        else
                            d.phase = "ORBIT"
                            if predPos then d.pos = predPos end
                            d.angle = d.angle + 5000 * dt  -- segue o player girando MUITO rápido
                        end
                    elseif PS.mode == "TOPFLING" then
                        d.phase = "VOID"; parkStep(d, dt, "TOP")
                    elseif PS.mode == "SEAT" then
                        if seatSeated then
                            PS.hadSeat = true
                            d.phase = "FRONT"; parkStep(d, dt, "FRONT")
                        elseif not PS.hadSeat then
                            d.phase = "ORBIT"
                            if predPos then d.pos = predPos end  -- fase 1: vai no player e espera ele sentar
                        else
                            local r = myRoot()
                            d.phase = "VOID"
                            if r then
                                local tt = t * kVoidTrembleSpeed
                                d.pos = Vector3.new(r.Position.X, kVoidY, r.Position.Z) + Vector3.new(math.sin(tt) * kVoidTrembleAmp, math.sin(tt * 1.3) * kVoidTrembleAmp, math.cos(tt * 0.7) * kVoidTrembleAmp)
                            end
                        end
                    else
                        stepProp(d, t, dt, shouldShow, center, hardTP)
                        if PS.mode == "TARGET" and d.phase == "VOID" and PS.park ~= "VOID" then parkStep(d, dt, PS.park) end
                    end
                    local netGate = d.flingFast and 0 or kNetworkRate  -- flingFast: TP a cada frame (sem limite de rede), pra sair voando rápido quando levantar
                    if t - d.lastNet >= netGate then
                        d.lastNet = t
                        local cf = (d.flingFast and d.flingCF) or (CFrame.new(d.pos) * CFrame.Angles(0, d.angle, 0))
                        local remote = d.remote
                        task.spawn(function() pcall(function() remote:InvokeServer(cf) end) end)
                    end
                end
            end
            if ui.status then ui.status.Text = "PROPS: " .. tracked .. " TRACKED | MODE: " .. PS.mode end
        end)
    end
    function PS.setMode(m)
        PS.mode = m
        PS.flingGen = PS.flingGen + 1
        PS.hadSeat, PS.flingUp, PS.standSince = false, false, nil
        if m ~= "OFF" then lastScan = 0 connect() end
        if ui.selfBtn then
            ui.selfBtn.Text = "SWALLOW ME: " .. ((m == "SELF") and "ON" or "OFF")
            ui.selfBtn.TextColor3 = (m == "SELF") and Color3.fromRGB(255, 210, 0) or Color3.fromRGB(255, 230, 130)
            ui.targetBtn.Text = "FOLLOW TARGET: " .. ((m == "TARGET") and "ON" or "OFF")
            ui.targetBtn.TextColor3 = (m == "TARGET") and Color3.fromRGB(255, 210, 0) or Color3.fromRGB(255, 230, 130)
        end
    end
    function PS.setTarget(plr)
        if plr and not GTA_PL.canHit(plr) then
            GTA_PL.violation(plr, "tentou selecionar " .. plr.Name)
            plr = nil
        end
        PS.target = plr
        if plr and GTA_PL.retargetUses then GTA_PL.retargetUses(plr) end
        if ui.targetBox then ui.targetBox.Text = plr and ("TARGET: " .. plr.DisplayName) or "TARGET: NONE (CLICK SELECT)" end
        if not plr and (PS.mode == "TARGET" or PS.mode == "SEAT") then PS.setMode("OFF") end
    end
    Players.PlayerRemoving:Connect(function(plr) if plr == PS.target then PS.setTarget(nil) end end)

    -- ===== BARCO PIRATA: tp pro ponto -> pega o PirateFree -> senta no VehicleSeat -> vai no alvo girando muito rápido =====
    local kBoatSpawnPos, kBoatSpin = Vector3.new(-1217.29, 23.9, -1820.44), 99999999999
    PS.boatOn, PS.boatGen, PS.boatConn = false, 0, nil
    PS.boatHeight = 5  -- fixo (não configurável): fundo do barco na altura do corpo do alvo
    local boatHome, boatSpin = nil, nil
    local function deleteMyBoat(wait_gone)
        local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
        local ev = RE and RE:FindFirstChild("1Ca1r")
        if not ev then return end
        pcall(function() ev:FireServer("DeleteAllVehicles") end)
        if wait_gone then
            local vehicles = workspace:FindFirstChild("Vehicles")
            for _ = 1, 30 do
                if not (vehicles and vehicles:FindFirstChild(LP.Name .. "Car")) then break end
                task.wait(0.1)
            end
            task.wait(0.5)
        end
    end
    function PS.boatStop()
        PS.boatOn = false
        PS.boatGen = PS.boatGen + 1
        if PS.boatConn then PS.boatConn:Disconnect() PS.boatConn = nil end
        if PS.boatConn2 then PS.boatConn2:Disconnect() PS.boatConn2 = nil end
        if boatSpin then pcall(function() boatSpin:Destroy() end) boatSpin = nil end
        local ch = LP.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum.Sit = false end) end
        local r = myRoot()
        if r and boatHome then
            r.CFrame = boatHome
            r.AssemblyLinearVelocity = Vector3.zero
            r.AssemblyAngularVelocity = Vector3.zero
        end
        boatHome = nil
        task.delay(0.4, function() if not PS.boatOn then deleteMyBoat(false) end end)  -- apaga o barco velho: senão o próximo spawn buga
    end
    function PS.boatStart(solo)  -- solo=true: você sobe, sai do barco e ele vai sozinho (mais rápido e um pouco mais alto)
        local target = PS.target
        if not target then
            pcall(function() GTA_PL.toast("escolhe o 'Swallow: player alvo' antes", Color3.fromRGB(220, 80, 80)) end)
            return
        end
        if not GTA_PL.guardPlayer(target) then return end
        PS.boatStop()
        PS.boatOn = true
        local mine = PS.boatGen
        local function fail(msg)
            pcall(function() GTA_PL.toast(msg, Color3.fromRGB(220, 80, 80)) end)
            if PS.boatGen == mine then PS.boatStop() end
        end
        task.spawn(function()
            local ok, err = pcall(function()
                local ch = LP.Character
                local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                local r = myRoot()
                if not (hum and r) then PS.boatOn = false return end
                boatHome = r.CFrame
                -- 1) teleporta pro ponto do barco
                r.CFrame = CFrame.new(kBoatSpawnPos)
                task.wait(solo and 1.0 or 2.5)  -- passo 2 demora um pouco antes de pegar o barco (versão solo: mais rápido)
                if PS.boatGen ~= mine then return end
                -- 2) pega o barco PirateFree
                local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
                local ev = RE and RE:FindFirstChild("1Ca1r")
                if not ev then fail("remote do barco não encontrado") return end
                deleteMyBoat(true)  -- limpa barco antigo/bugado antes de spawnar um novo
                if PS.boatGen ~= mine then return end
                local vehicles = workspace:FindFirstChild("Vehicles")
                local car
                local lastFire = 0
                while true do  -- pede o barco; só repete a cada 2,5s (spawn rápido demais apaga o barco anterior); para assim que ele aparece
                    car = vehicles and vehicles:FindFirstChild(LP.Name .. "Car")
                    if car then break end
                    if tick() - lastFire >= 2.5 then
                        lastFire = tick()
                        pcall(function() ev:FireServer("PickingBoat", "PirateFree", "Boat") end)
                    end
                    task.wait(0.1)
                    vehicles = vehicles or workspace:FindFirstChild("Vehicles")
                    if PS.boatGen ~= mine then return end
                end
                if PS.boatGen ~= mine then return end
                if not car then fail("o barco não apareceu") return end
                -- 3) tp pro VehicleSeat e senta
                local seat
                for _ = 1, 30 do
                    seat = car:FindFirstChild("VehicleSeat", true)
                    if seat then break end
                    task.wait(0.1)
                end
                if not seat then fail("VehicleSeat não encontrado") return end
                local t0 = tick()
                repeat
                    task.wait(0.1)
                    r = myRoot()
                    if r then r.CFrame = seat.CFrame * CFrame.new(0, 1, 0) end
                until hum.SeatPart == seat or PS.boatGen ~= mine
                if PS.boatGen ~= mine then return end
                if hum.SeatPart ~= seat then fail("não consegui sentar no barco") return end
                -- 4) sentado: vai pro alvo e gira muito rápido
                local base = car.PrimaryPart or seat
                -- medidas do casco: o barco fica sempre reto e com a PARTE DE BAIXO encostando no alvo
                local bboxCF, bboxSize = car:GetBoundingBox()
                local cur0 = car:GetPivot()
                local bboxOff = cur0:PointToObjectSpace(bboxCF.Position)
                local yawAcc = 0
                if solo then
                    -- V2: depois de subir no barco, o script te tira dele e te teleporta pro player; o barco faz tudo do V1 sem você sentado
                    task.wait(0.4)
                    pcall(function() hum.Sit = false end)
                    task.wait(0.3)
                    local p0 = PS.target
                    local tr0 = p0 and p0.Character and p0.Character:FindFirstChild("HumanoidRootPart")
                    local r0 = myRoot()
                    if tr0 and r0 then r0.CFrame = tr0.CFrame * CFrame.new(0, 0, 3) end
                    if PS.boatGen ~= mine then return end
                end
                local height = PS.boatHeight
                bboxSize = Vector3.new(bboxSize.X, math.clamp(bboxSize.Y, 1, 20), bboxSize.Z)  -- sanidade: nunca joga o barco muito pra baixo
                local kBobAmp, kBobSpeed, kTweenSpeed = 0, 80, 6000  -- altura fixa (sem subir/descer)  -- sobe e desce rápido SÓ pra cima da altura base (nunca desce abaixo dela); Tween linear a 6000 studs/s
                local kFwdAmp, kFwdSpeed, kDirSpeed = 14, 150, 2.5  -- varre 14 studs pra cada lado do alvo, muito rápido; a direção da varredura gira (frente/trás e lados)
                local arrived = false
                local function stepBoat(dt)
                    if PS.boatGen ~= mine then return end
                    local p = PS.target
                    if not (p and p.Parent) or not GTA_PL.canHit(p) or not car.Parent then PS.boatStop() return end
                    local tr = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
                    if not tr then return end
                    local bpos = tr.Position + GTA_PL.predictLead(tr)  -- previsão automática (igual Fling Ball)
                    yawAcc = (yawAcc + kBoatSpin * dt) % (2 * math.pi)  -- giro por CFrame (sem velocidade de física, que jogava no void)
                    local rot = CFrame.Angles(0, yawAcc, 0)  -- só gira no eixo Y: nunca inclina
                    local bob = (math.sin(tick() * kBobSpeed) * 0.5 + 0.5) * kBobAmp  -- 0..1 stud: só pra cima, não afunda
                    local look = tr.CFrame.LookVector
                    local fwd = Vector3.new(look.X, 0, look.Z)
                    if fwd.Magnitude > 0.01 then fwd = fwd.Unit else fwd = Vector3.new(0, 0, -1) end
                    local right = Vector3.new(-fwd.Z, 0, fwd.X)
                    local ang = tick() * kDirSpeed  -- direção da linha de varredura: gira passando por frente/trás e lados
                    local dir = fwd * math.cos(ang) + right * math.sin(ang)
                    local sway = dir * (math.sin(tick() * kFwdSpeed) * kFwdAmp)  -- vai e volta atravessando SEMPRE o alvo (a linha passa pelo centro)
                    local center = Vector3.new(bpos.X + sway.X, bpos.Y + height + bob + bboxSize.Y / 2, bpos.Z + sway.Z)
                    local goal = CFrame.new(center) * rot * CFrame.new(-bboxOff)
                    if not arrived then
                        arrived = true  -- 1º: TP direto no alvo
                    else  -- depois: Tween linear muito rápido (sem suavização), nunca fica suave
                        local curPos = car:GetPivot().Position
                        local delta = goal.Position - curPos
                        local stepLen = kTweenSpeed * dt
                        if delta.Magnitude > stepLen then
                            goal = CFrame.new(curPos + delta.Unit * stepLen) * (goal - goal.Position)
                        end
                    end
                    car:PivotTo(goal)
                    base.AssemblyLinearVelocity = Vector3.zero
                    base.AssemblyAngularVelocity = Vector3.zero
                end
                PS.boatConn = RS.Heartbeat:Connect(stepBoat)
                PS.boatConn2 = RS.Stepped:Connect(function(_, dt) stepBoat(dt) end)  -- 2x por frame: giro ainda mais rápido
            end)
            if not ok then
                warn("[GTA Hub] Swallow Barco: " .. tostring(err))
                if PS.boatGen == mine then PS.boatStop() end
            end
        end)
    end

    -- ===== PROPS NO CHÃO (sofá etc.): cria N props do tipo escolhido no chão, onde você está =====
    PS.spawnCfg = { name = "Couch", cat = "Furniture", count = 6 }
    function PS.spawnGround()
        task.spawn(function()
            local ok, err = pcall(function()
                local RS2 = game:GetService("ReplicatedStorage")
                local RE = RS2:FindFirstChild("RE")
                local clearEv, toolEv = RE and RE:FindFirstChild("1Clea1rTool1s"), RE and RE:FindFirstChild("1Too1l")
                local ch = LP.Character
                local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                local r = myRoot()
                if not (clearEv and toolEv and hum and r) then return end
                local home = r.CFrame
                local rp = RaycastParams.new()
                rp.FilterType = Enum.RaycastFilterType.Exclude
                rp.FilterDescendantsInstances = {ch}
                local hit = workspace:Raycast(r.Position, Vector3.new(0, -50, 0), rp)
                local ground = hit and hit.Position or (r.Position - Vector3.new(0, 3, 0))
                local function pm() return (LP.Character and LP.Character:FindFirstChild("PropMaker")) or LP.Backpack:FindFirstChild("PropMaker") end
                if not pm() then
                    pcall(function() toolEv:InvokeServer("PickingTools", "PropMaker") end)
                    for _ = 1, 20 do if pm() then break end task.wait(0.1) end
                end
                local tool = pm()
                if not tool then
                    pcall(function() GTA_PL.toast("não consegui pegar o PropMaker", Color3.fromRGB(220, 80, 80)) end)
                    return
                end
                hum:EquipTool(tool)
                task.wait(0.4)
                clearEv:FireServer("RequestingPropName", PS.spawnCfg.name, PS.spawnCfg.cat)
                task.wait(0.4)
                local corner = workspace:FindFirstChild("Model") and workspace.Model:FindFirstChild("CornerHills")
                for _ = 1, PS.spawnCfg.count do
                    local t = LP.Character and LP.Character:FindFirstChild("PropMaker")
                    local mk = t and t:FindFirstChild("Tool_PropMake")
                    if mk then pcall(function() mk:FireServer(corner, ground) end) end
                    task.wait(0.9)
                end
                pcall(function() GTA_PL.toast("props criados no chão: " .. PS.spawnCfg.name, Color3.fromRGB(80, 200, 120)) end)
            end)
            if not ok then warn("[GTA Hub] Props no chão: " .. tostring(err)) end
        end)
    end

    -- ===== BOLA V2: pega a bola e dá spawn nela sozinho (FootballInteraction, 1x por bola pega), flinga o alvo e NÃO desliga sozinho =====
    -- Enquanto o alvo estiver voando (velocidade alta), fica com ESSA MESMA bola (não pega outra: ela fica "guardada").
    -- Se ela parar de funcionar (ou sumir), aí sim pega outra e testa, em loop, até achar uma que funcione — só para quando VOCÊ desliga.
    -- Teleporte não conta como fling: só a VELOCIDADE do alvo decide (um TP de outra função não gera essa velocidade, então não é contado).
    local kBallSpawnCF = CFrame.new(-151.60105895996094, 4.53006649017334, 181.74530029296875) * CFrame.Angles(3.1415927410125732, 1.3855276107788086, -3.141592502593994)
    local kBallFlingVel, kBallNoFlingTimeout, kBallColdGrace = 1000, 10, 4  -- sem tempo exato seu: usei valores bem maiores que antes (era ~4,5s e 1,5s); ajusta aqui se quiser mais/menos
    -- GUARDAR A BOLA: depois de usar (ou ao parar), a bola que funcionou fica PARADA longe do mapa (em cima) e é reutilizada depois, sem dar spawn de outra.
    -- Se ela parar de funcionar (ou sumir), vai pra lista de "ruins" por um tempo e o loop procura outra: a minha primeiro, depois TODAS as bolas do mapa; só spawna se não sobrar nenhuma.
    local kBallParkPos = Vector3.new(30000, 20000, 30000)  -- NÃO calibrado: ponto longe e alto onde a bola guardada fica parada (ajuste aqui)
    local kBallOtherTimeout, kBallBadFor = 3, 60           -- NÃO calibrado: bola dos outros desiste em 3s (a minha usa kBallNoFlingTimeout); bola ruim só é tentada de novo depois de 60s
    PS.ballOn, PS.ballGen, PS.ballFired, PS.ballCur = false, 0, nil, nil  -- ballFired: a Tool em que o FootballInteraction já foi disparado; ballCur: a bola guardada em uso
    PS.ballBad = setmetatable({}, { __mode = "k" })  -- bola -> até quando não tentar de novo
    local function unparkBall()
        if PS.ballParkConn then PS.ballParkConn:Disconnect() PS.ballParkConn = nil end
    end
    local function parkBall(balls)  -- deixa as bolas paradas longe (reaplica a posição todo frame; solta quando forem usadas de novo)
        unparkBall()
        if not (balls and #balls > 0) then return end
        PS.ballParkConn = RS.Heartbeat:Connect(function()
            local any = false
            for i, b in ipairs(balls) do
                if b.Parent then
                    any = true
                    b.CFrame = CFrame.new(kBallParkPos + Vector3.new(i * 4, 0, 0))
                    b.AssemblyLinearVelocity = Vector3.zero
                    b.AssemblyAngularVelocity = Vector3.zero
                end
            end
            if not any then unparkBall() end
        end)
    end
    function PS.ballStop()
        PS.ballOn = false
        PS.ballGen = PS.ballGen + 1
    end
    function PS.ballStart()
        local target = PS.target
        if not target then
            pcall(function() GTA_PL.toast("escolhe o 'Swallow: player alvo' antes", Color3.fromRGB(220, 80, 80)) end)
            return
        end
        if not GTA_PL.guardPlayer(target) then return end
        PS.ballStop()
        PS.ballOn = true
        local mine = PS.ballGen
        local prot = GTA_PL.protect and GTA_PL.protect.ballFling
        local wasProtOn = (prot and prot.get()) or false
        if prot and wasProtOn then pcall(function() prot.set(false) end) end  -- tira a proteção "Anti Fling Bola" (ela destrói as bolas) enquanto o Bola V2 roda
        task.spawn(function()
            local RSv = game:GetService("ReplicatedStorage")
            local ballName = "Soccer" .. LP.Name
            local RE, ServerBalls
            local function alive() return PS.ballOn and PS.ballGen == mine end
            local function restoreProtection()
                if prot and wasProtOn then pcall(function() prot.set(true) end) end  -- devolve a proteção, só se ela já tava ligada antes
            end
            local function restoreCamera()
                local cam = workspace.CurrentCamera
                local mh = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                if cam and mh then pcall(function() cam.CameraSubject = mh end) end
            end
            local function ownBalls(includeBad)  -- TODAS as bolas com o nome do meu personagem (BasePart na pasta de bolas cujo nome contém o meu nick); includeBad=false tira as marcadas como ruins
                local out, now = {}, tick()
                for _, b in ipairs(ServerBalls:GetDescendants()) do
                    if b:IsA("BasePart") and b.Name:find(LP.Name, 1, true) and (includeBad or not (PS.ballBad[b] and PS.ballBad[b] > now)) then out[#out + 1] = b end
                end
                return out
            end
            local function grabBall()  -- limpa as tools, pega a SoccerBall, equipa, dispara o FootballInteraction UMA vez (só bola nova) e espera a bola aparecer
                local ch, bp = LP.Character, LP:FindFirstChild("Backpack")
                if not (ch and bp) then return nil end
                pcall(function() RE["1Clea1rTool1s"]:FireServer("ClearAllTools") end)
                for _ = 1, 20 do
                    if not alive() or not ServerBalls:FindFirstChild(ballName) then break end
                    task.wait(0.1)
                end
                task.wait(0.3)
                local left = ownBalls(true)[1]
                if left then return left end  -- ainda existe uma bola minha: NÃO spawna outra (era isso que fazia aparecer 2)
                if PS.ballSpawnT and tick() - PS.ballSpawnT < 12 then  -- spawn recente ainda a caminho: só espera ela aparecer
                    for _ = 1, 120 do
                        if not alive() then return nil end
                        local nb = ownBalls(true)[1]
                        if nb then return nb end
                        task.wait(0.1)
                    end
                    return nil
                end
                pcall(function() RE["1Too1l"]:InvokeServer("PickingTools", "SoccerBall") end)
                local tool
                for _ = 1, 50 do
                    if not alive() then return nil end
                    tool = bp:FindFirstChild("SoccerBall") or ch:FindFirstChild("SoccerBall")
                    if tool then break end
                    task.wait(0.1)
                end
                if not tool then return nil end
                tool.Parent = ch
                if PS.ballFired ~= tool then  -- 1x por bola pega: só dispara de novo depois de pegar a bola de novo
                    task.wait(0.15)
                    local fi = tool:FindFirstChild("FootballInteraction") or tool:WaitForChild("FootballInteraction", 5)
                    if fi then
                        PS.ballFired = tool
                        PS.ballSpawnT = tick()  -- marca o spawn: nenhum outro é pedido nos próximos 12s
                        pcall(function() fi:FireServer(kBallSpawnCF) end)
                    end
                end
                local ball
                for _ = 1, 120 do  -- espera até 12s a bola aparecer (servidor lento era o que levava a pedir spawn de novo)
                    if not alive() then break end
                    ball = ownBalls(true)[1]
                    if ball then break end
                    task.wait(0.1)
                end
                pcall(function() if tool.Parent == ch then tool.Parent = bp end end)
                return ball
            end
            local function pickBall(troot)  -- a minha primeiro; depois TODAS as bolas do mapa (BaseParts da pasta de bolas), mais perto do alvo primeiro; ruins ficam de fora
                local now = tick()
                local function usable(b) return b:IsA("BasePart") and b.Parent ~= nil and not (PS.ballBad[b] and PS.ballBad[b] > now) end
                local own = ownBalls()
                if own[1] then return own[1] end
                local list = {}
                for _, b in ipairs(ServerBalls:GetChildren()) do
                    if usable(b) then list[#list + 1] = b end
                end
                table.sort(list, function(a, b) return (a.Position - troot.Position).Magnitude < (b.Position - troot.Position).Magnitude end)
                return list[1]
            end
            local function cycle()  -- uma volta: usa a bola guardada se ainda existir, senão pega/spawna outra; devolve false só quando tem que parar (alvo protegido)
                RE = RE or RSv:WaitForChild("RE")
                ServerBalls = ServerBalls or workspace:WaitForChild("WorkspaceCom"):WaitForChild("001_SoccerBalls")
                local tgt = PS.target
                if tgt and not GTA_PL.canHit(tgt) then return false end
                local tchar = tgt and tgt.Character
                local troot = tchar and tchar:FindFirstChild("HumanoidRootPart")
                local thum = tchar and tchar:FindFirstChildOfClass("Humanoid")
                if not (tgt and tgt.Parent and troot and thum) or thum.Health <= 0 then
                    task.wait(0.5)  -- alvo saiu / morreu / respawnando: espera e continua (o toggle fica ligado)
                    return true
                end
                local ball = PS.ballCur
                if ball and (not ball.Parent or (PS.ballBad[ball] and PS.ballBad[ball] > tick())) then ball = nil end
                if not ball then ball = pickBall(troot) end  -- sem bola guardada: procura nas bolas do mapa (a minha primeiro)
                if not ball then ball = grabBall() end       -- nenhuma bola usável no mapa: aí sim spawna a minha
                PS.ballCur = ball
                if not alive() then return true end
                if not ball then task.wait(1) return true end
                unparkBall()  -- tira a bola do esconderijo pra usar
                local isOwn = ball.Name:find(LP.Name, 1, true) ~= nil
                local noFlingTimeout = isOwn and kBallNoFlingTimeout or kBallOtherTimeout
                local group = { ball }  -- se for minha, puxa TODAS as minhas bolas juntas (a principal vai primeiro)
                if isOwn then
                    for _, b in ipairs(ownBalls()) do
                        if b ~= ball then group[#group + 1] = b end
                    end
                end
                local bvs = {}
                for _, b in ipairs(group) do
                    b.CanCollide = false
                    b.Massless = true
                    b.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0, 0)
                    local old = b:FindFirstChildWhichIsA("BodyVelocity")
                    if old then old:Destroy() end
                    local bv = Instance.new("BodyVelocity")
                    bv.Name = "FlingPower"
                    bv.Velocity = Vector3.new(9e8, 9e8, 9e8)
                    bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                    bv.P = 9e900
                    bv.Parent = b
                    bvs[#bvs + 1] = bv
                end
                local flung, lastHot, t0 = false, 0, tick()
                local bst, lastT  -- estado do Tween da bola (igual ao Fling normal): começa quando o alvo senta
                local cam = workspace.CurrentCamera
                local myHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                if cam then cam.CameraSubject = thum end
                while alive() do
                    if not (troot.Parent and ball.Parent and tgt.Parent) then break end
                    local v = troot.AssemblyLinearVelocity
                    local now = tick()
                    if v.Magnitude > kBallFlingVel then  -- só velocidade conta como fling (um TP não gera essa velocidade, então não entra aqui)
                        if not flung then
                            flung = true
                            pcall(function() GTA_PL.toast("Bola V2: alvo jogado longe", Color3.fromRGB(80, 200, 120)) end)
                        end
                        lastHot = now
                    end
                    if flung and now - lastHot > kBallColdGrace then break end        -- parou de voar: solta essa bola e tenta outra
                    if not flung and now - t0 > noFlingTimeout then break end    -- não pegou de jeito nenhum: tenta outra bola
                    -- mesma conta do Fling Ball: posição + velocidade/1.5
                    if thum.Sit and not bst then bst, lastT = PS.flingNewState(ball.Position), now end  -- alvo sentou: igual ao Fling normal, a bola dá TP pro destino
                    if bst then
                        ball.CFrame = PS.flingAdvance(bst, now - lastT)  -- mesmo motor do Fling: Tween só nos lados, girando nos 3 eixos
                        lastT = now
                    elseif v.Magnitude > 0 then
                        ball.CFrame = CFrame.new(troot.Position + v / 1.5)
                        ball.Orientation = ball.Orientation + Vector3.new(45, 60, 30)
                    else
                        ball.CFrame = troot.CFrame
                    end
                    local pcf = ball.CFrame  -- as outras bolas minhas ficam no mesmo ponto/giro da principal
                    for i = 2, #group do
                        if group[i].Parent then group[i].CFrame = pcf end
                    end
                    RS.Heartbeat:Wait()
                end
                if cam and myHum then cam.CameraSubject = myHum end
                for _, bv in ipairs(bvs) do pcall(function() bv:Destroy() end) end
                if ball.Parent and (flung or isOwn) and (flung or not alive()) then
                    PS.ballCur = ball  -- funcionou (ou eu parei com a minha bola): guarda essa bola e as outras minhas paradas longe, pra reusar sem spawn
                    parkBall(group)
                elseif not alive() then
                    PS.ballCur = ball.Parent and ball or nil  -- parei no meio sem ter testado: não marca como ruim
                else
                    for _, b in ipairs(group) do PS.ballBad[b] = tick() + kBallBadFor end  -- não funcionou (ou sumiu): marca como ruim e o loop procura outra
                    PS.ballCur = nil
                end
                return true
            end
            while alive() do
                local ok, res = pcall(cycle)
                if not ok then
                    warn("[GTA Hub] Bola V2: " .. tostring(res))
                    PS.ballCur = nil
                    task.wait(1)
                elseif res == false then
                    break
                end
            end
            restoreCamera()
            restoreProtection()
            if PS.ballGen == mine then PS.ballOn = false end
        end)
    end

    -- ===== ligar/desligar pela UI: anota pra religar quando o alvo lembrado voltar (Misc > Lembrar alvo que saiu) =====
    local starters = {
        boat = function() PS.boatStart() end,
        ball = function() PS.ballStart() end,
    }
    local stoppers = {
        boat = function() PS.boatStop() end,
        ball = function() PS.ballStop() end,
        mode = function() PS.setMode("OFF") end,
    }
    local isOn = {
        boat = function() return PS.boatOn end,
        ball = function() return PS.ballOn end,
    }
    function PS.useOn(key)  -- boat | ball: liga e anota
        local start = starters[key]
        if not start then return end
        start()
        local plr = PS.target
        if plr and isOn[key]() then GTA_PL.markUse(key, plr, start) end
    end
    function PS.modeOn(m)  -- TARGET | SEAT | FLING: liga o modo e anota
        local plr = PS.target
        if not plr then return end
        PS.setMode(m)
        GTA_PL.markUse("mode", plr, function() PS.setMode(m) end)
    end
    function PS.useOff(key)  -- boat | ball | mode: você desligou, então apaga a anotação e para
        GTA_PL.unmarkUse(key)
        local stop = stoppers[key]
        if stop then stop() end
    end
    function PS.stopAll()
        GTA_PL.clearUses()
        PS.ballStop() PS.setMode("OFF") PS.boatStop()
    end

    -- painel completo (UI do script original)
    function PS.openUI()
        if ui.sg and ui.sg.Parent then ui.sg:Destroy() ui = {} return end
        local sg = Instance.new("ScreenGui")
        sg.Name = "Prop_Swallow_Control" sg.ResetOnSpawn = false
        local parent
        pcall(function() parent = (gethui and gethui()) or CoreGui end)
        sg.Parent = parent or LP:WaitForChild("PlayerGui")
        ui.sg = sg
        local YELLOW, TXT = Color3.fromRGB(255, 210, 0), Color3.fromRGB(255, 230, 130)
        local main = Instance.new("Frame", sg)
        main.Size, main.Position = UDim2.new(0, 190, 0, 210), UDim2.new(0.05, 0, 0.3, 120)
        main.BackgroundColor3, main.BorderSizePixel, main.Active = Color3.fromRGB(35, 30, 5), 0, true
        local titleBar = Instance.new("Frame", main)
        titleBar.Size, titleBar.BackgroundColor3, titleBar.BorderSizePixel = UDim2.new(1, 0, 0, 25), Color3.fromRGB(70, 55, 5), 0
        local closeBtn = Instance.new("TextButton", titleBar)
        closeBtn.Size, closeBtn.Position = UDim2.fromOffset(20, 20), UDim2.new(1, -23, 0, 2)
        closeBtn.BackgroundColor3, closeBtn.BorderSizePixel = Color3.fromRGB(15, 12, 3), 0
        closeBtn.Text, closeBtn.TextColor3, closeBtn.Font, closeBtn.TextSize = "X", Color3.fromRGB(255, 120, 120), Enum.Font.SourceSansBold, 14
        closeBtn.MouseButton1Click:Connect(function() sg:Destroy() ui = {} end)
        local title = Instance.new("TextLabel", titleBar)
        title.Size, title.Position = UDim2.new(1, -58, 1, 0), UDim2.new(0, 5, 0, 0)
        title.BackgroundTransparency, title.Text = 1, "PROP SWALLOW | GTA HUB"
        title.TextColor3, title.Font, title.TextSize = Color3.fromRGB(255, 230, 100), Enum.Font.SourceSansBold, 12
        title.TextXAlignment = Enum.TextXAlignment.Left
        local status = Instance.new("TextLabel", main)
        status.Size, status.Position = UDim2.new(1, -10, 0, 15), UDim2.new(0, 5, 1, -30)
        status.BackgroundTransparency, status.Text = 1, "PROPS: 0 TRACKED"
        status.TextColor3, status.Font, status.TextSize = Color3.fromRGB(150, 255, 150), Enum.Font.Code, 10
        status.TextXAlignment = Enum.TextXAlignment.Left
        ui.status = status
        local credit = Instance.new("TextLabel", main)
        credit.Size, credit.Position = UDim2.new(1, 0, 0, 15), UDim2.new(0, 0, 1, -15)
        credit.BackgroundTransparency, credit.Text = 1, "by GTA"
        credit.TextColor3, credit.Font, credit.TextSize = YELLOW, Enum.Font.Code, 10
        do
            local dragging, dragStart, startPos = false, nil, nil
            titleBar.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging, dragStart, startPos = true, input.Position, main.Position
                    input.Changed:Connect(function() if input.UserInputState == Enum.UserInputState.End then dragging = false end end)
                end
            end)
            UIS.InputChanged:Connect(function(input)
                if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                    local d = input.Position - dragStart
                    main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
                end
            end)
        end
        local function styleBtn(b)
            b.BackgroundColor3, b.BorderSizePixel, b.BorderColor3 = Color3.fromRGB(15, 12, 3), 1, Color3.fromRGB(130, 100, 10)
            b.TextColor3, b.Font, b.TextSize = TXT, Enum.Font.SourceSansBold, 11
        end
        local selfBtn = Instance.new("TextButton", main)
        selfBtn.Size, selfBtn.Position, selfBtn.Text = UDim2.new(1, -10, 0, 26), UDim2.new(0, 5, 0, 32), "SWALLOW ME: OFF"
        styleBtn(selfBtn)
        local selectBtn = Instance.new("TextButton", main)
        selectBtn.Size, selectBtn.Position, selectBtn.Text = UDim2.new(1, -10, 0, 26), UDim2.new(0, 5, 0, 63), "CLICK SELECT: OFF"
        styleBtn(selectBtn)
        local targetBox = Instance.new("TextLabel", main)
        targetBox.Size, targetBox.Position = UDim2.new(1, -10, 0, 26), UDim2.new(0, 5, 0, 94)
        targetBox.BackgroundColor3, targetBox.BorderColor3, targetBox.BorderSizePixel = Color3.fromRGB(20, 15, 2), Color3.fromRGB(120, 95, 10), 1
        targetBox.TextColor3, targetBox.Font, targetBox.TextSize, targetBox.TextWrapped = Color3.fromRGB(255, 240, 180), Enum.Font.Code, 10, true
        targetBox.Text = PS.target and ("TARGET: " .. PS.target.DisplayName) or "TARGET: NONE (CLICK SELECT)"
        local targetBtn = Instance.new("TextButton", main)
        targetBtn.Size, targetBtn.Position, targetBtn.Text = UDim2.new(1, -10, 0, 26), UDim2.new(0, 5, 0, 125), "FOLLOW TARGET: OFF"
        styleBtn(targetBtn)
        local hint = Instance.new("TextLabel", main)
        hint.Size, hint.Position = UDim2.new(1, -10, 0, 30), UDim2.new(0, 5, 0, 153)
        hint.BackgroundTransparency, hint.TextWrapped = 1, true
        hint.Text = "Target: TP instantaneo enquanto ele ESTA EM PE. Ele senta -> void (girando)."
        hint.TextColor3, hint.Font, hint.TextSize = Color3.fromRGB(200, 190, 150), Enum.Font.Code, 9
        hint.TextXAlignment = Enum.TextXAlignment.Left
        ui.selfBtn, ui.targetBtn, ui.targetBox = selfBtn, targetBtn, targetBox
        PS.setMode(PS.mode)
        connect()
        selfBtn.MouseButton1Click:Connect(function() PS.setMode((PS.mode == "SELF") and "OFF" or "SELF") end)
        targetBtn.MouseButton1Click:Connect(function()
            if PS.mode == "TARGET" then PS.setMode("OFF") elseif PS.target then PS.setMode("TARGET") end
        end)
        local selecting = false
        selectBtn.MouseButton1Click:Connect(function()
            selecting = not selecting
            selectBtn.Text = "CLICK SELECT: " .. (selecting and "ON" or "OFF")
            selectBtn.TextColor3 = selecting and YELLOW or TXT
        end)
        local mouse = LP:GetMouse()
        UIS.InputBegan:Connect(function(input, gp)
            if gp or not selecting or not sg.Parent then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            task.spawn(function()
                RS.RenderStepped:Wait()
                local node, plr = mouse.Target, nil
                while node and node ~= workspace do
                    plr = Players:GetPlayerFromCharacter(node)
                    if plr then break end
                    node = node.Parent
                end
                if not plr or plr == LP then PS.setTarget(nil) else PS.setTarget(plr) end
            end)
        end)
    end
end

-- ================================================================
-- INVISIBLE FLY (portado, sem links) — GTA_PL.INV.open()
-- ================================================================
GTA_PL.INV = {}
do
function GTA_PL.INV.open()
    if GTA_PL.INV.api then return GTA_PL.INV.api end
    --==============================================================
    -- SERVICES
    --==============================================================
    local Players          = game:GetService("Players")
    local TweenService     = game:GetService("TweenService")
    local UserInputService = game:GetService("UserInputService")
    local RunService       = game:GetService("RunService")

    local LocalPlayer = Players.LocalPlayer
    local PlayerGui   = LocalPlayer:WaitForChild("PlayerGui")
    local Camera      = workspace.CurrentCamera or workspace:WaitForChild("CurrentCamera")

    for _, name in ipairs({ "InvisibleUI", "FEInvisiblegg", "FEInvisibleGuigg", "FEInvisibleGuiGGX", "FEInvisibleGuiGGXSphereLayer" }) do
        local old = PlayerGui:FindFirstChild(name)
        if old then old:Destroy() end
    end

    --==============================================================
    -- CONFIGURATION & THEME
    --==============================================================
    local CONFIG = {
        Title              = "GTA Invisible Fly <font color='#FFD700'>Alpha</font>",
        Author             = "Author: GTA",
        PanelWidth         = 220,
        PanelHeight        = 176,
        HeaderHeight       = 38,
        SphereSize         = 34,
        SphereTransparency = 0.40,
        SphereDisplayOrder = 32767,
        SphereZIndex       = 10000,
        FlySpeed           = 200, -- studs/s, fly starts at this speed
    }

    local Theme = {
        Panel         = Color3.fromRGB(19, 20, 25),
        PanelBorder   = Color3.fromRGB(54, 58, 70),
        Card          = Color3.fromRGB(27, 29, 35),
        CardBorder    = Color3.fromRGB(46, 49, 59),
        Divider       = Color3.fromRGB(40, 43, 52),
        TextPrimary   = Color3.fromRGB(238, 240, 246),
        TextSecondary = Color3.fromRGB(126, 131, 146),
        Button        = Color3.fromRGB(35, 37, 45),
        ButtonHover   = Color3.fromRGB(50, 53, 65),
        Icon          = Color3.fromRGB(198, 203, 216),
        IconHover     = Color3.fromRGB(255, 255, 255),
        CloseHover    = Color3.fromRGB(206, 62, 78),
        Accent        = Color3.fromRGB(92, 126, 255),
        AccentGlow    = Color3.fromRGB(140, 166, 255),
        TrackOff      = Color3.fromRGB(48, 51, 60),
        TrackBorder   = Color3.fromRGB(66, 70, 82),
        TrackDisabled = Color3.fromRGB(34, 36, 42),
        KnobOff       = Color3.fromRGB(176, 182, 196),
        KnobOn        = Color3.fromRGB(255, 255, 255),
        KnobDisabled  = Color3.fromRGB(80, 84, 96),
        Overlay       = Color3.fromRGB(8, 9, 12),
        Popup         = Color3.fromRGB(30, 32, 39),
        PopupBorder   = Color3.fromRGB(62, 66, 80),
        Danger        = Color3.fromRGB(206, 62, 78),
        DangerHover   = Color3.fromRGB(232, 84, 100),
        Neutral       = Color3.fromRGB(42, 45, 55),
        NeutralHover  = Color3.fromRGB(58, 62, 75),
        SphereTop     = Color3.fromRGB(48, 51, 62),
        SphereBottom  = Color3.fromRGB(18, 20, 26),
        SphereStroke  = Color3.fromRGB(145, 154, 180),
    }

    local TWEEN = {
        Toggle   = 0.18,
        Minimize = 0.30,
        Restore  = 0.34,
        Popup    = 0.24,
        Hover    = 0.15,
        Press    = 0.09,
    }

    --==============================================================
    -- STATE
    --==============================================================
    local State = {
        Invisible = false,   -- the original Invisible toggle (unchanged behaviour)
        Fly       = false,
        NC        = false,
        Minimized = false,
        PopupOpen = false,
        BaseScale = 1,
    }

    local PositionState = {
        Main              = UDim2.fromScale(0.5, 0.5),
