    -- ===== CASCA — troll em baixo das seções de prop/invisível =====
    do
    local okB, errB = pcall(function(TabB)
        local Plrs = game:GetService("Players")
        local RunS = game:GetService("RunService")
        local RStor = game:GetService("ReplicatedStorage")
        local LP = Plrs.LocalPlayer
        local TOOL = "Minions2026_BananaPeel"
        local target, on, gen, conn, savedCF = nil, false, 0, nil, nil
        local depth, leadTenths = 15, 6
        local autoRec, recovering = true, false

        TabB:AddSection({Name = "Casca"})
        TabB:AddParagraph({
            Title = "Casca",
            Text = "Pega a casca se você não tiver, fica embaixo do chão (o alvo não te vê) e planta cascas no alvo sem parar. Parado: na posição dele. Andando: um pouco à frente, conforme a velocidade."
        })
        local dd = TabB:AddDropdown({
            Name = "Casca: player alvo",
            Options = {},
            Default = "",
            Callback = function(v)
                local p = Plrs:FindFirstChild(tostring(v or ""))
                if p and not GTA_PL.guardPlayer(p) then target = nil return end
                target = p
            end,
        })
        pcall(function() GTA_PL.track(dd, false) end)
        TabB:AddSlider({Name = "Profundidade embaixo do chão", Min = 5, Max = 60, Increase = 1, Default = 15, Callback = function(v) depth = tonumber(v) or 15 end})
        TabB:AddSlider({Name = "Antecipação quando o alvo anda (décimos de segundo)", Min = 0, Max = 20, Increase = 1, Default = 6, Callback = function(v) leadTenths = tonumber(v) or 6 end})

        TabB:AddToggle({
            Name = "Auto-recuperar (se a casca sumir: volta pro lugar, pega de novo e desce)",
            Default = true,
            Callback = function(v) autoRec = v end,
        })

        local function getTool()
            local ch = LP.Character
            local bp = LP:FindFirstChildOfClass("Backpack")
            return (ch and ch:FindFirstChild(TOOL)) or (bp and bp:FindFirstChild(TOOL))
        end
        local function ensureTool()  -- vê se já tem; se não tem, pega; depois equipa
            local t = getTool()
            if not t then
                pcall(function() RStor.RE:FindFirstChild("1Too1l"):InvokeServer("PickingTools", TOOL) end)
                for _ = 1, 30 do
                    t = getTool()
                    if t then break end
                    task.wait(0.1)
                end
            end
            if not t then return nil end
            local ch = LP.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if hum and t.Parent ~= ch then
                pcall(function() hum:EquipTool(t) end)
                task.wait(0.2)
            end
            return ch and ch:FindFirstChild(TOOL)
        end
        local function stop()
            on = false
            recovering = false
            gen = gen + 1
            if conn then conn:Disconnect() conn = nil end
            local r = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if r and savedCF then r.CFrame = savedCF end
            savedCF = nil
        end

        TabB:AddToggle({
            Name = "Casca infinita no alvo (embaixo do chão)",
            Default = false,
            Callback = function(v)
                if not v then stop() return end
                if not target or not target.Parent then
                    pcall(function() GTA_PL.toast("escolhe o 'Casca: player alvo' antes", Color3.fromRGB(220, 80, 80)) end)
                    return
                end
                if not GTA_PL.guardPlayer(target) then return end
                stop()
                on = true
                gen = gen + 1
                local mine = gen
                task.spawn(function()
                    local tool = ensureTool()
                    if not tool then
                        pcall(function() GTA_PL.toast("não consegui pegar a casca", Color3.fromRGB(220, 80, 80)) end)
                        if gen == mine then on = false end
                        return
                    end
                    if gen ~= mine then return end
                    local r0 = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                    if not r0 then return end
                    savedCF = r0.CFrame
                    local lastPlace, lastEnsure = 0, 0
                    conn = RunS.Heartbeat:Connect(function()
                        if not on or gen ~= mine then return end
                        local p = target
                        if not (p and p.Parent) or not GTA_PL.canHit(p) then stop() return end
                        local tch = p.Character
                        local tr = tch and tch:FindFirstChild("HumanoidRootPart")
                        local mych = LP.Character
                        local mr = mych and mych:FindFirstChild("HumanoidRootPart")
                        if not (tr and mr) then return end
                        local rp = RaycastParams.new()
                        rp.FilterType = Enum.RaycastFilterType.Exclude
                        rp.FilterDescendantsInstances = {tch, mych}
                        local hit = workspace:Raycast(tr.Position, Vector3.new(0, -80, 0), rp)
                        local gy = hit and hit.Position.Y or (tr.Position.Y - 3)
                        local vel = tr.AssemblyLinearVelocity
                        local flat = Vector3.new(vel.X, 0, vel.Z)
                        local pos = tr.Position
                        local place
                        if flat.Magnitude < 2 then
                            place = Vector3.new(pos.X, gy, pos.Z)  -- parado: onde ele está
                        else
                            local lead = leadTenths / 10
                            place = Vector3.new(pos.X + flat.X * lead, gy, pos.Z + flat.Z * lead)  -- andando: mais à frente
                        end
                        local now = tick()
                        if autoRec and not mych:FindFirstChild(TOOL) then
                            -- a banana sumiu: volta pra onde eu estava (em cima do chão) e espera pegar a tool de novo
                            if savedCF then
                                mr.CFrame = savedCF
                                mr.AssemblyLinearVelocity = Vector3.zero
                            end
                            if not recovering and now - lastEnsure > 1 then
                                recovering = true
                                lastEnsure = now
                                task.spawn(function()
                                    ensureTool()
                                    recovering = false
                                end)
                            end
                            return
                        end
                        mr.CFrame = CFrame.new(pos.X, gy - depth, pos.Z)  -- embaixo do alvo, sempre
                        mr.AssemblyLinearVelocity = Vector3.zero
                        if now - lastPlace >= 0.08 then
                            lastPlace = now
                            local t = mych:FindFirstChild(TOOL)
                            local ev = t and t:FindFirstChild("PlaceBananaPeel")
                            if ev then
                                pcall(function() ev:FireServer(place) end)
                            elseif now - lastEnsure > 1.5 then  -- morreu/perdeu a tool: pega de novo
                                lastEnsure = now
                                task.spawn(ensureTool)
                            end
                        end
                    end)
                end)
            end,
        })
        TabB:AddButton({Name = "Parar casca e voltar pro lugar", Callback = stop})
    end, Troll)
    if not okB then warn("[GTA Hub] Casca: " .. tostring(errB)) end
