    local function GTA_canHit(p)
        if typeof(p) ~= "Instance" or p == LocalPlayer then return false end
        local ok1, res = pcall(function() return rawget(_G, "GTA_PL").canHit(p) end)
        return ok1 and res == true
    end
    local function GTA_hittable()
        local out = {}
        for _, p in ipairs(Players:GetPlayers()) do if GTA_canHit(p) then out[#out + 1] = p end end
        return out
    end
    local function GTA_target(name)
        local p = Players:FindFirstChild(tostring(name or ""))
        if p and GTA_canHit(p) then return p end
        return nil
    end

    local T = TabX
    local RE = ReplicatedStorage:WaitForChild("RE")
    local selBan, banOn = nil, false
