    T:AddButton({Name = "Atualizar lista", Callback = function()
        local l = {}
        for _, p in ipairs(GTA_hittable()) do l[#l + 1] = p.Name end
        banDD:Set(l)
    end})
    T:AddToggle({Name = "Auto Banimento", Default = false, Callback = function(v)
        banOn = v
        if not v then return end
        task.spawn(function()
            while banOn do
                if selBan and selBan.Parent then
                    local lots = workspace:FindFirstChild("001_Lots")
                    if lots then
                        for _, casa in ipairs(lots:GetChildren()) do
                            local pick = casa:FindFirstChild("HousePickedByPlayer")
                            local hm = pick and pick:FindFirstChild("HouseModel")
                            local perm = hm and hm:FindFirstChild("Permissions:Disallow")
                            if perm then pcall(function() perm:FireServer(selBan) end) end
                        end
                    end
                end
                task.wait(1)
            end
        end)
    end})
    T:AddSection({"Repetir nome da casa (King)"})
    local n1, n2, n3, rep = "", "", "", false
    T:AddTextBox({Name = "Nome 1", PlaceholderText = "Nick Casa", Callback = function(v) n1 = v or "" end})
