    T:AddTextBox({Name = "Nome 3", PlaceholderText = "Nick Casa", Callback = function(v) n3 = v or "" end})
    T:AddToggle({Name = "Repetir nome da casa", Default = false, Callback = function(v)
        rep = v
        if not v then return end
        task.spawn(function()
            local r = RE:FindFirstChild("1RPHous1eEven1t")
            while rep do
                if r then
                    for _, n in ipairs({n1, n2, n3}) do
                        if not rep then break end
                        pcall(function() r:FireServer("BusinessName", n) end)
                        task.wait(1)
                    end
                else
                    task.wait(1)
                end
            end
        end)
    end})

end, HouseTab)
