                    for _, o in ipairs(workspace:GetDescendants()) do killIf(o) end
                    local f = workspace:FindFirstChild("Audio all client")
                    if f then pcall(function() f:Destroy() end) end
                    task.wait(2)
                end
            end)
        end
    end})

