-- Variáveis globais
local pl = game.Players.LocalPlayer
local players = {}

-- Função para atualizar a lista de players
local function updatePlayerList()
    players = {}
    for _, player in pairs(GTA_PL.filter(game.Players:GetPlayers())) do
        table.insert(players, player.Name)
    end
    return players
end

-- Inicializa a lista de players
updatePlayerList()

-- Aba Child
do
local okK, errK = pcall(function(TabX)

    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local Workspace = game:GetService("Workspace")
    local UserInputService = game:GetService("UserInputService")
    local HttpService = game:GetService("HttpService")
    local Camera = workspace.CurrentCamera
    local Translator = {traduzir = function(_, s) return s end}
    local function GTA_canHit(p)
        if typeof(p) ~= "Instance" or p == LocalPlayer then return false end
        local ok1, res = pcall(function() return rawget(_G, "GTA_PL").canHit(p) end)
        return ok1 and res == true
    end
    local function GTA_hittable()
        local out = {}
        for _, p in ipairs(Players:GetPlayers()) do if GTA_canHit(p) then out[#out + 1] = p end end
        return out
    end
    local function GTA_target(name)
        local p = Players:FindFirstChild(tostring(name or ""))
        if p and GTA_canHit(p) then return p end
        return nil
    end

    local T = TabX
    local RE = ReplicatedStorage:WaitForChild("RE")
    local function names(list) local o = {} for _, e in ipairs(list) do o[#o + 1] = e[1] end return o end
    local function lookup(list, key) for _, e in ipairs(list) do if e[1] == key then return e[2] end end end
    local function vehicles()
        local l = {}
        local v = workspace:FindFirstChild("Vehicles")
        if v then for _, c in ipairs(v:GetChildren()) do l[#l + 1] = c.Name end end
        return l
    end
    local function seatOf(veh)
        local body = veh and veh:FindFirstChild("Body")
        if not body then return nil end
        for _, n in ipairs({"VehicleSeat", "CarSeatPosition", "Passenger"}) do
            local s = body:FindFirstChild(n)
            if s and s:IsA("BasePart") then return s end
        end
        return nil
    end
    local selVeh
    local carDD
    T:AddSection({"Carro selecionado (King)"})
    carDD = T:AddDropdown({Name = "Selecione um carro", Options = vehicles(), Default = "Carros", Callback = function(v) selVeh = v end})
    T:AddButton({Name = "Atualizar lista de carros", Callback = function() carDD:Set(vehicles()) end})
    T:AddButton({Name = "Teleportar ao assento", Callback = function()
        local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        local veh = selVeh and workspace:FindFirstChild("Vehicles") and workspace.Vehicles:FindFirstChild(selVeh)
        local seat = seatOf(veh)
        if root and seat then root.CFrame = seat.CFrame + Vector3.new(0, 3, 0) end
    end})
    T:AddButton({Name = "Puxar o carro até mim", Callback = function()
        local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        local veh = selVeh and workspace:FindFirstChild("Vehicles") and workspace.Vehicles:FindFirstChild(selVeh)
        local seat = seatOf(veh)
        if not (root and veh and seat) then return end
        local home = root.CFrame
        root.CFrame = seat.CFrame
        task.wait(0.8)
        if veh.PrimaryPart then veh:SetPrimaryPartCFrame(home) else veh:MoveTo(home.Position) end
        root.CFrame = home
    end})

    local espOn, espConns = false, {}
    local function clearESP()
        for _, c in ipairs(espConns) do pcall(function() c:Disconnect() end) end
        espConns = {}
        local v = workspace:FindFirstChild("Vehicles")
        if v then for _, car in ipairs(v:GetChildren()) do local e = car:FindFirstChild("GTA_ESP") if e then e:Destroy() end end end
    end
    T:AddToggle({Name = "ESP de carros", Default = false, Callback = function(on)
        espOn = on
        clearESP()
        if not on then return end
        local v = workspace:FindFirstChild("Vehicles")
        if not v then return end
        for _, car in ipairs(v:GetChildren()) do
            local part = car.PrimaryPart or car:FindFirstChildWhichIsA("BasePart", true)
            if part and not car:FindFirstChild("GTA_ESP") then
                local bb = Instance.new("BillboardGui")
                bb.Name = "GTA_ESP"
                bb.Size = UDim2.new(0, 160, 0, 30)
                bb.AlwaysOnTop = true
                bb.Adornee = part
                local tl = Instance.new("TextLabel", bb)
