                tl.BackgroundTransparency = 1
                tl.TextColor3 = Color3.fromRGB(255, 60, 60)
                tl.TextStrokeTransparency = 0
                tl.TextScaled = true
                bb.Parent = car
                espConns[#espConns + 1] = RunService.RenderStepped:Connect(function()
                    local me = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if espOn and me and part.Parent then
                        tl.Text = car.Name .. " | " .. math.floor((me.Position - part.Position).Magnitude) .. " studs"
                    end
                end)
            end
        end
    end})

