    local selSound, delay, loop, muteSelf = SOUNDS[1][1], 0.5, false, false

    local function playOn(id, where)
        id = tostring(id or "")
        if id == "" then return end
        if where == "Boombox" then
            if not findTool("Boombox") then getTool("Boombox") task.wait(0.4) end
            local bx = findTool("Boombox"); local h = hum()
            if bx and h and bx.Parent ~= char() then h:EquipTool(bx) task.wait(0.2) end
            pcall(function() RE.PlayerToolEvent:FireServer("ToolMusicText", id) end)
        elseif where == "Scooter" then
            pcall(function() RE["1NoMoto1rVehicle1s"]:FireServer("PickingScooterMusicText", id) end)
        elseif where == "Carro" then
            pcall(function() RE["1Player1sCa1r"]:FireServer("PickingCarMusicText", id) end)
        elseif where == "Casa" then
            pcall(function() RE["1Player1sHous1e"]:FireServer("PickHouseMusicText", id) end)
        end
