    T:AddTextBox({Name = "ID Customizado", PlaceholderText = "ID da música (opcional)", Callback = function(v) customId = v or "" end})
    T:AddDropdown({Name = "Tocar em", Options = {"Boombox", "Scooter", "Carro", "Casa"}, Default = "Boombox", Callback = function(v) target = v end})
    T:AddButton({Name = "Tocar", Callback = function()
