        task.spawn(playOn, id, target)
    end})
    T:AddButton({Name = "Parar tudo", Callback = function()
        for _, w in ipairs({"Boombox", "Scooter", "Carro", "Casa"}) do task.spawn(playOn, "0", w) end
    end})

    T:AddSection({"Sound Board (todos ouvem pela Boombox)"})
    T:AddDropdown({Name = "Sound board", Options = names(SOUNDS), Default = selSound, Callback = function(v) selSound = v end})
    T:AddTextBox({Name = "Delay (segundos)", PlaceholderText = "0.5", Callback = function(v) delay = math.max(0.1, tonumber(v) or 0.5) end})
    T:AddToggle({Name = "Mutar pra mim", Default = false, Callback = function(v) muteSelf = v end})
    local function playSound()
        task.spawn(playOn, lookup(SOUNDS, selSound), "Boombox")
        if muteSelf then
            task.spawn(function()
                for _ = 1, 20 do
                    for _, o in ipairs(char():GetDescendants()) do
                        if o:IsA("Sound") then o.Volume = 0 end
                    end
                    task.wait(0.1)
                end
            end)
        end
    end
    T:AddButton({Name = "Tocar sound board", Callback = playSound})
    local looping = false
    T:AddToggle({Name = "Loop do sound board", Default = false, Callback = function(v)
        looping = v
        if v then task.spawn(function() while looping do playSound() task.wait(delay) end end) end
    end})
end

