    T:AddToggle({Name = "Nome: Gradiente", Default = false, Callback = function(v)
        nG.on = v nG.speed = gradSpeed
        if v then colorLoop(nG, "PickingRPNameColor", grad) end
    end})
    T:AddToggle({Name = "Bio: Gradiente", Default = false, Callback = function(v)
        bG.on = v bG.speed = gradSpeed
        if v then colorLoop(bG, "PickingRPBioColor", grad) end
    end})
end

