-- ---------------------------------------------------------------- PROPS+ (auras)
local function tabProps()
    local T = ActiveWindow:MakeTab({Title = "Props+", Icon = "box"})
    local PROPS = {
        {"Blocos", {"QuarterFloor", "Building"}}, {"Bunkers", {"BigGunBunker", "Building"}},
        {"Fogo", {"TorchFireLong", "Torch"}}, {"Luzes", {"DanceMachineCouple", "Lights"}},
        {"Boneco de Neve", {"ChristmasSnowman", "Christmas"}}, {"Trampolim", {"Summer2026Trampoline", "Carnival"}},
        {"Cavalo", {"HorseBigBrown", "Horse"}},
    }
    local propSel, count, speed, radius, height, mode, onSelf, targetName = PROPS[1][1], 8, 2, 8, 3, "Orbit", true, nil
    local running = false

    local function myProps()
        local out = {}
        local f = WS:FindFirstChild("WorkspaceCom") and WS.WorkspaceCom:FindFirstChild("001_TrafficCones")
        if not f then return out end
        for _, p in ipairs(f:GetChildren()) do
            if p.Name == "Prop" .. LP.Name then out[#out + 1] = p end
        end
        return out
    end
    local function spawnProps()
        local def = lookup(PROPS, propSel); if not def then return end
        local c = char(); local r = hrp(); local h = hum(); if not (c and r and h) then return end
        local home = r.CFrame
        pcall(function() RE["1Clea1rTool1s"]:FireServer("ClearAllProps") end)
        task.wait(0.8)
        if not findTool("PropMaker") then getTool("PropMaker") task.wait(0.5) end
        local pm = findTool("PropMaker"); if pm then h:EquipTool(pm) end
        task.wait(0.4)
        pcall(function() RE["1Clea1rTool1s"]:FireServer("RequestingPropName", def[1], def[2]) end)
        task.wait(0.4)
        for _ = 1, count do
            if not running then break end
            local t = c:FindFirstChild("PropMaker") and c.PropMaker:FindFirstChild("Tool_PropMake")
            if t then pcall(function() t:FireServer(WS:FindFirstChild("Model") and WS.Model:FindFirstChild("CornerHills"), home.Position) end) end
            task.wait(0.9)
        end
        r.CFrame = home
    end
    local function targetRoot()
        if onSelf then return hrp() end
        local p = targetName and Plrs:FindFirstChild(targetName)
        return p and p.Character and p.Character:FindFirstChild("HumanoidRootPart")
    end
    local function offsetFor(i, n, t)
        local a = (i / n) * math.pi * 2
        if mode == "Orbit" then
            return CFrame.new(math.cos(a + t * speed) * radius, height, math.sin(a + t * speed) * radius)
        elseif mode == "Tornado" then
            local k = i / n
            local rr = radius * (0.3 + k)
            return CFrame.new(math.cos(a * 2 + t * speed * 2) * rr, height * 2 * k * 3, math.sin(a * 2 + t * speed * 2) * rr)
        elseif mode == "Wings" then
            local side = (i % 2 == 0) and 1 or -1
            local k = math.ceil(i / 2) / math.ceil(n / 2)
            return CFrame.new(side * (2 + k * radius * 0.6), height + math.sin(t * speed * 3 + k * 2) * 2, 1.5 + k * 1.5)
        elseif mode == "Stars" then
            local rr = radius * (0.6 + 0.4 * math.sin(t * speed + i))
            return CFrame.new(math.cos(a - t * speed) * rr, height + math.sin(t * speed * 2 + i) * 1.5, math.sin(a - t * speed) * rr)
        elseif mode == "Cobra" then
            return CFrame.new(math.sin(t * speed * 2 + i * 0.5) * 3, height + i * 1.2, -2 - i * 0.6)
        else -- Portal
            return CFrame.new(0, height + math.sin(a) * radius * 0.6, -radius + math.cos(a) * radius * 0.6) * CFrame.Angles(0, 0, t * speed)
        end
    end
    local function loop()
        local t0 = tick()
        while running do
            local root = targetRoot()
            local ps = myProps()
            if root and #ps > 0 then
                for i, p in ipairs(ps) do
                    local sc = p:FindFirstChild("SetCurrentCFrame")
                    if sc then
                        local cf = (root.CFrame + (onSelf and Vector3.new() or GTA_PL.predictLead(root))) * offsetFor(i, #ps, tick() - t0)
                        task.spawn(function() pcall(function() sc:InvokeServer(cf) end) end)
                    end
                end
            end
            task.wait(0.1)
        end
    end

    T:AddSection({"Aura de Props"})
    T:AddDropdown({Name = "Prop", Options = names(PROPS), Default = propSel, Callback = function(v) propSel = v end})
    T:AddDropdown({Name = "Aura", Options = {"Orbit", "Tornado", "Wings", "Stars", "Cobra", "Portal"}, Default = "Orbit", Callback = function(v) mode = v end})
    T:AddSlider({Name = "Quantidade", Min = 2, Max = 15, Increase = 1, Default = 8, Callback = function(v) count = v end})
    T:AddSlider({Name = "Velocidade", Min = 1, Max = 10, Increase = 1, Default = 2, Callback = function(v) speed = v end})
    T:AddSlider({Name = "Raio", Min = 3, Max = 25, Increase = 1, Default = 8, Callback = function(v) radius = v end})
    T:AddSlider({Name = "Altura", Min = -5, Max = 15, Increase = 1, Default = 3, Callback = function(v) height = v end})
    T:AddToggle({Name = "Em mim", Default = true, Callback = function(v) onSelf = v end})
    local dd = T:AddDropdown({Name = "Em outro player", Options = {}, Default = "", Callback = function(v) targetName = v onSelf = false end})
    pcall(function() if GTA_PL then GTA_PL.track(dd, false) end end)
    T:AddToggle({Name = "Ligar aura", Default = false, Callback = function(v)
        running = v
        if v then task.spawn(function() spawnProps() if running then loop() end end) end
    end})
    T:AddButton({Name = "Limpar todos os props", Callback = function()
        running = false
        pcall(function() RE["1Clea1rTool1s"]:FireServer("ClearAllProps") end)
    end})
end

-- ---------------------------------------------------------------- PROTEÇÃO + SCRIPTS
local function tabProtect()
    local T = ActiveWindow:MakeTab({Title = "Proteção+", Icon = "shield"})
    local conn
    T:AddSection({"Anti-Fling"})
    T:AddToggle({Name = "Anti-Fling (sem colisão + sem velocidade absurda)", Default = false, Callback = function(v)
        if conn then conn:Disconnect() conn = nil end
        if v then
            conn = RunS.Stepped:Connect(function()
                for _, p in ipairs(Plrs:GetPlayers()) do
                    if p ~= LP and p.Character then
                        for _, part in ipairs(p.Character:GetChildren()) do
                            if part:IsA("BasePart") then part.CanCollide = false end
                        end
                    end
                end
                local r = hrp()
                if r then
                    if r.AssemblyLinearVelocity.Magnitude > 120 then r.AssemblyLinearVelocity = Vector3.zero end
                    if r.AssemblyAngularVelocity.Magnitude > 60 then r.AssemblyAngularVelocity = Vector3.zero end
                end
            end)
        end
    end})

    local S = ActiveWindow:MakeTab({Title = "Scripts+", Icon = "scroll"})
    S:AddSection({"Desempenho"})
    S:AddButton({Name = "FPS Booster (nativo GTA)", Callback = function()
        pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
        local L = game:GetService("Lighting")
        L.GlobalShadows = false L.FogEnd = 9e9
        for _, o in ipairs(L:GetChildren()) do
            if o:IsA("BlurEffect") or o:IsA("SunRaysEffect") or o:IsA("BloomEffect") or o:IsA("DepthOfFieldEffect") or o:IsA("ColorCorrectionEffect") then o.Enabled = false end
        end
        for _, o in ipairs(WS:GetDescendants()) do
            if o:IsA("ParticleEmitter") or o:IsA("Trail") or o:IsA("Smoke") or o:IsA("Fire") or o:IsA("Sparkles") then o.Enabled = false
            elseif o:IsA("Decal") or o:IsA("Texture") then o.Transparency = 1
            elseif o:IsA("BasePart") then o.Material = Enum.Material.SmoothPlastic o.CastShadow = false end
        end
        note("GTA Hub", "FPS Booster aplicado")
    end})
end

-- ---------------------------------------------------------------- EXTRAS (bombas, glue, anti-fling, shift lock, shaders, partes, telekinesis)
local function tabExtras()
    local TP = ActiveWindow:MakeTab({Title = "Troll Players", Icon = "🎯"})
    local PR = ActiveWindow:MakeTab({Title = "Proteção+", Icon = "shield"})
    local SU = ActiveWindow:MakeTab({Title = "Scripts Universais", Icon = "plane"})

    -- Bombas (a bomba é pega no ClickDetector da loja criminal, explode pelo remote do próprio jogo)
    local bombAmount = 5
    local function bombPart()
        local ok, b = pcall(function() return WS.WorkspaceCom["001_CriminalWeapons"].GiveTools.Bomb end)
        return ok and b or nil
    end
    local function collectBombs(n)
        local r, b = hrp(), bombPart()
        if not (r and b) then note("GTA Hub", "Bomba não encontrada") return end
        local home = r.CFrame
        for _ = 1, n do
            r.CFrame = b.CFrame
            pcall(function() fireclickdetector(b.ClickDetector) end)
            task.wait(0.15)
        end
        r.CFrame = home
    end
    local function explodeBombs(n)
        for _ = 1, n do
            pcall(function() RE["1Blo1wBomb1sServe1r"]:FireServer("Bomb" .. LP.Name) end)
            task.wait(0.2)
        end
    end
    TP:AddSection({"Bombas"})
    TP:AddSlider({Name = "Quantidade de bombas", Min = 1, Max = 30, Increase = 1, Default = 5, Callback = function(v) bombAmount = v end})
    TP:AddButton({Name = "Collect Bombs", Callback = function() task.spawn(collectBombs, bombAmount) end})
    TP:AddButton({Name = "Explode Bombs", Callback = function() task.spawn(explodeBombs, bombAmount) end})
    TP:AddButton({Name = "Spam Bombs (pega e explode)", Callback = function()
        task.spawn(function() collectBombs(bombAmount) explodeBombs(bombAmount) end)
    end})

    -- Tornado de veículo (qualquer veículo em que você estiver sentado)
