                    root.AssemblyAngularVelocity = Vector3.new(0, 60, 0)
                    root.AssemblyLinearVelocity = Vector3.new(lv.X * 0.5, 20 + 25 * math.sin(tick() * 3), lv.Z * 0.5)
                end
                task.wait()
            end
