    -- Ataques com Prop: os props nascem com o teu nome em WorkspaceCom.001_TrafficCones e são movidos pelo SetCurrentCFrame
    local PA = {sel = nil, running = false, count = 8}
    local VOID = CFrame.new(5000000, -9999999, -5000000)
    local function myProps()
        local out = {}
        local f = WS:FindFirstChild("WorkspaceCom") and WS.WorkspaceCom:FindFirstChild("001_TrafficCones")
        if f then
            for _, p in ipairs(f:GetChildren()) do
                if p.Name:find("Prop" .. LP.Name, 1, true) and p:FindFirstChild("SetCurrentCFrame") then out[#out + 1] = p end
            end
        end
        return out
    end
    local function sendCF(p, cf)
        local sc = p:FindFirstChild("SetCurrentCFrame")
        if sc then task.spawn(function() pcall(function() sc:InvokeServer(cf) end) end) end
    end
    local function ensureProps()
        if #myProps() >= PA.count then return myProps() end
        local c, r, h = char(), hrp(), hum()
        if not (c and r and h) then return {} end
        local home = r.CFrame
        pcall(function() RE["1Clea1rTool1s"]:FireServer("ClearAllProps") end)
        task.wait(0.8)
        if not findTool("PropMaker") then getTool("PropMaker") task.wait(0.5) end
        local pm = findTool("PropMaker"); if pm then h:EquipTool(pm) end
        task.wait(0.4)
        pcall(function() RE["1Clea1rTool1s"]:FireServer("RequestingPropName", "BigGunBunker", "Big") end)
        task.wait(0.4)
        for _ = 1, PA.count do
            if not PA.running then break end
            local t = c:FindFirstChild("PropMaker") and c.PropMaker:FindFirstChild("Tool_PropMake")
            if t then pcall(function() t:FireServer(WS:FindFirstChild("Model") and WS.Model:FindFirstChild("CornerHills"), home.Position) end) end
            task.wait(0.9)
        end
        r.CFrame = home
        return myProps()
    end
    local function targetRoot()
        local p = PA.sel and Plrs:FindFirstChild(PA.sel)
        if p and not GTA_PL.canHit(p) then return nil end
        return p and p.Character and p.Character:FindFirstChild("HumanoidRootPart")
    end
    -- gira os props MUITO rápido em volta do alvo (órbita + rotação nos 3 eixos)
    local function spin(props, getRoot, dur, radius)
        local t0 = tick()
        while PA.running and (dur == nil or tick() - t0 < dur) do
            local tr = getRoot()
            if tr then
                local tpos = tr.Position
                if getRoot ~= hrp then tpos = tpos + GTA_PL.predictLead(tr) end  -- previsão no alvo (não em você)
                local t = tick() - t0
                for i, p in ipairs(props) do
                    local a = (i / #props) * math.pi * 2 + t * 40
                    local pos
                    if radius <= 0 then  -- DENTRO do alvo: treme minúsculo no centro dele, só a rotação é absurda
                        pos = tpos + Vector3.new(math.sin(t * 50 + i) * 0.4, math.sin(t * 37 + i) * 0.4, math.cos(t * 43 + i) * 0.4)
                    else
                        pos = tpos + Vector3.new(math.cos(a) * radius, math.sin(t * 25 + i) * 2, math.sin(a) * radius)
                    end
                    sendCF(p, CFrame.new(pos) * CFrame.Angles(t * 90 + i, t * 70, t * 110))
                end
            end
            RunS.Heartbeat:Wait()
        end
    end
    local function run(job)
        if PA.running then PA.running = false task.wait(0.3) end
        PA.running = true
        task.spawn(function()
            local props = ensureProps()
            if #props == 0 then note("GTA Hub", "Não consegui spawnar props") PA.running = false return end
            pcall(job, props)
            PA.running = false
        end)
    end
    local function stopAll()
        PA.running = false
        pcall(function() RE["1Clea1rTool1s"]:FireServer("ClearAllProps") end)
    end
    TP:AddSection({"Ataques com Prop"})
    local pdd = TP:AddDropdown({Name = "Prop: player alvo", Options = {}, Default = "", Callback = function(v) PA.sel = v end})
    pcall(function() if GTA_PL then GTA_PL.track(pdd, false) end end)
    TP:AddSlider({Name = "Props por ataque", Min = 3, Max = 15, Increase = 1, Default = 8, Callback = function(v) PA.count = v end})
    TP:AddToggle({Name = "Fling com Prop (girar dentro do alvo)", Default = false, Callback = function(v)
        if not v then stopAll() return end
        run(function(props) spin(props, targetRoot, nil, 0) end)
    end})
    TP:AddToggle({Name = "Fling com Prop (vibrar dentro do alvo)", Default = false, Callback = function(v)
        if not v then stopAll() return end
        run(function(props)
            while PA.running do
                local tr = targetRoot()
                if tr then
                    for _, p in ipairs(props) do
                        local t = tick()
                        sendCF(p, CFrame.new(tr.Position + GTA_PL.predictLead(tr) + Vector3.new(math.random(-8, 8) / 10, math.random(-8, 8) / 10, math.random(-8, 8) / 10)) * CFrame.Angles(t * 90, t * 70, t * 110))
                    end
                end
                task.wait(0.05)
            end
        end)
    end})
    TP:AddToggle({Name = "Fling Aura (joga todo mundo perto de você)", Default = false, Callback = function(v)
        if not v then stopAll() return end
        run(function(props) spin(props, hrp, nil, 7) end)
    end})
    TP:AddButton({Name = "Flingar player escolhido", Callback = function()
        if not targetRoot() then note("GTA Hub", "Escolha um player em 'Prop: player alvo'") return end
        run(function(props)
            spin(props, targetRoot, 4, 0)
            stopAll()
        end)
    end})
    local function doKillProp()
        run(function(props)
            spin(props, targetRoot, 2.5, 3)
            for _ = 1, 15 do
                for _, p in ipairs(props) do sendCF(p, VOID) end
                task.wait(0.1)
            end
            stopAll()
        end)
    end
    TP:AddButton({Name = "Kill com Prop (gira e manda pro void)", Callback = doKillProp})
    TP:AddButton({Name = "Bring com Prop (gira e traz até você)", Callback = function()
        run(function(props)
            spin(props, targetRoot, 1.5, 3)
            local t0 = tick()
            while PA.running and tick() - t0 < 2.5 do
                local r = hrp()
                if r then
                    for _, p in ipairs(props) do sendCF(p, r.CFrame * CFrame.new(0, 0, -4)) end
                end
                RunS.Heartbeat:Wait()
            end
            stopAll()
        end)
    end})
    local function doTrazer()
        run(function(props)
            local hadSeated, standSince = false, nil
            while PA.running do
                local pl = PA.sel and Plrs:FindFirstChild(PA.sel)
                local tr = targetRoot()
                local th = pl and pl.Character and pl.Character:FindFirstChildOfClass("Humanoid")
                local r = hrp()
                if not (tr and th and r) then break end
                if th.Sit then
                    hadSeated, standSince = true, nil
                    for _, p in ipairs(props) do sendCF(p, r.CFrame * CFrame.new(0, 0, -4)) end
                elseif not hadSeated then
                    for _, p in ipairs(props) do sendCF(p, tr.CFrame + GTA_PL.predictLead(tr)) end
                else
                    standSince = standSince or tick()
                    for _, p in ipairs(props) do sendCF(p, VOID) end
                    if tick() - standSince > 1.5 then break end
                end
                RunS.Heartbeat:Wait()
            end
            if PA.running then stopAll() end
        end)
    end
    TP:AddButton({Name = "Trazer player (sofá vai no alvo -> senta -> vem na tua frente -> levantou = void)", Callback = doTrazer})
    local function doFling()
        run(function(props)
            local up, last = false, tick()
            local ax, ay, az = 0, 0, 0  -- ângulos acumulados com dt: giro contínuo de verdade, sem estourar a precisão do double
            while PA.running do
                local now = tick(); local dt = math.min(now - last, 0.1); last = now
                local pl = PA.sel and Plrs:FindFirstChild(PA.sel)
                local tr = targetRoot()
                local th = pl and pl.Character and pl.Character:FindFirstChildOfClass("Humanoid")
                local r = hrp()
                if not (tr and th and r) then break end
                if th.Sit then up = true end
                ax = (ax + 90 * dt) % (2 * math.pi)  -- ~14 voltas/s em cada eixo, bem rápido
                ay = (ay + 70 * dt) % (2 * math.pi)
                az = (az + 110 * dt) % (2 * math.pi)
                if not up then
                    for i, p in ipairs(props) do sendCF(p, (tr.CFrame + GTA_PL.predictLead(tr)) * CFrame.new(math.sin(ax + i) * 1.5, 0, math.cos(ax + i) * 1.5) * CFrame.Angles(ax, ay, az)) end
                else
                    for i, p in ipairs(props) do sendCF(p, CFrame.new(r.Position.X + i * 0.4, 2500, r.Position.Z) * CFrame.Angles(ax, ay, az)) end
                end
                RunS.Heartbeat:Wait()
            end
            if PA.running then stopAll() end
        end)
    end
    TP:AddButton({Name = "Fling (vai no player girando, espera sentar, sobe e gira no topo)", Callback = doFling})
    TP:AddButton({Name = "Parar e limpar props", Callback = stopAll})
    GTA_PL.Actions = GTA_PL.Actions or {}
    GTA_PL.Actions.jail = doTrazer
    GTA_PL.Actions.kill = doKillProp
    GTA_PL.Actions.fling = doFling
    GTA_PL.Actions.stop = stopAll

    -- Misc: avisos de entrada/saída e memória de alvo
    local MI = ActiveWindow:MakeTab({Title = "Misc", Icon = "scroll"})
    MI:AddSection({Name = "Avisos de players"})
    MI:AddParagraph({Title = "Avisos", Text = "Os avisos aparecem no canto da tela mesmo com a UI do hub fechada."})
    MI:AddToggle({Name = "Avisar entrada e saída de players", Default = false, Callback = function(v) GTA_PL.cfg.notify = v end})
