        end})
        MI:AddButton({Name = "Save: Aplicar save agora", Callback = function()
            SV.apply()
            GTA_PL.toast("Save aplicado", Color3.fromRGB(90, 220, 120))
        end})
        MI:AddButton({Name = "Save: Apagar save", Callback = function()
            SV.clear()
            GTA_PL.toast("Save apagado", Color3.fromRGB(235, 80, 90))
        end})
    end

    -- Anti-fling extra: sem colisão com veículos, helicópteros e portas dos outros
    local function antiGroup(label, filter)
        local on = false
        PR:AddToggle({Name = label, Default = false, Callback = function(v)
            on = v
            if v then task.spawn(function()
                while on do
                    local mine = hum() and hum().SeatPart and hum().SeatPart:FindFirstAncestorOfClass("Model")
                    for _, o in ipairs(WS:GetDescendants()) do
                        if o:IsA("BasePart") and o.CanCollide and filter(o) and not (mine and o:IsDescendantOf(mine)) then
                            o.CanCollide = false
                        end
                    end
                    task.wait(3)
                end
            end) end
        end})
    end
    antiGroup("Anti Fling Veículos", function(o) return o:FindFirstAncestor("Vehicles") ~= nil end)
    antiGroup("Anti Helicóptero", function(o)
        local m = o:FindFirstAncestorOfClass("Model")
        return m ~= nil and m.Name:lower():find("heli") ~= nil
    end)
    antiGroup("Anti Fling Portas", function(o) return o:FindFirstAncestor("001_HouseDoors") ~= nil end)

    SU:AddButton({Name = "Prop Swallow (UI completa)", Callback = function() GTA_PL.PS.openUI() end})

    -- Shift Lock nativo
    local slConn
    SU:AddToggle({Name = "Shift Lock (GTA)", Default = false, Callback = function(v)
        if slConn then slConn:Disconnect() slConn = nil end
        local h = hum()
        if v then
            slConn = RunS.RenderStepped:Connect(function()
                local hh, r, c = hum(), hrp(), WS.CurrentCamera
                if hh and r and c then
                    hh.AutoRotate = false
                    UIS.MouseBehavior = Enum.MouseBehavior.LockCenter
                    local l = c.CFrame.LookVector
