    -- Shaders nativos
    SU:AddToggle({Name = "Shaders (GTA)", Default = false, Callback = function(v)
        local L = game:GetService("Lighting")
        for _, n in ipairs({"GTA_Bloom", "GTA_Color", "GTA_Rays", "GTA_Atmo"}) do
            local o = L:FindFirstChild(n) if o then o:Destroy() end
        end
        if v then
            local b = Instance.new("BloomEffect") b.Name = "GTA_Bloom" b.Intensity = 0.6 b.Size = 30 b.Threshold = 0.9 b.Parent = L
            local c = Instance.new("ColorCorrectionEffect") c.Name = "GTA_Color" c.Saturation = 0.2 c.Contrast = 0.15 c.Brightness = 0.02 c.Parent = L
            local r = Instance.new("SunRaysEffect") r.Name = "GTA_Rays" r.Intensity = 0.15 r.Spread = 0.8 r.Parent = L
            local a = Instance.new("Atmosphere") a.Name = "GTA_Atmo" a.Density = 0.25 a.Haze = 1 a.Parent = L
        end
    end})

    -- Shaders Tipo 1 (client-side): noite com estrelas, chuva, trovão e sons ambiente.
    -- Reversível: desligar restaura Lighting, materiais e reflectância e apaga tudo que foi criado.
    do
        local Lighting = game:GetService("Lighting")
        local Debris = game:GetService("Debris")
        local TweenService = game:GetService("TweenService")
        local S = {on = false, gen = 0, conns = {}, insts = {}, mats = {}, refl = {}, saved = nil}

        local function keep(inst)
            S.insts[#S.insts + 1] = inst
            return inst
        end
        local function newSound(parent, id, vol, looped)
            local s = Instance.new("Sound")
            s.SoundId = "rbxassetid://" .. id
            s.Volume = vol
            s.Looped = looped or false
            s.Parent = parent
            return s
        end

        local function disable()
            S.on = false
            S.gen = S.gen + 1
            for _, c in ipairs(S.conns) do pcall(function() c:Disconnect() end) end
            for _, i in ipairs(S.insts) do pcall(function() i:Destroy() end) end
            for p, m in pairs(S.mats) do pcall(function() p.Material = m end) end
            for p, r in pairs(S.refl) do pcall(function() p.Reflectance = r end) end
            if S.saved then
                for k, v in pairs(S.saved) do pcall(function() Lighting[k] = v end) end
            end
            S.conns, S.insts, S.mats, S.refl, S.saved = {}, {}, {}, {}, nil
        end

        local function enable()
            if S.on then return end
            S.on = true
            S.gen = S.gen + 1
            local my = S.gen
            local function alive() return S.on and S.gen == my end

            S.saved = {}
            for _, k in ipairs({"Brightness", "GlobalShadows", "OutdoorAmbient", "FogColor", "FogStart", "FogEnd", "EnvironmentSpecularScale", "EnvironmentDiffuseScale"}) do
                S.saved[k] = Lighting[k]
            end

            local fx = keep(Instance.new("Folder"))
            fx.Name = "GTA_ShaderFX"
            fx.Parent = WS

            -- materiais do mapa (guarda o original pra restaurar)
            local function setMat(p, m)
                if S.mats[p] == nil then S.mats[p] = p.Material end
                p.Material = m
            end
            local model = WS:FindFirstChild("Model")
            if model then
                local function paint(obj)
                    for _, c in ipairs(obj:GetChildren()) do
                        if c:IsA("BasePart") then
                            setMat(c, Enum.Material.Basalt)
                        elseif c:IsA("Model") or c:IsA("Folder") then
                            paint(c)
                        end
                    end
                end
                local snow = model:FindFirstChild("001_SnowStreet")
                if snow then paint(snow) end
                local street = model:FindFirstChild("Street")
                if street then
                    for _, o in ipairs(street:GetDescendants()) do
                        if o:IsA("BasePart") then setMat(o, Enum.Material.Basalt) end
                    end
                end
                local function sidewalk(o)
                    if o:IsA("BasePart") and (o.Name == "Sidewalk" or o.Name == "Wedge") and o.Material == Enum.Material.SmoothPlastic then
                        setMat(o, Enum.Material.Cobblestone)
                    end
                end
                for _, o in ipairs(model:GetChildren()) do sidewalk(o) end
                S.conns[#S.conns + 1] = model.ChildAdded:Connect(function(o)
                    if alive() then sidewalk(o) end
                end)
            end

            -- sons: pássaros seguem o jogador, lobo à noite, fonte, ambiente, chuva e trovão
            local soundPart = Instance.new("Part")
            soundPart.Size = Vector3.new(1, 1, 1)
            soundPart.Transparency = 1
            soundPart.Anchored = true
            soundPart.CanCollide = false
            soundPart.Parent = fx
            local birdSound = newSound(soundPart, 1237969272, 0.05, true)
            local wolfSound = newSound(fx, 6654360741, 0.05, false)
            S.conns[#S.conns + 1] = RunS.Heartbeat:Connect(function()
                local r = hrp()
                if r then soundPart.Position = r.Position + Vector3.new(0, 10, 0) end
            end)
            task.spawn(function()
                while alive() do
                    local t = Lighting.ClockTime
                    if t >= 18 or t <= 6 then
                        if birdSound.IsPlaying then birdSound:Stop() end
                        if wolfSound.IsPlaying then wolfSound:Stop() end
                        wolfSound:Play()
                    else
                        if wolfSound.IsPlaying then wolfSound:Stop() end
                        if not birdSound.IsPlaying then birdSound:Play() end
                    end
                    task.wait(20)
                end
            end)

            local fountainPart = Instance.new("Part")
            fountainPart.Anchored = true
            fountainPart.CanCollide = false
            fountainPart.Transparency = 1
            fountainPart.Size = Vector3.new(1, 1, 1)
            fountainPart.Position = Vector3.new(-27, 19, 15)
            fountainPart.Parent = fx
            local fountainAtt = Instance.new("Attachment")
            fountainAtt.Parent = fountainPart
            local fountain = newSound(fountainAtt, 4766793559, 0.03, true)
            fountain.EmitterSize = 10
            fountain.RollOffMode = Enum.RollOffMode.Linear
            fountain.MaxDistance = 100
            fountain:Play()

            local ambient = newSound(fx, 9048659736, 0.01, true)
            ambient:Play()
            local spaceSound = newSound(fx, 1843520836, 0.3, true)
            local birds = newSound(fx, 9111139882, 0.2, true)
            birds:Play()
            local rainSound = newSound(fx, 9118823106, 0.3, true)
            rainSound:Play()
            local thunder = newSound(fx, 9120018695, 0.4, false)

            -- céu noturno: estrelas fixas piscando + estrelas cadentes
            local night = false
            local stars = {}
            local shoots = Instance.new("Folder")
            shoots.Name = "ShootingStars"
            shoots.Parent = fx

            local function createStar()
                local star = Instance.new("Part")
                local size = math.random(1, 3) * 0.5
                star.Size = Vector3.new(size, size, size)
                star.Position = Vector3.new(math.random(-1000, 1000), math.random(300, 700), math.random(-1000, 1000))
                star.Anchored = true
                star.CanCollide = false
                star.Material = Enum.Material.Neon
                local colors = {Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 255, 180), Color3.fromRGB(180, 200, 255)}
                star.Color = colors[math.random(1, #colors)]
                star.Name = "Star"
                star.Parent = fx
                local light = Instance.new("PointLight")
                light.Brightness = 2 + math.random() * 1.5
                light.Range = 12
                light.Parent = star
                stars[#stars + 1] = {part = star, freq = math.random(2, 5)}
            end
            local function clearStars()
                for _, s in ipairs(stars) do pcall(function() s.part:Destroy() end) end
                stars = {}
                for _, p in ipairs(shoots:GetChildren()) do p:Destroy() end
            end
            S.conns[#S.conns + 1] = RunS.Heartbeat:Connect(function()
                if not night then return end
                local t = tick()
                for _, s in ipairs(stars) do
                    if s.part.Parent then s.part.Transparency = 0.2 + math.sin(t * s.freq) * 0.2 end
                end
            end)

            local function createShootingStar()
                if not (alive() and night) then return end
                local ang = math.random() * math.pi * 2
                local dir = Vector3.new(math.cos(ang), (math.random() - 0.5) * 0.2, math.sin(ang)).Unit
                local speed = math.random(350, 550)
                local isFire = math.random() <= 0.3
                local color = isFire and Color3.fromRGB(255, 50, 50) or Color3.fromRGB(255, 255, 220)
                local trailColor = isFire
                    and ColorSequence.new(Color3.fromRGB(255, 120, 0), Color3.fromRGB(255, 230, 50))
                    or ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 255, 180))
                local star = Instance.new("Part")
                star.Size = Vector3.new(0.5, 0.5, 3)
                star.Position = Vector3.new(math.random(-1000, 1000), math.random(350, 600), math.random(-1000, 1000))
                star.Anchored = true
                star.CanCollide = false
                star.Material = Enum.Material.Neon
                star.Color = color
                star.Name = "ShootingStar"
                star.Parent = shoots
                local a0 = Instance.new("Attachment")
                a0.Parent = star
                local a1 = Instance.new("Attachment")
                a1.Position = Vector3.new(0, 0, -3)
                a1.Parent = star
                local trail = Instance.new("Trail")
                trail.Attachment0 = a0
                trail.Attachment1 = a1
                trail.Lifetime = 0.35
                trail.Color = trailColor
                trail.LightEmission = 1
                trail.WidthScale = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0)})
                trail.Parent = star
                local light = Instance.new("PointLight")
                light.Brightness = isFire and 12 or 7
                light.Range = 35
                light.Color = color
                light.Parent = star
                if isFire then
                    local fire = Instance.new("Fire")
                    fire.Heat = 15
                    fire.Size = 3.5
                    fire.Color = Color3.fromRGB(255, 110, 0)
                    fire.SecondaryColor = Color3.fromRGB(255, 210, 0)
                    fire.Parent = star
                end
                local lifetime = 1 + math.random() * 0.5
                local passed = 0
                local conn
                conn = RunS.Heartbeat:Connect(function(dt)
                    if not (alive() and night) or passed >= lifetime or not star.Parent then
                        conn:Disconnect()
                        if star.Parent then star:Destroy() end
                        return
                    end
                    passed = passed + dt
                    local curve = math.sin(passed * 20) * 0.5
                    star.Position = star.Position + (dir + Vector3.new(0, curve, 0)).Unit * speed * dt
                end)
                Debris:AddItem(star, 4)
            end

            local function updateSky()
                local hour = Lighting.ClockTime
                local want = hour >= 18 or hour < 6
                if want and not night then
                    night = true
                    Lighting.FogColor = Color3.fromRGB(10, 10, 30)
                    Lighting.FogEnd = 5000
                    Lighting.Brightness = 2
                    clearStars()
                    for _ = 1, 300 do createStar() end
                    spaceSound:Play()
                elseif not want and night then
                    night = false
                    clearStars()
                    spaceSound:Stop()
                    Lighting.FogColor = Color3.fromRGB(192, 192, 192)
                    Lighting.FogEnd = 100000
                    Lighting.Brightness = 2
                end
            end
            task.spawn(function()
                while alive() do
                    if night then
                        for _ = 1, 12 do
                            createShootingStar()
                            task.wait(0.1)
                        end
                    else
                        task.wait(1)
                    end
                end
            end)
            task.spawn(function()
                while alive() do
                    updateSky()
                    task.wait(1)
                end
            end)

            -- chuva e trovão
            local rainFolder = Instance.new("Folder")
            rainFolder.Name = "FakeRain"
            rainFolder.Parent = fx
            local function spawnRain()
                birds.Volume = 0
                for _ = 1, 120 do
                    local drop = Instance.new("Part")
                    drop.Size = Vector3.new(0.1, 2, 0.1)
                    drop.Anchored = true
                    drop.CanCollide = false
                    drop.Material = Enum.Material.Glass
                    drop.Transparency = 0.5
                    drop.Color = Color3.fromRGB(160, 160, 255)
                    drop.Position = Vector3.new(math.random(-150, 150), 100, math.random(-150, 150))
                    drop.Parent = rainFolder
                    TweenService:Create(drop, TweenInfo.new(1), {Position = drop.Position - Vector3.new(0, 60, 0)}):Play()
                    Debris:AddItem(drop, 1.5)
                end
                task.wait(1.5)
                birds.Volume = 0.2
            end
            local function lightning()
                local flash = Instance.new("Part")
                flash.Size = Vector3.new(1, 1000, 1)
                flash.Anchored = true
                flash.CanCollide = false
                flash.Transparency = 0.4
                flash.Material = Enum.Material.Neon
                flash.Color = Color3.new(1, 1, 1)
                flash.Position = Vector3.new(math.random(-100, 100), 500, math.random(-100, 100))
                flash.Parent = fx
                Lighting.Brightness = Lighting.Brightness + 1.5
                thunder:Play()
                task.wait(0.1)
                if alive() then Lighting.Brightness = Lighting.Brightness - 1.5 end
                flash:Destroy()
            end
            task.spawn(function()
                while alive() do
                    spawnRain()
                    if alive() and math.random() < 0.2 then lightning() end
                    task.wait(1)
                end
            end)

            -- reflexo nas partes SmoothPlastic do mapa (em fatias pra não travar o frame)
            task.spawn(function()
                local n = 0
                for _, p in ipairs(WS:GetDescendants()) do
                    if not alive() then return end
                    if p:IsA("BasePart") and p.Material == Enum.Material.SmoothPlastic and S.refl[p] == nil then
                        S.refl[p] = p.Reflectance
                        p.Reflectance = 0.25
                    end
                    n = n + 1
                    if n % 1500 == 0 then task.wait() end
                end
            end)

            -- iluminação, céu e efeitos
            Lighting.Brightness = 2
            Lighting.GlobalShadows = true
            Lighting.OutdoorAmbient = Color3.fromRGB(70, 70, 70)
            Lighting.FogColor = Color3.fromRGB(120, 130, 140)
            Lighting.FogStart = 80
            Lighting.FogEnd = 600
            Lighting.EnvironmentSpecularScale = 1
            Lighting.EnvironmentDiffuseScale = 0.5
            local function addEffect(className, name, props)
                local e = keep(Instance.new(className))
                e.Name = name
                for k, v in pairs(props) do e[k] = v end
                e.Parent = Lighting
                return e
            end
            addEffect("Sky", "GTA_S1_Sky", {
                SkyboxBk = "rbxassetid://159454299", SkyboxDn = "rbxassetid://159454296",
                SkyboxFt = "rbxassetid://159454293", SkyboxLf = "rbxassetid://159454286",
                SkyboxRt = "rbxassetid://159454300", SkyboxUp = "rbxassetid://159454304",
            })
            addEffect("ColorCorrectionEffect", "GTA_S1_Color", {Brightness = 0.03, Contrast = 0.15, Saturation = 0.05, TintColor = Color3.fromRGB(255, 240, 220)})
            addEffect("BloomEffect", "GTA_S1_Bloom", {Intensity = 0.8, Size = 56, Threshold = 0.9})
            addEffect("SunRaysEffect", "GTA_S1_Rays", {Intensity = 0.05, Spread = 0.8})
            addEffect("BlurEffect", "GTA_S1_Blur", {Size = 0})
        end

        SU:AddToggle({Name = "Shaders Tipo 1 (noite, chuva, estrelas)", Default = false, Callback = function(v)
            if v then task.spawn(enable) else disable() end
        end})
    end

    -- Bring Parts (partes soltas do mapa em volta de você)
    local bpOn = false
    SU:AddToggle({Name = "Bring Parts (partes soltas)", Default = false, Callback = function(v)
        bpOn = v
        if v then task.spawn(function()
            while bpOn do
                local r = hrp()
                if r then
                    local i = 0
                    for _, o in ipairs(WS:GetDescendants()) do
                        if o:IsA("BasePart") and not o.Anchored and not o:IsDescendantOf(char()) and not o.Parent:FindFirstChildOfClass("Humanoid") and (o.Position - r.Position).Magnitude < 200 then
                            i = i + 1
                            if i > 80 then break end
                            local a = i / 80 * math.pi * 2 + tick()
                            o.CFrame = r.CFrame * CFrame.new(math.cos(a) * 10, 4, math.sin(a) * 10)
                        end
                    end
                end
                task.wait(0.1)
            end
        end) end
    end})

    -- Telekinesis (segura o clique numa parte solta e arrasta com o mouse)
    local tkConns, held = {}, nil
    SU:AddToggle({Name = "Telekinesis (GTA)", Default = false, Callback = function(v)
        for _, c in ipairs(tkConns) do c:Disconnect() end
        tkConns, held = {}, nil
        if not v then return end
        local m = LP:GetMouse()
        tkConns[#tkConns + 1] = m.Button1Down:Connect(function()
            local t = m.Target
            if t and t:IsA("BasePart") and not t.Anchored and not t.Parent:FindFirstChildOfClass("Humanoid") then held = t end
        end)
        tkConns[#tkConns + 1] = m.Button1Up:Connect(function() held = nil end)
        tkConns[#tkConns + 1] = RunS.RenderStepped:Connect(function()
            if held and held.Parent then
                held.AssemblyLinearVelocity = Vector3.zero
                held.CFrame = CFrame.new(m.Hit.Position + Vector3.new(0, 3, 0))
            end
        end)
    end})
end

