    local T = ActiveWindow:MakeTab({Title = "Avatar", Icon = "🧍"})
    local sel = PARTS[1][1]
    local function find(n) for _, p in ipairs(PARTS) do if p[1] == n then return p end end end
    local function apply(p)
        local rem = Remotes and Remotes:FindFirstChild("ApplyEmmiter")
        if not (rem and p) then note("GTA Hub", "Remote de partículas não encontrado") return false end
        local ok, e = pcall(function() rem:InvokeServer(p[2], p[3]) end)
        if not ok then warn("[GTA Hub] partícula: " .. tostring(e)) end
        return ok
    end
    T:AddSection({"Partículas"})
    T:AddDropdown({Name = "Partícula", Options = names(PARTS), Default = sel, Callback = function(v) sel = v end})
    T:AddButton({Name = "Aplicar partícula", Callback = function() task.spawn(apply, find(sel)) end})
    local rainbow = false
    T:AddToggle({Name = "Partículas em sequência", Default = false, Callback = function(v)
        rainbow = v
        if v then task.spawn(function()
            local i = 1
            while rainbow do
                apply(PARTS[i])
                i = i % #PARTS + 1
                task.wait(1.5)
            end
        end) end
    end})
    T:AddSection({"Fire Loop (bolhas)"})
