        Vermelho = {"18637500927", "064BubbleRed"},
        Roxo = {"18637497343", "063BubblePurple"},
        Azul = {"18637499282", "062BubbleBlue"},
        Verde = {"18637493072", "061BubbleGreen"},
    }
    local fireSel, fireOn, fireGen = "Verde", false, 0
    T:AddDropdown({Name = "Cor do Fire Loop", Options = {"Vermelho", "Roxo", "Azul", "Verde"}, Default = "Verde", Callback = function(v) fireSel = v end})
    T:AddToggle({Name = "Fire Loop (sobrescreve o Outfit 25)", Default = false, Callback = function(v)
        fireOn = v
        fireGen = fireGen + 1
        local my = fireGen
        if not v then return end
        task.spawn(function()
            local d = FIRE_BUBBLES[fireSel]
            local rem = Remotes and Remotes:FindFirstChild("ApplyEmmiter")
            if rem and d then pcall(function() rem:InvokeServer(d[1], d[2]) end) end
            task.wait(0.5)
            while fireOn and fireGen == my do
                pcall(function()
                    Remotes.SaveOutfit:InvokeServer(25, "Outfit 25")
                    Remotes.LoadOutfit:InvokeServer(25)
                end)
                task.wait(0.1)
            end
        end)
    end})
end

-- ---------------------------------------------------------------- DARKONES (remotes lidos do código recuperado: casa, billboard, jobs, tamanho, acessórios, teleportes)
local function tabDarkones()
    local H = ActiveWindow:MakeTab({Title = "Casas", Icon = "🏠"})
    local A = ActiveWindow:MakeTab({Title = "Avatar", Icon = "🧍"})
    local C = ActiveWindow:MakeTab({Title = "Carro", Icon = "🚗"})
    local I = ActiveWindow:MakeTab({Title = "Itens", Icon = "🎒"})
    local TPT = ActiveWindow:MakeTab({Title = "Teleportes", Icon = "📍"})
    local LPT = ActiveWindow:MakeTab({Title = "Local Player", Icon = "👤"})

    local function loop(flagName, interval, fn)
        local on = {}
        return function(v)
            on.v = v
            if v then task.spawn(function() while on.v do pcall(fn) task.wait(interval) end end) end
        end
    end
    local function houseEv(...) local a = {...} pcall(function() RE["1Player1sHous1e"]:FireServer(unpack(a)) end) end

    -- CASA
    H:AddSection({"Casa: troll"})
    H:AddToggle({Name = "Spam Lock (trancar portas)", Default = false, Callback = loop("lock", 0.5, function() houseEv("LockDoors") end)})
    H:AddToggle({Name = "Spam Cortinas", Default = false, Callback = loop("cur", 0.5, function() houseEv("Curtains") end)})
    H:AddToggle({Name = "Spam Garagem", Default = false, Callback = loop("gar", 0.5, function() houseEv("GarageDoor") end)})
    H:AddButton({Name = "Fogo na Casa", Callback = function() houseEv("PlayerWantsFireOnFirePass") end})
    local evil = false
    H:AddToggle({Name = "Casa Maligna (pisca vermelho e preto)", Default = false, Callback = function(v)
        evil = v
        if v then task.spawn(function()
            while evil do
                houseEv("ColorPickHouse", Color3.new(1, 0, 0)) task.wait(1)
                houseEv("ColorPickHouse", Color3.new(0, 0, 0)) task.wait(1)
            end
        end) end
    end})
    H:AddTextBox({Name = "Nome da empresa da casa", PlaceholderText = "texto", Callback = function(v)
        pcall(function() RE["1RPHous1eEven1t"]:FireServer("BusinessName", v) end)
    end})

    -- BILLBOARD (3 outdoor billboards do mapa; teleporta até cada um, escreve e volta)
    local bbText = "GTA HUB"
    local BOARDS = {
