        local r = hrp()
        if not r or not firetouchinterest or not fireclickdetector then toast("Falta firetouchinterest/fireclickdetector no executor", Color3.fromRGB(235, 80, 90)) return end
        local piz = Wk.WorkspaceCom["001_Mall"]["001_Pizza"]
        if piz.Burner2.Color ~= Color3.new(1, 0, 0) then
            local cf = r.CFrame
            r.CFrame = CFrame.new(187, 4, -231)
            task.wait()
            fireclickdetector(piz.Switch.ClickDetector)
            local t0 = tick()
            repeat task.wait() until piz.Burner2.Color == Color3.new(1, 0, 0) or tick() - t0 > 6
            r.CFrame = cf
            task.wait()
        end
        firetouchinterest(piz.CatchFire, r, 0)
        task.wait()
        firetouchinterest(piz.CatchFire, r, 1)
    end
