                local function grip(tool, target)
                    local hand = ch:FindFirstChild("Right Arm") or ch:FindFirstChild("RightHand")
                    local n = hand.CFrame * CFrame.new(0, -1, 0, 1, 0, 0, 0, 0, 1, 0, -1, 0)
                    tool.Grip = n:ToObjectSpace(target):Inverse()
                end
                local t0 = tick()
                repeat
                    task.wait()
                    local tc = t.Character
                    local th = tc and tc:FindFirstChildOfClass("Humanoid")
                    local tr = tc and tc:FindFirstChild("HumanoidRootPart")
                    if not (th and tr) then break end
                    couch.Parent = lp.Backpack
                    grip(couch, tr.CFrame + th.MoveDirection * 5.8)
                    couch.Parent = ch
                    if th.Sit then
                        couch.Parent = lp.Backpack
                        grip(couch, ch.HumanoidRootPart.CFrame + Vector3.new(9e9, 0, 9e9))
                        task.wait(0.1)
                        couch.Parent = ch
                    end
                until (th.SeatPart and th.SeatPart.Parent and th.SeatPart.Parent.Parent and th.SeatPart.Parent.Parent.Name == lp.Name) or tick() - t0 > 25
                ch.Animate.Disabled = false
            end)
