local function tabRGB()
    if not (_G.GTA_CanUseRestricted and _G.GTA_CanUseRestricted()) then return end  -- usuário normal: nada da aba RGB é criado
    local Plrs = game:GetService("Players")
    local lp = Plrs.LocalPlayer
    local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
    local function reF(clean) if RE then for _, c in ipairs(RE:GetChildren()) do if (c.Name:gsub("%d", "")) == clean then return c end end end end
    local RG = ActiveWindow:MakeTab({Title = "RGB", Icon = "🌈"})
    local speed, rate = 0.25, 0.05  -- ciclos de cor por segundo / intervalo de envio
    local function hueNow() return Color3.fromHSV((tick() * speed) % 1, 1, 1) end
    local function loop(name, interval, fn, onStop)
        local on, gen = false, 0
        RG:AddToggle({Name = name, Default = false, Callback = function(v)
            on = v; gen = gen + 1
            local my = gen
            if v then
                task.spawn(function()
                    while on and gen == my do pcall(fn); task.wait(interval()) end
                    if onStop then pcall(onStop) end
                end)
            end
        end})
    end
    RG:AddSection({Name = "Ajustes"})
    RG:AddSlider({Name = "Velocidade do RGB", Min = 1, Max = 100, Increase = 1, Default = 25, Callback = function(v) speed = v / 100 end})
    RG:AddSlider({Name = "Suavidade (envios/seg)", Min = 5, Max = 30, Increase = 1, Default = 20, Callback = function(v) rate = 1 / v end})

    RG:AddSection({Name = "Nome e Bio"})
    loop("RGB Nome (fluido)", function() return rate end, function()
        local r = reF("RPNameColor"); if r then r:FireServer("PickingRPNameColor", hueNow()) end
    end)
    loop("RGB Bio (fluido)", function() return rate end, function()
        local r = reF("RPNameColor"); if r then r:FireServer("PickingRPBioColor", hueNow()) end
    end)
    loop("RGB Nome + Bio juntos", function() return rate end, function()
        local r = reF("RPNameColor"); if not r then return end
        local c = hueNow()  -- nome e bio com a MESMA cor, combinadas
        r:FireServer("PickingRPNameColor", c)
        r:FireServer("PickingRPBioColor", c)
    end)
    RG:AddButton({Name = "Aplicar nome e bio GTA agora", Callback = function() if GTA_PL.applyIdentity then task.spawn(GTA_PL.applyIdentity) end end})
    RG:AddToggle({Name = "Aplicar nome/bio GTA ao iniciar", Default = true, Callback = function(v) GTA_PL.identityOn = v end})

    RG:AddSection({Name = "Corpo"})
    loop("RGB Cabelo (fluido)", function() return math.max(rate, 0.15) end, function()
        local r = reF("Maxy"); if r then r:FireServer("ChangeHairColor3", hueNow()) end
    end, function()
        local r = reF("Maxy"); if r then r:FireServer("ChangeHairColor3", Color3.new(1, 0.753, 0.796)) end
    end)
    local Rem = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
    local skin = {"Pastel brown","Light orange","Dark nougat","Brown","Pine Cone","Dirt brown","Really black","Black","Smoke grey","Dark stone grey","Medium stone grey","Fossil","Flint","Cloudy grey","Mid gray","Institutional white","Mulberry","Eggplant","Bright violet","Magenta","Royal purple","Navy blue"}
    local si = 0
    loop("RGB Pele (lista de cores do jogo)", function() return 0.1 end, function()
        si = si % #skin + 1
        local r = Rem and Rem:FindFirstChild("ChangeBodyColor"); if r then r:FireServer(skin[si]) end
    end)

    RG:AddSection({Name = "Combinações de cores (efeitos)"})
    local NAMED = {red = Color3.fromRGB(255,0,0), blue = Color3.fromRGB(0,70,255), green = Color3.fromRGB(0,255,60), yellow = Color3.fromRGB(255,235,0),
        orange = Color3.fromRGB(255,130,0), purple = Color3.fromRGB(150,0,255), pink = Color3.fromRGB(255,80,200), cyan = Color3.fromRGB(0,230,255),
        white = Color3.fromRGB(255,255,255), black = Color3.fromRGB(0,0,0), gray = Color3.fromRGB(120,120,120), brown = Color3.fromRGB(120,70,20),
        magenta = Color3.fromRGB(255,0,255), lime = Color3.fromRGB(150,255,0), gold = Color3.fromRGB(255,190,0), darkred = Color3.fromRGB(120,0,0)}
    local function C(n) return NAMED[n] end
    local COMBOS = {
        {"Vermelho <-> Preto", {"red", "black"}}, {"Azul <-> Branco", {"blue", "white"}}, {"Roxo <-> Rosa", {"purple", "pink"}},
        {"Verde <-> Preto (Matrix)", {"green", "black"}}, {"Laranja <-> Amarelo", {"orange", "yellow"}}, {"Ciano <-> Azul", {"cyan", "blue"}},
        {"Fogo", {"red", "orange", "yellow"}}, {"Gelo", {"white", "cyan", "blue"}}, {"Sangue", {"darkred", "black", "red"}},
        {"Neon", {"pink", "cyan", "lime"}}, {"Toxic", {"green", "purple"}}, {"Ouro", {"gold", "white"}},
        {"Polícia", {"blue", "red"}}, {"Pôr do sol", {"orange", "pink", "purple"}}, {"Vermelho + Vermelho escuro", {"red", "darkred"}},
        {"Aleatória (infinitas combinações)", "RAND"},
    }
    local comboNames, comboMap = {}, {}
    for _, c in ipairs(COMBOS) do comboNames[#comboNames + 1] = c[1]; comboMap[c[1]] = c[2] end
    local cur, effect, apply, custom = comboMap[comboNames[1]], "Vai e volta", "Opostos (Nome em cima / Bio embaixo)", nil
    local function parseCustom(txt)
        local out = {}
        for tok in tostring(txt):gmatch("[^,;%s]+") do
            local t = tok:lower()
            local c = NAMED[t]
            if t == "rand" or t == "random" then c = Color3.fromHSV(math.random(), 0.8 + math.random() * 0.2, 1) end
            if not c then
                local h = t:match("^#?(%x%x%x%x%x%x)$")
                if h then c = Color3.fromRGB(tonumber(h:sub(1,2),16), tonumber(h:sub(3,4),16), tonumber(h:sub(5,6),16)) end
            end
            if c then out[#out + 1] = c end
        end
        return #out > 0 and out or nil
    end
    local rndCols, rndAt = nil, 0
    local function randomPalette()
        local n, o = math.random(2, 5), {}
        local h0 = math.random()
        for i = 1, n do o[i] = Color3.fromHSV((h0 + math.random() * 0.9) % 1, 0.7 + math.random() * 0.3, 0.6 + math.random() * 0.4) end
        if math.random() < 0.4 then o[#o + 1] = BLK end
        return o
    end
    local function colorsOf()
        if cur == "RAND" then
            if not rndCols or tick() - rndAt > 6 then rndCols, rndAt = randomPalette(), tick() end  -- paleta nova a cada 6s: infinitas combinações
            return rndCols
        end
        if custom then return custom end
        local o = {}
        for _, n in ipairs(cur) do o[#o + 1] = C(n) end
        return o
    end
    local BLK, WHT = Color3.new(0, 0, 0), Color3.new(1, 1, 1)
    local function hash(x) local v = math.sin(x * 127.1) * 43758.5453; return v - math.floor(v) end
    local function cyc(cols, p)      -- gradiente cíclico suave pela lista (p qualquer, repete)
        local n = #cols
        local seg = (p % 1) * n
        local i = math.floor(seg)
        return cols[i % n + 1]:Lerp(cols[(i + 1) % n + 1], seg - i)
    end
    local function lin(cols, p)      -- gradiente linear 0..1 (sem repetir)
        local n = #cols
        p = math.clamp(p, 0, 1)
        local seg = p * (n - 1)
        local i = math.min(math.floor(seg), n - 2)
        return cols[i + 1]:Lerp(cols[i + 2], seg - i)
    end
    local function pp(t) return math.abs((t % 2) - 1) end                       -- triângulo 0..1..0 (período 2)
    local function sm(x) return x * x * (3 - 2 * x) end                         -- smoothstep
    local function step(cols, t, hz) return cols[(math.floor(t * hz) % #cols) + 1] end
    local function bright(c, k) return BLK:Lerp(c, k) end
    local EFFECTS = {
        {"Vai e volta", function(c, t) return lin(c, pp(t * 0.5)) end},
        {"Vai e volta rápido", function(c, t) return lin(c, pp(t * 1.2)) end},
        {"Vai e volta lento", function(c, t) return lin(c, pp(t * 0.2)) end},
        {"Vai e volta suave (ease)", function(c, t) return lin(c, sm(pp(t * 0.5))) end},
        {"Ciclo", function(c, t) return cyc(c, t * 0.25) end},
        {"Ciclo reverso", function(c, t) return cyc(c, -t * 0.25) end},
        {"Dente de serra", function(c, t) return lin(c, (t * 0.5) % 1) end},
        {"Pisca", function(c, t) return step(c, t, 2) end},
        {"Pisca rápido", function(c, t) return step(c, t, 6) end},
        {"Pisca aleatório", function(c, t) return c[math.floor(hash(math.floor(t * 5)) * #c) + 1] end},
        {"Strobo", function(c, t) return (math.floor(t * 8) % 2 == 0) and cyc(c, t * 0.1) or BLK end},
        {"Pulso", function(c, t) return bright(c[(math.floor(t * 0.5) % #c) + 1], (math.sin(t * math.pi) + 1) / 2) end},
        {"Respiração", function(c, t) return bright(lin(c, pp(t * 0.15)), 0.25 + 0.75 * (math.sin(t * 1.5) + 1) / 2) end},
        {"Batida (coração)", function(c, t)
            local ph = (t * 0.8) % 1
            local k = math.max(math.exp(-((ph - 0.1) * 18) ^ 2), 0.8 * math.exp(-((ph - 0.3) * 18) ^ 2))
            return bright(cyc(c, t * 0.05), 0.15 + 0.85 * k)
        end},
        {"Pulso duplo", function(c, t) local ph = (t * 0.6) % 1; local k = (ph < 0.5) and math.abs(math.sin(ph * math.pi * 4)) or 0; return bright(cyc(c, t * 0.05), 0.1 + 0.9 * k) end},
        {"Onda seno", function(c, t) return lin(c, (math.sin(t * 1.2) + 1) / 2) end},
        {"Onda triangular", function(c, t) return lin(c, pp(t * 0.8)) end},
        {"Tremor", function(c, t) return lin(c, math.clamp(pp(t * 0.4) + (hash(math.floor(t * 20)) - 0.5) * 0.25, 0, 1)) end},
        {"Aleatório suave", function(c, t) return cyc(c, (math.sin(t * 0.7) + math.sin(t * 1.9) * 0.5 + math.sin(t * 3.1) * 0.25) * 0.3) end},
        {"Caos", function(c, t) return cyc(c, hash(math.floor(t * 30))) end},
        {"Glitch", function(c, t)
            if hash(math.floor(t * 12)) > 0.8 then return c[math.floor(hash(t * 3) * #c) + 1] end
            return cyc(c, t * 0.2)
        end},
        {"Relâmpago", function(c, t) local ph = (t * 0.7) % 1; return (ph < 0.06) and WHT or ((ph < 0.12) and BLK or cyc(c, t * 0.1)) end},
        {"Chama", function(c, t) return lin(c, math.clamp(0.5 + (math.sin(t * 9) * 0.25 + math.sin(t * 23) * 0.15 + (hash(math.floor(t * 15)) - 0.5) * 0.3), 0, 1)) end},
        {"Sirene", function(c, t) local k = (math.sin(t * 6) + 1) / 2; return c[1]:Lerp(c[#c], k > 0.5 and 1 or 0):Lerp(c[1], 1 - math.min(1, math.abs(k - 0.5) * 8)) end},
        {"Dupla (1ª e última)", function(c, t) return c[1]:Lerp(c[#c], (math.sin(t * 2.5) + 1) / 2) end},
        {"Degrau suave", function(c, t) local i = math.floor(t * 0.7); local f = sm(math.clamp(((t * 0.7) % 1) * 2 - 0.4, 0, 1)); return c[i % #c + 1]:Lerp(c[(i + 1) % #c + 1], f) end},
        {"Espiral (acelera)", function(c, t) return cyc(c, math.sin(t * 0.3) * 1.5 + t * 0.1) end},
        {"Invertido (cores ao contrário)", function(c, t) return cyc(c, 1 - (t * 0.25 % 1)) end},
        {"Fade pra branco", function(c, t) return lin(c, pp(t * 0.4)):Lerp(WHT, (math.sin(t * 2) + 1) / 4) end},
        {"Escurecer", function(c, t) return bright(lin(c, pp(t * 0.4)), 0.2 + 0.8 * pp(t * 0.8)) end},
        {"Brilho alternado", function(c, t) return bright(cyc(c, t * 0.1), 0.35 + 0.65 * ((math.floor(t * 3) % 2 == 0) and 1 or 0)) end},
        {"Saturação", function(c, t)
            local h, sa, v = lin(c, pp(t * 0.4)):ToHSV()
            return Color3.fromHSV(h, math.clamp(sa * (0.3 + 0.7 * pp(t * 0.7)), 0, 1), v)
        end},
        {"Complementar", function(c, t)
            local base = cyc(c, t * 0.15)
            local h, sa, v = base:ToHSV()
            return base:Lerp(Color3.fromHSV((h + 0.5) % 1, sa, v), (math.sin(t * 1.5) + 1) / 2)
        end},
        {"Arco-íris", function(c, t) return Color3.fromHSV((t * 0.1) % 1, 1, 1) end},
        {"Arco-íris vai e volta", function(c, t) return Color3.fromHSV(pp(t * 0.3) * 0.8, 1, 1) end},
        {"Arco-íris pastel", function(c, t) return Color3.fromHSV((t * 0.1) % 1, 0.45, 1) end},
    }
    local effectNames, effectMap = {}, {}
    for _, e in ipairs(EFFECTS) do effectNames[#effectNames + 1] = e[1]; effectMap[e[1]] = e[2] end
    local function comboColor(cols, t)
        if #cols == 1 then cols = {cols[1], BLK} end
        local f = effectMap[effect] or effectMap["Vai e volta"]
        local ok, c = pcall(f, cols, t)
        return ok and c or cols[1]
    end
    RG:AddDropdown({Name = "Combinação (RGB)", Options = comboNames, Default = comboNames[1], Callback = function(v) if comboMap[v] then cur = comboMap[v] end end})
    RG:AddDropdown({Name = "Efeito da combinação", Options = effectNames, Default = "Vai e volta", Callback = function(v) effect = v end})
    RG:AddDropdown({Name = "Aplicar combinação em", Options = {"Opostos (Nome em cima / Bio embaixo)", "Nome + Bio (mesma cor)", "Só Nome", "Só Bio"}, Default = "Opostos (Nome em cima / Bio embaixo)", Callback = function(v) apply = v end})
    RG:AddTextBox({Name = "Cores custom (ex: red, blue, black ou #ff00aa) - vazio usa a combinação", Default = "", Callback = function(v) custom = parseCustom(v) end})
    loop("Ligar combinação de cores", function() return rate end, function()
        local r = reF("RPNameColor"); if not r then return end
        local cols, t = colorsOf(), tick() * speed * 4
        local c1 = comboColor(cols, t)
        if apply == "Só Nome" then r:FireServer("PickingRPNameColor", c1)
        elseif apply == "Só Bio" then r:FireServer("PickingRPBioColor", c1)
        elseif apply == "Opostos (Nome em cima / Bio embaixo)" then
            -- espelho exato: quando o nome tá vermelho a bio tá preta, e vai e volta em loop
            local rev = {}
            for i = #cols, 1, -1 do rev[#rev + 1] = cols[i] end
            r:FireServer("PickingRPNameColor", c1)
            r:FireServer("PickingRPBioColor", comboColor(rev, t))
        else
            r:FireServer("PickingRPNameColor", c1)
            r:FireServer("PickingRPBioColor", c1)
        end
    end)
end

-- ============================================================
-- GTA HUB | ADMIN
-- O transporte Prometheus antigo foi removido por completo.
-- Um RemoteEvent criado no cliente do executor não replica para os
-- outros clientes; comandos cooperativos exigem relay/receptor real.
-- ============================================================
local function tabAdmin()
    local Plrs = game:GetService("Players")
    local lp = Plrs.LocalPlayer

    local function canOpenAdmin()
        if _G.GTA_FullAccess and _G.GTA_FullAccess() then return true end
        for _, tag in ipairs(_G.GTA_FULL_ACCESS_TAGS or {"D", "CO", "ADM", "SADM", "DEV"}) do
            if GTA_PL.hasRole(lp, tag) then return true end
        end
        return false
    end

    if not canOpenAdmin() then return end

    local AD = ActiveWindow:MakeTab({Title = "Admin", Icon = "🛡️"})
    AD:AddParagraph({
        Title = "Admin cooperativo — transporte pendente",
        Text = "O Admin Prometheus antigo foi removido. Esta versão roda por executor e não possui um relay compartilhado nem um receptor cooperativo nos clientes. Um RemoteEvent criado localmente não aparece nos outros jogadores. Por isso, Kill, Kick, Fling, Jail e comandos semelhantes não são apresentados como funcionais nem enviados por este painel."
    })

    AD:AddSection({Name = "Proteção de cargos"})
    AD:AddParagraph({
        Title = "Imunidade ativa",
        Text = "Dono (D) e Desenvolvedor (DEV) são imunes: ficam fora dos seletores que usam GTA_PL.filter e não podem ser alvos por GTA_PL.guardPlayer / GTA_PL.guardName."
    })
    AD:AddParagraph({
        Title = "Acesso à aba",
        Text = "D, CO, ADM, SADM e DEV podem abrir esta aba. A autorização local controla a interface; ela não concede autoridade no servidor do Brookhaven."
    })
    AD:AddButton({Name = "Verificar meus cargos", Callback = function()
        local roles = GTA_PL.rolesOf(lp)
        local roleText = #roles > 0 and table.concat(roles, ", ") or "Nenhum cargo reconhecido"
        if GTA_PL.toast then
            GTA_PL.toast("Seus cargos: " .. roleText, Color3.fromRGB(80, 180, 255))
        else
            warn("[GTA Admin] Seus cargos: " .. roleText)
        end
    end})

    AD:AddSection({Name = "Painel (mesmo servidor)"})
    AD:AddParagraph({
        Title = "Quem pode usar",
        Text = "Só D, CO, ADM, SADM e DEV (conferido de novo a cada clique). Age só em quem está NESTE servidor, pelos remotes do próprio jogo. Dono e DEV não aparecem em seletor nenhum e ninguém mira neles. Admin só aparece pra D/DEV; um usuário sem cargo de admin nunca vê nem acerta admin. Precisa de props (Props+) pra Trazer/Kill/Fling."
    })
    local adTarget = ""
    local adDD = AD:AddDropdown({
        Name = "Jogador",
        Options = {},
        Default = "",
        Callback = function(v) adTarget = tostring(v or "") end,
    })
    pcall(function() GTA_PL.track(adDD, false) end)
    local function adRun(action)
        if not canOpenAdmin() then return end
        if adTarget == "" then
            pcall(function() GTA_PL.toast("escolhe um jogador", Color3.fromRGB(220, 80, 80)) end)
            return
        end
        if not GTA_PL.guardName(adTarget) then return end  -- protegido: bloqueia (e pune quem tentou)
        pcall(GTA_PL.pick, adTarget)  -- sincroniza o alvo em todos os seletores (Prop etc.)
        task.wait(0.25)
        local fn = GTA_PL.Actions and GTA_PL.Actions[action]
        if fn then
            pcall(fn)
        else
            pcall(function() GTA_PL.toast("ação indisponível ainda (abra Props+ uma vez)", Color3.fromRGB(220, 80, 80)) end)
        end
    end
    AD:AddButton({Name = "Atualizar lista", Callback = function() pcall(GTA_PL.refreshAll) end})
    AD:AddButton({Name = "Trazer player (jail)", Callback = function() adRun("jail") end})
    AD:AddButton({Name = "Matar (prop pro void)", Callback = function() adRun("kill") end})
    AD:AddButton({Name = "Flingar", Callback = function() adRun("fling") end})
    AD:AddButton({Name = "Parar tudo", Callback = function() if canOpenAdmin() and GTA_PL.Actions and GTA_PL.Actions.stop then pcall(GTA_PL.Actions.stop) end end})
end

local function tabTrace()
    local Plrs = game:GetService("Players")
    local lp = Plrs.LocalPlayer
    local RStor = game:GetService("ReplicatedStorage")
    local RM = RStor:FindFirstChild("Remotes")
    local function R(n) return RM and RM:FindFirstChild(n) end
    local function inv(n, ...) local r, a = R(n), {...}; if r then pcall(function() r:InvokeServer(unpack(a)) end) end end
    local function fire(n, ...) local r, a = R(n), {...}; if r then pcall(function() r:FireServer(unpack(a)) end) end end
    local function loopToggle(tab, name, interval, fn)
        local on, gen = false, 0
        tab:AddToggle({Name = name, Default = false, Callback = function(v)
            on = v; gen = gen + 1
            local my = gen
            if v then task.spawn(function()
                while on and gen == my do pcall(fn); task.wait(interval) end
            end) end
        end})
    end

    local AT = ActiveWindow:MakeTab({Title = "Avatar+", Icon = "🧍"})
    AT:AddSection({Name = "FE Avatar"})
    AT:AddButton({Name = "FE Naked", Callback = function() inv("WearShirt", 15821796333); task.wait(0.1); inv("WearPants", 15885405395) end})
    AT:AddButton({Name = "FE Korblox", Callback = function() inv("ChangeCharacterBody", {[4] = 139607718}) end})
    AT:AddButton({Name = "FE Headless", Callback = function() inv("ChangeCharacterBody", {[6] = 134082579}) end})
    AT:AddButton({Name = "FE Headless + Korblox", Callback = function() inv("ChangeCharacterBody", {[4] = 139607718, [6] = 134082579}) end})
    AT:AddButton({Name = "Resetar avatar", Callback = function() fire("ResetCharacterAppearance") end})
    AT:AddTextBox({Name = "Catalog ID (vestir)", Default = "", Callback = function(v) if tonumber(v) then inv("Wear", tonumber(v)) end end})
    AT:AddSection({Name = "Loops do avatar"})
    loopToggle(AT, "Loop trocar emprego", 0.1, function()
        for _, j in ipairs({"Dancer","Grocery Store","Police","Hospital","Fire House","Teacher","Student","Bank","S.W.A.T.","Actor","Babysitter","Club Brooks","Driver","Repairman","Hair & Nails","Sheriff","Criminal","Athlete","Chef","Model","Singer","Musician","News","UTuber","Principal","Day Care","Detective","Gamer","Ice Cream","Lifeguard","Maid","Mayor","Clothing","Bodyguard","Stables","Military Police","At home dad","At home mom","Church","Flight Attendant","Pilot","Security","Spy","Writer","Office Worker","Mo's Pizza","Burger Barn","Taxi Driver","Sell Houses","Park Ranger","Military"}) do
            fire("GiveJobUIMenu", j); task.wait(0.1)
        end
    end)
    loopToggle(AT, "Loop tamanho do corpo", 0.1, function() fire("IncrementBodySize", true) end)

    local TT = ActiveWindow:MakeTab({Title = "Troll+", Icon = "🌀"})
    TT:AddSection({Name = "Pull Parts (CYA)"})
    local RunS, WS = game:GetService("RunService"), game:GetService("Workspace")
    local ppTarget
    local plNames = {}
    for _, pl in ipairs(GTA_PL.filter(Plrs:GetPlayers())) do if pl ~= lp then plNames[#plNames + 1] = pl.Name end end
    TT:AddDropdown({Name = "Player alvo (Pull Parts)", Options = plNames, Default = "", Callback = function(v) ppTarget = v end})
    local ppOn, ppGen, ppAdded, ppConn = false, 0, {}, nil
    local ppFolder, ppPart, ppAtt
    local function ppForce(v)
        if not (v:IsA("BasePart") and not v.Anchored) then return end
        if v:IsDescendantOf(lp.Character or WS) and lp.Character and v:IsDescendantOf(lp.Character) then return end
        local par = v.Parent
        if par and (par:FindFirstChildOfClass("Humanoid") or par:FindFirstChild("Head")) then return end
        if ppFolder and v:IsDescendantOf(ppFolder) then return end
        pcall(function()
            for _, x in ipairs(v:GetChildren()) do
                if x:IsA("BodyMover") or x:IsA("RocketPropulsion") then x:Destroy() end
            end
            v.CanCollide = false
            local att = Instance.new("Attachment"); att.Name = "GTA_PP"; att.Parent = v
            local tq = Instance.new("Torque"); tq.Name = "GTA_PP"; tq.Torque = Vector3.new(1e5, 1e5, 1e5); tq.Attachment0 = att; tq.Parent = v
            local ap = Instance.new("AlignPosition"); ap.Name = "GTA_PP"
            ap.MaxForce, ap.MaxVelocity, ap.Responsiveness = math.huge, math.huge, 200
            ap.Attachment0, ap.Attachment1 = att, ppAtt; ap.Parent = v
            ppAdded[#ppAdded + 1] = {att, tq, ap}
        end)
    end
    local function ppStop()
        ppOn = false; ppGen = ppGen + 1
        if ppConn then ppConn:Disconnect() ppConn = nil end
        for _, t in ipairs(ppAdded) do for _, i in ipairs(t) do pcall(function() i:Destroy() end) end end
        ppAdded = {}
        if ppFolder then pcall(function() ppFolder:Destroy() end) ppFolder = nil end
    end
    TT:AddToggle({Name = "Pull Parts (puxa as peças pro alvo)", Default = false, Callback = function(v)
        if not v then ppStop() return end
        local tp = ppTarget and Plrs:FindFirstChild(ppTarget)
        if not tp then
            if GTA_PL and GTA_PL.toast then GTA_PL.toast("escolhe o player alvo antes", Color3.fromRGB(220,80,80)) end
            return
        end
        ppStop(); ppOn = true
        local my = ppGen
        pcall(function() lp.ReplicationFocus = WS end)
        pcall(function() sethiddenproperty(lp, "SimulationRadius", math.huge) end)
        ppFolder = Instance.new("Folder"); ppFolder.Name = "GTA_PP"; ppFolder.Parent = WS
        ppPart = Instance.new("Part"); ppPart.Anchored = true; ppPart.CanCollide = false; ppPart.Transparency = 1; ppPart.Parent = ppFolder
        ppAtt = Instance.new("Attachment"); ppAtt.Parent = ppPart
        for _, d in ipairs(WS:GetDescendants()) do ppForce(d) end
        ppConn = WS.DescendantAdded:Connect(function(d) if ppOn then ppForce(d) end end)
        task.spawn(function()
            while ppOn and ppGen == my do
                local r = tp.Character and tp.Character:FindFirstChild("HumanoidRootPart")
                if r then ppPart.CFrame = r.CFrame end
                RunS.RenderStepped:Wait()
            end
        end)
    end})
    TT:AddParagraph({Title = "Aviso", Text = "chega perto do alvo. Desligar solta as peças (remove só o que o toggle criou)."})
    TT:AddSection({Name = "Nomes prontos"})
    for _, n in ipairs({"Anonymus","PRO","ERR0R_666","DARKNE1SSS","GHOST","JOKER","ADMIN","TUBERS 93","CO0 LKID","GAME ATTACKED BY MAFIA","INC0MUN","BAD BOY"}) do
        TT:AddButton({Name = "Nome: " .. n, Callback = function()
            local r = RStor:FindFirstChild("RE")
            if r then for _, c in ipairs(r:GetChildren()) do
                if (c.Name:gsub("%d", "")) == "RPNameText" then pcall(function() c:FireServer("RolePlayName", " " .. n .. " ") end) break end
            end end
        end})
    end

    TT:AddSection({Name = "Expansão de Domínio (CYA)"})
    local domOn, domGen, domModel = false, 0, nil
    local function domStop()
        domOn = false; domGen = domGen + 1
        if domModel then pcall(function() domModel:Destroy() end) domModel = nil end
    end
    TT:AddToggle({Name = "Expansão de Domínio (esfera + Assault em todos)", Default = false, Callback = function(v)
        if not v then domStop() return end
        domStop(); domOn = true
        local my = domGen
        local r = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
        if r then
            domModel = Instance.new("Model"); domModel.Name = "GTA_Dominio"; domModel.Parent = WS
            local e = Instance.new("Part"); e.Shape = Enum.PartType.Ball; e.Size = Vector3.new(300, 300, 300)
            e.Position = r.Position; e.Anchored = true; e.CanCollide = false
            e.Material = Enum.Material.ForceField; e.Transparency = 0.3; e.Color = Color3.new(0, 0, 0); e.Parent = domModel
            local l = Instance.new("PointLight", e); l.Color = Color3.fromRGB(0, 153, 255); l.Brightness = 10; l.Range = 60
            local ps = Instance.new("ParticleEmitter", e)
            ps.Texture = "rbxassetid://243660364"; ps.Color = ColorSequence.new(Color3.fromRGB(0, 153, 255)); ps.LightEmission = 1
            ps.Size = NumberSequence.new(3); ps.Transparency = NumberSequence.new(0.2); ps.Rate = 300
            ps.Lifetime = NumberRange.new(2); ps.Speed = NumberRange.new(0); ps.VelocitySpread = 180
            local sd = Instance.new("Sound", e); sd.SoundId = "rbxassetid://1843527678"; sd.Volume = 2; sd:Play()
        end
        task.spawn(function()
            while domOn and domGen == my do
                local clr, tl = reF("ClearTools"), reF("Tool")
                local gun = reF("Gun")
                if clr then pcall(function() clr:FireServer("ClearAllTools") end) end
                if tl then pcall(function() tl:InvokeServer("PickingTools", "Assault") end) end
                local t0 = tick()
                local bp = lp:FindFirstChildOfClass("Backpack")
                while domOn and domGen == my and bp and not bp:FindFirstChild("Assault") and tick() - t0 < 5 do task.wait(0.2) end
                local tool = bp and bp:FindFirstChild("Assault")
                local gs = tool and tool:FindFirstChild("GunScript_Local")
                if gs and gun then
                    for _ = 1, 3 do
                        for _, pl in ipairs(GTA_PL.filter(Plrs:GetPlayers())) do
                            if not (domOn and domGen == my) then break end
                            local pr = pl ~= lp and pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
                            if pr then
                                pcall(function()
                                    gun:FireServer(pr, pr, Vector3.new(1e14, 1e14, 1e14), pr.Position, gs:FindFirstChild("MuzzleEffect"), gs:FindFirstChild("HitEffect"), 0, 0, {false},
                                        {25, Vector3.new(100, 100, 100), BrickColor.new(29), 0.25, Enum.Material.SmoothPlastic, 0.25}, true, false)
                                end)
                                task.wait(0.1)
                            end
                        end
                    end
                end
                task.wait(1)
            end
        end)
    end})
    TT:AddSection({Name = "Burst Eardrums (CYA)"})
    local bID, bDelay, bOn, bGen = 6314880174, 0.03, false, 0
    TT:AddTextBox({Name = "ID do áudio (burst)", Default = "6314880174", Callback = function(v) if tonumber(v) then bID = tonumber(v) end end})
    TT:AddSlider({Name = "Intervalo burst (x0.01s)", Min = 3, Max = 100, Increase = 1, Default = 3, Callback = function(v) bDelay = v / 100 end})
    TT:AddToggle({Name = "Burst Eardrums (todos ouvem)", Default = false, Callback = function(v)
        bOn = v; bGen = bGen + 1
        local my = bGen
        if not v then return end
        task.spawn(function()
            while bOn and bGen == my do
                local gs = reF("GunSounds")
                if gs then pcall(function() gs:FireServer(WS, bID, 1) end) end
                task.spawn(function()
                    pcall(function()
                        local snd = Instance.new("Sound"); snd.SoundId = "rbxassetid://" .. bID; snd.Volume = 1; snd.Parent = WS
                        snd:Play(); task.wait(1); snd:Destroy()
                    end)
                end)
                task.wait(bDelay)
            end
        end)
    end})

    local IT = ActiveWindow:MakeTab({Title = "Ice+", Icon = "🧊"})
