    local function ri(clean, ...) local r, a = reF(clean), {...}; if r then pcall(function() r:InvokeServer(unpack(a)) end) end end
    local function strVals(path)  -- StringValues da GUI de cores do jogo (rainbow de nome)
        local o = {}
        pcall(function()
            local node = lp.PlayerGui
            for _, k in ipairs(path) do node = node:FindFirstChild(k) end
            for _, d in ipairs(node:GetDescendants()) do if d:IsA("StringValue") then o[#o + 1] = d end end
