    IT:AddButton({Name = "Cavalo marrom", Callback = function() rf("HorseRemote", "BrownHorseFree") end})
    loopToggle(IT, "Alternar cor do cavalo", 0.5, function() rf("HorseRemote", "BrownHorseFree"); task.wait(0.25); rf("HorseRemote", "BlackHorseFree") end)

    IT:AddSection({Name = "Veículos especiais"})
    local SP = {
        {"Foodtruck", "FoodTruck", "ReturningFoodTruckName", "PickingFoodTruckNameColor", {"MainGUIHandler","Menu","FoodTruckName","A","B","C","Frame"}},
        {"Van", "Van", "ReturningVanName", "PickingVanNameColor", {"MainGUIHandler","Menu","VanName","A","B","C","Frame"}},
        {"Trailer (camping)", "RV", "ReturningRVName", "PickingRVNameColor", {"MainGUIHandler","Menu","RVName","A","B","C","Frame"}},
        {"Nascar", "NascarTruck", "ReturningNascarTruckName", "PickingNascarTruckNameColor", {"MainGUIHandler","Menu","NascarTruckName","A","B","C","Frame"}},
        {"Student Driver", "StudentDriver", "ReturningStudentDriverName", nil, nil},
    }
    for _, e in ipairs(SP) do
        IT:AddButton({Name = "Spawn " .. e[1], Callback = function() rf("Car", "PickingCar", e[2]) end})
        IT:AddTextBox({Name = "Nome " .. e[1], Default = "", Callback = function(v) if v and v ~= "" then rf("Cemetery", e[3], v) end end})
