local function tabAnimations()
    local lp = game:GetService("Players").LocalPlayer
    local T = ActiveWindow:MakeTab({Title = "Animações", Icon = "🏃"})
    local PACKS = {
        {"Adidas", {idle1 = 18537376492, idle2 = 18537371272, walk = 18537392113, run = 18537384940, jump = 18537380791, fall = 18537367238, climb = 18537378510, swim = 18537389531, swimidle = 18537387180}},
        {"Vampire", {idle1 = 1083445855, idle2 = 1083450166, walk = 1083473930, run = 1083462077, jump = 1083455352, climb = 1083439238, fall = 1083443587}},
        {"Hero", {idle1 = 616111295, idle2 = 616113536, walk = 616122287, run = 616117076, jump = 616115533, climb = 616104706, fall = 616108001}},
        {"Zombie", {idle1 = 616158929, idle2 = 616160636, walk = 616168032, run = 616163682, jump = 616161997, climb = 616156119, fall = 616157476}},
        {"Mage", {idle1 = 707742142, idle2 = 707855907, walk = 707897309, run = 707861613, jump = 707853694, climb = 707826056, fall = 707829716}},
        {"Ghost", {idle1 = 616006778, idle2 = 616008087, walk = 616010382, run = 616013216, jump = 616008936, climb = 616003713, fall = 616005863}},
        {"Elder", {idle1 = 845397899, idle2 = 845400520, walk = 845403856, run = 845386501, jump = 845398858, climb = 845392038, fall = 845396048}},
        {"Levitation", {idle1 = 616006778, idle2 = 616008087, walk = 616013216, run = 616010382, jump = 616008936, climb = 616003713, fall = 616005863}},
        {"Toy", {idle1 = 782841498, idle2 = 782845736, walk = 782843345, run = 782842708, jump = 782847020, climb = 782843869, fall = 782846423}},
        {"Ninja", {idle1 = 656117400, idle2 = 656118341, walk = 656121766, run = 656118852, jump = 656117878, climb = 656114359, fall = 656115606}},
        {"Cartoon", {idle1 = 742637544, idle2 = 742638445, walk = 742640026, run = 742638842, jump = 742637942, climb = 742636889, fall = 742637151}},
        {"Pirate", {idle1 = 750781874, idle2 = 750782770, walk = 750785693, run = 750783738, jump = 750782230, climb = 750779899, fall = 750780242}},
        {"Knight", {idle1 = 657595757, idle2 = 657568135, walk = 657552124, run = 657564596, jump = 658409194, climb = 658360781, fall = 657600338}},
        {"Sneaky", {idle1 = 1132473842, idle2 = 1132477671, walk = 1132510133, run = 1132494274, jump = 1132489853, climb = 1132461372, fall = 1132469004}},
        {"Werewolf", {idle1 = 1083195517, idle2 = 1083214717, walk = 1083178339, run = 1083216690, jump = 1083218792, climb = 1083182000, fall = 1083189019}},
    }
    local current = nil
    local original = setmetatable({}, {__mode = "k"})

    local function put(anim, id)
        if id and anim and anim:IsA("Animation") then
            if original[anim] == nil then original[anim] = anim.AnimationId end
            anim.AnimationId = "rbxassetid://" .. id
        end
    end
    local function withAnimate(char, fn)
        local hum = char:WaitForChild("Humanoid", 5)
        local animate = char:WaitForChild("Animate", 5)
        if not (hum and animate) then return false end
        animate.Disabled = true
        for _, tr in ipairs(hum:GetPlayingAnimationTracks()) do tr:Stop() end
        fn(animate)
        hum:ChangeState(Enum.HumanoidStateType.Jumping)
        animate.Disabled = false
        return true
    end
    local function applyPack(char, ids)
        withAnimate(char, function(animate)
            local idle = animate:FindFirstChild("idle")
            if idle then
                put(idle:FindFirstChild("Animation1"), ids.idle1)
                put(idle:FindFirstChild("Animation2"), ids.idle2)
            end
            for _, s in ipairs({"walk", "run", "jump", "climb", "fall", "swim"}) do
                local f = animate:FindFirstChild(s)
                if f then
                    for _, a in ipairs(f:GetChildren()) do put(a, ids[s]) end
                end
            end
            local sw = animate:FindFirstChild("swimidle") or animate:FindFirstChild("swimIdle")
            if sw then
                for _, a in ipairs(sw:GetChildren()) do put(a, ids.swimidle) end
            end
        end)
    end
    local function restoreDefault(char)
        withAnimate(char, function()
            for anim, id in pairs(original) do pcall(function() anim.AnimationId = id end) end
        end)
        original = setmetatable({}, {__mode = "k"})
    end

    lp.CharacterAdded:Connect(function(char)
        if not current then return end
        task.wait(0.5)
        applyPack(char, current)
    end)

    T:AddSection({"Pacotes de animação"})
    for _, p in ipairs(PACKS) do
        T:AddButton({Name = p[1] .. " Animation", Callback = function()
            current = p[2]
            local ch = lp.Character
            if ch then applyPack(ch, current) end
            if GTA_PL and GTA_PL.toast then GTA_PL.toast(p[1] .. " Animation aplicada", Color3.fromRGB(80, 180, 255)) end
        end})
    end
    T:AddSection({"Padrão"})
    T:AddButton({Name = "Restaurar animação padrão", Callback = function()
        current = nil
        local ch = lp.Character
        if ch then restoreDefault(ch) end
    end})
end

-- ---------------------------------------------------------------- EMOTE HUB (GTA): script embutido, sem link
local function openEmoteHub()
--[[
    GTA EMOTE HUB v4.10
    - NOVO: página ⚡ Eventos (emote ao nascer + emote ao pular/pousar/parar de correr/sentar/nadar/equipar/tomar dano...)
    - NOVO: página 👥 Jogadores (copia o emote que outro jogador está tocando)
    - NOVO: apelido e cor por emote (segura o card), ping-pong, câmera de ombro, tremor no pouso, câmera inclina nas curvas
    - NOVO: cabeça refeita (olha a câmera, vira antes do corpo, olhadas no idle; R6 também), pegadas, respingo, modo performance, FPS/ping, novidades
    - NOVO: 1ª pessoa com câmera no olho da cabeça: se a cabeça vira (animação/emote) a câmera vira junto, giro livre por cima + balanço
    - NOVO: primeira pessoa realista (Config): câmera nativa livre, corpo visível, FOV, volta pra 3ª no emote. Tecla V
    - NOVO: abas próprias de emotes (＋ Aba na página Emotes; 📁 nos cards pra botar emote na aba)
    - NOVO: mini botão flutuante (repetir · parar · aleatório) — liga em Extras
    - NOVO: AFK — escolhe um emote que toca sozinho quando fica parado + Anti-AFK (não cai por inatividade)
    - NOVO: efeitos — partículas, aura, rastro, arco-íris e cor RGB livre (salvam e voltam no respawn)
    - NOVO: realismo — inclinar ao frear, poeira nos passos, balanço de câmera
    - REALISMO (Config): pés no chão em escada (IK), quadril, inclinar ao virar, cabeça, respiração, pouso
    - Prévia 3D de emote e de pack (👁): clona seu personagem num ViewportFrame; arrasta pra girar
    - Editar pack (✏) salva uma CÓPIA; copiar ID de só uma parte (idle, walk...) no menu ⋯ e na prévia
    - Tecla do hub configurável (Config). Padrão : (dois pontos). INSERT sempre funciona
    - Loja tem modo "Packs": bundles de animação (walk, idle, run...) com menu ⋯ pra aplicar só uma parte
    - UI nova: sidebar com indicador, animações suaves, cards com hover
    - UI compacta, botão flutuante arrastável (posição salva)
    - Copiar ID, favoritar, mandar pra roda nativa do Roblox (até 8)
    - Esconder o hub nas configs: fica só a roda. Reabrir = 2 dedos de cima pra baixo, devagar (ou INSERT)
    - Packs: salvar, favoritar, pesquisar, buscar na loja (bundles) ou importar por link/ID
    - Tudo que você faz é salvo sozinho em GTA_EmoteHub_v4.json
]]

if getgenv and getgenv().GTAEmoteHub and getgenv().GTAEmoteHub.Destroy then
    pcall(getgenv().GTAEmoteHub.Destroy)
end

