local function toNumList(t)
    local o = {}
    if type(t) == "table" then for _, v in ipairs(t) do local n = tonumber(v); if n and n ~= 0 then o[#o + 1] = n end end end
    return o
end

local function packToJson(p)
    local o = { key = p.key, name = p.name }
    for _, f in ipairs(PACK_FIELDS) do o[f] = tostring(p[f] or 0) end
    return o
end
local function packFromJson(d)
    if type(d) ~= "table" or type(d.key) ~= "string" then return nil end
    local p = { key = d.key, name = tostring(d.name or d.key), saved = true }
    for _, f in ipairs(PACK_FIELDS) do p[f] = tonumber(d[f]) or 0 end
    return p
end

local function save()
    if not writefile then return end
    local function strs(t) local o = {}; for i, v in ipairs(t) do o[i] = tostring(v) end; return o end
    local cp = {}; for k, v in pairs(S.customPack) do cp[k] = tostring(v) end
    local st = {}; for k, v in pairs(S.stats) do st[tostring(k)] = v end
    local sp = {}; for i, p in ipairs(S.savedPacks) do sp[i] = packToJson(p) end
    local ut = {}; for i, t in ipairs(S.userTabs) do ut[i] = { id = t.id, name = t.name, ids = strs(t.ids) } end
    local af = { on = S.afk.on, secs = S.afk.secs, emote = tostring(S.afk.emote) }
    local spw = { on = S.spawn.on, join = S.spawn.join, emote = tostring(S.spawn.emote), delay = S.spawn.delay }
    local evs = {}; for k, v in pairs(S.ev) do evs[k] = { on = v.on, emote = tostring(v.emote) } end
    local tg = {}; for id, t in pairs(S.tags) do tg[tostring(id)] = { n = t.n, c = t.c } end
    local data = {
        theme = S.theme, sound = S.sound, autoReload = S.autoReload, lastEmote = tostring(S.lastEmote),
        speed = S.speed, loop = S.loop, reverse = S.reverse, walkEmote = S.walkEmote, pack = S.pack, parts = S.parts, toggleKey = S.toggleKey, real = S.real,
        hidden = S.hidden, fab = S.fab, fabPos = S.fabPos, winPos = S.winPos, page = S.page, emoteKey = S.emoteKey,
        favs = strs(S.favs), packFavs = S.packFavs, customEmotes = strs(S.customEmotes), wheel = strs(S.wheel),
        playlist = strs(S.playlist), recents = strs(S.recents), customPack = cp, stats = st, savedPacks = sp,
        fx = S.fx, fp = S.fp, userTabs = ut, mini = S.mini, miniPos = S.miniPos, antiAfk = S.antiAfk, afk = af,
        sh = S.sh, spawn = spw, ev = evs, evCd = S.evCd, evLandMin = S.evLandMin, evRunMin = S.evRunMin, tags = tg,
        perf = S.perf, hud = S.hud, hudPos = S.hudPos, seenLog = S.seenLog, pingpong = S.pingpong,
    }
    pcall(function() writefile(CFG.SaveFile, HttpService:JSONEncode(data)) end)
end

local function loadSave()
    if not (readfile and isfile and isfile(CFG.SaveFile)) then return end
    local ok, d = pcall(function() return HttpService:JSONDecode(readfile(CFG.SaveFile)) end)
    if not ok or type(d) ~= "table" then return end
    S.theme      = math.clamp(tonumber(d.theme) or 1, 1, #THEMES)
    if d.sound ~= nil then S.sound = d.sound end
    S.autoReload = d.autoReload == true
    S.lastEmote  = tonumber(d.lastEmote) or 0
    S.speed      = tonumber(d.speed) or 1
    if d.loop ~= nil then S.loop = d.loop end
    S.reverse    = d.reverse == true
    S.walkEmote  = d.walkEmote == true
    S.pack       = type(d.pack) == "string" and d.pack or "none"
    if type(d.toggleKey) == "string" then
        local okk, kc = pcall(function() return Enum.KeyCode[d.toggleKey] end)
        if okk and kc then S.toggleKey = d.toggleKey end
    end
    if type(d.real) == "table" then
        for k, v in pairs(S.real) do
            if type(d.real[k]) == type(v) then S.real[k] = d.real[k] end
        end
        S.real.reach = math.clamp(S.real.reach, 0.3, 2)
        S.real.leanAmt = math.clamp(S.real.leanAmt, 0.2, 2)
        S.real.camAmt = math.clamp(S.real.camAmt, 0.2, 2)
    end
    if type(d.parts) == "table" then
        for g, k in pairs(d.parts) do if GROUPS[g] and type(k) == "string" then S.parts[g] = k end end
    end
    S.hidden     = d.hidden == true
    if d.fab ~= nil then S.fab = d.fab end
    if type(d.fabPos) == "table" and #d.fabPos == 4 then S.fabPos = d.fabPos end
    if type(d.winPos) == "table" and #d.winPos == 4 then S.winPos = d.winPos end
    if type(d.page) == "string" then S.page = d.page end
    if type(d.emoteKey) == "string" then S.emoteKey = d.emoteKey end
    S.favs         = toNumList(d.favs)
    S.customEmotes = toNumList(d.customEmotes)
    S.wheel        = toNumList(d.wheel)
    S.playlist     = toNumList(d.playlist)
    S.recents      = toNumList(d.recents)
    if type(d.packFavs) == "table" then S.packFavs = d.packFavs end
    if type(d.customPack) == "table" then
        for _, f in ipairs(PACK_FIELDS) do S.customPack[f] = tonumber(d.customPack[f]) or 0 end
    end
    if type(d.stats) == "table" then for k, v in pairs(d.stats) do S.stats[tonumber(k) or k] = v end end
    if type(d.savedPacks) == "table" then
        for _, pd in ipairs(d.savedPacks) do local p = packFromJson(pd); if p then S.savedPacks[#S.savedPacks + 1] = p end end
    end
    if type(d.fx) == "table" then
        for k, v in pairs(S.fx) do if type(d.fx[k]) == type(v) then S.fx[k] = d.fx[k] end end
        for _, k in ipairs({ "r", "g", "b" }) do S.fx[k] = math.clamp(S.fx[k], 0, 1) end
    end
    if type(d.fp) == "table" then
        for k, v in pairs(S.fp) do if type(d.fp[k]) == type(v) then S.fp[k] = d.fp[k] end end
        S.fp.fov = math.clamp(S.fp.fov, 60, 110); S.fp.depth = math.clamp(S.fp.depth, 0, 1.2)
        S.fp.followAmt = math.clamp(S.fp.followAmt, 0, 1); S.fp.motion = math.clamp(S.fp.motion, 0, 2)
    end
    S.mini = d.mini == true
    if d.antiAfk ~= nil then S.antiAfk = d.antiAfk == true end
    if type(d.miniPos) == "table" and #d.miniPos == 4 then S.miniPos = d.miniPos end
    if type(d.afk) == "table" then
        S.afk.on = d.afk.on == true
        S.afk.secs = math.clamp(tonumber(d.afk.secs) or 60, CFG.AfkMinSecs, 3600)
        S.afk.emote = tonumber(d.afk.emote) or 0
    end
    if type(d.sh) == "table" then
        for k, v in pairs(S.sh) do if type(d.sh[k]) == type(v) then S.sh[k] = d.sh[k] end end
        S.sh.side = (S.sh.side < 0) and -1 or 1
        S.sh.x = math.clamp(S.sh.x, 0.3, 3.5); S.sh.y = math.clamp(S.sh.y, -1.5, 1.5)
        S.sh.dist = math.clamp(S.sh.dist, 3, 15); S.sh.fov = math.clamp(S.sh.fov, 45, 100)
    end
    if type(d.spawn) == "table" then
        S.spawn.on = d.spawn.on == true; S.spawn.join = d.spawn.join == true
        S.spawn.emote = tonumber(d.spawn.emote) or 0
        S.spawn.delay = math.clamp(tonumber(d.spawn.delay) or 1.5, 0.3, 8)
    end
    if type(d.ev) == "table" then
        for k, v in pairs(S.ev) do
            local e = d.ev[k]
            if type(e) == "table" then v.on = e.on == true; v.emote = tonumber(e.emote) or 0 end
        end
    end
    S.evCd = math.clamp(tonumber(d.evCd) or 3, 1, 20)
    S.evLandMin = math.clamp(tonumber(d.evLandMin) or 60, 20, 150)
    S.evRunMin = math.clamp(tonumber(d.evRunMin) or 14, 6, 30)
    if type(d.tags) == "table" then
        for k, t in pairs(d.tags) do
            local id = tonumber(k)
            if id and type(t) == "table" then
                local c = tonumber(t.c)
                if c and (c < 1 or c > #TAG_COLORS) then c = nil end
                local n = type(t.n) == "string" and t.n:sub(1, 18) or nil
                if n or c then S.tags[id] = { n = n, c = c } end
            end
        end
    end
    if type(d.perf) == "table" then S.perf.on = d.perf.on == true; S.perf.min = math.clamp(tonumber(d.perf.min) or 25, 10, 60) end
    S.hud = d.hud == true
    if type(d.hudPos) == "table" and #d.hudPos == 4 then S.hudPos = d.hudPos end
    S.seenLog = tonumber(d.seenLog) or 0
    S.pingpong = d.pingpong == true
    if type(d.userTabs) == "table" then
        for _, t in ipairs(d.userTabs) do
            if type(t) == "table" and type(t.id) == "string" and type(t.name) == "string" and #S.userTabs < CFG.MaxUserTabs then
                S.userTabs[#S.userTabs + 1] = { id = t.id, name = t.name, ids = toNumList(t.ids) }
            end
        end
    end
end
loadSave()

-- ══════════════════════════════════════════════════════════
--  UTIL
-- ══════════════════════════════════════════════════════════
local UI = { conns = {}, themed = {}, paints = {}, refreshers = {}, orders = {}, revealed = false, firstShow = {} }
local E  = { track = nil, token = 0, orig = {}, viaEmote = {}, animOf = {}, wasMoving = false, seqId = 0 }
local WH = { wasVisible = false }
local FP = { off = Vector3.zero, begun = false, first = false, tok = 0, body = {}, hide = {}, dirty = true,
             nativeCF = nil, bob = Vector3.zero, roll = 0, ph = 0 }
local SH = { off = Vector3.zero, active = false }            -- câmera de ombro (3ª pessoa estilo cinema)
local CAMFX = { roll = 0, amp = 0, t = 0 }                   -- efeitos de câmera: inclinação nas curvas + tremor
function CAMFX.kick(fall) -- pouso forte: tremida + mergulho da câmera
    local k = math.clamp((fall - 32) / 70, 0, 1)
    if k > CAMFX.amp then CAMFX.amp = k end
end

local function parseId(raw)
    if not raw then return 0 end
    local s = tostring(raw):gsub("%s+", "")
    if s == "" or s == "0" then return 0 end
    if s:match("^%d+$") then return tonumber(s) end
    local patterns = {
        "rbxassetid://(%d+)", "asset/%?id=(%d+)", "/store/asset/(%d+)", "/catalog/(%d+)",
        "/library/(%d+)", "/bundles/(%d+)", "/animations/(%d+)", "/asset/(%d+)", "[?&]id=(%d+)",
    }
    for _, p in ipairs(patterns) do
        local m = s:match(p)
        if m then return tonumber(m) end
    end
    local f = s:match("(%d%d%d%d%d%d+)")
    return f and tonumber(f) or 0
end

local function notify(title, text) if UI.toast then UI.toast(title, text) end end

local function sound(name)
    if not S.sound or not SOUNDS[name] then return end
    pcall(function()
        local s = Instance.new("Sound")
        s.SoundId = "rbxassetid://" .. SOUNDS[name]; s.Volume = 0.4; s.Parent = SoundService
        s:Play(); Debris:AddItem(s, 3)
    end)
end

local function copyText(t)
    local fn = setclipboard or toclipboard or set_clipboard or (syn and syn.write_clipboard) or (Clipboard and Clipboard.set)
    if fn then
        local ok = pcall(fn, t)
        if ok then notify("Copiado", t); return true end
    end
    if UI.idBox then UI.idBox.Text = t end
    notify("Sem clipboard", "ID colocado na caixa: " .. t)
    return false
end

local function isFav(id) return table.find(S.favs, id) ~= nil end
local function toggleFav(id)
    local i = table.find(S.favs, id)
    if i then table.remove(S.favs, i) else table.insert(S.favs, 1, id) end
    save()
    return i == nil
end

local Names = { cache = {} }
function Names.get(id, cb)
    local c = Names.cache[id]
    if c then cb(c); return end
    task.spawn(function()
        local ok, info = pcall(function() return MarketplaceService:GetProductInfo(id, Enum.InfoType.Asset) end)
        local n = (ok and info and info.Name and info.Name ~= "" and info.Name) or ("Anim " .. id)
        Names.cache[id] = n
        cb(n)
    end)
end

-- ══════════════════════════════════════════════════════════
--  ENGINE: EMOTES
-- ══════════════════════════════════════════════════════════
function E.parts()
    local c = LP.Character
    local h = c and c:FindFirstChildOfClass("Humanoid")
    local a = h and h:FindFirstChildOfClass("Animator")
    return c, h, a
end

function E.applySpeed()
    local t = E.track
    if not t then return end
    pcall(function()
        -- ping-pong: E.dir inverte a direção toda vez que bate numa ponta (ver loop principal)
        local facing = (S.reverse and -1 or 1) * (S.pingpong and (E.dir or 1) or 1)
        if S.pingpong then t.Looped = true end
        t:AdjustSpeed(S.speed * facing)
        if facing == -1 and not E.ppFlip and t.TimePosition < 0.1 and t.Length > 0 then t.TimePosition = t.Length - 0.05 end
    end)
end

function E.stop()
    E.token += 1
    if E.track then pcall(function() E.track:Stop(0.1) end); E.track = nil end
end

local function loadTrack(animator, id, timeout)
    local anim = Instance.new("Animation")
    anim.AnimationId = (type(id) == "string" and id:find("://", 1, true)) and id or ("rbxassetid://" .. tostring(id))
    if timeout then pcall(function() game:GetService("ContentProvider"):PreloadAsync({ anim }) end) end
    local ok, tr = pcall(function() return animator:LoadAnimation(anim) end)
    if not ok or not tr then return nil end
    local t0, lim = os.clock(), timeout or CFG.LoadTimeout
    while tr.Length == 0 and os.clock() - t0 < lim do task.wait(0.05) end
    if tr.Length == 0 then pcall(function() tr:Destroy() end); return nil end
    return tr
end

function E.record(id)
    S.lastEmote = id
    local i = table.find(S.recents, id); if i then table.remove(S.recents, i) end
    table.insert(S.recents, 1, id)
    while #S.recents > 30 do table.remove(S.recents) end
    S.stats[id] = (S.stats[id] or 0) + 1
    save()
end

function E.play(id, quiet)
    id = tonumber(id)
    if not id or id == 0 then return false end
    local _, hum, animator = E.parts()
    if not animator or hum.Health <= 0 then notify("Erro", "Personagem não está pronto"); return false end

    E.token += 1
    local my = E.token
    if E.track then pcall(function() E.track:Stop(0) end); E.track = nil end

    local track
    if not E.viaEmote[id] then track = loadTrack(animator, id) end
    if my ~= E.token then if track then pcall(function() track:Destroy() end) end; return false end

    if not track then
        -- fallback: id de emote do catálogo (asset type 61) só toca via PlayEmote
        local ok, succ, tr = pcall(function() return hum:PlayEmoteAndGetAnimTrackById(id) end)
        if ok and succ and tr then
            track = tr; E.viaEmote[id] = true
            pcall(function() local a = tr.Animation; local n = a and parseId(a.AnimationId) or 0; if n ~= 0 and n ~= id then E.animOf[id] = n end end)
        end
    end
    if my ~= E.token then return false end

    if not track then
        notify("Não carregou", "ID " .. id .. " — dono privado ou não é R15/animação")
        sound("error")
        return false
    end

    pcall(function() track.Priority = Enum.AnimationPriority.Action4 end)
    pcall(function() track.Looped = S.loop end)
    E.track = track
    E.dir = 1
    track.Stopped:Connect(function() if E.track == track then E.track = nil end end)
    if not track.IsPlaying then pcall(function() track:Play(0.1) end) end
    E.applySpeed()
    if not quiet then E.record(id) end
    return true
end

function E.runSeq(ids, delay, forever)
    if #ids == 0 then return end
    E.seqId += 1
    local my = E.seqId
    task.spawn(function()
        repeat
            for _, id in ipairs(ids) do
                if E.seqId ~= my then return end
                E.play(id)
                local t0 = os.clock()
                while E.seqId == my and os.clock() - t0 < delay do task.wait(0.1) end
            end
        until (not forever) or E.seqId ~= my
    end)
end
function E.stopSeq() E.seqId += 1 end

function E.pool()
    local pool = {}
    for _, t in ipairs(TABS) do for _, r in ipairs(t.ids) do local id = parseId(r); if id ~= 0 then pool[#pool + 1] = id end end end
    for _, id in ipairs(S.favs) do pool[#pool + 1] = id end
    for _, id in ipairs(S.customEmotes) do pool[#pool + 1] = id end
    for _, t in ipairs(S.userTabs) do for _, id in ipairs(t.ids) do pool[#pool + 1] = id end end
    return pool
end
function E.random()
    local pool = E.pool()
    if #pool > 0 then E.play(pool[math.random(#pool)]) end
end

local FX = { Blue = Color3.fromRGB(0,180,255), Purple = Color3.fromRGB(180,0,255), Gold = Color3.fromRGB(255,200,0), Red = Color3.fromRGB(255,40,60) }
function E.clearFx()
    local c = LP.Character; if not c then return end
    for _, d in ipairs(c:GetDescendants()) do
        if d.Name == "EH_PE" then pcall(function() d:Destroy() end) end
    end
end
-- efeitos (tudo local, só você vê). Tudo que é criado se chama EH_PE, então E.clearFx limpa tudo
function E.fxColor()
    local o, F = E.fxObjs, S.fx
    if not o or F.rainbow then return end
    local col = Color3.new(F.r, F.g, F.b)
    pcall(function()
        if o.pe then o.pe.Color = ColorSequence.new(col) end
        if o.hl then o.hl.FillColor = col; o.hl.OutlineColor = col end
        if o.tr then o.tr.Color = ColorSequence.new(col) end
    end)
end

function E.fxApply()
    E.clearFx(); E.fxObjs = nil
    local F = S.fx
    if E.perf or not (F.particles or F.aura or F.trail) then return end
    local c = LP.Character
    local hrp = c and c:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local o = {}
    pcall(function()
        if F.particles then
            local pe = Instance.new("ParticleEmitter")
            pe.Name = "EH_PE"; pe.Texture = "rbxassetid://6101261226"
            pe.Rate = 28; pe.Lifetime = NumberRange.new(1.8); pe.Speed = NumberRange.new(6)
            pe.SpreadAngle = Vector2.new(180, 180); pe.LightEmission = 0.8
            pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.4), NumberSequenceKeypoint.new(1, 0) })
            pe.Parent = hrp; o.pe = pe
        end
        if F.aura then
            local hl = Instance.new("Highlight")
            hl.Name = "EH_PE"; hl.FillTransparency = 0.7; hl.OutlineTransparency = 0.05
            hl.DepthMode = Enum.HighlightDepthMode.Occluded
            hl.Parent = c; o.hl = hl
        end
        if F.trail then
            local a0 = Instance.new("Attachment"); a0.Name = "EH_PE"; a0.Position = Vector3.new(0, 1.2, 0); a0.Parent = hrp
            local a1 = Instance.new("Attachment"); a1.Name = "EH_PE"; a1.Position = Vector3.new(0, -1.6, 0); a1.Parent = hrp
            local tr = Instance.new("Trail")
            tr.Name = "EH_PE"; tr.Attachment0 = a0; tr.Attachment1 = a1; tr.Lifetime = 0.55; tr.LightEmission = 0.85
            tr.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.15), NumberSequenceKeypoint.new(1, 1) })
            tr.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0.2) })
            tr.Parent = hrp; o.tr = tr
        end
    end)
    E.fxObjs = o
    E.fxColor()
end

-- atalho dos botões de cor: define a cor, liga partículas se nada estava ligado; nil = desliga tudo
function E.fxQuick(color)
    local F = S.fx
    if not color then
        F.particles, F.aura, F.trail = false, false, false
    else
        F.r, F.g, F.b = color.R, color.G, color.B
        F.rainbow = false
        if not (F.particles or F.aura or F.trail) then F.particles = true end
    end
    save(); E.fxApply()
end

UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function()
    local o = E.fxObjs
    if not o or not S.fx.rainbow then return end
    local col = Color3.fromHSV((os.clock() * 0.18) % 1, 0.85, 1)
    pcall(function()
        if o.pe then o.pe.Color = ColorSequence.new(col) end
        if o.hl then o.hl.FillColor = col; o.hl.OutlineColor = col end
        if o.tr then o.tr.Color = ColorSequence.new(col) end
    end)
end)

-- ══════════════════════════════════════════════════════════
--  RODA NATIVA DO ROBLOX
--  S.wheel (até 8 ids) -> HumanoidDescription:SetEmotes/SetEquippedEmotes
--  + botão invisível por cima de cada slot: passar o dedo/mouse toca o emote
-- ══════════════════════════════════════════════════════════
function WH.root()
    local ok, w = pcall(function() return CoreGui.RobloxGui.EmotesMenu.Children.Main.EmotesWheel end)
    return ok and w or nil
end
function WH.front()
    local ok, r = pcall(function() return CoreGui.RobloxGui.EmotesMenu.Children.Main.EmotesWheel.Front.EmotesButtons end)
    return ok and r or nil
end

function WH.inject()
    if #S.wheel == 0 then return end
    local char = LP.Character; local hum = char and char:FindFirstChildOfClass("Humanoid"); if not hum then return end
    if hum.RigType == Enum.HumanoidRigType.R6 then notify("Roda", "R6 não suportado, use R15"); return end
    local hd = hum:FindFirstChildOfClass("HumanoidDescription") or hum:FindFirstChild("HumanoidDescription")
    if not hd then return end
    local emoteTable, equipped = {}, {}
    for i = 1, math.min(#S.wheel, CFG.WheelMax) do
        local id = S.wheel[i]
        local base = (Names.cache[id] or ("E" .. id)):gsub("[^%w%s_%-]", ""):sub(1, 30)
        local slot = "S" .. i .. "_" .. base
        emoteTable[slot] = { id }; equipped[i] = slot
    end
    pcall(function() hd:SetEmotes(emoteTable); hd:SetEquippedEmotes(equipped) end)
    task.delay(0.3, WH.connect)
end

local function sortSlots(buttons)
    local hasLayout = false
    for _, b in ipairs(buttons) do if b.LayoutOrder and b.LayoutOrder ~= 0 then hasLayout = true; break end end
    if hasLayout then
        table.sort(buttons, function(a, b) return (a.LayoutOrder or 999) < (b.LayoutOrder or 999) end)
        return
    end
    table.sort(buttons, function(a, b)
        local aa = math.atan2(a.Position.X.Scale - 0.5, -(a.Position.Y.Scale - 0.5))
        local bb = math.atan2(b.Position.X.Scale - 0.5, -(b.Position.Y.Scale - 0.5))
        if aa < 0 then aa += math.pi * 2 end
        if bb < 0 then bb += math.pi * 2 end
        return aa < bb
    end)
end

function WH.connect()
    local front = WH.front(); if not front then return end
    local buttons = {}
    for _, c in pairs(front:GetChildren()) do if c:IsA("ImageLabel") then buttons[#buttons + 1] = c end end
    sortSlots(buttons)
    for i, img in ipairs(buttons) do
        local id = S.wheel[i]
        if id then
            local btn = img:FindFirstChild("EH_Slot")
            if not btn then
                btn = Instance.new("TextButton"); btn.Name = "EH_Slot"
                btn.Size = UDim2.new(1, 0, 1, 0); btn.BackgroundTransparency = 1; btn.Text = ""
                btn.ZIndex = img.ZIndex + 10; btn.Parent = img
            end
            btn:SetAttribute("EmoteId", id)
        else
            local btn = img:FindFirstChild("EH_Slot"); if btn then btn:Destroy() end
        end
    end
end

local function pointIn(px, py, obj)
    local p, s = obj.AbsolutePosition, obj.AbsoluteSize
    return px >= p.X and px <= p.X + s.X and py >= p.Y and py <= p.Y + s.Y
end

function WH.hover(px, py)
    local w = WH.root()
    if not w or not w.Visible then WH.last = nil; return end
    local front = WH.front(); if not front then return end
    local hovered
    for _, img in pairs(front:GetChildren()) do
        if img:IsA("ImageLabel") then
            local b = img:FindFirstChild("EH_Slot")
            if b and pointIn(px, py, img) then hovered = b; break end
        end
    end
    if hovered ~= WH.last then
        WH.last = hovered
        if hovered then
            local id = hovered:GetAttribute("EmoteId")
            if id and id ~= 0 then task.spawn(E.play, id) end
        end
    end
end

function WH.add(id)
    if table.find(S.wheel, id) then notify("Roda", "Já está na roda"); return end
    if #S.wheel >= CFG.WheelMax then notify("Roda cheia", "Máximo " .. CFG.WheelMax .. " — remova um na aba 🎡 Roda"); sound("error"); return end
    table.insert(S.wheel, id); save(); WH.inject()
    notify("🎡 Roda", "Adicionado (" .. #S.wheel .. "/" .. CFG.WheelMax .. ")"); sound("success")
end
function WH.remove(id)
    local i = table.find(S.wheel, id)
    if i then table.remove(S.wheel, i); save(); WH.inject(); task.delay(0.35, WH.connect) end
end

-- ══════════════════════════════════════════════════════════
--  ENGINE: PACKS DE MOVIMENTO
-- ══════════════════════════════════════════════════════════
local MAP = {
    walk = {"walk", 1}, run = {"run", 1}, idle1 = {"idle", 1}, idle2 = {"idle", 2},
    jump = {"jump", 1}, fall = {"fall", 1}, climb = {"climb", 1}, swim = {"swim", 1}, swimidle = {"swimidle", 1},
}

local function packByKey(key)
    if key == "custom" then
        local p = { key = "custom", name = "Custom" }
        for _, f in ipairs(PACK_FIELDS) do p[f] = S.customPack[f] end
        return p
    end
    for _, p in ipairs(PACKS) do if p.key == key then return p end end
    for _, p in ipairs(S.savedPacks) do if p.key == key then return p end end
    return nil
end

local function allPacks()
    local o = {}
    for _, p in ipairs(PACKS) do o[#o + 1] = p end
    for _, p in ipairs(S.savedPacks) do o[#o + 1] = p end
    return o
end

local function packIsEmpty(p)
    for _, f in ipairs(PACK_FIELDS) do if (p[f] or 0) ~= 0 then return false end end
    return true
end

local function packText(p)
    local t = {}
    for _, f in ipairs(PACK_FIELDS) do t[#t + 1] = f .. "=" .. tostring(p[f] or 0) end
    return p.name .. ": " .. table.concat(t, " ")
end

function E.applyPack(char, quiet)
    char = char or LP.Character
    local animate = char and (char:FindFirstChild("Animate") or char:WaitForChild("Animate", 8))
    if not animate then return end
    local pack = packByKey(S.pack)
    for key, m in pairs(MAP) do
        local folder = animate:FindFirstChild(m[1])
        if folder then
            local list = {}
            for _, a in ipairs(folder:GetChildren()) do if a:IsA("Animation") then list[#list + 1] = a end end
            table.sort(list, function(a, b) return a.Name < b.Name end)
            local t = list[m[2]]
            if t then
                local ok = m[1] .. m[2]
                if not E.orig[ok] then E.orig[ok] = t.AnimationId end
                -- parte com override (menu ⋯) vem do pack escolhido pra ela; senão do pack principal
                local ov = S.parts[FIELD_GROUP[key]]
                local src = (ov and packByKey(ov)) or pack
                local nid = src and src[key] or 0
                t.AnimationId = (nid ~= 0) and ("rbxassetid://" .. nid) or E.orig[ok]
            end
        end
    end
    pcall(function()
        animate.Disabled = true
        local _, _, an = E.parts()
        if an then for _, t in ipairs(an:GetPlayingAnimationTracks()) do if t ~= E.track then t:Stop(0) end end end
        task.wait()
        animate.Disabled = false
    end)
    if not quiet then
        local n = 0; for _ in pairs(S.parts) do n += 1 end
        notify(pack and pack.name or "Original", (pack and "Pack aplicado" or "Animações restauradas") .. (n > 0 and (" · " .. n .. " parte(s) trocada(s)") or ""))
    end
    if UI.updateStatus then UI.updateStatus() end
end

function E.setPack(key)
    S.pack = key; S.parts = {}; save() -- escolher pack inteiro limpa os overrides
    task.spawn(E.applyPack)
end

-- aplica só uma parte (walk, idle...) de um pack em cima do pack atual
function E.setPart(group, key)
    if not GROUPS[group] then return end
    S.parts[group] = key; save()
    task.spawn(E.applyPack)
end
function E.clearParts()
    S.parts = {}; save()
    task.spawn(E.applyPack)
end

-- ══════════════════════════════════════════════════════════
--  LOJA (catálogo / creator store / bundles de animação)
-- ══════════════════════════════════════════════════════════
local reqFn = (syn and syn.request) or http_request or request or (fluxus and fluxus.request) or (http and http.request)

local function getJSON(url, tries)
    tries = tries or 0
    if not reqFn then return nil, "executor sem request()" end
    local ok, res = pcall(reqFn, { Url = url, Method = "GET" })
    if not ok or not res then return nil, "request falhou" end
    local code = res.StatusCode
    -- 429 = rate limit: espera e tenta de novo (até 2x)
    if code == 429 and tries < 2 then task.wait(1.5 * (tries + 1)); return getJSON(url, tries + 1) end
    if code and code ~= 200 then
        -- mostra a mensagem que a API mandou junto do código, pra saber o motivo
        local msg
        pcall(function()
            local b = HttpService:JSONDecode(res.Body)
            msg = (b.errors and b.errors[1] and b.errors[1].message) or b.message
        end)
        return nil, "HTTP " .. tostring(code) .. (msg and (" · " .. tostring(msg)) or "")
    end
    local ok2, data = pcall(function() return HttpService:JSONDecode(res.Body) end)
    if not ok2 then return nil, "JSON inválido" end
    return data
end

-- filtros do catálogo (Loja): sort 0 relevância · 1 curtidos · 2 vendidos · 3 atualizados · 4 menor preço · 5 maior preço
-- agg (período, vale pra curtidos/vendidos): 1 hoje · 3 semana · 4 mês · 5 sempre · price: 0 todos · 1 grátis · 2 pagos
local CATF = { sort = 0, agg = 5, price = 0 }
local function catfQuery()
    local q = ""
    if CATF.sort ~= 0 then q = q .. "&SortType=" .. CATF.sort end
    if CATF.sort == 1 or CATF.sort == 2 then q = q .. "&SortAggregation=" .. CATF.agg end
    if CATF.price == 1 then q = q .. "&MinPrice=0&MaxPrice=0" elseif CATF.price == 2 then q = q .. "&MinPrice=1" end
    return q
end

-- fontes de emote: fetch(keyword, token) -> items{ {id,name} }, nextToken | nil, err
local SOURCES = {
    {
        name = "Animações (Creator Store)",
        fetch = function(kw, token)
            local page = tonumber(token) or 0
            local url = ("https://apis.roblox.com/toolbox-service/v1/marketplace/24?limit=%d&pageNumber=%d&keyword=%s")
                :format(CFG.PageSize, page, HttpService:UrlEncode(kw))
            local d, err = getJSON(url)
            if not d then return nil, nil, err end
            local ids = {}
            for _, it in ipairs(d.data or {}) do if it.id then ids[#ids + 1] = it.id end end
            if #ids == 0 then return {}, nil end
            -- sem request de detalhes: os nomes chegam depois, por card (Names.get), e a lista aparece 1 request mais rápido
            local out = {}
            for _, id in ipairs(ids) do out[#out + 1] = { id = id } end
            return out, (#ids >= CFG.PageSize) and (page + 1) or nil
        end,
    },
    {
        name = "Catálogo (emotes)",
        fetch = function(kw, token)
            local function fromToolbox(page)
                -- plano B: Creator Store, asset type 61 (EmoteAnimation) — mesmo host da fonte de Animações
                local url = ("https://apis.roblox.com/toolbox-service/v1/marketplace/61?limit=%d&pageNumber=%d&keyword=%s")
                    :format(CFG.PageSize, page, HttpService:UrlEncode(kw))
                local d, err = getJSON(url)
                if not d then return nil, nil, err end
                local out = {}
                for _, it in ipairs(d.data or {}) do if it.id then out[#out + 1] = { id = it.id } end end
                return out, (#out >= CFG.PageSize) and ("t:" .. (page + 1)) or nil
            end
            -- já caiu pro plano B nas páginas anteriores: continua nele
            if token and tostring(token):sub(1, 2) == "t:" then return fromToolbox(tonumber(tostring(token):sub(3)) or 0) end

            -- Category 12 = Animations, Subcategory 39 = EmoteAnimations (filtro no servidor: toda página vem cheia de emote)
            local function fromCatalog(limit)
                local url = "https://catalog.roblox.com/v1/search/items/details?Category=12&Subcategory=39&Limit=" .. limit .. catfQuery()
                    .. (kw ~= "" and ("&Keyword=" .. HttpService:UrlEncode(kw)) or "")
                    .. (token and ("&Cursor=" .. HttpService:UrlEncode(token)) or "")
                local d, err = getJSON(url)
                if not d then return nil, nil, err end
                local out = {}
                for _, it in ipairs(d.data or {}) do
                    if it.id then out[#out + 1] = { id = it.id, name = it.name } end
                end
                local nxt = d.nextPageCursor
                if nxt == "" then nxt = nil end
                return out, nxt
            end
            local items, nxt, err = fromCatalog(CFG.CatalogLimit)
            if not items and err and err:find("HTTP 400") and CFG.CatalogLimit ~= 30 then
                items, nxt, err = fromCatalog(30) -- limite recusado: tenta o padrão
            end
            if not items and not token then
                local i2, n2, e2 = fromToolbox(0) -- catálogo fora do ar/bloqueado: usa a Creator Store
                if i2 then return i2, n2 end
                return nil, nil, tostring(err) .. "  |  plano B: " .. tostring(e2)
            end
            return items, nxt, err
        end,
    },
}

-- cache da sessão: mesma busca/página não bate na API de novo
local FC = {}
local function cachedFetch(idx, kw, token)
    local k = idx .. "|" .. kw .. "|" .. tostring(token or "") .. "|" .. catfQuery()
    local hit = FC[k]
    if hit then return hit[1], hit[2] end
    local items, nxt, err = SOURCES[idx].fetch(kw, token)
    if items then FC[k] = { items, nxt } end
    return items, nxt, err
end

-- packs de animação (bundles)
local Store = {}
local ASSET_FIELD = { [48] = "climb", [50] = "fall", [51] = "idle", [52] = "jump", [53] = "run", [54] = "swim", [55] = "walk" }

function Store.search(kw, cursor)
    -- Category 12 = Animations, Subcategory 38 = AnimationBundles
    local url = "https://catalog.roblox.com/v1/search/items/details?Category=12&Subcategory=38&Limit=30" .. catfQuery()
        .. (kw ~= "" and ("&Keyword=" .. HttpService:UrlEncode(kw)) or "")
        .. (cursor and ("&Cursor=" .. HttpService:UrlEncode(cursor)) or "")
    local d, err = getJSON(url)
    if not d then return nil, nil, err end
    local out = {}
    for _, it in ipairs(d.data or {}) do
        if it.id then out[#out + 1] = { id = it.id, name = it.name or ("Bundle " .. it.id) } end
    end
    local nxt = d.nextPageCursor
    if nxt == "" then nxt = nil end
    return out, nxt
end

-- pega os Animation ids reais dentro de um asset de animação do pack
local function innerAnims(assetId)
    local out = {}
    local ok, objs = pcall(function() return game:GetObjects("rbxassetid://" .. tostring(assetId)) end)
    if ok and objs then
        for _, o in ipairs(objs) do
            local function add(a) local n = parseId(a.AnimationId); if n ~= 0 then out[#out + 1] = { name = a.Name, id = n } end end
            if o:IsA("Animation") then add(o) end
            for _, d in ipairs(o:GetDescendants()) do if d:IsA("Animation") then add(d) end end
        end
    end
    table.sort(out, function(a, b) return a.name < b.name end)
    return out
end

function Store.resolve(bundleId, name)
    local d, err = getJSON("https://catalog.roblox.com/v1/bundles/" .. tostring(bundleId) .. "/details")
    if not d then return nil, err end
    local pack = { key = "s" .. tostring(bundleId), name = name or d.name or ("Bundle " .. bundleId), saved = true }
    for _, f in ipairs(PACK_FIELDS) do pack[f] = 0 end
    local got = 0
    for _, it in ipairs(d.items or {}) do
        if it.type == "Asset" then
            local ok, info = pcall(function() return MarketplaceService:GetProductInfo(it.id, Enum.InfoType.Asset) end)
            local field = ok and info and ASSET_FIELD[info.AssetTypeId]
            if field then
                local anims = innerAnims(it.id)
                if field == "idle" then
                    pack.idle1 = anims[1] and anims[1].id or it.id
                    pack.idle2 = anims[2] and anims[2].id or pack.idle1
                elseif field == "swim" then
                    for _, a in ipairs(anims) do
                        if a.name:lower():find("idle") then pack.swimidle = a.id else pack.swim = a.id end
                    end
                    if pack.swim == 0 then pack.swim = it.id end
                else
                    pack[field] = anims[1] and anims[1].id or it.id
                end
                got += 1
            end
        end
    end
    if got == 0 then return nil, "bundle sem animações de movimento" end
    return pack
end

-- ══════════════════════════════════════════════════════════
--  UI — helpers
-- ══════════════════════════════════════════════════════════
local TweenService = game:GetService("TweenService")
local WHITE = Color3.new(1, 1, 1)

function UI.computeCol()
    local t = THEMES[S.theme]
    UI.col = {
        bg = t.bg,
        panel = t.bg:Lerp(WHITE, 0.055),
        card = t.bg:Lerp(WHITE, 0.10),
        card2 = t.bg:Lerp(WHITE, 0.17),   -- hover
        stroke = t.bg:Lerp(WHITE, 0.22),
        primary = t.primary, accent = t.accent,
        text = Color3.fromRGB(240, 242, 250), sub = Color3.fromRGB(140, 146, 172),
        danger = Color3.fromRGB(255, 82, 98), gold = Color3.fromRGB(255, 208, 70),
    }
end
UI.computeCol()

local function mk(class, props, parent)
    local o = Instance.new(class)
    for k, v in pairs(props) do o[k] = v end
    if parent then o.Parent = parent end
    return o
end
local function th(o, prop, key)
    UI.themed[#UI.themed + 1] = { o, prop, key }
    o[prop] = UI.col[key]
end
local function corner(o, r) return mk("UICorner", { CornerRadius = UDim.new(0, r) }, o) end
local function nextOrder(p) UI.orders[p] = (UI.orders[p] or 0) + 1; return UI.orders[p] end

local function tw(o, props, t, style, dir)
    local ok, tween = pcall(function()
        return TweenService:Create(o, TweenInfo.new(t or 0.15, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out), props)
    end)
    if ok and tween then tween:Play() end
    return tween
end

-- borda temática (registrada no tema)
local function stroke(o, key, thick, transp)
    local s = mk("UIStroke", { Thickness = thick or 1, Transparency = transp or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, o)
    th(s, "Color", key or "stroke")
    return s
end

-- gradiente temático (o objeto precisa de BackgroundColor3 branco, então NÃO usar th no fundo dele)
local function gradient(o, k0, k1, rot)
    o.BackgroundColor3 = WHITE
    local g = mk("UIGradient", { Rotation = rot or 90 }, o)
    local function paint() g.Color = ColorSequence.new(UI.col[k0], UI.col[k1]) end
    UI.paints[#UI.paints + 1] = paint
    paint()
    return g
end

-- hover: sobe 12% de branco no cor base; volta ao soltar (touch não dispara Leave, então volta sozinho após o toque)
local function hoverFx(b, key)
    local function base() return UI.col[key] end
    b.MouseEnter:Connect(function() tw(b, { BackgroundColor3 = base():Lerp(WHITE, 0.12) }, 0.12) end)
    b.MouseLeave:Connect(function() tw(b, { BackgroundColor3 = base() }, 0.14) end)
    b.Activated:Connect(function() task.delay(0.15, function() if b.Parent then tw(b, { BackgroundColor3 = base() }, 0.18) end end) end)
end

function UI.recolor()
    UI.computeCol()
    local keep = {}
    for _, e in ipairs(UI.themed) do
        if e[1] and e[1].Parent then
            keep[#keep + 1] = e
            pcall(function() e[1][e[2]] = UI.col[e[3]] end)
        end
    end
    UI.themed = keep -- poda o que já foi destruído (cards da Loja etc.)
    for _, p in ipairs(UI.paints) do pcall(p) end
    for _, r in ipairs(UI.refreshers) do pcall(r) end
end

local function label(parent, text, size, key, font, extra)
    local l = mk("TextLabel", {
        BackgroundTransparency = 1, Text = text, TextSize = size or 12, Font = font or Enum.Font.GothamMedium,
        TextXAlignment = Enum.TextXAlignment.Left, TextWrapped = true,
    }, parent)
    if extra then for k, v in pairs(extra) do l[k] = v end end
    th(l, "TextColor3", key or "text")
    return l
end

local function button(parent, text, size, onClick, key)
    key = key or "card"
    local b = mk("TextButton", {
        Size = size, AutoButtonColor = false, Text = text, Font = Enum.Font.GothamBold, TextSize = 11, BorderSizePixel = 0,
    }, parent)
    th(b, "BackgroundColor3", key); th(b, "TextColor3", "text"); corner(b, 8)
    if key == "primary" then stroke(b, "accent", 1, 0.55) else stroke(b, "stroke", 1, 0.4) end
    hoverFx(b, key)
    b.Activated:Connect(function() sound("click"); onClick(b) end)
    return b
end

local function textbox(parent, placeholder, size, pos)
    local t = mk("TextBox", {
        Size = size, Position = pos or UDim2.new(), PlaceholderText = placeholder, Text = "", ClearTextOnFocus = false,
        Font = Enum.Font.Gotham, TextSize = 11, BorderSizePixel = 0, TextXAlignment = Enum.TextXAlignment.Left,
    }, parent)
    th(t, "BackgroundColor3", "panel"); th(t, "TextColor3", "text"); th(t, "PlaceholderColor3", "sub")
    corner(t, 8); mk("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 6) }, t)
    local st = stroke(t, "stroke", 1, 0.2)
    t.Focused:Connect(function() st.Color = UI.col.accent; st.Transparency = 0 end)
    t.FocusLost:Connect(function() st.Color = UI.col.stroke; st.Transparency = 0.2 end)
    return t
end

local function chips(parent, names, onPick, initial)
    local sel = initial or 1
    local btns, strokes = {}, {}
    local function paint(instant)
        for i, b in ipairs(btns) do
            local on = (i == sel)
            local bg = on and UI.col.primary or UI.col.card
            if instant then b.BackgroundColor3 = bg else tw(b, { BackgroundColor3 = bg }, 0.15) end
            b.TextColor3 = on and UI.col.text or UI.col.sub
            strokes[i].Color = on and UI.col.accent or UI.col.stroke
            strokes[i].Transparency = on and 0.35 or 0.5
        end
    end
    for i, n in ipairs(names) do
        local b = mk("TextButton", {
            Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, AutoButtonColor = false, Text = n,
            Font = Enum.Font.GothamBold, TextSize = 11, BorderSizePixel = 0, LayoutOrder = i,
        }, parent)
        mk("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }, b)
        corner(b, 14)
        strokes[i] = mk("UIStroke", { Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, b)
        b.MouseEnter:Connect(function() if i ~= sel then tw(b, { BackgroundColor3 = UI.col.card2 }, 0.1) end end)
        b.MouseLeave:Connect(function() if i ~= sel then tw(b, { BackgroundColor3 = UI.col.card }, 0.12) end end)
        b.Activated:Connect(function() sel = i; paint(); sound("click"); onPick(i) end)
        btns[i] = b
    end
    UI.paints[#UI.paints + 1] = paint
    paint(true)
    return { get = function() return sel end, set = function(i) sel = i; paint() end }
end

local function chipRow(parent, pos)
    local r = mk("ScrollingFrame", {
        Position = pos, Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 0,
        AutomaticCanvasSize = Enum.AutomaticSize.X, CanvasSize = UDim2.new(), ScrollingDirection = Enum.ScrollingDirection.X,
    }, parent)
    mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, VerticalAlignment = Enum.VerticalAlignment.Center }, r)
    mk("UIPadding", { PaddingLeft = UDim.new(0, 1), PaddingTop = UDim.new(0, 1), PaddingBottom = UDim.new(0, 1) }, r)
    return r
end

local function scroller(parent, pos, size)
    local s = mk("ScrollingFrame", {
        Position = pos, Size = size, BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3,
        AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(),
    }, parent)
    th(s, "ScrollBarImageColor3", "accent")
    return s
end

local function clearKids(s)
    for _, c in ipairs(s:GetChildren()) do
        if not c:IsA("UIListLayout") and not c:IsA("UIGridLayout") and not c:IsA("UIPadding") then c:Destroy() end
    end
end

local function gridOf(parent, pos, size)
    local s = scroller(parent, pos, size)
    mk("UIGridLayout", { CellSize = UDim2.fromOffset(106, 130), CellPadding = UDim2.fromOffset(8, 8), SortOrder = Enum.SortOrder.LayoutOrder }, s)
    mk("UIPadding", { PaddingTop = UDim.new(0, 3), PaddingLeft = UDim.new(0, 2), PaddingBottom = UDim.new(0, 6) }, s)
    return s
end

local function listOf(parent, pos, size, pad)
    local s = scroller(parent, pos, size)
    mk("UIListLayout", { Padding = UDim.new(0, pad or 5), SortOrder = Enum.SortOrder.LayoutOrder }, s)
    return s
end

-- botãozinho de ícone (usado nos cards): fundo escuro, hover vira primary
local function miniBtn(parent, text, order, wScale, count)
    local b = mk("TextButton", {
        Size = UDim2.new(1 / count, -3, 1, 0), BackgroundColor3 = UI.col.panel,
        Text = text, TextSize = 12, Font = Enum.Font.GothamBold, TextColor3 = UI.col.accent, BorderSizePixel = 0,
        AutoButtonColor = false, LayoutOrder = order,
    }, parent)
    corner(b, 7)
    b.MouseEnter:Connect(function() tw(b, { BackgroundColor3 = UI.col.primary }, 0.1) end)
    b.MouseLeave:Connect(function() tw(b, { BackgroundColor3 = UI.col.panel }, 0.12) end)
    return b
end

-- card de emote: toca no clique; strip embaixo = 📋 copiar ID · ★ favorito · 🎡 roda · ✕ remover
-- (cores diretas, sem th(): a Loja cria centenas de cards e eles são refeitos no recolor)
function UI.emoteCard(grid, id, name, onRemove)
    if name then Names.cache[id] = name end
    local c = mk("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = UI.col.card, BorderSizePixel = 0 }, grid)
    corner(c, 11)
    local st = mk("UIStroke", { Color = UI.col.stroke, Thickness = 1, Transparency = 0.5, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, c)
    local img = mk("ImageLabel", {
        Size = UDim2.new(1, -12, 0, 72), Position = UDim2.fromOffset(6, 6), BackgroundColor3 = UI.col.panel,
        Image = ("rbxthumb://type=Asset&id=%d&w=150&h=150"):format(id), ScaleType = Enum.ScaleType.Fit, BorderSizePixel = 0,
    }, c)
    corner(img, 8)
    -- 👁 prévia 3D (canto da miniatura)
    local eye = mk("TextButton", {
        Position = UDim2.new(1, -25, 0, 3), Size = UDim2.fromOffset(22, 22), BackgroundColor3 = UI.col.bg, BackgroundTransparency = 0.3,
        Text = "👁", TextSize = 12, Font = Enum.Font.GothamBold, TextColor3 = UI.col.text, BorderSizePixel = 0, AutoButtonColor = false,
    }, img)
    corner(eye, 7)
    eye.MouseEnter:Connect(function() tw(eye, { BackgroundTransparency = 0, BackgroundColor3 = UI.col.primary }, 0.1) end)
    eye.MouseLeave:Connect(function() tw(eye, { BackgroundTransparency = 0.3, BackgroundColor3 = UI.col.bg }, 0.12) end)
    eye.Activated:Connect(function() sound("click"); UI.previewEmote(id, Names.cache[id]) end)
    local nm = mk("TextLabel", {
        Position = UDim2.fromOffset(8, 82), Size = UDim2.new(1, -16, 0, 14), BackgroundTransparency = 1, Text = "...",
        TextColor3 = UI.col.text, Font = Enum.Font.GothamMedium, TextSize = 10, TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
    }, c)
    -- faixa de cor + apelido (segurar o card edita)
    local tagBar = mk("Frame", { Position = UDim2.fromOffset(0, 12), Size = UDim2.fromOffset(4, 54), BorderSizePixel = 0, Visible = false, BackgroundColor3 = WHITE }, c)
    corner(tagBar, 2)
    local function paintTag()
        if not nm.Parent then return end
        local t = S.tags[id]
        if t and t.c then tagBar.Visible = true; tagBar.BackgroundColor3 = TAG_COLORS[t.c] else tagBar.Visible = false end
        if t and t.n and t.n ~= "" then nm.Text = t.n elseif Names.cache[id] then nm.Text = Names.cache[id] end
    end
    Names.get(id, function() paintTag() end)
    paintTag()

    local hasTabs = #S.userTabs > 0
    local count = (onRemove and 4 or 3) + (hasTabs and 1 or 0)
    local strip = mk("Frame", { Position = UDim2.new(0, 6, 1, -28), Size = UDim2.new(1, -9, 0, 22), BackgroundTransparency = 1 }, c)
    mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder }, strip)

    local bCopy = miniBtn(strip, "📋", 1, nil, count)
    bCopy.Activated:Connect(function() sound("click"); copyText(tostring(id)) end)

    local function paintStar(b, on) b.Text = on and "★" or "☆"; b.TextColor3 = on and UI.col.gold or UI.col.accent end
    local bFav = miniBtn(strip, "☆", 2, nil, count)
    paintStar(bFav, isFav(id))
    bFav.Activated:Connect(function()
        paintStar(bFav, toggleFav(id)); sound("click")
        if UI.emoteKey == "fav" and UI.refreshEmotes then UI.refreshEmotes() end
    end)

    local bWheel = miniBtn(strip, "🎡", 3, nil, count)
    bWheel.Activated:Connect(function() WH.add(id) end)

    if hasTabs then -- 📁 abre a lista das suas abas pra botar/tirar esse emote
        local bTab = miniBtn(strip, "📁", 4, nil, count)
        bTab.Activated:Connect(function() sound("click"); UI.tabPicker(bTab, id) end)
    end

    if onRemove then
        local bDel = miniBtn(strip, "✕", 5, nil, count)
        bDel.TextColor3 = UI.col.danger
        bDel.Activated:Connect(function() sound("click"); onRemove(id) end)
    end
    if count >= 5 then -- 5 botões: fonte menor pra caber
        for _, b in ipairs(strip:GetChildren()) do if b:IsA("TextButton") then b.TextSize = 10 end end
    end

    c.MouseEnter:Connect(function() tw(c, { BackgroundColor3 = UI.col.card2 }, 0.12); tw(st, { Transparency = 0.05, Color = UI.col.accent }, 0.12) end)
    c.MouseLeave:Connect(function() tw(c, { BackgroundColor3 = UI.col.card }, 0.14); tw(st, { Transparency = 0.5, Color = UI.col.stroke }, 0.14) end)
    local held, pressT, pressPos = false, nil, nil
    c.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            held = false
            local my = os.clock(); pressT = my; pressPos = i.Position
            task.delay(0.55, function()
                if pressT == my and c.Parent then held = true; sound("click"); UI.tagEditor(c, id, paintTag) end
            end)
        end
    end)
    c.InputChanged:Connect(function(i) -- arrastou (rolando a lista): cancela o "segurar"
        if pressT and pressPos and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch)
            and (Vector2.new(i.Position.X, i.Position.Y) - Vector2.new(pressPos.X, pressPos.Y)).Magnitude > 14 then pressT = nil end
    end)
    c.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then pressT = nil end
    end)
    c.Activated:Connect(function()
        if held then held = false; return end
        sound("click"); task.spawn(E.play, id)
        -- piscada de "tocou"
        st.Color = UI.col.primary; st.Thickness = 2
        task.delay(0.18, function() if st.Parent then st.Thickness = 1; st.Color = UI.col.accent end end)
    end)
    return c
end

