-- linha de configuração: card com texto à esquerda e switch (com animação) à direita
local function toggleRow(parent, text, get, set)
    local row = mk("Frame", { Size = UDim2.new(1, -8, 0, 32), BorderSizePixel = 0, LayoutOrder = nextOrder(parent) }, parent)
    th(row, "BackgroundColor3", "card"); corner(row, 9)
    label(row, text, 12, "text", nil, { Size = UDim2.new(1, -64, 1, 0), Position = UDim2.fromOffset(11, 0) })
    local sw = mk("TextButton", {
        AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -9, 0.5, 0), Size = UDim2.fromOffset(38, 20),
        Text = "", AutoButtonColor = false, BorderSizePixel = 0,
    }, row)
    corner(sw, 10)
    local knob = mk("Frame", { Size = UDim2.fromOffset(14, 14), BackgroundColor3 = WHITE, BorderSizePixel = 0 }, sw)
    corner(knob, 7)
    local function paint(instant)
        local on = get()
        local bg = on and UI.col.primary or UI.col.stroke
        local pos = on and UDim2.fromOffset(21, 3) or UDim2.fromOffset(3, 3)
        if instant then sw.BackgroundColor3 = bg; knob.Position = pos
        else tw(sw, { BackgroundColor3 = bg }, 0.15); tw(knob, { Position = pos }, 0.15, Enum.EasingStyle.Back) end
    end
    sw.Activated:Connect(function() set(not get()); paint(); sound("toggle") end)
    UI.paints[#UI.paints + 1] = paint
    paint(true)
end

-- slider arrastável (mouse/toque). get/set em unidades reais; fmt formata o valor mostrado
local function sliderRow(parent, text, min, max, get, set, fmt)
    local row = mk("Frame", { Size = UDim2.new(1, -8, 0, 42), BorderSizePixel = 0, LayoutOrder = nextOrder(parent) }, parent)
    th(row, "BackgroundColor3", "card"); corner(row, 9)
    label(row, text, 12, "text", nil, { Size = UDim2.new(1, -90, 0, 18), Position = UDim2.fromOffset(11, 4), TextWrapped = false })
    local val = label(row, "", 11, "accent", Enum.Font.GothamBold, { Size = UDim2.fromOffset(70, 18), Position = UDim2.new(1, -80, 0, 4), TextXAlignment = Enum.TextXAlignment.Right })
    local track = mk("Frame", { Position = UDim2.new(0, 11, 0, 29), Size = UDim2.new(1, -22, 0, 6), BorderSizePixel = 0 }, row)
    th(track, "BackgroundColor3", "stroke"); corner(track, 3)
    local fill = mk("Frame", { Size = UDim2.new(0, 0, 1, 0), BorderSizePixel = 0 }, track)
    th(fill, "BackgroundColor3", "primary"); corner(fill, 3)
    local knob = mk("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(14, 14), Position = UDim2.new(0, 0, 0.5, 0), BackgroundColor3 = WHITE, BorderSizePixel = 0 }, track)
    corner(knob, 7)
    local function paint()
        local v = get()
        local pct = math.clamp((v - min) / (max - min), 0, 1)
        fill.Size = UDim2.new(pct, 0, 1, 0); knob.Position = UDim2.new(pct, 0, 0.5, 0)
        val.Text = fmt and fmt(v) or tostring(v)
    end
    local hit = mk("TextButton", { Position = UDim2.new(0, 5, 0, 22), Size = UDim2.new(1, -10, 0, 20), BackgroundTransparency = 1, Text = "" }, row)
    local dragging = false
    local function setFromX(x)
        local pct = math.clamp((x - track.AbsolutePosition.X) / math.max(1, track.AbsoluteSize.X), 0, 1)
        local v = min + pct * (max - min)
        set(math.floor(v * 20 + 0.5) / 20) -- passo de 0.05
        paint()
    end
    hit.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            dragging = true; setFromX(i.Position.X)
        end
    end)
    UI.conns[#UI.conns + 1] = UserInputService.InputChanged:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then setFromX(i.Position.X) end
    end)
    UI.conns[#UI.conns + 1] = UserInputService.InputEnded:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then dragging = false; save() end
    end)
    UI.paints[#UI.paints + 1] = paint
    paint()
end

local function btnRow(parent, items)
