function UI.toast(title, text)
    if not UI.toasts then return end
    local holder = mk("Frame", { Size = UDim2.fromOffset(250, 50), BackgroundTransparency = 1, LayoutOrder = math.floor(os.clock() * 100) }, UI.toasts)
    local f = mk("Frame", { Position = UDim2.fromOffset(280, 0), Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = UI.col.panel, BorderSizePixel = 0 }, holder)
    corner(f, 11)
    mk("UIStroke", { Color = UI.col.stroke, Thickness = 1, Transparency = 0.15, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, f)
    local bar = mk("Frame", { Position = UDim2.fromOffset(8, 9), Size = UDim2.new(0, 3, 1, -18), BackgroundColor3 = UI.col.accent, BorderSizePixel = 0 }, f)
    corner(bar, 2)
    mk("TextLabel", {
        Position = UDim2.fromOffset(19, 6), Size = UDim2.new(1, -28, 0, 18), BackgroundTransparency = 1, Text = tostring(title),
        TextColor3 = UI.col.text, Font = Enum.Font.GothamBold, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, f)
    mk("TextLabel", {
        Position = UDim2.fromOffset(19, 25), Size = UDim2.new(1, -28, 0, 18), BackgroundTransparency = 1, Text = tostring(text or ""),
        TextColor3 = UI.col.sub, Font = Enum.Font.Gotham, TextSize = 10, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
    }, f)
    tw(f, { Position = UDim2.fromOffset(0, 0) }, 0.28, Enum.EasingStyle.Back)
    task.delay(2.8, function()
        if f.Parent then tw(f, { Position = UDim2.fromOffset(280, 0) }, 0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.In) end
    end)
    Debris:AddItem(holder, 3.3)
end

