-- INSERT sempre funciona como reserva, pra você nunca ficar trancado fora do hub
function UI.keyCodes()
    local t = { Enum.KeyCode.Insert }
    local ok, kc = pcall(function() return Enum.KeyCode[S.toggleKey] end)
    if ok and kc then
        t[#t + 1] = kc
        if kc == Enum.KeyCode.Semicolon then t[#t + 1] = Enum.KeyCode.Colon end -- ":" = Shift + ;
    end
    return t
end
function UI.keyLabel()
    if S.toggleKey == "Semicolon" then return ":" end
    return tostring(S.toggleKey)
end
function UI.helpText()
    return "Reabrir escondido: 2 dedos no topo da tela descendo devagar (ou a tecla " .. UI.keyLabel() .. " no PC). Fechar no ✕ esconde de novo."
end
function UI.updateKeyLabel()
    local t = UI.keyLabel()
    if UI.keyCap then UI.keyCap.Text = t end
    if UI.keyBtn then UI.keyBtn.Text = "[ " .. t .. " ]" end
    if UI.keyHelp then UI.keyHelp.Text = UI.helpText() end
end

