    function UI.updateStatus()
        local p = (S.pack ~= "none") and packByKey(S.pack) or nil
        local n = 0; for _ in pairs(S.parts) do n += 1 end
        nm.Text = (p and p.name or "Original") .. (n > 0 and ("  +" .. n) or "")
    end
    UI.refreshers[#UI.refreshers + 1] = UI.updateStatus
    UI.updateStatus()
end

local Content = mk("Frame", { Position = UDim2.fromOffset(126, 46), Size = UDim2.new(1, -126, 1, -46), BackgroundTransparency = 1 }, Main)
mk("UIPadding", { PaddingTop = UDim.new(0, 10), PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 12), PaddingBottom = UDim.new(0, 10) }, Content)

local pages, pageBtns = {}, {}
local function newPage(name, icon)
    local p = mk("Frame", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Visible = false }, Content)
    pages[name] = p
    local b = mk("TextButton", {
        Size = UDim2.new(1, 0, 0, 34), AutoButtonColor = false, Text = "", BorderSizePixel = 0, LayoutOrder = #pageBtns + 1,
        BackgroundColor3 = UI.col.card, BackgroundTransparency = 1,
    }, SideList)
    corner(b, 9)
    local bar = mk("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(3, 16), BorderSizePixel = 0, Visible = false }, b)
    corner(bar, 2); th(bar, "BackgroundColor3", "accent")
    local ic = mk("TextLabel", { Position = UDim2.fromOffset(11, 0), Size = UDim2.fromOffset(20, 34), BackgroundTransparency = 1, Text = icon, TextSize = 14, Font = Enum.Font.GothamBold }, b)
    local lb = mk("TextLabel", {
        Position = UDim2.fromOffset(36, 0), Size = UDim2.new(1, -40, 1, 0), BackgroundTransparency = 1, Text = name,
        Font = Enum.Font.GothamBold, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
    }, b)
    pageBtns[name] = { btn = b, bar = bar, ic = ic, lb = lb }
    b.MouseEnter:Connect(function() if UI.current ~= name then tw(b, { BackgroundTransparency = 0.6, BackgroundColor3 = UI.col.card }, 0.1) end end)
    b.MouseLeave:Connect(function() if UI.current ~= name then tw(b, { BackgroundTransparency = 1 }, 0.12) end end)
    b.Activated:Connect(function() sound("click"); UI.show(name) end)
    return p
end
function UI.show(name)
    if not pages[name] then name = "Emotes" end
    local changed = (UI.current ~= name)
    for n, p in pairs(pages) do p.Visible = (n == name) end
    if changed then -- a página nova sobe 10px suavemente
        pages[name].Position = UDim2.fromOffset(0, 10)
        tw(pages[name], { Position = UDim2.new() }, 0.2)
    end
    for n, e in pairs(pageBtns) do
        local on = (n == name)
        tw(e.btn, { BackgroundTransparency = on and 0 or 1, BackgroundColor3 = on and UI.col.primary or UI.col.card }, 0.15)
        e.bar.Visible = on
        e.lb.TextColor3 = on and UI.col.text or UI.col.sub
        e.ic.TextColor3 = on and UI.col.text or UI.col.sub
    end
    UI.current = name
    if UI.closePopup then UI.closePopup() end
    if UI.closePreview then UI.closePreview() end
    local f = UI.firstShow[name]
    if f then UI.firstShow[name] = nil; task.defer(f) end
    if S.page ~= name then S.page = name; save() end
end
UI.paints[#UI.paints + 1] = function() if UI.current then UI.show(UI.current) end end

