function UI.placePopup(pop, anchor)
    task.defer(function()
        if not pop.Parent or not anchor.Parent then return end
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
        local ap, as = anchor.AbsolutePosition, anchor.AbsoluteSize
        local w, h = pop.AbsoluteSize.X, pop.AbsoluteSize.Y
        local x = math.clamp(ap.X, 8, math.max(8, vp.X - w - 8))
        local y = ap.Y + as.Y + 5
        if y + h > vp.Y - 8 then y = math.max(8, ap.Y - h - 5) end
        pop.Position = UDim2.fromOffset(x, y)
    end)
end

-- segurar o card: apelido (aparece no lugar do nome) + cor (faixa na lateral do card)
function UI.tagEditor(anchor, id, onChange)
    UI.closePopup()
    local catcher = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 100 }, Gui)
    catcher.Activated:Connect(UI.closePopup)
    local pop = mk("Frame", {
        Position = UDim2.fromOffset(-3000, -3000), Size = UDim2.fromOffset(214, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundColor3 = UI.col.panel, BorderSizePixel = 0, ZIndex = 101,
    }, Gui)
    corner(pop, 12)
    mk("UIStroke", { Color = UI.col.accent, Thickness = 1.2, Transparency = 0.25, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, pop)
    mk("UIScale", { Scale = UI.baseScale or 1 }, pop)
    mk("UIPadding", { PaddingTop = UDim.new(0, 9), PaddingBottom = UDim.new(0, 9), PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9) }, pop)
    mk("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, pop)
    UI.popup, UI.catcher = pop, catcher
    local cur = S.tags[id] or {}
    local pick = cur.c
    mk("TextLabel", {
        Size = UDim2.new(1, 0, 0, 16), LayoutOrder = 0, BackgroundTransparency = 1, Text = "Apelido e cor", Font = Enum.Font.GothamBold,
        TextSize = 11, TextColor3 = UI.col.accent, TextXAlignment = Enum.TextXAlignment.Left,
    }, pop)
    local tb = textbox(pop, "apelido (opcional)", UDim2.new(1, 0, 0, 28))
    tb.LayoutOrder = 1; tb.Text = cur.n or ""
    local sw = mk("Frame", { Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1, LayoutOrder = 2 }, pop)
    mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, sw)
    local marks = {}
    local function paintSw()
        for i, m in pairs(marks) do m.Thickness = (pick == i or (i == 0 and pick == nil)) and 2 or 0 end
    end
    for i = 0, #TAG_COLORS do
        local b = mk("TextButton", {
            Size = UDim2.fromOffset(20, 20), LayoutOrder = i, AutoButtonColor = false, BorderSizePixel = 0, Text = i == 0 and "✕" or "",
            TextSize = 11, Font = Enum.Font.GothamBold, TextColor3 = UI.col.sub, BackgroundColor3 = i == 0 and UI.col.card or TAG_COLORS[i],
        }, sw)
        corner(b, 10)
        marks[i] = mk("UIStroke", { Color = WHITE, Thickness = 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, b)
        b.Activated:Connect(function() sound("click"); pick = (i > 0) and i or nil; paintSw() end)
    end
    paintSw()
    local save1 = button(pop, "Salvar", UDim2.new(1, 0, 0, 28), function()
        local nm = tb.Text:gsub("^%s+", ""):gsub("%s+$", "")
        nm = nm:sub(1, 18)
        if nm == "" and not pick then S.tags[id] = nil else S.tags[id] = { n = (nm ~= "") and nm or nil, c = pick } end
        save(); UI.closePopup()
        if onChange then onChange() end
    end, "primary")
    save1.LayoutOrder = 3
    UI.placePopup(pop, anchor)
end

-- 📁 dos cards: popup com as suas abas. Toca numa aba pra botar o emote (✔ = já está, toca de novo pra tirar)
function UI.tabPicker(anchor, id)
    UI.closePopup()
    local catcher = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 100 }, Gui)
    catcher.Activated:Connect(UI.closePopup)
    local pop = mk("Frame", {
        Position = UDim2.fromOffset(-3000, -3000), Size = UDim2.fromOffset(176, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundColor3 = UI.col.panel, BorderSizePixel = 0, ZIndex = 101,
    }, Gui)
    corner(pop, 12)
    mk("UIStroke", { Color = UI.col.accent, Thickness = 1.2, Transparency = 0.25, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, pop)
    mk("UIScale", { Scale = UI.baseScale or 1 }, pop)
    mk("UIPadding", { PaddingTop = UDim.new(0, 9), PaddingBottom = UDim.new(0, 9), PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9) }, pop)
    mk("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder }, pop)
    UI.popup, UI.catcher = pop, catcher
    mk("TextLabel", {
        Size = UDim2.new(1, 0, 0, 16), LayoutOrder = 0, BackgroundTransparency = 1, Text = "Botar / tirar da aba", Font = Enum.Font.GothamBold,
        TextSize = 11, TextColor3 = UI.col.accent, TextXAlignment = Enum.TextXAlignment.Left,
    }, pop)
    for i, t in ipairs(S.userTabs) do
        local has = table.find(t.ids, id) ~= nil
        local b = mk("TextButton", {
            Size = UDim2.new(1, 0, 0, 28), LayoutOrder = i, AutoButtonColor = false, BorderSizePixel = 0, Font = Enum.Font.GothamBold,
            TextSize = 11, Text = (has and "✔  " or "📁  ") .. t.name, TextColor3 = UI.col.text, TextTruncate = Enum.TextTruncate.AtEnd,
            BackgroundColor3 = has and UI.col.primary or UI.col.card,
        }, pop)
        corner(b, 8)
        b.Activated:Connect(function()
            sound("click")
            local idx = table.find(t.ids, id)
            if idx then table.remove(t.ids, idx); notify(t.name, "Emote tirado da aba")
            else table.insert(t.ids, 1, id); notify(t.name, "Emote adicionado (" .. #t.ids .. ")") end
            save(); UI.closePopup()
            if UI.emoteKey == "t:" .. t.id and UI.refreshEmotes then UI.refreshEmotes() end
        end)
    end
    task.defer(function()
        if not pop.Parent or not anchor.Parent then return end
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
        local ap, as = anchor.AbsolutePosition, anchor.AbsoluteSize
        local w, h = pop.AbsoluteSize.X, pop.AbsoluteSize.Y
        local x = math.clamp(ap.X, 8, math.max(8, vp.X - w - 8))
        local y = ap.Y + as.Y + 5
        if y + h > vp.Y - 8 then y = math.max(8, ap.Y - h - 5) end
        pop.Position = UDim2.fromOffset(x, y)
    end)
end

do
    local page = newPage("Emotes", "🎭")
    local BASE_KEYS = { "1", "2", "3", "custom", "fav", "recent", "top", "wheel" }
    local BASE_NAMES = { TABS[1].name, TABS[2].name, TABS[3].name, "Custom", "★ Favs", "Recentes", "Top", "🎡 Roda" }
    local keys, names = {}, {}

    -- "t:<id>" = aba própria
    local function userTab(key)
        local tid = type(key) == "string" and key:match("^t:(.+)$")
        if not tid then return nil end
        for _, t in ipairs(S.userTabs) do if t.id == tid then return t end end
        return nil
    end
    local function rebuildKeys()
        keys, names = {}, {}
        for i, k in ipairs(BASE_KEYS) do keys[i] = k; names[i] = BASE_NAMES[i] end
        for _, t in ipairs(S.userTabs) do keys[#keys + 1] = "t:" .. t.id; names[#names + 1] = "📁 " .. t.name end
    end
    rebuildKeys()
    local initial = table.find(keys, S.emoteKey) or 1
    UI.emoteKey = keys[initial]

    local function items(key)
        local out = {}
        local ut = userTab(key)
        if ut then for _, id in ipairs(ut.ids) do out[#out + 1] = id end
        elseif key == "fav" then for _, id in ipairs(S.favs) do out[#out + 1] = id end
        elseif key == "recent" then for _, id in ipairs(S.recents) do out[#out + 1] = id end
        elseif key == "custom" then for _, id in ipairs(S.customEmotes) do out[#out + 1] = id end
        elseif key == "wheel" then for _, id in ipairs(S.wheel) do out[#out + 1] = id end
        elseif key == "top" then
            local arr = {}
            for k, v in pairs(S.stats) do if tonumber(k) then arr[#arr + 1] = { tonumber(k), v } end end
            table.sort(arr, function(a, b) return a[2] > b[2] end)
            for i = 1, math.min(#arr, 24) do out[i] = arr[i][1] end
        else
            local tab = TABS[tonumber(key)]
            if tab then for _, r in ipairs(tab.ids) do local id = parseId(r); if id ~= 0 then out[#out + 1] = id end end end
        end
        return out
    end
    UI.emoteItems = items

    local grid
    local function removeFor(key)
        local ut = userTab(key)
        if ut then
            return function(id)
                local i = table.find(ut.ids, id); if i then table.remove(ut.ids, i); save() end
                UI.refreshEmotes()
            end
        elseif key == "custom" then
            return function(id)
                local i = table.find(S.customEmotes, id); if i then table.remove(S.customEmotes, i); save() end
                UI.refreshEmotes()
            end
        elseif key == "wheel" then
            return function(id) WH.remove(id); UI.refreshEmotes() end
        end
        return nil
    end
    function UI.refreshEmotes()
        clearKids(grid)
        local rm = removeFor(UI.emoteKey)
        for i, id in ipairs(items(UI.emoteKey)) do UI.emoteCard(grid, id, nil, rm).LayoutOrder = i end
    end

    local row = chipRow(page, UDim2.new())
    local c, showNew, addBtn
    local function updateAddBtn()
        if addBtn then addBtn.Text = userTab(UI.emoteKey) and "+ Aba" or "+ Custom" end
    end
    local function buildChips()
        clearKids(row)
        rebuildKeys()
        if not table.find(keys, UI.emoteKey) then UI.emoteKey = keys[1]; S.emoteKey = keys[1] end
        local cur = table.find(keys, UI.emoteKey) or 1
        local shown = {}
        for i, n in ipairs(names) do shown[i] = n end
        if #S.userTabs < CFG.MaxUserTabs then shown[#shown + 1] = "＋ Aba" end
        if UI.chipPaint then -- tira o repaint dos chips antigos (já destruídos)
            local i = table.find(UI.paints, UI.chipPaint); if i then table.remove(UI.paints, i) end
        end
        c = chips(row, shown, function(i)
            if i > #keys then -- "＋ Aba": abre a linha de nome e volta a seleção pra aba atual
                c.set(table.find(keys, UI.emoteKey) or 1)
                showNew(true)
                return
            end
            UI.emoteKey = keys[i]; S.emoteKey = keys[i]; save(); UI.refreshEmotes(); updateAddBtn()
        end, cur)
        UI.chipPaint = UI.paints[#UI.paints]
    end

    local inRow = mk("Frame", { Position = UDim2.fromOffset(0, 35), Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1 }, page)
    local box = textbox(inRow, "cole ID ou link do emote", UDim2.new(1, -150, 1, 0))
    UI.idBox = box
    button(inRow, "▶", UDim2.new(0, 30, 1, 0), function()
        local id = parseId(box.Text)
        if id == 0 then notify("ID inválido", "Cole um número ou link"); sound("error"); return end
        task.spawn(E.play, id)
    end, "primary").Position = UDim2.new(1, -146, 0, 0)
    addBtn = button(inRow, "+ Custom", UDim2.new(0, 62, 1, 0), function()
        local id = parseId(box.Text)
        if id == 0 then notify("ID inválido", "Cole um número ou link"); sound("error"); return end
        local ut = userTab(UI.emoteKey)
        if ut then -- numa aba própria: salva nela e fica nela
            if not table.find(ut.ids, id) then table.insert(ut.ids, 1, id); save() end
            notify(ut.name, "Salvo (" .. #ut.ids .. ")")
            UI.refreshEmotes()
            return
        end
        if not table.find(S.customEmotes, id) then table.insert(S.customEmotes, id); save() end
        notify("Custom", "Salvo (" .. #S.customEmotes .. ")")
        c.set(4); UI.emoteKey = "custom"; S.emoteKey = "custom"; save(); UI.refreshEmotes(); updateAddBtn()
    end)
    addBtn.Position = UDim2.new(1, -112, 0, 0)
    button(inRow, "🎡+", UDim2.new(0, 46, 1, 0), function()
        local id = parseId(box.Text)
        if id == 0 then notify("ID inválido", "Cole um número ou link"); sound("error"); return end
        WH.add(id)
        if UI.emoteKey == "wheel" then UI.refreshEmotes() end
    end).Position = UDim2.new(1, -46, 0, 0)

    -- linha de "nova aba" (troca de lugar com a linha do ID enquanto aberta)
    local newRow = mk("Frame", { Position = UDim2.fromOffset(0, 35), Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, Visible = false }, page)
    local nbox = textbox(newRow, "nome da nova aba", UDim2.new(1, -112, 1, 0))
    local function createTab()
        local nm = nbox.Text:gsub("^%s+", ""):gsub("%s+$", "")
        nm = nm:sub(1, 14)
        if nm == "" then notify("Aba", "Dá um nome pra aba"); sound("error"); return end
        if #S.userTabs >= CFG.MaxUserTabs then notify("Aba", "Limite de " .. CFG.MaxUserTabs .. " abas"); sound("error"); return end
        for _, t in ipairs(S.userTabs) do
            if t.name:lower() == nm:lower() then notify("Aba", "Já existe uma aba com esse nome"); sound("error"); return end
        end
        local tab = { id = HttpService:GenerateGUID(false):sub(1, 8), name = nm, ids = {} }
        S.userTabs[#S.userTabs + 1] = tab
        UI.emoteKey = "t:" .. tab.id; S.emoteKey = UI.emoteKey; save()
        showNew(false); buildChips(); updateAddBtn(); UI.refreshEmotes()
        if UI.refreshTabsMgr then UI.refreshTabsMgr() end
        notify("Aba criada", nm .. "  ·  botar emote: + Aba ou 📁 nos cards")
    end
    button(newRow, "Criar", UDim2.new(0, 58, 1, 0), createTab, "primary").Position = UDim2.new(1, -106, 0, 0)
    button(newRow, "✕", UDim2.new(0, 46, 1, 0), function() showNew(false) end).Position = UDim2.new(1, -46, 0, 0)
    nbox.FocusLost:Connect(function(enter) if enter then createTab() end end)
    showNew = function(v)
        newRow.Visible = v; inRow.Visible = not v
        if v then nbox.Text = ""; task.defer(function() pcall(function() nbox:CaptureFocus() end) end) end
    end

    grid = gridOf(page, UDim2.fromOffset(0, 72), UDim2.new(1, 0, 1, -72))
    UI.refreshers[#UI.refreshers + 1] = UI.refreshEmotes
    function UI.rebuildEmoteTabs() buildChips(); updateAddBtn(); UI.refreshEmotes() end
    buildChips(); updateAddBtn()
    UI.refreshEmotes()
end

