-- ══════════════════════════════════════════════════════════
--  MENU ⋯ DOS PACKS (popup) + CARD DE PACK
--  Aplicar pack inteiro, ou só uma parte (walk / run / idle / jump / fall / climb / swim)
-- ══════════════════════════════════════════════════════════
function UI.closePopup()
    if UI.popup then pcall(function() UI.popup:Destroy() end); UI.popup = nil end
    if UI.catcher then pcall(function() UI.catcher:Destroy() end); UI.catcher = nil end
end

-- garante que o pack existe em PACKS/Salvos (bundle da loja é resolvido e salvo na hora)
-- carrega os dados do pack SEM salvar (usado pela prévia e pelo editor)
function UI.loadPack(ctx, cb)
    if not ctx.pack and ctx.bundleId then ctx.pack = packByKey("s" .. tostring(ctx.bundleId)) end
    if ctx.pack then cb(ctx.pack); return end
    if not ctx.bundleId then cb(nil, "pack indisponível"); return end
    task.spawn(function()
        local p, err = Store.resolve(ctx.bundleId, ctx.name)
        if not p then cb(nil, err); return end
        ctx.pack = p; cb(p)
    end)
end

function UI.ensurePack(ctx, cb)
    if not ctx.pack and ctx.bundleId then ctx.pack = packByKey("s" .. tostring(ctx.bundleId)) end
    if ctx.pack then
        -- pack que só foi resolvido pra prévia ainda não está em Salvos: salva agora que vai ser usado
        if ctx.bundleId and not packByKey(ctx.pack.key) then table.insert(S.savedPacks, 1, ctx.pack); save() end
        cb(ctx.pack); return
    end
    if not ctx.bundleId then return end
    task.spawn(function()
        notify("Pack", "resolvendo " .. tostring(ctx.name) .. "...")
        local p, err = Store.resolve(ctx.bundleId, ctx.name)
        if not p then notify("Erro", tostring(err)); sound("error"); return end
        for i, sp in ipairs(S.savedPacks) do if sp.key == p.key then table.remove(S.savedPacks, i); break end end
        table.insert(S.savedPacks, 1, p); save()
        ctx.pack = p
        cb(p)
    end)
end

local function groupHas(p, g)
    for _, f in ipairs(GROUPS[g]) do if (p[f] or 0) ~= 0 then return true end end
    return false
end

-- ctx = { name = "...", pack = <pack já existente> | nil, bundleId = <id da loja> | nil }
function UI.packMenu(anchor, ctx)
    UI.closePopup()
    local catcher = mk("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 100 }, Gui)
    catcher.Activated:Connect(UI.closePopup)
    local pop = mk("Frame", {
        Position = UDim2.fromOffset(-3000, -3000), Size = UDim2.fromOffset(212, 0), AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundColor3 = UI.col.panel, BorderSizePixel = 0, ZIndex = 101,
    }, Gui)
    corner(pop, 12)
    mk("UIStroke", { Color = UI.col.accent, Thickness = 1.2, Transparency = 0.25, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, pop)
    mk("UIScale", { Scale = UI.baseScale or 1 }, pop)
    mk("UIPadding", { PaddingTop = UDim.new(0, 9), PaddingBottom = UDim.new(0, 9), PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9) }, pop)
    mk("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder }, pop)
    UI.popup, UI.catcher = pop, catcher

    local order = 0
    local function nxt() order += 1; return order end
    local function done() UI.closePopup(); if UI.refreshPacks then UI.refreshPacks() end end

    local function pbtn(parent, text, size, active, onClick, color)
        local base = active and UI.col.primary or UI.col.card
        local b = mk("TextButton", {
            Size = size, LayoutOrder = nxt(), AutoButtonColor = false, BorderSizePixel = 0, Text = text, Font = Enum.Font.GothamBold,
            TextSize = 11, BackgroundColor3 = base, TextColor3 = color or UI.col.text,
        }, parent)
        corner(b, 8)
        mk("UIStroke", { Color = active and UI.col.accent or UI.col.stroke, Thickness = 1, Transparency = active and 0.3 or 0.55, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, b)
        b.MouseEnter:Connect(function() tw(b, { BackgroundColor3 = base:Lerp(WHITE, 0.14) }, 0.1) end)
        b.MouseLeave:Connect(function() tw(b, { BackgroundColor3 = base }, 0.12) end)
        b.Activated:Connect(function() sound("click"); onClick() end)
        return b
    end

    -- título
    mk("TextLabel", {
        Size = UDim2.new(1, 0, 0, 18), LayoutOrder = nxt(), BackgroundTransparency = 1, Text = tostring(ctx.name), Font = Enum.Font.GothamBold,
        TextSize = 12, TextColor3 = UI.col.accent, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
    }, pop)

    -- prévia 3D + editar (editar sempre salva uma CÓPIA, o original não muda)
    do
        local r = mk("Frame", { Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, LayoutOrder = nxt() }, pop)
        mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, r)
        pbtn(r, "👁 Prévia", UDim2.new(0.5, -3, 1, 0), false, function() UI.closePopup(); UI.previewPack(ctx) end)
        pbtn(r, "✏ Editar", UDim2.new(0.5, -3, 1, 0), false, function()
            UI.loadPack(ctx, function(p, err)
                if not p then notify("Erro", tostring(err)); sound("error"); return end
                UI.closePopup(); UI.editPack(p)
            end)
        end)
    end

    pbtn(pop, "✔   Aplicar pack inteiro", UDim2.new(1, 0, 0, 30), true, function()
        UI.ensurePack(ctx, function(p) E.setPack(p.key); done() end)
    end)

    -- modo da grade: aplicar só a parte  /  copiar o ID só da parte
    local copyMode = false
    local gridBtns = {}
    local modeLbl = mk("TextLabel", {
        Size = UDim2.new(1, 0, 0, 14), LayoutOrder = nxt(), BackgroundTransparency = 1, Text = "SÓ UMA PARTE (em cima do pack atual)", Font = Enum.Font.GothamBold,
        TextSize = 9, TextColor3 = UI.col.sub, TextXAlignment = Enum.TextXAlignment.Left,
    }, pop)
    local mA, mB
    local function paintMode()
        for _, pair in ipairs({ { mA, not copyMode }, { mB, copyMode } }) do
            local b, on = pair[1], pair[2]
            b.BackgroundColor3 = on and UI.col.primary or UI.col.card
            b.TextColor3 = on and UI.col.text or UI.col.sub
        end
        modeLbl.Text = copyMode and "TOCA NA PARTE PRA COPIAR O ID DELA" or "SÓ UMA PARTE (em cima do pack atual)"
        for g, b in pairs(gridBtns) do
            if copyMode then b.Text = "📋 " .. GROUP_LABEL[g] else
                local on = ctx.pack and S.parts[g] == ctx.pack.key
                b.Text = (on and "✔ " or (GROUP_ICON[g] .. " ")) .. GROUP_LABEL[g]
            end
        end
    end
    do
        local r = mk("Frame", { Size = UDim2.new(1, 0, 0, 24), BackgroundTransparency = 1, LayoutOrder = nxt() }, pop)
        mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, r)
        mA = pbtn(r, "Aplicar", UDim2.new(0.5, -3, 1, 0), false, function() copyMode = false; paintMode() end)
        mB = pbtn(r, "Copiar ID", UDim2.new(0.5, -3, 1, 0), false, function() copyMode = true; paintMode() end)
    end

    local grid = mk("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = nxt() }, pop)
    mk("UIGridLayout", { CellSize = UDim2.new(0.5, -3, 0, 28), CellPadding = UDim2.fromOffset(6, 6), SortOrder = Enum.SortOrder.LayoutOrder }, grid)
    for _, g in ipairs(GROUP_ORDER) do
        gridBtns[g] = pbtn(grid, GROUP_ICON[g] .. " " .. GROUP_LABEL[g], UDim2.new(), false, function()
            if copyMode then
                -- copia só os IDs dessa parte (idle = idle1 e idle2; o resto = 1 id). não salva nada
                UI.loadPack(ctx, function(p, err)
                    if not p then notify("Erro", tostring(err)); sound("error"); return end
                    local ids, seen = {}, {}
                    for _, f in ipairs(GROUPS[g]) do
                        local v = p[f] or 0
                        if v ~= 0 and not seen[v] then seen[v] = true; ids[#ids + 1] = tostring(v) end
                    end
                    if #ids == 0 then notify(GROUP_LABEL[g], "esse pack não tem " .. GROUP_LABEL[g]:lower()); sound("error"); return end
                    copyText(table.concat(ids, "\n"))
                    notify("📋 " .. GROUP_LABEL[g], #ids == 1 and ("ID " .. ids[1] .. " copiado") or (#ids .. " IDs copiados"))
                    UI.closePopup()
                end)
                return
            end
            UI.ensurePack(ctx, function(p)
                if not groupHas(p, g) then notify(GROUP_LABEL[g], "esse pack não tem " .. GROUP_LABEL[g]:lower()); sound("error"); return end
                E.setPart(g, p.key)
                notify(GROUP_LABEL[g] .. " trocado", "← " .. p.name)
                done()
            end)
        end)
    end
    pbtn(grid, "↺ Tirar partes", UDim2.new(), false, function() E.clearParts(); done() end, UI.col.sub)
    paintMode()

    if ctx.bundleId and not packByKey("s" .. tostring(ctx.bundleId)) then
        pbtn(pop, "💾   Salvar em Salvos", UDim2.new(1, 0, 0, 28), false, function()
            UI.ensurePack(ctx, function(p) notify("💾 " .. p.name, "salvo em Salvos"); sound("success"); done() end)
        end)
    end
    pbtn(pop, "📋   Copiar todos os IDs", UDim2.new(1, 0, 0, 28), false, function()
        UI.loadPack(ctx, function(p, err)
            if not p then notify("Erro", tostring(err)); sound("error"); return end
            copyText(packText(p)); notify("📋 " .. p.name, "IDs do pack copiados"); UI.closePopup()
        end)
    end)

    -- posiciona (abre pra baixo; se não couber, abre pra cima) e anima
    task.defer(function()
        if not pop.Parent or not anchor.Parent then return end
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
        local ap, as = anchor.AbsolutePosition, anchor.AbsoluteSize
        local w, h = pop.AbsoluteSize.X, pop.AbsoluteSize.Y
        local x = math.clamp(ap.X + as.X - w, 8, math.max(8, vp.X - w - 8))
        local y = ap.Y + as.Y + 5
        if y + h > vp.Y - 8 then y = math.max(8, ap.Y - h - 5) end
        pop.Position = UDim2.fromOffset(x, y)
    end)
end

-- card de pack (lista): thumb/ícone + nome + sub + botões à direita. o = { order, title, sub, active, empty, thumb, onClick, buttons }
-- buttons = { {texto, fn(btn), cor?}, ... }   (cores diretas: os cards são refeitos no recolor)
function UI.packCard(parent, o)
    local nb = #(o.buttons or {})
    local card = mk("TextButton", {
        Size = UDim2.new(1, -6, 0, 54), AutoButtonColor = false, Text = "", BorderSizePixel = 0, LayoutOrder = o.order,
        BackgroundColor3 = o.active and UI.col.primary:Lerp(UI.col.bg, 0.5) or UI.col.card,
    }, parent)
    corner(card, 11)
    local st = mk("UIStroke", {
        Color = o.active and UI.col.accent or UI.col.stroke, Thickness = o.active and 1.6 or 1, Transparency = o.active and 0.05 or 0.5,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    }, card)
    local ic = mk("ImageLabel", {
        Position = UDim2.fromOffset(9, 7), Size = UDim2.fromOffset(40, 40), BackgroundColor3 = UI.col.panel, BorderSizePixel = 0,
        ScaleType = Enum.ScaleType.Fit, Image = o.thumb and ("rbxthumb://type=BundleThumbnail&id=%d&w=150&h=150"):format(o.thumb) or "",
    }, card)
    corner(ic, 10)
    if not o.thumb then
        mk("TextLabel", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Text = "🏃", TextSize = 18, Font = Enum.Font.GothamBold }, ic)
    end
    local reserve = 62 + nb * 30 + 6
    mk("TextLabel", {
        Position = UDim2.fromOffset(59, 8), Size = UDim2.new(1, -reserve, 0, 18), BackgroundTransparency = 1, Text = o.title,
        TextColor3 = UI.col.text, Font = Enum.Font.GothamBold, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
    }, card)
    mk("TextLabel", {
        Position = UDim2.fromOffset(59, 28), Size = UDim2.new(1, -reserve, 0, 16), BackgroundTransparency = 1, Text = o.empty and "vazio" or (o.sub or ""),
        TextColor3 = UI.col.sub, Font = Enum.Font.Gotham, TextSize = 10, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
    }, card)
    local strip = mk("Frame", {
        AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0), Size = UDim2.new(0, 0, 0, 26),
        AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1,
    }, card)
    mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }, strip)
    for i, b in ipairs(o.buttons or {}) do
        local btn = mk("TextButton", {
            Size = UDim2.fromOffset(26, 26), BackgroundColor3 = UI.col.panel, Text = b[1], TextColor3 = b[3] or UI.col.accent,
            TextSize = (b[1] == "···") and 16 or 13, Font = Enum.Font.GothamBold, BorderSizePixel = 0, AutoButtonColor = false, LayoutOrder = i,
        }, strip)
        corner(btn, 8)
        btn.MouseEnter:Connect(function() tw(btn, { BackgroundColor3 = UI.col.primary }, 0.1) end)
        btn.MouseLeave:Connect(function() tw(btn, { BackgroundColor3 = UI.col.panel }, 0.12) end)
        btn.Activated:Connect(function() sound("click"); b[2](btn) end)
    end
    if not o.active then
        card.MouseEnter:Connect(function() tw(card, { BackgroundColor3 = UI.col.card2 }, 0.12); tw(st, { Transparency = 0.15, Color = UI.col.accent }, 0.12) end)
        card.MouseLeave:Connect(function() tw(card, { BackgroundColor3 = UI.col.card }, 0.14); tw(st, { Transparency = 0.5, Color = UI.col.stroke }, 0.14) end)
    end
    if o.onClick and not o.empty then card.Activated:Connect(function() sound("success"); o.onClick() end) end
    return card
end

-- ══════════════════════════════════════════════════════════
--  PRÉVIA 3D (emote e pack)
--  Clona seu personagem num ViewportFrame e toca a animação nele, sem mexer no seu boneco real.
--  Arrasta pra girar · roda do mouse = zoom · ↻ gira sozinho
-- ══════════════════════════════════════════════════════════
local PV = { token = 0, yaw = 0, dist = 9, auto = false, drag = false, center = Vector3.new(0, 0, 0), map = E.animOf } -- map: id do emote -> id real da animação (compartilhado com E.play)

local Prev = mk("Frame", {
    Position = UDim2.fromOffset(132, 52), Size = UDim2.new(1, -144, 1, -62), BorderSizePixel = 0, Visible = false, ZIndex = 30,
}, Main)
th(Prev, "BackgroundColor3", "panel"); corner(Prev, 12); stroke(Prev, "accent", 1, 0.45)

local Stage = mk("ViewportFrame", {
    Position = UDim2.fromOffset(10, 10), Size = UDim2.new(0, 232, 1, -20), BorderSizePixel = 0,
    Ambient = Color3.fromRGB(150, 150, 170), LightColor = Color3.fromRGB(255, 246, 232), LightDirection = Vector3.new(-0.6, -1, -0.8),
}, Prev)
th(Stage, "BackgroundColor3", "bg"); corner(Stage, 10); stroke(Stage, "stroke", 1, 0.3)
local PCam = mk("Camera", { FieldOfView = 38 }, Stage)
Stage.CurrentCamera = PCam

local StageMsg = mk("TextLabel", {
    Size = UDim2.new(1, -20, 0, 40), Position = UDim2.new(0, 10, 0.5, -20), BackgroundTransparency = 1, Text = "", Font = Enum.Font.GothamMedium,
    TextSize = 11, TextWrapped = true, ZIndex = 2,
}, Stage)
th(StageMsg, "TextColor3", "sub")

local function aim()
    local d = PV.dist
    PCam.CFrame = CFrame.lookAt(PV.center + Vector3.new(math.sin(PV.yaw) * d, 1.1, -math.cos(PV.yaw) * d), PV.center)
end
aim()

function PV.clear()
    PV.token += 1
    if PV.track then pcall(function() PV.track:Stop(0) end); PV.track = nil end
    if PV.wm then pcall(function() PV.wm:Destroy() end) end
    PV.wm, PV.model, PV.hum, PV.animator = nil, nil, nil, nil
end

function PV.buildDummy()
    PV.clear()
    local char = LP.Character
    if not char then return false, "sem personagem pra clonar" end
    pcall(function() char.Archivable = true end)
    local okc, clone = pcall(function() return char:Clone() end)
    if not okc or not clone then return false, "não deu pra clonar o personagem" end
    local kill = {}
    for _, d in ipairs(clone:GetDescendants()) do
        if d:IsA("LuaSourceContainer") or d:IsA("Sound") or d:IsA("ForceField") or d:IsA("BillboardGui") or d:IsA("Highlight") then
            kill[#kill + 1] = d
        end
    end
    for _, d in ipairs(kill) do pcall(function() d:Destroy() end) end
    local hum = clone:FindFirstChildOfClass("Humanoid")
    local root = clone:FindFirstChild("HumanoidRootPart")
    if not hum or not root then pcall(function() clone:Destroy() end); return false, "personagem sem Humanoid" end
    hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
    hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff

    local wm = Instance.new("WorldModel"); wm.Parent = Stage
    clone.Parent = wm
    clone:PivotTo(CFrame.new(0, 0, 0))
    root.Anchored = true
    local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)

    -- plataforma de neon embaixo dos pés
    local feet = hum.HipHeight + root.Size.Y / 2
    local plat = Instance.new("Part")
    plat.Shape = Enum.PartType.Cylinder; plat.Size = Vector3.new(0.2, 5.2, 5.2); plat.Anchored = true; plat.CanCollide = false
    plat.Material = Enum.Material.Neon; plat.Color = UI.col.accent; plat.Transparency = 0.5
    plat.CFrame = CFrame.new(0, -feet - 0.1, 0) * CFrame.Angles(0, 0, math.rad(90))
    plat.Parent = wm

    PV.wm, PV.model, PV.hum, PV.animator = wm, clone, hum, animator
    PV.center = Vector3.new(0, -feet + 2.6, 0)
    PV.r6 = (hum.RigType == Enum.HumanoidRigType.R6)
    aim()
    return true
end

-- toca um id no boneco da prévia (yield: chamar dentro de task.spawn)
-- emote do catálogo (tipo 61) não carrega direto no clone e PlayEmote não roda dentro do ViewportFrame.
-- Tenta em ordem: id real em cache → id direto (com preload) → GetObjects → id real lido do personagem → KeyframeSequence → PlayEmote.
-- Se tudo falhar, devolve (e dá warn no console) o que cada etapa respondeu.
PV.timeout = 5
function PV.play(id, loop, speed, onStep)
    PV.token += 1
    local my = PV.token
    if PV.track then pcall(function() PV.track:Stop(0.1) end); PV.track = nil end
    local animator, hum = PV.animator, PV.hum
    if not animator then return false, "sem boneco" end
    onStep = onStep or function() end

    local tr
    local notes = {}
    local function dead() return my ~= PV.token end
    local function drop(t) if t then pcall(function() t:Destroy() end) end end
    local function try(aid, tag)
        local t = loadTrack(animator, aid, PV.timeout)
        notes[#notes + 1] = tag .. (t and ":ok" or ":x")
        return t
    end

    -- 0) id real já descoberto
    local real = PV.map[id]
    if real and real ~= id then tr = try(real, "cache") end
    if dead() then drop(tr); return false, "cancelado" end

    -- 1) id direto
    if not tr then onStep("carregando..."); tr = try(id, "direto") end
    if dead() then drop(tr); return false, "cancelado" end

    -- 2) abre o asset e pega o Animation de dentro
    if not tr then
        onStep("resolvendo emote... (1/3)")
        local inner = innerAnims(id)
        notes[#notes + 1] = "objs:" .. #inner
        if dead() then return false, "cancelado" end
        for _, a in ipairs(inner) do
            if a.id ~= id then
                tr = try(a.id, "inner")
                if dead() then drop(tr); return false, "cancelado" end
                if tr then PV.map[id] = a.id; break end
            end
        end
    end

    -- 3) lê o id real da animação no personagem de verdade (toca e para no mesmo frame, não aparece)
    if not tr then
        onStep("resolvendo emote... (2/3)")
        local _, rh = E.parts()
        if rh and rh.Health > 0 and not E.track then
            local ok, succ, rt = pcall(function() return rh:PlayEmoteAndGetAnimTrackById(id) end)
            if ok and succ and rt then
                local n = 0
                pcall(function() n = parseId(rt.Animation.AnimationId) end)
                pcall(function() rt:Stop(0) end)
                notes[#notes + 1] = "real:" .. n
                if n ~= 0 and n ~= id then
                    tr = try(n, "realid")
                    if tr then PV.map[id] = n end
                end
            else
                notes[#notes + 1] = "real:x"
            end
        else
            notes[#notes + 1] = "real:pulou"
        end
        if dead() then drop(tr); return false, "cancelado" end
    end

    -- 4) KeyframeSequence direto (registra e carrega pelo hash)
    if not tr then
        onStep("resolvendo emote... (3/3)")
        local KSP = game:GetService("KeyframeSequenceProvider")
        local src = (PV.map[id] and PV.map[id] ~= id) and PV.map[id] or id
        local ok, ks = pcall(function() return KSP:GetKeyframeSequenceAsync("rbxassetid://" .. tostring(src)) end)
        if ok and ks then
            local ok2, hash = pcall(function() return KSP:RegisterKeyframeSequence(ks) end)
            if ok2 and hash then tr = try(hash, "ks") else notes[#notes + 1] = "ks:reg" end
        else
            notes[#notes + 1] = "ks:get"
        end
        if dead() then drop(tr); return false, "cancelado" end
    end

    -- 5) último recurso
    if not tr and hum then
        local ok, succ, t2 = pcall(function() return hum:PlayEmoteAndGetAnimTrackById(id) end)
        notes[#notes + 1] = "emote:" .. ((ok and succ and t2) and "ok" or "x")
        if ok and succ and t2 then tr = t2 end
        if dead() then drop(tr); return false, "cancelado" end
    end

    if not tr then
        local why = table.concat(notes, " ")
        pcall(function() warn("[GTA EmoteHub] prévia falhou id=" .. id .. " → " .. why) end)
        return false, "não carregou na prévia [" .. why .. "] — use \"tocar no meu personagem\""
    end

    pcall(function() tr.Priority = Enum.AnimationPriority.Action4 end)
    pcall(function() tr.Looped = loop ~= false end)
    PV.track = tr
    if not tr.IsPlaying then pcall(function() tr:Play(0.1) end) end
    pcall(function() tr:AdjustSpeed(speed or 1) end)
    return true
end

-- ── cabeçalho / coluna da direita ───────────────────────────
local Right = mk("Frame", { Position = UDim2.fromOffset(252, 10), Size = UDim2.new(1, -262, 1, -20), BackgroundTransparency = 1 }, Prev)
local PName = label(Right, "", 14, "text", Enum.Font.GothamBold, { Size = UDim2.new(1, -30, 0, 20), TextWrapped = false, TextTruncate = Enum.TextTruncate.AtEnd })
local PSub = label(Right, "", 10, "sub", Enum.Font.Gotham, { Position = UDim2.fromOffset(0, 21), Size = UDim2.new(1, 0, 0, 14), TextWrapped = false, TextTruncate = Enum.TextTruncate.AtEnd })
local PStat = label(Right, "", 10, "accent", Enum.Font.GothamBold, { Position = UDim2.fromOffset(0, 37), Size = UDim2.new(1, 0, 0, 28), TextYAlignment = Enum.TextYAlignment.Top })
local Ctl = mk("ScrollingFrame", {
    Position = UDim2.fromOffset(0, 70), Size = UDim2.new(1, 0, 1, -70 - 36), BackgroundTransparency = 1, BorderSizePixel = 0,
    ScrollBarThickness = 3, AutomaticCanvasSize = Enum.AutomaticSize.Y, CanvasSize = UDim2.new(), ScrollingDirection = Enum.ScrollingDirection.Y,
}, Right)
th(Ctl, "ScrollBarImageColor3", "accent")
mk("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, Ctl)
mk("UIPadding", { PaddingRight = UDim.new(0, 5) }, Ctl)

local function pstat(txt, bad)
    PStat.Text = txt or ""
    PStat.TextColor3 = bad and UI.col.danger or UI.col.accent
end

function UI.closePreview()
    if not Prev.Visible then return end
    Prev.Visible = false
    PV.ctx = nil; PV.clear()
end

do -- fechar, girar
    local x = mk("TextButton", {
        AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), Size = UDim2.fromOffset(24, 24), BorderSizePixel = 0,
        Text = "✕", Font = Enum.Font.GothamBold, TextSize = 11, AutoButtonColor = false,
    }, Right)
    th(x, "BackgroundColor3", "card"); th(x, "TextColor3", "sub"); corner(x, 7)
    x.MouseEnter:Connect(function() tw(x, { BackgroundColor3 = UI.col.danger, TextColor3 = WHITE }, 0.1) end)
    x.MouseLeave:Connect(function() tw(x, { BackgroundColor3 = UI.col.card, TextColor3 = UI.col.sub }, 0.12) end)
    x.Activated:Connect(function() sound("click"); UI.closePreview() end)

    local back = button(Right, "←  Voltar", UDim2.new(1, 0, 0, 28), function() UI.closePreview() end)
    back.AnchorPoint = Vector2.new(0, 1); back.Position = UDim2.new(0, 0, 1, 0)

    local spin = mk("TextButton", {
        AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 8), Size = UDim2.fromOffset(28, 28), BorderSizePixel = 0,
        Text = "↻", Font = Enum.Font.GothamBold, TextSize = 16, AutoButtonColor = false, ZIndex = 3, BackgroundTransparency = 0.25,
    }, Stage)
    th(spin, "BackgroundColor3", "card"); th(spin, "TextColor3", "sub"); corner(spin, 8)
    spin.Activated:Connect(function()
        PV.auto = not PV.auto; sound("click")
        spin.TextColor3 = PV.auto and UI.col.accent or UI.col.sub
    end)
end

-- arrastar = girar · roda = zoom
Stage.InputBegan:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
        PV.drag = true; PV.lastX = i.Position.X
    end
end)
UI.conns[#UI.conns + 1] = UserInputService.InputChanged:Connect(function(i)
    if not Prev.Visible then return end
    if PV.drag and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
        PV.yaw -= (i.Position.X - (PV.lastX or i.Position.X)) * 0.012
        PV.lastX = i.Position.X; aim()
    elseif i.UserInputType == Enum.UserInputType.MouseWheel then
        local p, s = Stage.AbsolutePosition, Stage.AbsoluteSize
        local m = UserInputService:GetMouseLocation()
        if m.X >= p.X and m.X <= p.X + s.X and m.Y >= p.Y - 36 and m.Y <= p.Y + s.Y then
            PV.dist = math.clamp(PV.dist - i.Position.Z * 0.8, 4.5, 15); aim()
        end
    end
end)
UI.conns[#UI.conns + 1] = UserInputService.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then PV.drag = false end
end)
UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function(dt)
    if Prev.Visible and PV.auto and not PV.drag then PV.yaw += dt * 0.7; aim() end
end)

local function openCommon(title, sub)
    UI.closePopup()
    Prev.Visible = true
    PName.Text = title; PSub.Text = sub; pstat("")
    clearKids(Ctl)
    local ok, why = PV.buildDummy()
    StageMsg.Text = ok and "" or tostring(why)
    if ok and PV.r6 then pstat("personagem R6: animações R15 não tocam na prévia", true) end
    return ok
end

-- linha com 2 botões lado a lado
local function row2(parent, a, b)
    local r = mk("Frame", { Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, LayoutOrder = nextOrder(parent) }, parent)
    mk("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, r)
    local ba = button(r, a[1], UDim2.new(0.5, -3, 1, 0), a[2], a[3]); ba.LayoutOrder = 1
    local bb = button(r, b[1], UDim2.new(0.5, -3, 1, 0), b[2], b[3]); bb.LayoutOrder = 2
    return ba, bb
end
local function wide(parent, text, fn, key)
    local b = button(parent, text, UDim2.new(1, 0, 0, 30), fn, key)
    b.LayoutOrder = nextOrder(parent)
    return b
end

-- ── prévia de EMOTE ─────────────────────────────────────────
function UI.previewEmote(id, name)
    id = tonumber(id); if not id then return end
    PV.ctx = { kind = "emote", id = id }
    local ctx = PV.ctx
    local ok = openCommon(name or Names.cache[id] or ("Emote " .. id), "ID " .. id)
    if not name and not Names.cache[id] then Names.get(id, function(n) if PV.ctx == ctx then PName.Text = n end end) end

    local loop, speeds, si = S.loop, { 0.5, 1, 1.5, 2 }, 2
    local function start()
        if not ok then return end
        pstat("carregando...")
        task.spawn(function()
            local good, err = PV.play(id, loop, speeds[si], function(t) if PV.ctx == ctx then pstat(t) end end)
            if PV.ctx ~= ctx then return end
            if good then pstat("▶ tocando na prévia") elseif err ~= "cancelado" then pstat(err, true) end
        end)
    end

    row2(Ctl, { "▶ Reiniciar", function() start() end }, { "⏹ Parar", function()
        PV.token += 1; if PV.track then pcall(function() PV.track:Stop(0.1) end); PV.track = nil end; pstat("parado")
    end })
    local bLoop, bSpd
    bLoop, bSpd = row2(Ctl,
        { "🔁 Loop: " .. (loop and "sim" or "não"), function() loop = not loop; bLoop.Text = "🔁 Loop: " .. (loop and "sim" or "não"); if PV.track then pcall(function() PV.track.Looped = loop end) end end },
        { "⏩ Vel: " .. speeds[si] .. "x", function() si = si % #speeds + 1; bSpd.Text = "⏩ Vel: " .. speeds[si] .. "x"; if PV.track then pcall(function() PV.track:AdjustSpeed(speeds[si]) end) end end })
    local bFav
    bFav = select(1, row2(Ctl,
        { isFav(id) and "★ Favorito" or "☆ Favoritar", function() bFav.Text = toggleFav(id) and "★ Favorito" or "☆ Favoritar" end },
        { "🎡 Pra roda", function() WH.add(id) end }))
    wide(Ctl, "🎭  Tocar no meu personagem", function() task.spawn(E.play, id) end, "primary")
    start()
end

-- ── prévia de PACK ──────────────────────────────────────────
function UI.previewPack(ctx)
    PV.ctx = { kind = "pack", src = ctx }
    local me = PV.ctx
    local ok = openCommon(tostring(ctx.name), "carregando pack...")
    pstat("resolvendo pack...")
    UI.loadPack(ctx, function(p, err)
        if PV.ctx ~= me or not Prev.Visible then return end
        if not p then pstat(tostring(err or "pack indisponível"), true); return end
        PSub.Text = ("walk %s · run %s · idle %s"):format(p.walk or 0, p.run or 0, p.idle1 or 0)
        pstat("escolhe a parte pra ver")

        local sel, cyc, btns = nil, {}, {}
        local function paint()
            for g, b in pairs(btns) do
                local on = (g == sel)
                b.BackgroundColor3 = on and UI.col.primary or UI.col.card
                b.TextColor3 = (groupHas(p, g) and UI.col.text or UI.col.sub)
            end
        end
        local bUse
        local function fieldOf(g)
            local fs = GROUPS[g]
            local i = cyc[g] or 1
            local f = fs[i]
            if (p[f] or 0) == 0 then f = fs[1] end
            return f
        end
        local function show(g)
            if not groupHas(p, g) then return end
            if sel == g and #GROUPS[g] > 1 then cyc[g] = ((cyc[g] or 1) % #GROUPS[g]) + 1 end -- 2º clique no Idle alterna idle1/idle2
            sel = g; paint()
            if bUse then bUse.Text = "Usar só " .. GROUP_LABEL[g] end
            local f = fieldOf(g)
            if not ok then return end
            pstat("carregando " .. GROUP_LABEL[g] .. "...")
            task.spawn(function()
                local good, e2 = PV.play(p[f], true, 1)
                if PV.ctx ~= me then return end
                if good then pstat("▶ " .. GROUP_LABEL[g] .. (#GROUPS[g] > 1 and (" (" .. f .. ")") or "")) elseif e2 ~= "cancelado" then pstat(e2, true) end
            end)
        end

        label(Ctl, "PARTES", 9, "sub", Enum.Font.GothamBold, { Size = UDim2.new(1, 0, 0, 12), LayoutOrder = nextOrder(Ctl) })
        local grid = mk("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = nextOrder(Ctl) }, Ctl)
        mk("UIGridLayout", { CellSize = UDim2.new(1 / 3, -4, 0, 26), CellPadding = UDim2.fromOffset(5, 5), SortOrder = Enum.SortOrder.LayoutOrder }, grid)
        for i, g in ipairs(GROUP_ORDER) do
            local b = mk("TextButton", {
                BorderSizePixel = 0, AutoButtonColor = false, Text = GROUP_ICON[g] .. " " .. GROUP_LABEL[g], Font = Enum.Font.GothamBold,
                TextSize = 10, LayoutOrder = i, BackgroundColor3 = UI.col.card, TextColor3 = UI.col.text,
            }, grid)
            corner(b, 8)
            b.Activated:Connect(function() sound("click"); show(g) end)
            btns[g] = b
        end
        paint()

        wide(Ctl, "✔  Aplicar pack inteiro", function()
            UI.ensurePack(ctx, function(pk) E.setPack(pk.key); if UI.refreshPacks then UI.refreshPacks() end end)
        end, "primary")
        bUse = wide(Ctl, "Usar só …", function()
            if not sel then pstat("escolhe uma parte antes", true); return end
            UI.ensurePack(ctx, function(pk)
                E.setPart(sel, pk.key); notify(GROUP_LABEL[sel] .. " trocado", "← " .. pk.name)
                if UI.refreshPacks then UI.refreshPacks() end
            end)
        end)
        bUse.Text = "Usar só …"

        -- 📋 ID só da parte que está na prévia · ✏ editar (vira cópia)
        row2(Ctl, { "📋 ID da parte", function()
            if not sel then pstat("escolhe uma parte antes", true); return end
            local ids, seen = {}, {}
            for _, f in ipairs(GROUPS[sel]) do
                local v = p[f] or 0
                if v ~= 0 and not seen[v] then seen[v] = true; ids[#ids + 1] = tostring(v) end
            end
            copyText(table.concat(ids, "\n"))
            notify("📋 " .. GROUP_LABEL[sel], #ids == 1 and ("ID " .. ids[1] .. " copiado") or (#ids .. " IDs copiados"))
        end }, { "✏ Editar", function() UI.closePreview(); UI.editPack(p) end })

        -- começa mostrando idle (ou a primeira parte que existir)
        for _, g in ipairs({ "idle", "walk", "run", "jump", "fall", "climb", "swim" }) do
            if groupHas(p, g) then show(g); break end
        end
    end)
end

-- ══════════════════════════════════════════════════════════
--  PÁGINA: PACKS  (seus packs: todos / favoritos / salvos / custom)
-- ══════════════════════════════════════════════════════════
do
    local page = newPage("Packs", "🏃")
    local tabNames = { "Todos", "★ Favs", "Salvos", "Custom" }
    local tab = 1

    local row = chipRow(page, UDim2.new())
    local box = textbox(page, "pesquisar pack...", UDim2.new(1, -226, 0, 28), UDim2.fromOffset(0, 35))
    local list = listOf(page, UDim2.fromOffset(0, 72), UDim2.new(1, 0, 1, -72), 6)
    local form = scroller(page, UDim2.fromOffset(0, 72), UDim2.new(1, 0, 1, -72))
    mk("UIGridLayout", { CellSize = UDim2.new(0.333, -6, 0, 50), CellPadding = UDim2.fromOffset(6, 6), SortOrder = Enum.SortOrder.LayoutOrder }, form)

    local refresh

    -- quais partes (idle, walk...) desse pack estão em uso por override
    local function partsUsing(p)
        local t = {}
        for _, g in ipairs(GROUP_ORDER) do if S.parts[g] == p.key then t[#t + 1] = GROUP_LABEL[g] end end
        return #t > 0 and (" · usando: " .. table.concat(t, ", ")) or ""
    end

    refresh = function()
        clearKids(list)
        list.Visible = (tab ~= 4); form.Visible = (tab == 4); box.Visible = (tab ~= 4)
        if tab == 4 then return end
        local q = box.Text:lower()
        local n = 0
        for _, p in ipairs(allPacks()) do
            local show = (tab == 1) or (tab == 2 and S.packFavs[p.key]) or (tab == 3 and p.saved)
            if show and (q == "" or p.name:lower():find(q, 1, true)) then
                n += 1
                local isF = S.packFavs[p.key] and true or false
                local btns = {
                    { isF and "★" or "☆", function() S.packFavs[p.key] = (not S.packFavs[p.key]) or nil; save(); refresh() end, isF and UI.col.gold or nil },
                    { "👁", function() UI.previewPack({ name = p.name, pack = p }) end },
                    { "···", function(b) UI.packMenu(b, { name = p.name, pack = p }) end },
                }
                if p.saved then
                    btns[#btns + 1] = { "✕", function()
                        for i, sp in ipairs(S.savedPacks) do if sp.key == p.key then table.remove(S.savedPacks, i); break end end
                        S.packFavs[p.key] = nil
                        for g, k in pairs(S.parts) do if k == p.key then S.parts[g] = nil end end
                        if S.pack == p.key then S.pack = "none" end
                        save(); task.spawn(E.applyPack); refresh()
                    end, UI.col.danger }
                end
                local bid = p.key:match("^s(%d+)$")
                UI.packCard(list, {
                    order = n, title = p.name .. (S.pack == p.key and "   ✔ ativo" or ""),
                    sub = ("walk %s · run %s · idle %s"):format(p.walk or 0, p.run or 0, p.idle1 or 0) .. partsUsing(p),
                    active = (S.pack == p.key), empty = packIsEmpty(p), thumb = bid and tonumber(bid) or nil,
                    onClick = function() E.setPack(p.key); task.delay(0.15, refresh) end, buttons = btns,
                })
            end
        end
        if n == 0 then
            if tab == 3 then UI.empty(list, "💾", "Nenhum pack salvo", "Pegue um na Loja de packs ou edite um pack (✏) pra criar uma cópia.")
            elseif tab == 2 then UI.empty(list, "☆", "Sem favoritos", "Toca na ☆ de um pack pra ele aparecer aqui.")
            else UI.empty(list, "🔎", "Nada encontrado", "Tenta outro nome.") end
        end
    end
    UI.refreshPacks = function() refresh() end
    UI.refreshers[#UI.refreshers + 1] = function() refresh() end

    local tabChips = chips(row, tabNames, function(i) tab = i; refresh() end)
    box:GetPropertyChangedSignal("Text"):Connect(function() refresh() end)

    button(page, "🛒 Loja de packs", UDim2.new(0, 116, 0, 28), function()
        if UI.openStorePacks then UI.openStorePacks() end
    end, "primary").Position = UDim2.new(1, -220, 0, 35)
    button(page, "↺ Original", UDim2.new(0, 98, 0, 28), function()
        E.setPack("none"); task.delay(0.2, refresh)
    end).Position = UDim2.new(1, -98, 0, 35)

    -- ── editor de pack ──────────────────────────────────────────
    -- Editar qualquer pack (da loja, built-in, salvo) NUNCA altera o original: "Salvar" cria uma CÓPIA em Salvos.
    -- Cada campo tem 📋 pra copiar o ID só daquela parte.
    local boxes = {}
    local nameCell = mk("Frame", { BackgroundTransparency = 1, LayoutOrder = 0 }, form)
    local srcLbl = label(nameCell, "nome da cópia", 10, "sub", Enum.Font.GothamMedium, { Size = UDim2.new(1, 0, 0, 14), TextWrapped = false, TextTruncate = Enum.TextTruncate.AtEnd })
    local nameBox = textbox(nameCell, "nome do pack", UDim2.new(1, 0, 0, 28), UDim2.fromOffset(0, 17))
    for i, f in ipairs(PACK_FIELDS) do
        local cell = mk("Frame", { BackgroundTransparency = 1, LayoutOrder = i }, form)
        label(cell, f .. "  (" .. (FIELD_GROUP[f] or "") .. ")", 10, "sub", Enum.Font.GothamMedium, { Size = UDim2.new(1, 0, 0, 14), TextWrapped = false })
        local tb = textbox(cell, "id", UDim2.new(1, -31, 0, 28), UDim2.fromOffset(0, 17))
        tb.Text = (S.customPack[f] ~= 0) and tostring(S.customPack[f]) or ""
        boxes[f] = tb
        local cp = mk("TextButton", {
            Position = UDim2.new(1, -27, 0, 17), Size = UDim2.fromOffset(27, 28), BorderSizePixel = 0, Text = "📋", TextSize = 12,
            Font = Enum.Font.GothamBold, AutoButtonColor = false,
        }, cell)
        th(cp, "BackgroundColor3", "card"); th(cp, "TextColor3", "accent"); corner(cp, 8); stroke(cp, "stroke", 1, 0.4)
        cp.MouseEnter:Connect(function() tw(cp, { BackgroundColor3 = UI.col.primary }, 0.1) end)
        cp.MouseLeave:Connect(function() tw(cp, { BackgroundColor3 = UI.col.card }, 0.12) end)
        cp.Activated:Connect(function()
            local v = parseId(tb.Text)
            if v == 0 then notify(f, "campo vazio"); sound("error"); return end
            sound("click"); copyText(tostring(v)); notify("📋 " .. f, "ID " .. v .. " copiado")
        end)
    end

    local function trim(s) return (s:gsub("^%s+", ""):gsub("%s+$", "")) end
    local function saveClone(apply)
        local nm = trim(nameBox.Text); if nm == "" then nm = "Pack custom" end
        local p = { key = "u" .. os.time() .. math.random(100, 999), name = nm, saved = true }
        local any = false
        for _, f in ipairs(PACK_FIELDS) do
            p[f] = parseId(boxes[f].Text); S.customPack[f] = p[f]
            if p[f] ~= 0 then any = true end
        end
        if not any then notify("Pack vazio", "põe pelo menos 1 ID"); sound("error"); return end
        table.insert(S.savedPacks, 1, p)
        if apply then E.setPack(p.key) else save() end
        notify("💾 " .. nm, apply and "cópia salva e aplicada" or "cópia salva em Salvos"); sound("success")
        tab = 3; tabChips.set(3); refresh()
    end

    -- mesma conta do applyPack: pack principal + partes trocadas (S.parts)
    local function effectiveFields()
        local base = (S.pack ~= "none") and packByKey(S.pack) or nil
        local t = {}
        for _, f in ipairs(PACK_FIELDS) do
            local ov = S.parts[FIELD_GROUP[f]]
            local src = (ov and packByKey(ov)) or base
            t[f] = src and src[f] or 0
        end
        return t
    end
    local function fill(vals, name, from)
        for _, f in ipairs(PACK_FIELDS) do
            local v = vals[f] or 0
            boxes[f].Text = (v ~= 0) and tostring(v) or ""
        end
        nameBox.Text = name
        srcLbl.Text = from
    end

    local function cell(order) return mk("Frame", { BackgroundTransparency = 1, LayoutOrder = order }, form) end
    button(cell(90), "💾 Salvar cópia", UDim2.new(1, 0, 0, 30), function() saveClone(false) end).Position = UDim2.fromOffset(0, 17)
    button(cell(91), "✔ Salvar e aplicar", UDim2.new(1, 0, 0, 30), function() saveClone(true) end, "primary").Position = UDim2.fromOffset(0, 17)
    button(cell(92), "📥 Do pack atual", UDim2.new(1, 0, 0, 30), function()
        local cur = (S.pack ~= "none") and packByKey(S.pack) or nil
        fill(effectiveFields(), (cur and cur.name or "Original") .. " (mix)", "cópia de: pack atual + partes")
        sound("click"); notify("📥 Pack atual", "campos preenchidos (inclui as partes trocadas)")
    end).Position = UDim2.fromOffset(0, 17)
    button(cell(93), "🧹 Limpar campos", UDim2.new(1, 0, 0, 30), function() fill({}, "", "nome da cópia"); sound("click") end).Position = UDim2.fromOffset(0, 17)

    -- abre o editor com os dados de um pack (usado pelo menu ⋯ e pela prévia)
    UI.editPack = function(p)
        fill(p, tostring(p.name) .. " (cópia)", "cópia de: " .. tostring(p.name))
        UI.show("Packs")
        tab = 4; tabChips.set(4); refresh()
        notify("✏ Editando cópia", "salvar cria um pack novo; o original não muda")
    end

    refresh()
end

-- ══════════════════════════════════════════════════════════
--  PÁGINA: LOJA  (Emotes · Animações · Packs de animação)
--  Packs de animação = bundles (walk, run, idle, jump, fall, climb, swim). Menu ⋯ aplica só uma parte.
-- ══════════════════════════════════════════════════════════
do
    local page = newPage("Loja", "🛒")
    local C = { mode = 1, kw = "", token = nil, busy = false, n = 0, gen = 0 } -- 1 emotes · 2 animações · 3 packs
    local PH = { "buscar emote (dance, wave...)", "buscar animação (walk, idle...)", "buscar pack ou colar link/ID do bundle" }
    local run

    local row = chipRow(page, UDim2.new())
    local box = textbox(page, PH[1], UDim2.new(1, -176, 0, 28), UDim2.fromOffset(0, 35))

    -- filtros: ordenar por · período · preço (só emotes e packs; Creator Store não tem esses filtros)
    local SORT_NAMES = { "Relevância", "❤ Curtidos", "🔥 Vendidos", "🆕 Atualizados", "💲 Menor preço", "💲 Maior preço" }
    local SORT_VAL   = { 0, 1, 2, 3, 4, 5 }
    local AGG_NAMES  = { "Hoje", "Semana", "Mês", "Sempre" }
    local AGG_VAL    = { 1, 3, 4, 5 }
    local PRICE_NAMES = { "💰 Todos", "💰 Grátis", "💰 Pagos" }
    local sortRow = chipRow(page, UDim2.fromOffset(0, 67))
    local filtRow = chipRow(page, UDim2.fromOffset(0, 97))
    chips(sortRow, SORT_NAMES, function(i) CATF.sort = SORT_VAL[i]; run(true) end, 1)
    chips(filtRow, AGG_NAMES, function(i) CATF.agg = AGG_VAL[i]; if CATF.sort == 1 or CATF.sort == 2 then run(true) end end, 4)
    local priceBtn
    priceBtn = button(filtRow, PRICE_NAMES[1], UDim2.new(0, 96, 1, 0), function()
        CATF.price = (CATF.price + 1) % 3
        priceBtn.Text = PRICE_NAMES[CATF.price + 1]
        run(true)
    end)
    priceBtn.LayoutOrder = 20

    local status = label(page, "Aperte Buscar. Animação privada de outro dono não toca.", 10, "sub", nil,
        { Position = UDim2.fromOffset(2, 129), Size = UDim2.new(1, -4, 0, 16), TextWrapped = false, TextTruncate = Enum.TextTruncate.AtEnd })
    local grid = gridOf(page, UDim2.fromOffset(0, 150), UDim2.new(1, 0, 1, -150))
    local list = listOf(page, UDim2.fromOffset(0, 150), UDim2.new(1, 0, 1, -150), 6)
    list.Visible = false

    local function applyBundle(it)
        UI.ensurePack({ name = it.name, bundleId = it.id }, function(p)
            E.setPack(p.key)
            notify("💾 " .. p.name, "salvo e aplicado"); sound("success")
            if UI.refreshPacks then UI.refreshPacks() end
        end)
    end

    local function addPackCard(it, order)
        local key = "s" .. it.id
        UI.packCard(list, {
            order = order, title = it.name, sub = "bundle " .. it.id .. (packByKey(key) and " · salvo" or ""), thumb = it.id,
            active = (S.pack == key), onClick = function() applyBundle(it) end,
            buttons = {
                { "👁", function() UI.previewPack({ name = it.name, bundleId = it.id, pack = packByKey(key) }) end },
                { "···", function(b) UI.packMenu(b, { name = it.name, bundleId = it.id, pack = packByKey(key) }) end },
                { "▶", function() applyBundle(it) end },
            },
        })
    end

    run = function(reset)
        if not reqFn then status.Text = "Seu executor não tem request()/http_request()."; return end
        if reset then
            C.gen += 1; clearKids(grid); clearKids(list); C.token = nil; C.n = 0; C.kw = box.Text; C.busy = false
        elseif C.busy then
            return
        end
        local gen = C.gen
        C.busy = true; status.Text = "buscando..."
        UI.skeleton(C.mode == 3 and list or grid, C.mode == 3 and 5 or 8, C.mode == 3 and 54 or nil)
        task.spawn(function()
            local items, nxt, err
            if C.mode == 3 then
                -- link/ID de bundle: importa direto
                if reset and (C.kw:find("bundles") or C.kw:match("^%s*%d+%s*$")) then
                    local id = parseId(C.kw)
                    if id ~= 0 then items = { { id = id, name = "Bundle " .. id } } end
                end
                if not items then items, nxt, err = Store.search(C.kw, C.token) end
            else
                items, nxt, err = cachedFetch(C.mode == 1 and 2 or 1, C.kw, C.token) -- 2 = catálogo de emotes · 1 = creator store
            end
            if gen ~= C.gen then return end -- veio outra busca por cima
            UI.clearSkeleton(grid); UI.clearSkeleton(list)
            if not items then C.busy = false; status.Text = "Erro: " .. tostring(err); sound("error"); return end
            C.token = nxt
            local total = C.n + #items
            status.Text = total .. (C.mode == 3 and " packs" or " resultados") .. (nxt and " — tem mais" or " — fim")
                .. (total == 0 and " (nada achado)" or "")
            -- cards em lotes de 10: os primeiros aparecem na hora e a UI não trava
            for i, it in ipairs(items) do
                if gen ~= C.gen then return end
                C.n += 1
                if C.mode == 3 then addPackCard(it, C.n) else UI.emoteCard(grid, it.id, it.name).LayoutOrder = C.n end
                if i % 10 == 0 then task.wait() end
            end
            C.busy = false
        end)
    end

    local modeChips = chips(row, { "🎭 Emotes", "🎞 Animações", "🏃 Packs de animação" }, function(i)
        C.mode = i; box.PlaceholderText = PH[i]
        grid.Visible = (i ~= 3); list.Visible = (i == 3)
        sortRow.Visible = (i ~= 2); filtRow.Visible = (i ~= 2)
        run(true)
    end, 1)

    UI.firstShow["Loja"] = function() run(true) end
    UI.openStorePacks = function()
        UI.firstShow["Loja"] = nil -- antes do show, senão ele dispara a busca de emotes à toa
        UI.show("Loja")
        modeChips.set(3); C.mode = 3; box.PlaceholderText = PH[3]
        grid.Visible = false; list.Visible = true
        sortRow.Visible = true; filtRow.Visible = true
        run(true)
    end

    button(page, "Buscar", UDim2.new(0, 80, 0, 28), function() run(true) end, "primary").Position = UDim2.new(1, -170, 0, 35)
    button(page, "Mais ▸", UDim2.new(0, 84, 0, 28), function()
        if C.token == nil then status.Text = "Sem mais páginas."; return end
        run(false)
    end).Position = UDim2.new(1, -84, 0, 35)
    box.FocusLost:Connect(function(enter) if enter then run(true) end end)
end

-- ══════════════════════════════════════════════════════════
--  PÁGINA: EXTRAS
-- ══════════════════════════════════════════════════════════
do
    local page = newPage("Extras", "✨")
    local l = listOf(page, UDim2.new(), UDim2.new(1, 0, 1, 0), 5)

    header(l, "EMOTE")
    toggleRow(l, "Loop", function() return S.loop end, function(v)
        S.loop = v; save(); if E.track then pcall(function() E.track.Looped = v end) end
    end)
    toggleRow(l, "Reverse", function() return S.reverse end, function(v) S.reverse = v; save(); E.applySpeed() end)
    toggleRow(l, "Ping-pong (vai e volta)", function() return S.pingpong end, function(v)
        S.pingpong = v; E.dir = 1; save(); if E.track then E.applySpeed() end
    end)
    toggleRow(l, "Manter emote ao andar", function() return S.walkEmote end, function(v) S.walkEmote = v; save() end)
    toggleRow(l, "Freeze (para as outras animações)", function() return S.freeze end, function(v) S.freeze = v end)
    toggleRow(l, "Auto-reload no respawn", function() return S.autoReload end, function(v) S.autoReload = v; save() end)
    inputRow(l, "Velocidade (x)", S.speed, "Aplicar", function(t)
        local n = tonumber(t)
        if not n or n == 0 then notify("Velocidade", "valor inválido"); return end
        S.speed = math.clamp(n, 0.05, 10); save(); E.applySpeed(); notify("Velocidade", S.speed .. "x")
    end)
    btnRow(l, {
        { "0.3x", function() S.speed = 0.3; save(); E.applySpeed() end },
        { "1x",   function() S.speed = 1;   save(); E.applySpeed() end },
        { "3x",   function() S.speed = 3;   save(); E.applySpeed() end },
        { "⏹ Parar", function() E.stopSeq(); E.stop() end, "primary" },
        { "🎲", function() E.random() end },
    })

    header(l, "RODA DO ROBLOX")
    btnRow(l, {
        { "🎡 Abrir roda", function() pcall(function() GuiService:SetEmotesMenuOpen(true) end) end, "primary" },
        { "Reinjetar", function() WH.inject() end },
        { "Limpar roda", function()
            S.wheel = {}; save(); notify("Roda", "Limpa (reabra a roda)")
            if UI.emoteKey == "wheel" and UI.refreshEmotes then UI.refreshEmotes() end
        end },
    })

    header(l, "PLAYLIST / COMBO")
    local plLabel = label(l, "", 11, "sub", nil, { Size = UDim2.new(1, -8, 0, 16), LayoutOrder = nextOrder(l) })
    local function plRefresh() plLabel.Text = "Playlist: " .. #S.playlist .. " emotes" end
    plRefresh()
    btnRow(l, {
        { "+ Atual", function()
            if S.lastEmote == 0 then notify("Playlist", "Toque um emote antes"); return end
            table.insert(S.playlist, S.lastEmote); save(); plRefresh(); notify("Playlist", "+1 (" .. #S.playlist .. ")")
        end },
        { "▶ Iniciar", function()
            if #S.playlist == 0 then notify("Playlist", "Vazia"); return end
            E.runSeq(S.playlist, CFG.PlaylistDelay, true)
        end, "primary" },
        { "⏹", function() E.stopSeq() end },
        { "Limpar", function() S.playlist = {}; save(); plRefresh() end },
        { "🎭 Combo", function()
            local ids = UI.emoteItems(UI.emoteKey)
            if #ids < 2 then notify("Combo", "Precisa de 2+ emotes na aba"); return end
            E.runSeq(ids, CFG.ComboDelay, false)
        end },
    })
    inputRow(l, "Repetir último (x)", 3, "Repetir", function(t)
        local n = math.clamp(math.floor(tonumber(t) or 1), 1, 50)
        if S.lastEmote == 0 then notify("Repetir", "Nenhum emote ainda"); return end
        local ids = {}; for i = 1, n do ids[i] = S.lastEmote end
        E.runSeq(ids, CFG.ComboDelay, false)
    end)

    header(l, "MINI BOTÃO")
    toggleRow(l, "Mini botão flutuante (🔁 ⏹ 🎲)", function() return S.mini end, function(v)
        S.mini = v; save(); UI.applyVis()
    end)
    label(l, "Arrasta pelo ⋮⋮. Some junto quando o hub está escondido.", 10, "sub", nil, { Size = UDim2.new(1, -8, 0, 16), LayoutOrder = nextOrder(l) })

    header(l, "AFK")
    toggleRow(l, "Anti-AFK (não cai por ficar parado)", function() return S.antiAfk end, function(v) S.antiAfk = v; save() end)
    toggleRow(l, "Emote automático quando ficar parado", function() return S.afk.on end, function(v) S.afk.on = v; save() end)
    inputRow(l, "Parado por (seg)", S.afk.secs, "Aplicar", function(t)
        local n = tonumber(t)
        if not n then notify("AFK", "valor inválido"); return end
        S.afk.secs = math.clamp(math.floor(n), CFG.AfkMinSecs, 3600); save()
        notify("AFK", S.afk.secs .. "s parado toca o emote")
    end)
    local afkLbl = label(l, "", 11, "sub", nil, { Size = UDim2.new(1, -8, 0, 16), LayoutOrder = nextOrder(l) })
    local function afkRefresh()
        local id = S.afk.emote
        if id == 0 then afkLbl.Text = "Emote AFK: 🎲 aleatório"; return end
        afkLbl.Text = "Emote AFK: " .. id
        Names.get(id, function(n) if S.afk.emote == id then afkLbl.Text = "Emote AFK: " .. n .. "  (" .. id .. ")" end end)
    end
    afkRefresh()
    inputRow(l, "ID do emote AFK", "", "Definir", function(t)
        local id = parseId(t)
        if id == 0 then notify("AFK", "Cole um ID ou link"); sound("error"); return end
        S.afk.emote = id; save(); afkRefresh(); notify("AFK", "Emote AFK definido")
    end)
    btnRow(l, {
        { "📌 Usar último", function()
            if S.lastEmote == 0 then notify("AFK", "Toque um emote antes"); return end
            S.afk.emote = S.lastEmote; save(); afkRefresh(); notify("AFK", "Emote AFK = último tocado")
        end, "primary" },
        { "🎲 Aleatório", function() S.afk.emote = 0; save(); afkRefresh() end },
        { "▶ Testar", function()
            local id = S.afk.emote
            if id == 0 then local pool = E.pool(); id = pool[math.random(math.max(#pool, 1))] end
            if id then task.spawn(E.play, id, true) end
        end },
    })

    header(l, "ABAS DE EMOTES")
    local mgr = mk("Frame", { Size = UDim2.new(1, -8, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = nextOrder(l) }, l)
    mk("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder }, mgr)
    function UI.refreshTabsMgr()
        clearKids(mgr)
        if #S.userTabs == 0 then
            label(mgr, "Nenhuma aba ainda. Na página Emotes toca em  ＋ Aba  pra criar.", 10, "sub", nil, { Size = UDim2.new(1, 0, 0, 28), LayoutOrder = 1 })
            return
        end
        for i, t in ipairs(S.userTabs) do
            local r = mk("Frame", { Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, LayoutOrder = i }, mgr)
            local tb = textbox(r, "", UDim2.new(1, -66, 1, 0))
            tb.Text = t.name
            tb.FocusLost:Connect(function() -- editar o nome aqui renomeia a aba
                local nm = tb.Text:gsub("^%s+", ""):gsub("%s+$", "")
                nm = nm:sub(1, 14)
                if nm == "" or nm == t.name then tb.Text = t.name; return end
                t.name = nm; save(); UI.rebuildEmoteTabs()
            end)
            button(r, "🗑", UDim2.new(0, 60, 1, 0), function(b)
                if not b:GetAttribute("armed") then -- 2 toques: o 1º só pede confirmação
                    b:SetAttribute("armed", true); b.Text = "certeza?"
                    task.delay(2.5, function() if b.Parent then b:SetAttribute("armed", nil); b.Text = "🗑" end end)
                    return
                end
                local idx = table.find(S.userTabs, t)
                if idx then table.remove(S.userTabs, idx) end
                if UI.emoteKey == "t:" .. t.id then UI.emoteKey = "1"; S.emoteKey = "1" end
                save(); UI.rebuildEmoteTabs(); UI.refreshTabsMgr()
            end).Position = UDim2.new(1, -60, 0, 0)
        end
    end
    UI.refreshTabsMgr()

    header(l, "EFEITOS  ·  só você vê")
    toggleRow(l, "Partículas", function() return S.fx.particles end, function(v) S.fx.particles = v; save(); E.fxApply() end)
    toggleRow(l, "Aura (contorno brilhando)", function() return S.fx.aura end, function(v) S.fx.aura = v; save(); E.fxApply() end)
    toggleRow(l, "Rastro (trail)", function() return S.fx.trail end, function(v) S.fx.trail = v; save(); E.fxApply() end)
    toggleRow(l, "Arco-íris", function() return S.fx.rainbow end, function(v)
        S.fx.rainbow = v; save(); if not v then E.fxColor() end
    end)
    local function chan(text, key)
        sliderRow(l, text, 0, 255, function() return S.fx[key] * 255 end, function(v) S.fx[key] = v / 255; E.fxColor() end,
            function(v) return tostring(math.floor(v + 0.5)) end)
    end
    chan("Cor · R", "r"); chan("Cor · G", "g"); chan("Cor · B", "b")
    btnRow(l, {
        { "Azul",     function() E.fxQuick(FX.Blue);   UI.recolor() end },
        { "Roxo",     function() E.fxQuick(FX.Purple); UI.recolor() end },
        { "Dourado",  function() E.fxQuick(FX.Gold);   UI.recolor() end },
        { "Vermelho", function() E.fxQuick(FX.Red);    UI.recolor() end },
        { "Off",      function() E.fxQuick(nil);       UI.recolor() end },
    })
end

-- linha de escolha de emote com miniatura: ID/link, 📌 último tocado, 🎲 aleatório, ▶ testar
local function emotePickRows(l, title, get, set)
    local box = mk("Frame", { Size = UDim2.new(1, -8, 0, 40), BorderSizePixel = 0, LayoutOrder = nextOrder(l) }, l)
    th(box, "BackgroundColor3", "card"); corner(box, 9)
    local img = mk("ImageLabel", {
        Position = UDim2.fromOffset(6, 4), Size = UDim2.fromOffset(32, 32), BackgroundColor3 = UI.col.panel, BorderSizePixel = 0,
        ScaleType = Enum.ScaleType.Fit,
    }, box)
    corner(img, 8)
    local nm = label(box, "", 11, "text", nil, { Position = UDim2.fromOffset(46, 2), Size = UDim2.new(1, -52, 0, 36) })
    local function refresh()
        local id = get()
        if id == 0 then img.Image = ""; nm.Text = title .. ": 🎲 aleatório"; return end
        img.Image = ("rbxthumb://type=Asset&id=%d&w=150&h=150"):format(id)
        nm.Text = title .. ": " .. id
        Names.get(id, function(n) if get() == id and nm.Parent then nm.Text = title .. ": " .. n end end)
    end
    local row = mk("Frame", { Size = UDim2.new(1, -8, 0, 28), BackgroundTransparency = 1, LayoutOrder = nextOrder(l) }, l)
    local tb = textbox(row, "ID ou link do emote", UDim2.new(1, -168, 1, 0))
    local function put(x, w, text, fn, key)
        local b = button(row, text, UDim2.new(0, w, 1, 0), fn, key)
        b.Position = UDim2.new(1, x, 0, 0)
        return b
    end
    put(-164, 38, "OK", function()
        local id = parseId(tb.Text)
        if id == 0 then notify(title, "ID inválido"); sound("error"); return end
        set(id); tb.Text = ""; refresh()
    end, "primary")
    put(-122, 36, "📌", function()
        if S.lastEmote == 0 then notify(title, "Toque um emote antes"); return end
        set(S.lastEmote); refresh()
    end)
    put(-82, 36, "🎲", function() set(0); refresh() end)
    put(-42, 38, "▶", function()
        local id = get()
        if id == 0 then local pool = E.pool(); id = pool[math.random(math.max(#pool, 1))] end
        if id then task.spawn(E.play, id, true) end
    end)
    refresh()
    return refresh
end

