    emotePickRows(l, "Emote do spawn", function() return S.spawn.emote end, function(id) S.spawn.emote = id; save() end)
    sliderRow(l, "Esperar antes de tocar", 0.3, 5, function() return S.spawn.delay end, function(v) S.spawn.delay = v end, pct1)
    label(l, "Com o emote do spawn ligado, o Auto-reload (Extras) não toca. Qualquer movimento seu para o emote.", 10, "sub", nil,
        { Size = UDim2.new(1, -8, 0, 28), LayoutOrder = nextOrder(l) })

    header(l, "TOCA UM EMOTE QUANDO EU...")
    sliderRow(l, "Intervalo mínimo entre eventos", 1, 20, function() return S.evCd end, function(v) S.evCd = v end,
        function(v) return ("%ds"):format(math.floor(v + 0.5)) end)
    for _, e in ipairs(EVENTS) do
        toggleRow(l, e.name, function() return S.ev[e.key].on end, function(v) S.ev[e.key].on = v; save() end)
        emotePickRows(l, "Emote", function() return S.ev[e.key].emote end, function(id) S.ev[e.key].emote = id; save() end)
        if e.key == "land" then
            sliderRow(l, "↳ Queda mínima pra valer", 20, 150, function() return S.evLandMin end, function(v) S.evLandMin = v end,
                function(v) return tostring(math.floor(v + 0.5)) end)
        elseif e.key == "stopRun" then
            sliderRow(l, "↳ Velocidade mínima de corrida", 6, 30, function() return S.evRunMin end, function(v) S.evRunMin = v end,
                function(v) return tostring(math.floor(v + 0.5)) end)
        end
    end
    label(l, "Evento não interrompe um emote que você já está tocando. 🎲 sorteia entre todos os seus emotes. Esses emotes não entram em Recentes/Top.", 10, "sub", nil,
        { Size = UDim2.new(1, -8, 0, 40), LayoutOrder = nextOrder(l) })
end

-- ══════════════════════════════════════════════════════════
--  PÁGINA: JOGADORES  (copia o emote que outro jogador está tocando)
-- ══════════════════════════════════════════════════════════
do
    local page = newPage("Jogadores", "👥")
    local l = listOf(page, UDim2.new(), UDim2.new(1, 0, 1, 0), 5)
    header(l, "COPIAR EMOTE DE OUTRO JOGADOR")
    label(l, "Toca em Copiar enquanto a pessoa estiver dançando: o emote vai pra aba de destino.", 10, "sub", nil,
        { Size = UDim2.new(1, -8, 0, 28), LayoutOrder = nextOrder(l) })

    local dest = 0 -- 0 = Custom; n = S.userTabs[n]
    local destBtn
    local function destName()
        if dest > 0 and S.userTabs[dest] then return "📁 " .. S.userTabs[dest].name end
        dest = 0
        return "Custom"
    end
    destBtn = button(l, "Destino: Custom", UDim2.new(1, -8, 0, 30), function()
        dest += 1
        if dest > #S.userTabs then dest = 0 end
        destBtn.Text = "Destino: " .. destName()
    end)
    destBtn.LayoutOrder = nextOrder(l)
    local refreshBtn = button(l, "↻ Atualizar lista", UDim2.new(1, -8, 0, 30), function() UI.refreshPlayers() end)
    refreshBtn.LayoutOrder = nextOrder(l)
    local listF = mk("Frame", { Size = UDim2.new(1, -8, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = nextOrder(l) }, l)
    mk("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.LayoutOrder }, listF)

    -- emotes que ESSA pessoa está tocando agora: ignora idle/movement e as animações do script Animate
    local function emotesOf(plr)
        local out, seen = {}, {}
        local ch = plr.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local an = hum and hum:FindFirstChildOfClass("Animator")
        if not an then return out end
        local ok, tracks = pcall(function() return an:GetPlayingAnimationTracks() end)
        if not ok then return out end
        local P = Enum.AnimationPriority
        for _, t in ipairs(tracks) do
            local anim = t.Animation
            if anim and t.Priority ~= P.Idle and t.Priority ~= P.Movement and not anim:FindFirstAncestor("Animate") then
                local id = parseId(anim.AnimationId)
                if id ~= 0 and not seen[id] then seen[id] = true; out[#out + 1] = id end
            end
        end
        return out
    end
    local function copyFrom(plr)
        local ids = emotesOf(plr)
        if #ids == 0 then notify(plr.DisplayName, "nenhum emote tocando agora"); sound("error"); return end
        local tab = (dest > 0) and S.userTabs[dest] or nil
        local list = tab and tab.ids or S.customEmotes
        local added = 0
        for _, id in ipairs(ids) do
            if not table.find(list, id) then table.insert(list, 1, id); added += 1 end
        end
        save()
        notify(plr.DisplayName, ("%d emote(s) → %s%s"):format(#ids, tab and tab.name or "Custom", added < #ids and " (alguns já existiam)" or ""))
        if UI.refreshEmotes then UI.refreshEmotes() end
    end

    function UI.refreshPlayers()
        clearKids(listF)
        local arr = {}
        for _, pl in ipairs(Players:GetPlayers()) do if pl ~= LP then arr[#arr + 1] = pl end end
        table.sort(arr, function(a, b) return a.DisplayName:lower() < b.DisplayName:lower() end)
        if #arr == 0 then
            label(listF, "Ninguém mais no servidor.", 11, "sub", nil, { Size = UDim2.new(1, 0, 0, 24), LayoutOrder = 1 })
            return
        end
        for i, pl in ipairs(arr) do
            local r = mk("Frame", { Size = UDim2.new(1, 0, 0, 40), BorderSizePixel = 0, LayoutOrder = i }, listF)
            th(r, "BackgroundColor3", "card"); corner(r, 9)
            local av = mk("ImageLabel", {
                Position = UDim2.fromOffset(6, 4), Size = UDim2.fromOffset(32, 32), BackgroundColor3 = UI.col.panel, BorderSizePixel = 0,
                Image = ("rbxthumb://type=AvatarHeadShot&id=%d&w=48&h=48"):format(pl.UserId),
            }, r)
            corner(av, 16)
            label(r, pl.DisplayName, 12, "text", nil, { Position = UDim2.fromOffset(46, 2), Size = UDim2.new(1, -134, 0, 18), TextWrapped = false, TextTruncate = Enum.TextTruncate.AtEnd })
            label(r, "@" .. pl.Name, 10, "sub", nil, { Position = UDim2.fromOffset(46, 20), Size = UDim2.new(1, -134, 0, 16), TextWrapped = false, TextTruncate = Enum.TextTruncate.AtEnd })
            button(r, "Copiar", UDim2.new(0, 72, 0, 28), function() copyFrom(pl) end, "primary").Position = UDim2.new(1, -80, 0, 6)
        end
    end
    UI.refreshPlayers()
    UI.conns[#UI.conns + 1] = Players.PlayerAdded:Connect(function() if UI.current == "Jogadores" then UI.refreshPlayers() end end)
    UI.conns[#UI.conns + 1] = Players.PlayerRemoving:Connect(function() task.defer(function() if UI.current == "Jogadores" then UI.refreshPlayers() end end) end)
    UI.firstShow["Jogadores"] = nil
end

-- ══════════════════════════════════════════════════════════
--  PÁGINA: CONFIG
-- ══════════════════════════════════════════════════════════
do
    local page = newPage("Config", "⚙")
