    header(l, "TEMA")
    local items = {}
    for i, t in ipairs(THEMES) do
        items[#items + 1] = { t.name, function() S.theme = i; save(); UI.recolor() end }
    end
    btnRow(l, { items[1], items[2], items[3] })
    btnRow(l, { items[4], items[5], items[6] })

    header(l, "HUB")
    toggleRow(l, "Botão flutuante", function() return S.fab end, function(v) S.fab = v; save(); UI.applyVis() end)
    toggleRow(l, "Esconder hub (só a roda)", function() return S.hidden end, function(v)
        S.hidden = v; UI.revealed = false; save()
        if v then
            Main.Visible = false
            notify("Hub escondido", "Reabrir: 2 dedos de cima pra baixo, devagar")
        end
        UI.applyVis()
    end)
    UI.keyHelp = label(l, UI.helpText(), 10, "sub", nil, { Size = UDim2.new(1, -8, 0, 40), LayoutOrder = nextOrder(l) })
    toggleRow(l, "Sons", function() return S.sound end, function(v) S.sound = v; save() end)

    header(l, "TECLA DO HUB")
    do
        local row = mk("Frame", { Size = UDim2.new(1, -8, 0, 38), BorderSizePixel = 0, LayoutOrder = nextOrder(l) }, l)
        th(row, "BackgroundColor3", "card"); corner(row, 9)
        label(row, "Abrir / fechar o hub", 12, "text", nil, { Size = UDim2.new(1, -190, 1, 0), Position = UDim2.fromOffset(11, 0) })
        local kb = mk("TextButton", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0), Size = UDim2.fromOffset(104, 28),
            AutoButtonColor = false, BorderSizePixel = 0, Font = Enum.Font.GothamBold, TextSize = 12, Text = "",
        }, row)
        th(kb, "BackgroundColor3", "primary"); th(kb, "TextColor3", "text"); corner(kb, 8); stroke(kb, "accent", 1, 0.4)
        kb.MouseEnter:Connect(function() tw(kb, { BackgroundColor3 = UI.col.primary:Lerp(WHITE, 0.12) }, 0.1) end)
        kb.MouseLeave:Connect(function() tw(kb, { BackgroundColor3 = UI.col.primary }, 0.12) end)
        UI.keyBtn = kb

        local rs = button(row, "↺", UDim2.fromOffset(28, 28), function()
            S.toggleKey = "Semicolon"; save(); UI.updateKeyLabel(); notify("Tecla do hub", "voltou pro padrão  :")
        end)
        rs.AnchorPoint = Vector2.new(1, 0.5); rs.Position = UDim2.new(1, -118, 0.5, 0)

        -- teclas que o jogo usa (abrir o hub andando seria um inferno) e modificadoras
        local BAD = {
            [Enum.KeyCode.W] = true, [Enum.KeyCode.A] = true, [Enum.KeyCode.S] = true, [Enum.KeyCode.D] = true,
            [Enum.KeyCode.Space] = true, [Enum.KeyCode.Slash] = true, [Enum.KeyCode.Tab] = true, [Enum.KeyCode.Unknown] = true,
            [Enum.KeyCode.Return] = true, [Enum.KeyCode.Backspace] = true,
        }
        local MOD = {
            [Enum.KeyCode.LeftShift] = true, [Enum.KeyCode.RightShift] = true, [Enum.KeyCode.LeftControl] = true,
            [Enum.KeyCode.RightControl] = true, [Enum.KeyCode.LeftAlt] = true, [Enum.KeyCode.RightAlt] = true,
        }
        kb.Activated:Connect(function()
            if UI.capturing then return end
            UI.capturing = true; kb.Text = "aperte uma tecla..."
            local conn
            conn = UserInputService.InputBegan:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.Keyboard then return end
                local kc = i.KeyCode
                if MOD[kc] then return end
                conn:Disconnect()
                UI.capturing = false; UI.captureUntil = os.clock() + 0.3 -- a mesma tecla não pode abrir/fechar o hub na hora
                if kc == Enum.KeyCode.Escape then UI.updateKeyLabel(); return end
                if BAD[kc] then
                    notify("Tecla reservada", kc.Name .. " é usada pelo jogo — escolhe outra"); sound("error"); UI.updateKeyLabel(); return
                end
                S.toggleKey = kc.Name; save(); UI.updateKeyLabel()
                notify("Tecla do hub", "agora é  " .. UI.keyLabel() .. "   (INSERT continua funcionando)"); sound("success")
            end)
            -- desistiu? 8s sem tecla cancela
            task.delay(8, function()
                if UI.capturing and conn.Connected then conn:Disconnect(); UI.capturing = false; UI.updateKeyLabel() end
            end)
        end)
        UI.updateKeyLabel()
    end

