--  BOTÃO FLUTUANTE (arrastável, posição salva)
-- ══════════════════════════════════════════════════════════
do
    local fab = mk("TextButton", {
        Size = UDim2.fromOffset(44, 44), Position = UDim2.fromScale(0.02, 0.45), Text = "", BackgroundTransparency = 1,
        BorderSizePixel = 0, AutoButtonColor = false, ZIndex = 50,
    }, Gui)
    corner(fab, 22)
    do -- degradê num Frame de fundo (UIGradient tingiria o emoji) + emoji por cima
        local bg = mk("Frame", { Size = UDim2.new(1, 0, 1, 0), BorderSizePixel = 0, ZIndex = 1 }, fab)
        corner(bg, 22); gradient(bg, "primary", "accent", 45)
        mk("TextLabel", { Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1, Text = "🎭", TextSize = 21, Font = Enum.Font.GothamBold, ZIndex = 2 }, fab)
    end
    do local st = mk("UIStroke", { Thickness = 2, Transparency = 0.35, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, fab); th(st, "Color", "text") end
    UI.fab = fab
    if S.fabPos then fab.Position = arrPos(S.fabPos) end
    makeDraggable(fab, fab, function() return 1 end, function() S.fabPos = posArr(fab); save() end, function()
        sound("click"); UI.toggle()
    end)
    -- se a posição salva ficou fora da tela (resolução mudou), volta pro padrão
    task.defer(function()
        local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
        local p = fab.AbsolutePosition
        if p.X < -10 or p.Y < -10 or p.X > vp.X - 10 or p.Y > vp.Y - 10 then
            fab.Position = UDim2.fromScale(0.02, 0.45); S.fabPos = nil
        end
    end)
end

