-- ══════════════════════════════════════════════════════════
--  INPUT: tecla + gesto (2 dedos de cima pra baixo, devagar) + hover da roda
-- ══════════════════════════════════════════════════════════
UI.conns[#UI.conns + 1] = UserInputService.InputBegan:Connect(function(i, processed)
    if i.UserInputType ~= Enum.UserInputType.Keyboard then return end
    if not table.find(UI.keyCodes(), i.KeyCode) then return end
    -- trocando a tecla na Config (ou acabou de trocar): não abre/fecha
    if UI.capturing or os.clock() < (UI.captureUntil or 0) then return end
    -- digitando numa caixa de texto (ex: colando ID): não abre/fecha
    if processed or UserInputService:GetFocusedTextBox() then return end
    UI.toggle()
end)

local G = { t = {}, fired = false }
local function gestureCheck()
    if G.fired then return end
    local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
    local need, zone = vp.Y * CFG.GestureDist, vp.Y * CFG.GestureZone
    local ok, tmax = 0, 0
    for inp, d in pairs(G.t) do
        if d.y0 <= zone and (inp.Position.Y - d.y0) >= need then ok += 1 end
        if d.t0 > tmax then tmax = d.t0 end
    end
    if ok >= 2 then
        G.fired = true -- só dispara uma vez por gesto
        if os.clock() - tmax >= CFG.GestureMinTime then UI.reveal() end -- rápido demais = ignora
    end
end

UI.conns[#UI.conns + 1] = UserInputService.InputBegan:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.Touch then
        G.t[i] = { y0 = i.Position.Y, t0 = os.clock() }
    end
    if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
        WH.hover(i.Position.X, i.Position.Y)
    end
end)
UI.conns[#UI.conns + 1] = UserInputService.InputChanged:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.Touch then
        if G.t[i] then gestureCheck() end
        WH.hover(i.Position.X, i.Position.Y)
    elseif i.UserInputType == Enum.UserInputType.MouseMovement then
        WH.hover(i.Position.X, i.Position.Y)
    end
end)
UI.conns[#UI.conns + 1] = UserInputService.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.Touch then
        G.t[i] = nil
        if next(G.t) == nil then G.fired = false end
    end
    if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then WH.last = nil end
end)

-- ══════════════════════════════════════════════════════════
--  LOOP PRINCIPAL + CHARACTER
-- ══════════════════════════════════════════════════════════
UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function()
    -- roda abriu -> reinjeta emotes
    local w = WH.root()
    if w then
        local v = w.Visible
        if v and not WH.wasVisible then WH.inject(); task.delay(0.35, WH.connect) end
        WH.wasVisible = v
    end

    local _, hum, animator = E.parts()
    if not hum then return end
    local moving = hum.MoveDirection.Magnitude > 0
    if moving and not E.wasMoving and E.track and not S.walkEmote then E.stop() end
    E.wasMoving = moving
    local pt = E.track
    if S.pingpong and pt then
        pcall(function()
            local len = pt.Length
            if len > 0.3 then
                local facing = (S.reverse and -1 or 1) * (E.dir or 1)
                local pos = pt.TimePosition
                if (facing == 1 and pos >= len - 0.06) or (facing == -1 and pos <= 0.06) then
                    E.dir = -(E.dir or 1); E.ppFlip = true; E.applySpeed(); E.ppFlip = false
                end
            end
        end)
    end
    if S.freeze and animator then
        pcall(function()
            for _, t in ipairs(animator:GetPlayingAnimationTracks()) do
                if t ~= E.track then t:Stop(0) end
            end
        end)
    end
end)

-- ══════════════════════════════════════════════════════════
--  ANTI-AFK + EMOTE AFK
--  • Anti-AFK: o Roblox avisa que você ficou ocioso (LP.Idled) e a gente manda um clique virtual
--  • Emote AFK: parado por N segundos (sem input e sem andar) toca o emote escolhido em Extras
--    (id 0 = aleatório). Qualquer input para o emote. Não entra em Recentes/Top.
-- ══════════════════════════════════════════════════════════
local AF = { last = os.clock(), track = nil, nextTry = 0, acc = 0, busy = false }

local function afkTouch()
    AF.last = os.clock()
    if AF.track then
        if E.track == AF.track then E.stop() end
        AF.track = nil
    end
end
UI.conns[#UI.conns + 1] = UserInputService.InputBegan:Connect(function(i)
    if i.UserInputType ~= Enum.UserInputType.Focus then afkTouch() end
end)
UI.conns[#UI.conns + 1] = UserInputService.InputChanged:Connect(function(i)
    local t = i.UserInputType
    if t == Enum.UserInputType.MouseMovement or t == Enum.UserInputType.MouseWheel or t == Enum.UserInputType.Touch
        or t == Enum.UserInputType.Gamepad1 then afkTouch() end
end)

UI.conns[#UI.conns + 1] = LP.Idled:Connect(function()
    if not S.antiAfk then return end
    pcall(function()
        VirtualUser:CaptureController()
        VirtualUser:ClickButton2(Vector2.new(0, 0))
    end)
end)

UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function(dt)
    AF.acc += dt
    if AF.acc < CFG.AfkCheck then return end
    AF.acc = 0
    local A = S.afk
    if not A.on or AF.busy then return end
    local _, hum = E.parts()
    if not hum or hum.Health <= 0 then return end
    local now = os.clock()
    if hum.MoveDirection.Magnitude > 0 then AF.last = now; return end -- andando conta como atividade
    if hum.Sit or E.track ~= nil or now - AF.last < A.secs or now < AF.nextTry then return end
    local id = A.emote
    if id == 0 then
        local pool = E.pool()
        id = pool[math.random(math.max(#pool, 1))]
        if not id then return end
    end
    AF.busy = true
    local okp, res = pcall(E.play, id, true)
    AF.busy = false
    if okp and res then AF.track = E.track; AF.nextTry = now + 1 else AF.nextTry = now + 30 end -- falhou: espera 30s pra não spammar
end)

-- ══════════════════════════════════════════════════════════
--  REALISMO (Config → REALISMO). Tudo local: só VOCÊ vê. Precisa de personagem R15.
--  • Pés no chão (IK): parado em degrau/escada, os pés esticam até o chão se alcançarem (limite = "alcance")
--  • Quadril desce pra ajudar a perna a alcançar
--  • Inclina o corpo ao andar/virar, cabeça olha pra câmera, respiração, pouso com impacto
--  Mexe nos C0 dos Motor6D (a animação não sobrescreve C0) + IKControl nas pernas. Desligar restaura tudo.
-- ══════════════════════════════════════════════════════════
local RL = {
    c = nil, t = 0, fall = 0, landPos = 0, landVel = 0, clean = true, warned = false,
    sm = { p = 0, pitch = 0, roll = 0, hy = 0, hp = 0, br = 0 },
    pf = 0, acc = 0,                       -- velocidade pra frente anterior / aceleração suavizada (freada)
    bob = Vector3.zero, bobPh = 0,         -- balanço de câmera: offset atual / fase do passo
    gl = { t = 1.5, yaw = 0, pit = 0, hold = false }, -- olhadas aleatórias da cabeça (idle)
    prints = {}, pdist = 0, side = 1, splash = nil,    -- pegadas e respingo
}
-- modo performance: o que é pesado fica desligado, o resto continua do jeito que você configurou
RL.perfR = setmetatable({ footIK = false, dust = false, camBob = false, prints = false, splash = false, camLean = false, shake = false },
    { __index = S.real })

function RL.restore(c)
    c = c or RL.c; if not c then return end
    for k, m in pairs({ waist = c.waist, neck = c.neck, rootJ = c.rootJ }) do
        if m and c.o[k] then pcall(function() m.C0 = c.o[k] end) end
    end
    for _, L in pairs(c.legs or {}) do
        if L.ik then pcall(function() L.ik.Weight = 0 end); L.w = 0 end
    end
    if c.hum and c.camBase then pcall(function() c.hum.CameraOffset = c.camBase + FP.off + SH.off end) end
    RL.bob = Vector3.zero
    if c.dust then pcall(function() c.dust.Enabled = false end) end
end

function RL.reset()
    local c = RL.c
    if c then
        RL.restore(c)
        if c.conn then pcall(function() c.conn:Disconnect() end) end
        for _, L in pairs(c.legs or {}) do
            if L.ik then pcall(function() L.ik:Destroy() end) end
        end
        if c.targets then pcall(function() c.targets:Destroy() end) end
        if c.dustAtt then pcall(function() c.dustAtt:Destroy() end) end
    end
    RL.c = nil
    RL.fall, RL.landPos, RL.landVel, RL.clean = 0, 0, 0, true
    RL.pf, RL.acc, RL.bob, RL.bobPh = 0, 0, Vector3.zero, 0
    RL.gl = { t = 1.5, yaw = 0, pit = 0, hold = false }
    RL.pdist = 0
    if RL.splash then pcall(function() RL.splash.part:Destroy() end); RL.splash = nil end
    for _, p in ipairs(RL.prints) do pcall(function() p:Destroy() end) end
    RL.prints = {}
    for k in pairs(RL.sm) do RL.sm[k] = 0 end
end

function RL.setup(char)
    RL.reset()
    local hum = char:FindFirstChildOfClass("Humanoid")
    local root = char:FindFirstChild("HumanoidRootPart")
    if not hum or not root then return end
    local r6 = hum.RigType ~= Enum.HumanoidRigType.R15
    local function joint(part, name)
        local p = char:FindFirstChild(part); return p and p:FindFirstChild(name)
    end
    local c = {
        char = char, hum = hum, root = root, camBase = hum.CameraOffset, r6 = r6,
        waist = (not r6) and joint("UpperTorso", "Waist") or nil,
        neck = r6 and joint("Torso", "Neck") or joint("Head", "Neck"), -- R15: Neck fica na Head; R6: no Torso
        rootJ = (not r6) and joint("LowerTorso", "Root") or nil,
        o = {}, legs = {},
    }
    for k, m in pairs({ waist = c.waist, neck = c.neck, rootJ = c.rootJ }) do if m then c.o[k] = m.C0 end end
    local lt = char:FindFirstChild("LowerTorso")
    for _, side in ipairs({ "Left", "Right" }) do
        local up, lo, ft = char:FindFirstChild(side .. "UpperLeg"), char:FindFirstChild(side .. "LowerLeg"), char:FindFirstChild(side .. "Foot")
        local hipJ = lt and lt:FindFirstChild(side .. "Hip")
        local kneeJ = up and up:FindFirstChild(side .. "Knee")
        local ankJ = lo and lo:FindFirstChild(side .. "Ankle")
        if up and lo and ft and hipJ and kneeJ and ankJ and hipJ:IsA("Motor6D") and hipJ.Part0 then
            c.legs[side] = {
                up = up, lo = lo, ft = ft, hip = hipJ, w = 0,
                -- comprimento real da perna (quadril→joelho→tornozelo), não o tamanho das peças (que é maior e deixava o joelho travar)
                len = (hipJ.C1.Position - kneeJ.C0.Position).Magnitude + (kneeJ.C1.Position - ankJ.C0.Position).Magnitude,
                ank = ankJ.C1.Position, -- onde o tornozelo fica dentro do pé
            }
        end
    end
    c.params = RaycastParams.new()
    c.params.FilterType = Enum.RaycastFilterType.Exclude
    c.params.RespectCanCollide = true -- ignora Parts sem colisão (decoração, triggers)
    c.params.FilterDescendantsInstances = { char }
    -- pouso: guarda a velocidade da queda e dispara a mola quando encosta no chão
    c.conn = hum.StateChanged:Connect(function(_, new)
        if new == Enum.HumanoidStateType.Landed then
            if S.real.land then RL.landPos = -math.clamp(RL.fall * 0.012, 0, 0.85); RL.landVel = 0 end
            if S.real.shake and not E.perf then CAMFX.kick(RL.fall) end
            RL.fall = 0
        end
    end)
    RL.c = c
    RL.clean = false
end

-- cria os IKControl das pernas só quando o recurso é ligado (alvos = Parts invisíveis sob a câmera, locais)
function RL.ensureIK(c)
    if c.ik ~= nil then return c.ik end
    local ok = pcall(function()
        local folder = Instance.new("Folder"); folder.Name = "EH_IK"
        folder.Parent = workspace
        c.targets = folder
        for _, L in pairs(c.legs) do
            local tp = Instance.new("Part")
            tp.Anchored = true; tp.CanCollide = false; tp.CanQuery = false; tp.CanTouch = false; tp.Transparency = 1
            tp.Size = Vector3.new(0.2, 0.2, 0.2); tp.Parent = folder
            local ik = Instance.new("IKControl")
            -- Transform = posição E rotação do pé (com Position o pé ficava livre e entortava no tornozelo)
            if not pcall(function() ik.Type = Enum.IKControlType.Transform end) then ik.Type = Enum.IKControlType.Position end
            ik.ChainRoot = L.up; ik.EndEffector = L.ft; ik.Target = tp
            ik.Weight = 0; ik.SmoothTime = 0.05; ik.Enabled = false
            ik.Parent = c.hum
            L.ik, L.tp = ik, tp
        end
    end)
    c.ik = ok
    if not ok then notify("Pés no chão", "IKControl indisponível aqui — o resto do realismo funciona") end
    return ok
end

-- poeira dos passos: emissor nos pés, criado só quando o recurso liga; cor segue o piso
local DUST_DEF = Color3.fromRGB(176, 176, 170)
local DUST_COL = {
    [Enum.Material.Grass] = Color3.fromRGB(122, 142, 98), [Enum.Material.LeafyGrass] = Color3.fromRGB(122, 142, 98),
    [Enum.Material.Sand] = Color3.fromRGB(205, 186, 140), [Enum.Material.Sandstone] = Color3.fromRGB(196, 170, 128),
    [Enum.Material.Ground] = Color3.fromRGB(150, 124, 96), [Enum.Material.Mud] = Color3.fromRGB(120, 98, 76),
    [Enum.Material.Snow] = Color3.fromRGB(240, 244, 250), [Enum.Material.Ice] = Color3.fromRGB(210, 230, 245),
}
function RL.ensureDust(c)
    if c.dust then return c.dust end
    pcall(function()
        local att = Instance.new("Attachment")
        att.Name = "EH_DUST"
        att.Position = Vector3.new(0, -(c.hum.HipHeight + c.root.Size.Y / 2) + 0.15, 0)
        att.Parent = c.root
        local pe = Instance.new("ParticleEmitter")
        pe.Name = "EH_DUST"; pe.Texture = "rbxasset://textures/particles/smoke_main.dds"
        pe.Rate = 0; pe.Enabled = false
        pe.Lifetime = NumberRange.new(0.45, 0.9); pe.Speed = NumberRange.new(1, 2.5)
        pe.SpreadAngle = Vector2.new(60, 60); pe.Acceleration = Vector3.new(0, 1.5, 0); pe.Drag = 2
        pe.Rotation = NumberRange.new(0, 360); pe.RotSpeed = NumberRange.new(-60, 60)
        pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.5), NumberSequenceKeypoint.new(1, 1.7) })
        pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.65), NumberSequenceKeypoint.new(1, 1) })
        pe.Color = ColorSequence.new(DUST_DEF)
        pe.Parent = att
        c.dustAtt, c.dust = att, pe
    end)
    return c.dust
end

-- pegadas: só em piso mole; a cor é o piso escurecido. Ficam na Camera (só você vê) e somem sozinhas
local PRINT_COL = {
    [Enum.Material.Snow] = Color3.fromRGB(185, 200, 220), [Enum.Material.Sand] = Color3.fromRGB(140, 118, 80),
    [Enum.Material.Sandstone] = Color3.fromRGB(150, 125, 90), [Enum.Material.Mud] = Color3.fromRGB(62, 46, 34),
    [Enum.Material.Ground] = Color3.fromRGB(85, 68, 50),
}

-- raio pra baixo que também enxerga a água do Terrain (o do pé/IK ignora água)
function RL.floorRay(c)
    if not c.fparams then
        local p = RaycastParams.new()
        p.FilterType = Enum.RaycastFilterType.Exclude
        local cam = workspace.CurrentCamera
        p.FilterDescendantsInstances = cam and { c.char, cam } or { c.char }
        p.IgnoreWater = false
        c.fparams = p
    end
    return workspace:Raycast(c.root.Position, Vector3.new(0, -(c.hum.HipHeight + c.root.Size.Y / 2 + 2.5), 0), c.fparams)
end

function RL.stamp(c, hit)
    local n = hit.Normal
    local right = c.root.CFrame.RightVector
    right = right - n * right:Dot(n)
    if right.Magnitude < 0.05 then return end
    right = right.Unit
    local cam = workspace.CurrentCamera
    if not cam then return end
    local pt = Instance.new("Part")
    pt.Shape = Enum.PartType.Cylinder
    pt.Size = Vector3.new(0.05, 0.55, 0.95) -- X = espessura (vira o eixo da normal), Y/Z = elipse do pé
    pt.Anchored, pt.CanCollide, pt.CanQuery, pt.CanTouch, pt.CastShadow = true, false, false, false, false
    pt.Material = Enum.Material.SmoothPlastic
    pt.Color = PRINT_COL[hit.Material]
    pt.Transparency = 0.3
    pt.CFrame = CFrame.fromMatrix(hit.Position + n * 0.03 + right * (RL.side * 0.55), n, right)
    pt.Parent = cam
    local list = RL.prints
    list[#list + 1] = pt
    if #list > 40 then local old = table.remove(list, 1); pcall(function() old:Destroy() end) end
    TweenService:Create(pt, TweenInfo.new(7, Enum.EasingStyle.Linear), { Transparency = 1 }):Play()
    Debris:AddItem(pt, 7.3)
end

function RL.ensureSplash()
    local s2 = RL.splash
    if s2 and s2.part.Parent then return s2 end
    local cam = workspace.CurrentCamera
    if not cam then return nil end
    local part = Instance.new("Part")
    part.Name = "EH_SPLASH"; part.Size = Vector3.new(0.4, 0.2, 0.4); part.Transparency = 1
    part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
    part.Parent = cam
    local pe = Instance.new("ParticleEmitter")
    pe.Texture = "rbxasset://textures/particles/smoke_main.dds"
    pe.Color = ColorSequence.new(Color3.fromRGB(210, 235, 255))
    pe.Rate = 0; pe.Enabled = false
    pe.Lifetime = NumberRange.new(0.35, 0.7); pe.Speed = NumberRange.new(6, 11)
    pe.SpreadAngle = Vector2.new(35, 35); pe.Acceleration = Vector3.new(0, -32, 0)
    pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.3), NumberSequenceKeypoint.new(1, 0.75) })
    pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.2), NumberSequenceKeypoint.new(1, 1) })
    pe.LightEmission = 0.3
    pe.Parent = part
    RL.splash = { part = part, pe = pe }
    return RL.splash
end

local function hitsCharacter(inst)
    local m = inst and inst:FindFirstAncestorOfClass("Model")
    return m ~= nil and m:FindFirstChildOfClass("Humanoid") ~= nil
end

function RL.update(dt)
    local c = RL.c
    if not c or not c.char.Parent or c.hum.Health <= 0 then return end
    local R = E.perf and RL.perfR or S.real
    local anyOn = R.footIK or R.lean or R.head or R.breathe or R.land or R.brake or R.dust or R.camBob
        or R.headLead or R.glance or R.prints or R.splash or R.shake
    if anyOn then RL.clean = false elseif RL.clean then return end
    dt = math.min(dt, 0.05); RL.t += dt

    local hum, root, sm = c.hum, c.root, RL.sm
    local state = hum:GetState()
    local vel = root.AssemblyLinearVelocity
    local lv = root.CFrame:VectorToObjectSpace(vel)
    local speed = Vector3.new(vel.X, 0, vel.Z).Magnitude
    local grounded = hum.FloorMaterial ~= Enum.Material.Air
    local special = hum.Sit or hum.PlatformStand or state == Enum.HumanoidStateType.Climbing or state == Enum.HumanoidStateType.Swimming
        or state == Enum.HumanoidStateType.Seated or state == Enum.HumanoidStateType.Dead or state == Enum.HumanoidStateType.Ragdoll
    local ok = (not special) and (E.track == nil) -- emote tocando: não mexe no corpo
    local a = 1 - math.exp(-dt * 10)

    if state == Enum.HumanoidStateType.Freefall then RL.fall = math.max(RL.fall, -vel.Y) end

    -- aceleração pra frente (suavizada): bem negativa = freando
    do
        local fwd = -lv.Z
        local rawAcc = math.clamp((fwd - RL.pf) / math.max(dt, 0.001), -300, 300)
        RL.pf = fwd
        RL.acc += (rawAcc - RL.acc) * (1 - math.exp(-dt * 12))
    end

    -- ── pés no chão ─────────────────────────────────────────
    -- só parado: andando a animação manda (senão o pé gruda no chão e o passo trava)
    local still = speed < 3 and hum.MoveDirection.Magnitude < 0.1
        and (state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.RunningNoPhysics or state == Enum.HumanoidStateType.Landed)
    local wantIK = R.footIK and ok and grounded and still and not c.r6
    if wantIK and c.ik == nil then RL.ensureIK(c) end
    local planeY
    if c.ik then
        local r = workspace:Raycast(root.Position, Vector3.new(0, -(hum.HipHeight + root.Size.Y / 2 + 3), 0), c.params)
        planeY = r and r.Position.Y
    end

    -- 1) chão embaixo de CADA pé (precisa ser andável, não ser outro personagem, e estar dentro do alcance)
    local nlegs, hits, nh, maxAbs, valid = 0, {}, 0, 0, true
    for _ in pairs(c.legs) do nlegs += 1 end
    if wantIK and c.ik and planeY and nlegs > 0 then
        for side, L in pairs(c.legs) do
            local fp = L.ft.Position
            local rr = workspace:Raycast(Vector3.new(fp.X, planeY + R.reach + 0.5, fp.Z), Vector3.new(0, -(R.reach * 2 + 1), 0), c.params)
            if rr and rr.Normal.Y >= 0.7 and not hitsCharacter(rr.Instance) then
                local d = rr.Position.Y - planeY
                if math.abs(d) <= R.reach then
                    hits[side] = { pos = rr.Position, n = rr.Normal, d = d }; nh += 1; maxAbs = math.max(maxAbs, math.abs(d))
                else valid = false end
            else valid = false end
        end
    end
    -- chão plano (diferença < 0.05) = não faz nada: IK à toa só tortura o tornozelo
    if not valid or nh < nlegs or maxAbs < 0.05 then hits = {}; nh = 0 end

    -- 2) quadril: desce metade da diferença do pé mais baixo
    local dMin = 0
    for _, h in pairs(hits) do if h.d < dMin then dMin = h.d end end
    local pelvisT = (R.pelvis and ok) and dMin * 0.5 or 0
    local hipShift = pelvisT - sm.p -- quanto o quadril ainda vai descer (usado na checagem de alcance)

    -- 3) alvo de cada pé: posição no chão + pé deitado na superfície; só vale se a perna alcança
    local plan, np = {}, 0
    for side, h in pairs(hits) do
        local L = c.legs[side]
        local n = h.n
        local right = root.CFrame.RightVector
        right = right - n * right:Dot(n)
        if right.Magnitude > 0.01 then
            right = right.Unit
            local rot = CFrame.fromMatrix(Vector3.zero, right, n)
            local center = h.pos + n * (L.ft.Size.Y / 2)
            local ankleT = center + rot:VectorToWorldSpace(L.ank)
            local hipPos = (L.hip.Part0.CFrame * L.hip.C0).Position + Vector3.new(0, hipShift, 0)
            if (ankleT - hipPos).Magnitude <= L.len * 0.96 then -- 4% de folga: joelho nunca trava esticado
                plan[side] = CFrame.new(center) * rot; np += 1
            end
        end
    end
    local all = (nlegs > 0 and np == nlegs)  -- os DOIS pés precisam alcançar, senão o corpo fica torto
    if not all then plan = {}; pelvisT = 0 end

    for side, L in pairs(c.legs) do
        if L.ik then
            local cf = plan[side]
            if cf then L.tp.CFrame = cf end
            L.w += ((cf and 1 or 0) - L.w) * a
            L.ik.Weight = L.w
            L.ik.Enabled = L.w > 0.01
        end
    end
    sm.p += (pelvisT - sm.p) * a

    -- ── pouso (mola amortecida) ─────────────────────────────
    if R.land then
        RL.landVel += (-120 * RL.landPos - 14 * RL.landVel) * dt
        RL.landPos += RL.landVel * dt
    else
        RL.landPos, RL.landVel = 0, 0
    end

    -- ── inclinação ao andar/virar ───────────────────────────
    local pitchT, rollT = 0, 0
    if R.lean and ok then
        pitchT = -math.clamp(-lv.Z * 0.011, -0.15, 0.22) * R.leanAmt -- X negativo = inclina pra frente
        rollT = math.clamp(root.AssemblyAngularVelocity.Y * 0.05 - lv.X * 0.012, -0.3, 0.3) * R.leanAmt
    end
    -- freada: o tronco vai pra trás por um instante quando para de correr (pitch positivo = pra trás)
    if R.brake and ok and grounded then
        pitchT += math.clamp(-RL.acc * 0.0045, 0, 0.3) * R.leanAmt
    end
    sm.pitch += (pitchT - sm.pitch) * a; sm.roll += (rollT - sm.roll) * a

    -- ── cabeça (refeita) ────────────────────────────────────
    --   1) olha pra onde a câmera aponta   2) vira ANTES do corpo nas curvas   3) olhadas aleatórias parado
    --   (hy = giro, hp = cabeça pra cima/baixo, relativos ao tronco; vão pro Neck.C0 lá embaixo)
    local hyT, hpT = 0, 0
    local cam = workspace.CurrentCamera
    local inFP = FP.first
    local md = hum.MoveDirection
    local moving = md.Magnitude > 0.1
    if (R.head or R.headLead or R.glance) and ok then
        -- em 1ª pessoa a câmera É o olho: olhar pra câmera e antecipar curva ficam desligados pra não realimentar
        if R.head and cam and not inFP then
            local l = root.CFrame:VectorToObjectSpace(cam.CFrame.LookVector)
            hyT = math.clamp(math.atan2(-l.X, -l.Z), -1.2, 1.2) * 0.85
            hpT = math.clamp(math.asin(math.clamp(l.Y, -1, 1)), -0.6, 0.6) * 0.8
        end
        if R.headLead and moving and not inFP and hum.AutoRotate and UserInputService.MouseBehavior ~= Enum.MouseBehavior.LockCenter then
            local l = root.CFrame:VectorToObjectSpace(md)
            local ang = math.atan2(-l.X, -l.Z) -- > 0 = esquerda
            if math.abs(ang) < 2.3 then hyT = math.clamp(ang, -1.2, 1.2) * 0.9 end -- andando de costas não vira
        end
        local gl = RL.gl
        if R.glance and not moving and speed < 0.5 and grounded then
            gl.t -= dt
            if gl.t <= 0 then
                if gl.hold then
                    gl.yaw, gl.pit, gl.hold = 0, 0, false
                    gl.t = 2.5 + math.random() * 4.5
                else
                    gl.yaw = (math.random() * 2 - 1) * 0.75
                    gl.pit = (math.random() * 2 - 1) * 0.25
                    gl.hold = true
                    gl.t = 0.8 + math.random() * 1.4
                end
            end
            local k = inFP and 0.35 or 1 -- em 1ª pessoa a olhada é bem mais sutil
            local free = 1 - math.clamp(math.abs(hyT) / 0.4, 0, 1) -- já virada pra câmera: não soma
            hyT += gl.yaw * k * free; hpT += gl.pit * k * free
        else
            gl.yaw, gl.pit, gl.hold, gl.t = 0, 0, false, 1.5
        end
    end
    local ah = 1 - math.exp(-dt * 8)
    sm.hy += (hyT - sm.hy) * ah; sm.hp += (hpT - sm.hp) * ah

    -- ── respiração ──────────────────────────────────────────
    local brT = (R.breathe and ok and grounded and speed < 0.5) and math.sin(RL.t * 1.8) * 0.012 or 0
    sm.br += (brT - sm.br) * a

    -- ── poeira dos passos ───────────────────────────────────
    if R.dust and ok and grounded and speed > 9 then
        local d = RL.ensureDust(c)
        if d then
            d.Rate = math.clamp((speed - 9) * 3, 0, 26)
            local mat = hum.FloorMaterial
            if c.dustMat ~= mat then c.dustMat = mat; d.Color = ColorSequence.new(DUST_COL[mat] or DUST_DEF) end
            d.Enabled = true
        end
    elseif c.dust then
        c.dust.Enabled = false
    end

    -- ── balanço de câmera (CameraOffset do Humanoid: a câmera do Roblox respeita, sem briga) ──
    local bobT = Vector3.zero
    if R.camBob and ok and grounded and speed > 2 then
        RL.bobPh += dt * speed * 0.6
        local k = math.clamp(speed / 16, 0.3, 1.6) * R.camAmt
        bobT = Vector3.new(math.cos(RL.bobPh) * 0.05 * k, (math.abs(math.sin(RL.bobPh)) - 0.5) * 0.12 * k, 0)
    end
    RL.bob = RL.bob:Lerp(bobT, a)
    if RL.bob.Magnitude > 0.0005 or RL.bobOn then
        RL.bobOn = RL.bob.Magnitude > 0.0005
        pcall(function() hum.CameraOffset = c.camBase + FP.off + SH.off + RL.bob end)
    end

    -- ── pegadas (neve/areia/lama) e respingo (água) ─────────
    local fh
    if (R.prints or R.splash) and not special and speed > 2.5 then fh = RL.floorRay(c) end
    if R.splash and fh and fh.Material == Enum.Material.Water then
        local sp2 = RL.ensureSplash()
        if sp2 then
            sp2.part.CFrame = CFrame.new(fh.Position + Vector3.new(0, 0.1, 0))
            sp2.pe.Rate = math.clamp(speed * 2.2, 6, 34)
            sp2.pe.Enabled = true
        end
    elseif RL.splash and RL.splash.pe.Enabled then
        RL.splash.pe.Enabled = false
    end
    if R.prints and ok and grounded and fh and PRINT_COL[fh.Material] then
        RL.pdist += speed * dt
        if RL.pdist >= 2.2 then RL.pdist = 0; RL.side = -RL.side; RL.stamp(c, fh) end
    end

    -- ── aplica nos Motor6D (sempre a partir do C0 original) ─
    local o = c.o
    if c.rootJ and o.rootJ then c.rootJ.C0 = o.rootJ * CFrame.new(0, sm.p + RL.landPos, 0) end
    if c.waist and o.waist then c.waist.C0 = o.waist * CFrame.Angles(sm.pitch + sm.br + RL.landPos * 0.5, 0, sm.roll) end
    -- pescoço compensa metade da inclinação do tronco, pra cabeça não tombar junto
    if c.neck and o.neck then
        -- giro aplicado no espaço do tronco e depois da rotação original do joint (vale pro R15 e pro R6, que tem o pescoço "deitado")
        c.neck.C0 = CFrame.new(o.neck.Position) * CFrame.Angles(0, sm.hy, 0)
            * CFrame.Angles(sm.hp - sm.pitch * 0.5, 0, -sm.roll * 0.5) * o.neck.Rotation
    end

    -- tudo desligado e já voltou a zero: restaura exato e para de gastar frame
    if not anyOn then
        local m = math.abs(sm.p) + math.abs(sm.pitch) + math.abs(sm.roll) + math.abs(sm.hy) + math.abs(sm.hp) + math.abs(sm.br) + math.abs(RL.landPos)
        for _, L in pairs(c.legs) do m += L.w end
        m += RL.bob.Magnitude
        if m < 0.002 then RL.restore(c); RL.clean = true end
    end
end

UI.conns[#UI.conns + 1] = RunService.RenderStepped:Connect(function(dt)
    local ok, err = pcall(RL.update, dt)
    if not ok and not RL.warned then RL.warned = true; warn("[GTA EmoteHub] realismo: " .. tostring(err)) end
end)

-- ══════════════════════════════════════════════════════════
--  PRIMEIRA PESSOA (Config → PRIMEIRA PESSOA). Só você vê.
--  Usa a câmera NATIVA do Roblox travando só o zoom em 0.5: arrastar a tela / mexer o mouse gira a câmera normal.
--  Realista: corpo visível (braços e pernas), cabeça e acessórios escondidos, FOV maior, câmera um pouco à frente
--  do rosto e volta pra 3ª pessoa sozinho enquanto um emote toca (opcional). Tecla: CFG.FpKey
-- ══════════════════════════════════════════════════════════
local FP_HIDE = { Hat = true, Hair = true, Face = true, Neck = true, Eyebrow = true, Eyelash = true }
local FP_OUT_DIST = 9 -- distância da câmera ao sair da 1ª pessoa

function FP.setZoom(lo, hi)
    pcall(function() LP.CameraMinZoomDistance = lo; LP.CameraMaxZoomDistance = hi end)
end

-- offset do Humanoid = base original + deslocamento da 1ª pessoa + balanço (realismo)
function FP.applyOffset()
    local _, hum = E.parts()
    if not hum then return end
    local base = (RL.c and RL.c.camBase) or FP.base0 or Vector3.zero
    pcall(function() hum.CameraOffset = base + FP.off + SH.off + RL.bob end)
end

function FP.rebuild()
    FP.body, FP.hide = {}, {}
    local c = LP.Character
    if not c then FP.head, FP.neck = nil, nil; return end
    FP.head = c:FindFirstChild("Head")
    local nk = FP.head and FP.head:FindFirstChild("Neck") -- R15: Neck fica na Head
    if not nk then local tor = c:FindFirstChild("Torso"); nk = tor and tor:FindFirstChild("Neck") end -- R6: fica no Torso
    FP.neck = (nk and nk:IsA("Motor6D")) and nk or nil
    for _, d in ipairs(c:GetDescendants()) do
        if d:IsA("BasePart") and d.Name ~= "HumanoidRootPart" then
            local acc = d:FindFirstAncestorOfClass("Accessory")
            local hide = false
            if acc then
                local ok, tp = pcall(function() return acc.AccessoryType.Name end)
                hide = ok and FP_HIDE[tp] == true
            else
                hide = (d.Name == "Head" and d.Parent == c)
            end
            local list = hide and FP.hide or FP.body
            list[#list + 1] = d
        end
    end
end

function FP.hook(char)
    if FP.dconn then pcall(function() FP.dconn:Disconnect() end); FP.dconn = nil end
    FP.dirty = true
    if char then FP.dconn = char.DescendantAdded:Connect(function() FP.dirty = true end) end
end

-- devolve a transparência local pro Roblox (senão a cabeça pode ficar invisível na 3ª pessoa)
local function fpClearLocal()
    for _, list in ipairs({ FP.body, FP.hide }) do
        for _, p in ipairs(list) do if p.Parent then pcall(function() p.LocalTransparencyModifier = 0 end) end end
    end
end

-- devolve a câmera pro CFrame nativo (sem o giro da cabeça/balanço) pra não dar pulo ao sair
function FP.dropNative()
    if FP.nativeCF then
        local cam = workspace.CurrentCamera
        if cam then pcall(function() cam.CFrame = FP.nativeCF end) end
    end
    FP.nativeCF = nil
    FP.bob, FP.roll, FP.ph = Vector3.zero, 0, 0
end

function FP.restoreZoom()
    if FP.zmin then FP.setZoom(FP.zmin, FP.zmax) end
end

-- sai da 1ª pessoa: afasta a câmera por um instante e devolve os limites de zoom originais
function FP.pullOut(keep)
    FP.tok += 1
    local my = FP.tok
    local lo, hi = FP.zmin or 0.5, FP.zmax or 128
    local d = math.clamp(FP_OUT_DIST, lo, hi)
    FP.setZoom(d, d)
    task.delay(0.3, function()
        if FP.tok ~= my then return end -- voltou pra 1ª pessoa nesse meio tempo
        FP.setZoom(lo, hi)
        if not keep then FP.zmin, FP.zmax = nil, nil end
    end)
end

function FP.goFirst()
    FP.tok += 1
    FP.first = true
    FP.rebuild(); FP.dirty = false
    FP.setZoom(0.5, 0.5)
    local cam = workspace.CurrentCamera
    if cam and not FP.fov0 then FP.fov0 = SH.fov0 or cam.FieldOfView end
    FP.off = Vector3.new(0, 0, -S.fp.depth)
    FP.applyOffset()
end

function FP.goOut(keep)
    FP.first = false
    FP.dropNative()
    fpClearLocal()
    local cam = workspace.CurrentCamera
    if cam and FP.fov0 then cam.FieldOfView = FP.fov0 end
    FP.fov0 = nil
    FP.off = Vector3.zero
    FP.applyOffset()
    FP.pullOut(keep)
end

function FP.sync()
    local F = S.fp
    if F.on and not FP.begun then
        FP.begun = true
        if not FP.zmin then FP.zmin, FP.zmax = LP.CameraMinZoomDistance, LP.CameraMaxZoomDistance end
        FP.hook(LP.Character)
        local _, hum = E.parts()
        FP.base0 = hum and hum.CameraOffset or Vector3.zero
    elseif not F.on and FP.begun then
        FP.begun = false
        if FP.first then FP.goOut(false) else FP.restoreZoom(); FP.zmin, FP.zmax = nil, nil end
        FP.hook(nil)
        return
    end
    if not FP.begun then return end
    local want = not (F.emoteOut and E.track ~= nil)
    if want and not FP.first then FP.goFirst()
    elseif (not want) and FP.first then FP.goOut(true) end
    if FP.first and (LP.CameraMinZoomDistance ~= 0.5 or LP.CameraMaxZoomDistance ~= 0.5) then FP.setZoom(0.5, 0.5) end
end

function FP.toggle()
    S.fp.on = not S.fp.on; save(); FP.sync()
    for _, p in ipairs(UI.paints) do pcall(p) end -- atualiza o switch na Config
    notify("Primeira pessoa", S.fp.on and "ligada" or "desligada")
end

-- câmera de ombro: CameraOffset lateral/altura (o Humanoid compõe com o balanço) + zoom puxado pra uma distância e depois liberado
function SH.zoom(d)
    if FP.first then return end
    SH.tok = (SH.tok or 0) + 1
    local my = SH.tok
    local lo = SH.lo or FP.zmin or LP.CameraMinZoomDistance
    local hi = SH.hi or FP.zmax or LP.CameraMaxZoomDistance
    SH.lo, SH.hi = lo, hi
    d = math.clamp(d, lo, hi)
    FP.setZoom(d, d)
    task.delay(0.3, function()
        if SH.tok ~= my then return end
        if not FP.first then FP.setZoom(lo, hi) end
        SH.lo, SH.hi = nil, nil
    end)
end

function SH.sync()
    local F = S.sh
    local want = F.on and not FP.first
    local target = want and Vector3.new(F.side * F.x, F.y, 0) or Vector3.zero
    if target ~= SH.off then SH.off = target; FP.applyOffset() end
    if want and not SH.active then SH.active = true; SH.zoom(F.dist)
    elseif not want and SH.active then SH.active = false end
end

function FP.charAdded(char, hum)
    if FP.first then FP.dropNative(); FP.first = false; FP.off = Vector3.zero end -- personagem novo: a sync volta pra 1ª pessoa sozinha
    FP.body, FP.hide = {}, {}
    FP.base0 = hum and hum.CameraOffset or Vector3.zero
    if FP.begun then FP.hook(char) end
end

-- Pipeline de câmera. A câmera do Roblox lê o CFrame da própria câmera pra saber pra onde você olha, então:
--   antes dela (PRE)   devolve o CFrame nativo (sem nossos efeitos), pra o seu giro livre continuar normal
--   depois dela (POST) guarda o CFrame nativo e aplica: 1ª pessoa (olho da cabeça + balanço), inclinação nas curvas e tremor
local function camPre()
    if not FP.nativeCF then return end
    local cam = workspace.CurrentCamera
    if cam then cam.CFrame = FP.nativeCF end
end

local function camStep(dt)
    local cam = workspace.CurrentCamera
    if not cam then return end
    local R = E.perf and RL.perfR or S.real
    local F = S.fp

    -- FOV de cinema (câmera de ombro, só na 3ª pessoa)
    if S.sh.on and S.sh.fovOn and not FP.first then
        if not SH.fov0 then SH.fov0 = cam.FieldOfView end
        if cam.FieldOfView ~= S.sh.fov then cam.FieldOfView = S.sh.fov end
    elseif SH.fov0 then
        cam.FieldOfView = SH.fov0; SH.fov0 = nil
    end

    CAMFX.t += dt
    CAMFX.amp *= math.exp(-dt * 5)
    if CAMFX.amp < 0.003 then CAMFX.amp = 0 end

    local c = LP.Character
    local root = c and c:FindFirstChild("HumanoidRootPart")
    local hum = c and c:FindFirstChildOfClass("Humanoid")
    local wantLean = (root ~= nil) and R.camLean
    if not (FP.first or wantLean or CAMFX.amp > 0 or math.abs(CAMFX.roll) > 1e-3) then
        FP.dropNative()
        return
    end

    if FP.first then
        if FP.dirty then FP.dirty = false; FP.rebuild() end
        -- corpo visível / cabeça escondida (a câmera nativa escondia tudo)
        local hv, bv = F.hideHead and 1 or 0, F.body and 0 or 1
        for _, p in ipairs(FP.hide) do if p.Parent then p.LocalTransparencyModifier = hv end end
        for _, p in ipairs(FP.body) do if p.Parent then p.LocalTransparencyModifier = bv end end
        if cam.FieldOfView ~= F.fov then cam.FieldOfView = F.fov end
    end
    if not (root and hum) then FP.nativeCF = nil; return end

    FP.nativeCF = cam.CFrame
    local rot, pos = FP.nativeCF.Rotation, FP.nativeCF.Position
    local a = 1 - math.exp(-dt * 10)
    local vel = root.AssemblyLinearVelocity
    local planar = Vector3.new(vel.X, 0, vel.Z)
    local speed = planar.Magnitude

    if FP.first then
        local head = FP.head
        if F.follow and head and head.Parent then
            -- olho = frente do rosto, na posição ATUAL da cabeça (anda, balança e inclina com a animação)
            pos = head.CFrame:PointToWorldSpace(Vector3.new(0, 0.1, -F.depth))
            -- giro da cabeça relativo ao corpo: só a animação do pescoço (Transform), não o C0 do "olhar pra câmera"
            local nk = FP.neck
            if nk and nk.Part0 and F.followAmt > 0 then
                local base = (nk.Part0.CFrame * nk.C0).Rotation
                local d = base * nk.Transform.Rotation * base:Inverse()
                rot = CFrame.new():Lerp(d, F.followAmt) * rot
            end
            -- movimento procedural da cabeça (olhadas do idle) também move a câmera
            local sm = RL.sm
            rot = CFrame.Angles(0, sm.hy * F.followAmt, 0) * rot * CFrame.Angles(sm.hp * F.followAmt, 0, 0)
        end
        -- balanço de passo + inclinação lateral (se o balanço do Realismo está ligado fora do modo "segue a cabeça", não dobra)
        local k = F.motion
        local bobT, rollT = Vector3.zero, 0
        if k > 0 and (F.follow or not R.camBob) then
            if hum.FloorMaterial ~= Enum.Material.Air and speed > 2 then
                FP.ph += dt * speed * 0.6
                local kk = math.clamp(speed / 16, 0.3, 1.6) * k
                bobT = Vector3.new(math.cos(FP.ph) * 0.04 * kk, (math.abs(math.sin(FP.ph)) - 0.5) * 0.1 * kk, 0)
            end
            rollT = -math.clamp(root.CFrame.RightVector:Dot(planar) / 16, -1.5, 1.5) * 0.04 * k
        end
        FP.bob = FP.bob:Lerp(bobT, a)
        FP.roll += (rollT - FP.roll) * a
    else
        FP.bob, FP.roll = Vector3.zero, 0
    end

    -- inclinar a câmera nas curvas (entra pro lado de dentro da curva)
    local rollC = 0
    if wantLean then
        rollC = math.clamp(root.AssemblyAngularVelocity.Y * 0.04, -0.14, 0.14) * math.clamp(speed / 16, 0, 1.2) * R.leanAmt
    end
    CAMFX.roll += (rollC - CAMFX.roll) * (1 - math.exp(-dt * 6))

    -- tremor + mergulho em pouso forte
    local sp, sy, sr, jit = 0, 0, 0, 0
    if CAMFX.amp > 0 then
        local t, k = CAMFX.t, CAMFX.amp
        sp = math.sin(t * 52) * k * 0.03
        sy = math.sin(t * 43 + 1.3) * k * 0.02
        sr = math.sin(t * 37 + 2.1) * k * 0.025
        jit = (math.sin(t * 58) * 0.04 - 0.22) * k
    end
    local camRot = rot * CFrame.Angles(sp, sy, (FP.first and FP.roll or 0) + CAMFX.roll + sr)
    cam.CFrame = CFrame.new(pos + Vector3.new(0, jit, 0) + camRot:VectorToWorldSpace(FP.bob)) * camRot
end
pcall(function() RunService:BindToRenderStep("EH_FP_PRE", Enum.RenderPriority.Camera.Value - 1, camPre) end)
pcall(function() RunService:BindToRenderStep("EH_FP", Enum.RenderPriority.Camera.Value + 1, camStep) end)

function FP.shutdown() -- no Destroy: devolve câmera/zoom/FOV e solta o bind (a config salva continua)
    if FP.begun then
        FP.begun = false
        if FP.first then FP.goOut(false) else FP.restoreZoom() end
    end
    pcall(function() RunService:UnbindFromRenderStep("EH_FP") end)
    pcall(function() RunService:UnbindFromRenderStep("EH_FP_PRE") end)
    if FP.dconn then pcall(function() FP.dconn:Disconnect() end) end
end

UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function() FP.sync() end)
UI.conns[#UI.conns + 1] = UserInputService.InputBegan:Connect(function(i, processed)
    if processed or i.UserInputType ~= Enum.UserInputType.Keyboard or i.KeyCode ~= CFG.FpKey then return end
    if UserInputService:GetFocusedTextBox() or UI.capturing then return end
    FP.toggle()
end)
UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function() SH.sync() end)
UI.conns[#UI.conns + 1] = UserInputService.InputBegan:Connect(function(i, processed)
    if processed or i.UserInputType ~= Enum.UserInputType.Keyboard or i.KeyCode ~= CFG.ShoulderKey then return end
    if UserInputService:GetFocusedTextBox() or UI.capturing then return end
    S.sh.on = not S.sh.on; save()
    if S.sh.on then SH.zoom(S.sh.dist) end
    for _, p in ipairs(UI.paints) do pcall(p) end
    notify("Câmera de ombro", S.sh.on and "ligada" or "desligada")
end)

-- ══════════════════════════════════════════════════════════
--  EVENTOS: toca um emote sozinho quando algo acontece (configuração na página ⚡ Eventos)
-- ══════════════════════════════════════════════════════════
local EV = { last = {}, any = 0, fall = 0, runT = 0, conns = {}, hp = 100, lowHp = false }

function EV.unhook()
    for _, cn in ipairs(EV.conns) do pcall(function() cn:Disconnect() end) end
    EV.conns = {}
end

local function evFire(key)
    local cfg = S.ev[key]
    if not cfg or not cfg.on then return end
    local now = os.clock()
    if now - (EV.last[key] or 0) < S.evCd or now - EV.any < 0.8 then return end
    local _, hum = E.parts()
    if not hum or hum.Health <= 0 or E.track ~= nil then return end -- nunca corta um emote que você já tocou
    local id = cfg.emote
    if id == 0 then
        local pool = E.pool()
        id = pool[math.random(math.max(#pool, 1))]
    end
    if not id then return end
    EV.last[key], EV.any = now, now
    task.spawn(E.play, id, true)
end

function EV.hook(char, hum)
    EV.unhook()
    EV.fall, EV.runT, EV.lowHp, EV.hp = 0, 0, false, hum.Health
    local function add(cn) EV.conns[#EV.conns + 1] = cn end
    add(hum.StateChanged:Connect(function(old, new)
        local T = Enum.HumanoidStateType
        if new == T.Jumping then evFire("jump")
        elseif new == T.Landed then
            local f = EV.fall; EV.fall = 0
            if f >= S.evLandMin then evFire("land") end
        elseif new == T.Swimming then evFire("swim")
        elseif old == T.Swimming then evFire("swimEnd") end
    end))
    add(hum:GetPropertyChangedSignal("Sit"):Connect(function() evFire(hum.Sit and "sit" or "stand") end))
    add(char.ChildAdded:Connect(function(ch) if ch:IsA("Tool") then evFire("equip") end end))
    add(char.ChildRemoved:Connect(function(ch) if ch:IsA("Tool") then evFire("unequip") end end))
    add(hum.HealthChanged:Connect(function(h)
        if h < EV.hp - 0.5 and h > 0 then evFire("hurt") end
        local frac = h / math.max(hum.MaxHealth, 1)
        if frac < 0.3 and h > 0 and not EV.lowHp then EV.lowHp = true; evFire("low")
        elseif frac > 0.5 then EV.lowHp = false end
        EV.hp = h
    end))
end

-- parou de correr (correu ≥ 0.5s acima da velocidade mínima e zerou) + maior velocidade de queda (pro "pousou")
UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function(dt)
    local _, hum = E.parts()
    local root = hum and hum.RootPart
    if not root then return end
    local v = root.AssemblyLinearVelocity
    local sp = Vector3.new(v.X, 0, v.Z).Magnitude
    if hum:GetState() == Enum.HumanoidStateType.Freefall then EV.fall = math.max(EV.fall, -v.Y) end
    if sp >= S.evRunMin then EV.runT += dt
    elseif sp < 1.5 then
        if EV.runT >= 0.5 then evFire("stopRun") end
        EV.runT = 0
    end
end)

-- ══════════════════════════════════════════════════════════
--  PERFORMANCE + FPS/PING
-- ══════════════════════════════════════════════════════════
local Stats = game:GetService("Stats")
local PF = { frames = 0, acc = 0, fps = 60, low = 0, high = 0, t0 = os.clock() }
E.perf = false

local hudBtn = mk("TextButton", {
    Size = UDim2.fromOffset(132, 24), Position = UDim2.fromOffset(8, 8), BorderSizePixel = 0, ZIndex = 49, Visible = false,
    AutoButtonColor = false, Text = "", TextSize = 11, Font = Enum.Font.GothamBold, TextColor3 = WHITE, BackgroundTransparency = 0.2,
}, Gui)
corner(hudBtn, 12); th(hudBtn, "BackgroundColor3", "panel"); stroke(hudBtn, "stroke", 1, 0.4)
if S.hudPos then hudBtn.Position = arrPos(S.hudPos) end
makeDraggable(hudBtn, hudBtn, function() return 1 end, function() S.hudPos = posArr(hudBtn); save() end)
UI.hud = hudBtn
UI.applyVis()

local function readPing()
    local ok, v = pcall(function() return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
    if ok and type(v) == "number" then return v end
    local ok2, v2 = pcall(function() return LP:GetNetworkPing() * 1000 end)
    return ok2 and v2 or 0
end

function PF.tick()
    local fps = PF.fps
    if S.hud and hudBtn.Visible then
        hudBtn.Text = ("%d FPS · %d ms%s"):format(math.floor(fps + 0.5), math.floor(readPing() + 0.5), E.perf and " ⚡" or "")
        hudBtn.TextColor3 = fps >= 50 and Color3.fromRGB(110, 255, 150) or (fps >= 30 and Color3.fromRGB(255, 220, 90) or Color3.fromRGB(255, 90, 90))
    end
    if not S.perf.on then
        if E.perf then E.perf = false; E.fxApply() end
        PF.low, PF.high = 0, 0
        return
    end
    if os.clock() - PF.t0 < 8 then return end -- ignora o começo (carregando)
    local mn = S.perf.min
    if fps < mn then PF.low += 0.5; PF.high = 0
    elseif fps > mn + 15 then PF.high += 0.5; PF.low = 0
    else PF.low = math.max(PF.low - 0.25, 0) end
    if not E.perf and PF.low >= 4 then
        E.perf = true; PF.low = 0; E.fxApply()
        notify("Modo performance", "FPS baixo: efeitos pausados")
    elseif E.perf and PF.high >= 20 then
        E.perf = false; PF.high = 0; E.fxApply()
        notify("Modo performance", "FPS ok: efeitos de volta")
    end
end
UI.conns[#UI.conns + 1] = RunService.Heartbeat:Connect(function(dt)
    PF.frames += 1; PF.acc += dt
    if PF.acc >= 0.5 then PF.fps = PF.frames / PF.acc; PF.frames, PF.acc = 0, 0; PF.tick() end
end)

