function UI.showChangelog(all)
    if UI.logGui then pcall(function() UI.logGui:Destroy() end) end
    local shade = mk("TextButton", {
        Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, Text = "", AutoButtonColor = false, ZIndex = 110,
    }, Gui)
    UI.logGui = shade
    local card = mk("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(330, 400), BorderSizePixel = 0, ZIndex = 111,
    }, shade)
    corner(card, 16); th(card, "BackgroundColor3", "panel"); stroke(card, "accent", 1.5, 0.3)
    mk("UIScale", { Scale = UI.baseScale or 1 }, card)
    label(card, "📰 Novidades", 15, "accent", Enum.Font.GothamBold, { Size = UDim2.new(1, -24, 0, 28), Position = UDim2.fromOffset(14, 10) })
    local l = listOf(card, UDim2.fromOffset(12, 46), UDim2.new(1, -24, 1, -100), 4)
    for i, sec in ipairs(CHANGELOG) do
        if all or i > S.seenLog then
            label(l, sec[1], 12, "accent", Enum.Font.GothamBold, { Size = UDim2.new(1, -8, 0, 20), LayoutOrder = nextOrder(l), TextWrapped = false })
            for _, line in ipairs(sec[2]) do
                label(l, "•  " .. line, 11, "text", nil, { Size = UDim2.new(1, -8, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = nextOrder(l) })
            end
        end
    end
    local function close()
        S.seenLog = #CHANGELOG; save()
        shade:Destroy(); UI.logGui = nil
    end
    button(card, "Beleza", UDim2.new(1, -24, 0, 34), close, "primary").Position = UDim2.new(0, 12, 1, -46)
end
task.delay(2.5, function()
    if not S.hidden and S.seenLog < #CHANGELOG then UI.showChangelog(false) end
end)

local function onChar(char)
    E.track = nil; E.orig = {}
    local hum = char:WaitForChild("Humanoid", 10)
    if not hum then return end
    hum:WaitForChild("Animator", 10)
    if hum.RigType == Enum.HumanoidRigType.R15 then -- realismo: espera as peças do R15 existirem
        for _, n in ipairs({ "UpperTorso", "LowerTorso", "Head", "LeftFoot", "RightFoot", "LeftLowerLeg", "RightLowerLeg" }) do char:WaitForChild(n, 5) end
        RL.setup(char)
    else
        char:WaitForChild("Torso", 5) -- R6: cabeça, câmera, poeira, pegadas e respingo funcionam (inclinação e IK são só do R15)
        RL.setup(char)
    end
    FP.charAdded(char, hum)
    EV.hook(char, hum)
    if S.pack ~= "none" then task.delay(0.6, function() E.applyPack(char, true) end) end
    if #S.wheel > 0 then task.delay(2, WH.inject) end
    if S.fx.particles or S.fx.aura or S.fx.trail then task.delay(1, E.fxApply) end
    local firstChar = not E.charSeen
    E.charSeen = true
    if S.spawn.on and (not firstChar or S.spawn.join) then
        task.delay(S.spawn.delay, function()
            if char ~= LP.Character or E.track ~= nil then return end
            local id = S.spawn.emote
            if id == 0 then local pool = E.pool(); id = pool[math.random(math.max(#pool, 1))] end
            if id then E.play(id, true) end
        end)
    elseif S.autoReload and S.lastEmote ~= 0 then
        task.delay(1.2, function() E.play(S.lastEmote) end)
    end
end
UI.conns[#UI.conns + 1] = LP.CharacterAdded:Connect(onChar)
if LP.Character then task.spawn(onChar, LP.Character) end

pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.EmotesMenu, true) end)
-- pré-carrega a 1ª página de emotes do catálogo em background: abrir a Loja já vem do cache
if reqFn then task.delay(1.5, function() pcall(cachedFetch, 2, "", nil) end) end
for _, id in ipairs(S.wheel) do Names.get(id, function() end) end -- aquece nomes pros slots da roda

