--  DESTROY
-- ══════════════════════════════════════════════════════════
local function destroy()
    E.stopSeq(); E.stop(); pcall(E.clearFx); pcall(FP.shutdown); pcall(EV.unhook); pcall(RL.reset)
    for _, c in ipairs(UI.conns) do pcall(function() c:Disconnect() end) end
    UI.conns = {}
    pcall(function() Gui:Destroy() end)
    if getgenv then getgenv().GTAEmoteHub = nil end
end
if getgenv then getgenv().GTAEmoteHub = { Destroy = destroy, Play = E.play, State = S } end

if S.hidden then
    notify("GTA Emote Hub", "Escondido — 2 dedos de cima pra baixo (devagar) abre")
else
    notify("GTA Emote Hub v4.10", "aperta  " .. UI.keyLabel() .. "  ou o botão 🎭 pra abrir/fechar")
end
end

-- ---------------------------------------------------------------- BROOKHAVEN (fusão do pacote Brookhaven → GTA)
-- Só entrou o que o GTA Hub ainda não tinha. Remotes e caminhos vêm do script original e NÃO foram testados num executor.
local function tabBrook()
    local function canHit(p)  -- fecha pra falso: sem GTA_PL ou imune/admin protegido, não mira
        if typeof(p) ~= "Instance" or p == LP then return false end
        local ok1, res = pcall(function() return GTA_PL.canHit(p) end)
        return ok1 and res == true
    end
    local function others()
        local out = {}
        for _, p in ipairs(Plrs:GetPlayers()) do if canHit(p) then out[#out + 1] = p end end
        return out
    end
    local function trackDD(dd) pcall(function() GTA_PL.track(dd, false) end) end
    local function myHouse()
        local lots = WS:FindFirstChild("001_Lots")
        local h = lots and lots:FindFirstChild(LP.Name .. "House")
        local picked = h and h:FindFirstChild("HousePickedByPlayer")
        return picked and picked:FindFirstChild("HouseModel")
    end
    local function runLoop(interval, fn)
        local alive = true
        task.spawn(function()
            while alive do
                local ok2, err = pcall(fn)
                if not ok2 then warn("[GTA Hub] Brookhaven: " .. tostring(err)) end
                task.wait(interval)
            end
        end)
        return function() alive = false end
    end
    local function switch(interval, fn, onStop)  -- callback de toggle: liga/desliga o loop sem deixar loop velho vivo
        local stop
        return function(v)
            if stop then stop() stop = nil end
            if v then
                stop = runLoop(interval, fn)
            elseif onStop then
                pcall(onStop)
            end
        end
    end
    local function rainbow() return Color3.fromHSV((tick() * 0.5) % 1, 1, 1) end

    -- ===== CASAS: props da minha casa =====
    local HT = ActiveWindow:MakeTab({Title = "Casas", Icon = "home"})
    HT:AddSection({"Props da minha casa"})
    HT:AddToggle({Name = "Bloquear props de outros na minha casa", Default = false, Callback = function(v)
        local hm = myHouse()
        local r = hm and hm:FindFirstChild("Permissions:SetPropPlacementBlockedForOthers")
        if not r then note("GTA Hub", "Casa não encontrada: pegue uma casa primeiro") return end
        local ok2, e = pcall(function() r:InvokeServer(v) end)
        if not ok2 then note("GTA Hub", "Falhou: " .. tostring(e):sub(1, 60)) end
    end})
    HT:AddButton({Name = "Apagar todos os props da minha casa", Callback = function()
        local hm = myHouse()
        local r = hm and hm:FindFirstChild("Permissions:ClearProps")
        if not r then note("GTA Hub", "Casa não encontrada: pegue uma casa primeiro") return end
        local ok2, e = pcall(function() r:InvokeServer() end)
        if not ok2 then note("GTA Hub", "Falhou: " .. tostring(e):sub(1, 60)) end
    end})

    -- ===== TROLL PLAYERS: anti tools, placas, teleporte em loop (só em quem está no servidor e passa no canHit) =====
    local TP = ActiveWindow:MakeTab({Title = "Troll Players", Icon = "🎯"})
    TP:AddSection({"Brookhaven: tools, placas e loop"})
    local function stripTool(p)
        local c = p.Character
        local tool = c and c:FindFirstChildOfClass("Tool")
        if not tool then return end
        local trig, clr = remote("1Playe1rTrigge1rEven1t"), remote("1Clea1rTool1s")
        if trig and clr then
            trig:FireServer("AcceptedToolToServer", tool.Name, p)
            clr:FireServer("ClearAllTools")
        end
    end
    local antiSel
    local ddAT = TP:AddDropdown({Name = "Alvo: Anti Tools", Options = {}, Default = "", Callback = function(v) antiSel = (v ~= "" and v) or nil end})
    trackDD(ddAT)
    TP:AddToggle({Name = "Anti Tools: tirar itens do alvo", Default = false, Callback = switch(0.1, function()
        local p = antiSel and Plrs:FindFirstChild(antiSel)
        if p and canHit(p) then stripTool(p) end
    end)})
    TP:AddToggle({Name = "Anti Tools: tirar itens de todos", Default = false, Callback = switch(0.1, function()
        for _, p in ipairs(others()) do stripTool(p) end
    end)})

    local signText = ""
    TP:AddTextBox({Name = "Texto da placa dos outros", PlaceholderText = "Texto", Callback = function(v) signText = tostring(v or "") end})
    TP:AddButton({Name = "Trocar placa de todos", Callback = function()
        if signText == "" then note("GTA Hub", "Digite o texto da placa antes") return end
        local n = 0
        for _, p in ipairs(others()) do
            local sign = p.Character and p.Character:FindFirstChild("Sign")
            local snd = sign and sign:FindFirstChild("ToolSound")
            if snd then
                pcall(function() snd:FireServer("Sign", "SignWords", signText) end)
                n = n + 1
            end
        end
        note("GTA Hub", "Placa trocada em " .. n .. " player(s)")
    end})

    local tpSel
    local ddTP = TP:AddDropdown({Name = "Alvo: teleporte em loop", Options = {}, Default = "", Callback = function(v) tpSel = (v ~= "" and v) or nil end})
    trackDD(ddTP)
    TP:AddToggle({Name = "Teleportar até o alvo em loop", Default = false, Callback = switch(0.05, function()
        local p = tpSel and Plrs:FindFirstChild(tpSel)
        if not (p and canHit(p)) then return end
        local tr = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
        local me = hrp()
        if tr and me then me.CFrame = tr.CFrame end
    end)})

    -- ===== PROTEÇÃO+ =====
    local PR = ActiveWindow:MakeTab({Title = "Proteção+", Icon = "shield"})
    PR:AddSection({"Brookhaven: remover itens dos outros (só no seu cliente)"})
    local function com() return WS:FindFirstChild("WorkspaceCom") end
    local function folderCanoes() local c = com() return c and c:FindFirstChild("001_CanoeStorage") end
    local function folderBalls() local c = com() return c and c:FindFirstChild("001_SoccerBalls") end
    local function folderJets()
        local c = com()
        local a = c and c:FindFirstChild("001_Airport")
        local h = a and a:FindFirstChild("AirportHanger")
        local j = h and h:FindFirstChild("001_JetStorage")
        return j and j:FindFirstChild("JetAirport")
    end
    local function hideFromOthers(label, getFolder, isMine, trackKey)  -- trackKey: expõe liga/desliga/estado em GTA_PL.protect pra outra função usar (ex.: Bola V2)
        local backup = {}
        local state = false
        local inner = switch(0.1, function()
            local f = getFolder()
            if not f then return end
            for _, item in ipairs(f:GetChildren()) do
                if not isMine(item) then
                    local okc, clone = pcall(function() return item:Clone() end)
                    if okc and clone then backup[#backup + 1] = {inst = clone, parent = f} end
                    item:Destroy()
                end
            end
        end, function()
            for _, b in ipairs(backup) do
                if b.parent and b.parent.Parent then pcall(function() b.inst.Parent = b.parent end) end
            end
            backup = {}
        end)
        local tg = PR:AddToggle({Name = label, Default = false, Callback = function(v) state = v inner(v) end})
        if trackKey then
            GTA_PL.protect = GTA_PL.protect or {}
            GTA_PL.protect[trackKey] = {get = function() return state end, set = function(v) tg:Set(v) end}
        end
    end
    hideFromOthers("Anti Canoa Fling (esconde canoas dos outros)", folderCanoes, function(item)
        local o = item:FindFirstChild("Owner")
        return o ~= nil and o.Value == LP
    end)
    hideFromOthers("Anti Fling Jatos (esconde jatos dos outros)", folderJets, function(item) return item.Name == LP.Name end)
    hideFromOthers("Anti Fling Bola (esconde as bolas de futebol)", folderBalls, function() return false end, "ballFling")

    local blockDoor
    PR:AddToggle({Name = "Anti Bloco (tira a porta da minha casa)", Default = false, Callback = function(v)
        if v then
            local hm = myHouse()
            local nl = hm and hm:FindFirstChild("NoLockHouseDoor", true)
            local door = nl and nl:FindFirstChild("Door")
            if not door then note("GTA Hub", "Porta da sua casa não encontrada") return end
            blockDoor = {door = door, parent = nl}
            door.Parent = nil
        elseif blockDoor then
            if blockDoor.parent and blockDoor.parent.Parent then blockDoor.door.Parent = blockDoor.parent end
            blockDoor = nil
        end
    end})

    PR:AddToggle({Name = "Anti Lag: apagar tools repetidas dos outros", Default = false, Callback = switch(2, function()
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p ~= LP then
                local boxes = {}
                if p.Character then boxes[#boxes + 1] = p.Character end
                local bp = p:FindFirstChildOfClass("Backpack")
                if bp then boxes[#boxes + 1] = bp end
                for _, box in ipairs(boxes) do
                    local seenName = {}
                    for _, t in ipairs(box:GetChildren()) do
                        if t:IsA("Tool") then
                            if seenName[t.Name] then pcall(function() t:Destroy() end) else seenName[t.Name] = true end
                        end
                    end
                end
            end
        end
    end)})

    -- ===== RGB: bicicleta e props =====
    local RG = ActiveWindow:MakeTab({Title = "RGB", Icon = "palette"})
    RG:AddSection({"Brookhaven: bicicleta e props"})
    RG:AddToggle({Name = "RGB Bicicleta", Default = false, Callback = switch(0.1, function()
        local ev = remote("1Player1sCa1r")
        if ev then ev:FireServer("NoMotorColor", rainbow()) end
    end)})
    RG:AddToggle({Name = "RGB nos meus props", Default = false, Callback = switch(0.1, function()
        local color = rainbow()
        local c = com()
        if c then
            for _, folder in ipairs(c:GetChildren()) do
                for _, prop in ipairs(folder:GetChildren()) do
                    local ev = prop.Name:find(LP.Name, 1, true) and prop:FindFirstChild("ChangePropColor")
                    if ev then task.spawn(function() pcall(function() ev:InvokeServer(color) end) end) end
                end
            end
        end
        pcall(function()
            LP.PlayerGui.NoResetGUIHandler.PropColorPicker.SetColor:FireServer(color)
        end)
    end)})

    -- ===== CARRO: câmera no carro escolhido =====
    local CT = ActiveWindow:MakeTab({Title = "Carro", Icon = "car"})
    CT:AddSection({"Brookhaven: câmera em outro carro"})
    local carSel, savedCam
    local function carNames()
        local t, v = {}, WS:FindFirstChild("Vehicles")
        if v then for _, c in ipairs(v:GetChildren()) do t[#t + 1] = c.Name end end
        table.sort(t)
        return t
    end
    local ddCar = CT:AddDropdown({Name = "Carro da câmera", Options = carNames(), Default = "", Callback = function(v) carSel = (v ~= "" and v) or nil end})
    CT:AddButton({Name = "Atualizar lista de carros", Callback = function() pcall(function() ddCar:Refresh(carNames()) end) end})
    CT:AddToggle({Name = "Ver câmera do carro selecionado", Default = false, Callback = function(v)
        local cam = WS.CurrentCamera
        if v then
            local vf = WS:FindFirstChild("Vehicles")
            local car = carSel and vf and vf:FindFirstChild(carSel)
            local seat = car and car:FindFirstChildWhichIsA("VehicleSeat", true)
            if not seat then note("GTA Hub", "Escolha um carro válido na lista") return end
            if not savedCam then savedCam = {subject = cam.CameraSubject, ctype = cam.CameraType} end
            cam.CameraSubject = seat
            cam.CameraType = Enum.CameraType.Follow
        elseif savedCam then
            cam.CameraSubject = savedCam.subject or hum()
            cam.CameraType = savedCam.ctype or Enum.CameraType.Custom
            savedCam = nil
        end
    end})

    -- ===== SCRIPTS UNIVERSAIS: Anti Som + Drone (versão local do GTA, sem link) =====
    local SU = ActiveWindow:MakeTab({Title = "Scripts Universais", Icon = "plane"})
    SU:AddSection({"Anti Som e Drone (GTA)"})

    local muted, soundConn, somStop = {}, nil, nil
    local function muteSound(s)
        if not s:IsA("Sound") then return end
        if LP.Character and s:IsDescendantOf(LP.Character) then return end
        if s.Volume > 0 then
            if muted[s] == nil then muted[s] = s.Volume end
            s.Volume = 0
        end
    end
    local function sweepSounds()
        for _, o in ipairs(WS:GetDescendants()) do muteSound(o) end
    end
    SU:AddToggle({Name = "Anti Som (silencia os sons do mapa e dos outros)", Default = false, Callback = function(v)
        if somStop then somStop() somStop = nil end
        if soundConn then soundConn:Disconnect() soundConn = nil end
        if v then
            soundConn = WS.DescendantAdded:Connect(function(o) task.defer(muteSound, o) end)
            somStop = runLoop(1, sweepSounds)
        else
            for s, vol in pairs(muted) do
                if s.Parent then pcall(function() s.Volume = vol end) end
            end
            muted = {}
        end
    end})

    local droneGui
    local function openDrone()
        if droneGui and droneGui.Parent then return end
        local CAS = game:GetService("ContextActionService")
        local cam = WS.CurrentCamera
        local STEP, ACTION = "GTA_Drone", "GTA_DroneSink"
        local active, smooth = false, false
        local speed, fov = 50, 70
        local yaw, pitch = 0, 0
        local camCF
        local vel = Vector3.zero
        local pad = {F = false, B = false, L = false, R = false, U = false, D = false}
        local saved, rotTouch, rmb, dragIn, dragStart, dragPos = nil, nil, false, nil, nil, nil
        local conns = {}

        local function mk(class, props, parent)
            local o = Instance.new(class)
            for k, val in pairs(props) do o[k] = val end
            o.Parent = parent
            return o
        end
        local gp = nil
        local okg, g = pcall(function() return gethui() end)
        if okg and typeof(g) == "Instance" then gp = g else gp = game:GetService("CoreGui") end
        local gui = mk("ScreenGui", {Name = "GTA_Drone", ResetOnSpawn = false, DisplayOrder = 900, IgnoreGuiInset = true}, nil)
        if not pcall(function() gui.Parent = gp end) or not gui.Parent then gui.Parent = LP:WaitForChild("PlayerGui") end
        droneGui = gui

        local BG, FG = Color3.fromRGB(14, 14, 18), Color3.fromRGB(255, 60, 60)
        local win = mk("Frame", {Size = UDim2.new(0, 240, 0, 214), Position = UDim2.new(0.5, -120, 0.12, 0), BackgroundColor3 = BG, BorderSizePixel = 0}, gui)
        mk("UICorner", {CornerRadius = UDim.new(0, 8)}, win)
        mk("UIStroke", {Color = FG, Thickness = 1.5}, win)
        local title = mk("TextLabel", {Size = UDim2.new(1, -64, 0, 28), Position = UDim2.new(0, 8, 0, 0), BackgroundTransparency = 1, Text = "Drone GTA", TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Left}, win)
        local function btn(text, x, y, w, h, parent)
            return mk("TextButton", {Text = text, Size = UDim2.new(0, w, 0, h), Position = UDim2.new(0, x, 0, y), BackgroundColor3 = Color3.fromRGB(34, 34, 42), TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextSize = 13, BorderSizePixel = 0, AutoButtonColor = true}, parent)
        end
        local bMin, bClose = btn("-", 178, 3, 26, 22, win), btn("X", 208, 3, 26, 22, win)
        local body = mk("Frame", {Size = UDim2.new(1, 0, 1, -30), Position = UDim2.new(0, 0, 0, 30), BackgroundTransparency = 1}, win)
        local bStart = btn("Começar", 10, 4, 220, 32, body)
        local function label(text, y) return mk("TextLabel", {Size = UDim2.new(0, 70, 0, 28), Position = UDim2.new(0, 10, 0, y), BackgroundTransparency = 1, Text = text, TextColor3 = Color3.fromRGB(200, 200, 210), Font = Enum.Font.Gotham, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left}, body) end
        label("Velocidade", 44)
        local bSm, tSpeed, bSp = btn("-", 86, 46, 28, 26, body), mk("TextBox", {Text = tostring(speed), Size = UDim2.new(0, 70, 0, 26), Position = UDim2.new(0, 118, 0, 46), BackgroundColor3 = Color3.fromRGB(24, 24, 30), TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.Gotham, TextSize = 13, BorderSizePixel = 0, ClearTextOnFocus = false}, body), btn("+", 192, 46, 28, 26, body)
        label("FOV", 78)
        local bFm, tFov, bFp = btn("-", 86, 80, 28, 26, body), mk("TextBox", {Text = tostring(fov), Size = UDim2.new(0, 70, 0, 26), Position = UDim2.new(0, 118, 0, 80), BackgroundColor3 = Color3.fromRGB(24, 24, 30), TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.Gotham, TextSize = 13, BorderSizePixel = 0, ClearTextOnFocus = false}, body), btn("+", 192, 80, 28, 26, body)
        local bSmooth = btn("Suave: desligado", 10, 114, 220, 28, body)
        mk("TextLabel", {Size = UDim2.new(1, -20, 0, 30), Position = UDim2.new(0, 10, 0, 144), BackgroundTransparency = 1, Text = "PC: WASD, Espaço sobe, Shift desce, botão direito gira. Celular: setas e arrastar a metade direita.", TextColor3 = Color3.fromRGB(150, 150, 160), Font = Enum.Font.Gotham, TextSize = 10, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left}, body)

        local padFrame = mk("Frame", {Size = UDim2.new(0, 230, 0, 112), Position = UDim2.new(0, 14, 1, -126), BackgroundTransparency = 1, Visible = false}, gui)
        local function hold(text, x, y, key)
            local b = mk("TextButton", {Text = text, Size = UDim2.new(0, 52, 0, 52), Position = UDim2.new(0, x, 0, y), BackgroundColor3 = BG, BackgroundTransparency = 0.25, TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextSize = 20, BorderSizePixel = 0, AutoButtonColor = false}, padFrame)
            mk("UICorner", {CornerRadius = UDim.new(0, 8)}, b)
            b.InputBegan:Connect(function(i) if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then pad[key] = true end end)
            b.InputEnded:Connect(function(i) if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then pad[key] = false end end)
        end
        hold("▲", 56, 0, "F") hold("◀", 0, 56, "L") hold("▼", 56, 56, "B") hold("▶", 112, 56, "R")
        hold("⬆", 176, 0, "U") hold("⬇", 176, 56, "D")

        local function setSpeed(n) speed = math.clamp(math.floor(tonumber(n) or speed), 1, 1000) tSpeed.Text = tostring(speed) end
        local function setFov(n) fov = math.clamp(math.floor(tonumber(n) or fov), 10, 120) tFov.Text = tostring(fov) end  -- Roblox limita FieldOfView a 120
        tSpeed.FocusLost:Connect(function() setSpeed(tSpeed.Text) end)
        tFov.FocusLost:Connect(function() setFov(tFov.Text) end)
        bSm.Activated:Connect(function() setSpeed(speed - 10) end)
        bSp.Activated:Connect(function() setSpeed(speed + 10) end)
        bFm.Activated:Connect(function() setFov(fov - 5) end)
        bFp.Activated:Connect(function() setFov(fov + 5) end)
        bSmooth.Activated:Connect(function()
            smooth = not smooth
            bSmooth.Text = smooth and "Suave: ligado" or "Suave: desligado"
        end)

        local function controls(on)
            pcall(function()
                local pm = LP:FindFirstChild("PlayerScripts") and LP.PlayerScripts:FindFirstChild("PlayerModule")
                if not pm then return end
                local c = require(pm):GetControls()
                if on then c:Enable() else c:Disable() end
            end)
        end
        local function update(dt)
            if not active then return end
            cam = WS.CurrentCamera
            local mv = Vector3.zero
            if not UIS:GetFocusedTextBox() then
                if UIS:IsKeyDown(Enum.KeyCode.W) then mv = mv + Vector3.new(0, 0, -1) end
                if UIS:IsKeyDown(Enum.KeyCode.S) then mv = mv + Vector3.new(0, 0, 1) end
                if UIS:IsKeyDown(Enum.KeyCode.A) then mv = mv + Vector3.new(-1, 0, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.D) then mv = mv + Vector3.new(1, 0, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.Space) then mv = mv + Vector3.new(0, 1, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then mv = mv + Vector3.new(0, -1, 0) end
            end
            if pad.F then mv = mv + Vector3.new(0, 0, -1) end
            if pad.B then mv = mv + Vector3.new(0, 0, 1) end
            if pad.L then mv = mv + Vector3.new(-1, 0, 0) end
            if pad.R then mv = mv + Vector3.new(1, 0, 0) end
            if pad.U then mv = mv + Vector3.new(0, 1, 0) end
            if pad.D then mv = mv + Vector3.new(0, -1, 0) end
            local rot = CFrame.fromOrientation(pitch, yaw, 0)
            local dir = rot:VectorToWorldSpace(Vector3.new(mv.X, 0, mv.Z)) + Vector3.new(0, mv.Y, 0)
            if dir.Magnitude > 0 then dir = dir.Unit end
            local goal = dir * speed
            if smooth then vel = vel:Lerp(goal, 1 - math.exp(-8 * dt)) else vel = goal end
            camCF = CFrame.new(camCF.Position + vel * dt) * rot
            cam.CFrame = camCF
            cam.FieldOfView = fov
        end
        local function stop()
            if not active then return end
            active = false
            pcall(function() RunS:UnbindFromRenderStep(STEP) end)
            pcall(function() CAS:UnbindAction(ACTION) end)
            controls(true)
            if saved then
                cam.CameraType = saved.ct
                cam.CameraSubject = saved.subj
                cam.FieldOfView = saved.fov
                saved = nil
            end
            vel, rotTouch, rmb = Vector3.zero, nil, false
            for k in pairs(pad) do pad[k] = false end
            padFrame.Visible = false
            bStart.Text = "Começar"
        end
        local function start()
            if active then return end
            cam = WS.CurrentCamera
            saved = {ct = cam.CameraType, subj = cam.CameraSubject, fov = cam.FieldOfView}
            camCF = cam.CFrame
            pitch, yaw = camCF:ToOrientation()
            vel = Vector3.zero
            active = true
            cam.CameraType = Enum.CameraType.Scriptable
            controls(false)
            CAS:BindActionAtPriority(ACTION, function() return Enum.ContextActionResult.Sink end, false, 3000,
                Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D, Enum.KeyCode.Space, Enum.KeyCode.LeftShift)
            RunS:BindToRenderStep(STEP, Enum.RenderPriority.Camera.Value + 1, update)
            padFrame.Visible = true
            bStart.Text = "Parar"
        end
        bStart.Activated:Connect(function() if active then stop() else start() end end)

        local minimized = false
        bMin.Activated:Connect(function()
            minimized = not minimized
            body.Visible = not minimized
            win.Size = minimized and UDim2.new(0, 240, 0, 30) or UDim2.new(0, 240, 0, 214)
        end)
        local function close()
            stop()
            for _, c in ipairs(conns) do c:Disconnect() end
            conns = {}
            gui:Destroy()
            droneGui = nil
        end
        bClose.Activated:Connect(close)

        title.Active = true
        title.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                dragIn, dragStart, dragPos = i, i.Position, win.Position
            end
        end)
        conns[#conns + 1] = UIS.InputBegan:Connect(function(i, processed)
            if i.UserInputType == Enum.UserInputType.MouseButton2 then rmb = true
            elseif i.UserInputType == Enum.UserInputType.Touch and active and not processed and not rotTouch and i.Position.X > cam.ViewportSize.X / 2 then
                rotTouch = i
            end
        end)
        conns[#conns + 1] = UIS.InputEnded:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton2 then rmb = false end
            if i == rotTouch then rotTouch = nil end
            if i == dragIn then dragIn = nil end
        end)
        conns[#conns + 1] = UIS.InputChanged:Connect(function(i)
            if dragIn and (i == dragIn or i.UserInputType == Enum.UserInputType.MouseMovement) then
                local d = i.Position - dragStart
                win.Position = UDim2.new(dragPos.X.Scale, dragPos.X.Offset + d.X, dragPos.Y.Scale, dragPos.Y.Offset + d.Y)
            end
            if not active then return end
            if i.UserInputType == Enum.UserInputType.MouseMovement and rmb then
                yaw = yaw - math.rad(i.Delta.X * 0.3)
                pitch = math.clamp(pitch - math.rad(i.Delta.Y * 0.3), -1.5, 1.5)
            elseif i == rotTouch then
                yaw = yaw - math.rad(i.Delta.X * 0.4)
                pitch = math.clamp(pitch - math.rad(i.Delta.Y * 0.4), -1.5, 1.5)
            end
        end)
        conns[#conns + 1] = LP.CharacterAdded:Connect(function() stop() end)
    end
    SU:AddButton({Name = "Drone GTA (câmera livre)", Callback = openDrone})
    SU:AddButton({Name = "Emote Hub GTA (abrir / fechar tudo)", Callback = function()
        local cur = getgenv and getgenv().GTAEmoteHub
        if cur and cur.Destroy then pcall(cur.Destroy) return end
        local okE, errE = pcall(openEmoteHub)
        if not okE then note("GTA Hub", "Emote Hub falhou: " .. tostring(errE):sub(1, 70)) end
    end})
end

-- ---------------------------------------------------------------- GTA EXTRA (fusão do script "King Hub" → GTA)
-- Só entrou o que o GTA Hub ainda não tinha: listas novas de áudio, músicas de carro, packs de avatar e 4 poderes visuais.
-- Webhook do Discord, loadstring de terceiros e telemetria do script original NÃO vieram. NÃO testado num executor.
local function tabKing()
    local TSv = game:GetService("TweenService")
    local Lit = game:GetService("Lighting")
    local Deb = game:GetService("Debris")
    local function canHit(p)
        if typeof(p) ~= "Instance" or p == LP then return false end
        local ok1, res = pcall(function() return GTA_PL.canHit(p) end)
        return ok1 and res == true
    end
    local function hostileChars()  -- personagens de quem o GTA proíbe mirar (dono/admin protegido) + o meu
        local set = {}
        for _, p in ipairs(Plrs:GetPlayers()) do
            if p == LP or not canHit(p) then
                if p.Character then set[p.Character] = true end
            end
        end
        return set
    end
    local function genLoop(getId, interval)  -- toggle de loop sem deixar loop velho vivo
        local gen = 0
        return function(v)
            gen = gen + 1
            if v then
                local mine = gen
                task.spawn(function()
                    while gen == mine do
                        pcall(getId)
                        task.wait(interval)
                    end
                end)
            end
        end
    end

    local T = ActiveWindow:MakeTab({Title = "GTA Extra", Icon = "star"})

    -- ===== helper de som (usado pelos poderes; as listas de áudio foram pra aba Audio All)
    local function shout(id)  -- toca pra todos (remote do som da arma) e localmente
        id = tonumber(id)
        if not id then return end
        pcall(function()
            local r = RE:FindFirstChild("1Gu1nSound1s")
            if r then r:FireServer(WS, id, 1) end
        end)
        pcall(function()
            local root = hrp()
            if not root then return end
            local s = Instance.new("Sound")
            s.SoundId = "rbxassetid://" .. id
            s.Volume = 1
            s.Parent = root
            s:Play()
            Deb:AddItem(s, 8)
        end)
    end
