            local Mouse = LP:GetMouse()
            local c, root = LP.Character, hrp()
            local gt = WS:FindFirstChild("WorkspaceCom") and WS.WorkspaceCom:FindFirstChild("001_GiveTools")
            local src = gt and gt:FindFirstChild("Basketball")
            local cd = src and src:FindFirstChildOfClass("ClickDetector")
            if not (c and root and src and cd) then note("GTA Extra", "Bola de basquete não encontrada no mapa") ballOn = false return end
            local old = root.CFrame
            for _ = 1, 1000 do
                if not ballOn then break end
                task.wait()
                root.CFrame = src.CFrame
                pcall(fireclickdetector, cd)
            end
            root.CFrame = old
            while ballOn do
                task.wait()
                local ch = LP.Character
                if not ch then break end
                for _, tool in ipairs(ch:GetChildren()) do
                    if tool:IsA("Tool") and tool.Name == "Basketball" then
                        local ev = tool:FindFirstChild("ClickEvent")
                        if ev then pcall(function() ev:FireServer(Mouse.Hit.p) end) end
                    end
