        task.spawn(function()
            for _, id in ipairs(pk[2]) do wear(id) task.wait(0.4) end
            local rem = Remotes or RS:FindFirstChild("Remotes")
            if pk[3] and rem then
                pcall(function()
                    rem.ChangeCharacterBody:InvokeServer({pk[3][1] or 0, pk[3][2] or 0, pk[3][3] or 0, pk[3][4] or 0, pk[3][5] or 0, pk[3][6] or 0})
                end)
