        task.delay(5, function()
            if gui.Parent then
                TSv:Create(img, TweenInfo.new(0.8), {ImageTransparency = 1}):Play()
                Deb:AddItem(gui, 1)
            end
        end)
    end})

    T:AddButton({Name = "Parar todos os poderes", Callback = function()
        for _, o in ipairs(fx) do pcall(function() o:Destroy() end) end
        fx = {}
        local root = hrp()
        if root then
            for _, o in ipairs(root:GetChildren()) do
                if o:IsA("PointLight") or o:IsA("ParticleEmitter") then pcall(function() o:Destroy() end) end
            end
        end
        if savedSky then savedSky.Parent = Lit savedSky = nil end
        domainOn = false
    end})
end

for i, f in ipairs({tabMusic, tabAvatar, tabLocal, tabItems, tabProps, tabProtect, tabExtras, tabParticles, tabDarkones, tabStark, tabIce, tabRGB, tabAdmin, tabTrace, tabAnimations, tabBrook, tabKing}) do
    local tabNames = {"Música", "Avatar", "Local", "Itens", "Props", "Proteção+", "Extras", "Partículas", "Darkones", "Stark", "Ice", "RGB", "Admin", "Trace", "Animações", "Brookhaven", "GTA Extra"}
    local ok, e = pcall(f)
    if not ok then
        warn("[GTA Hub+] aba " .. tabNames[i] .. ": " .. tostring(e))
        pcall(function() ActiveWindow:MakeNotify({Title = "GTA Hub+", Text = "aba " .. tabNames[i] .. " falhou: " .. tostring(e):sub(1, 90), Time = 8}) end)
    end
end
end)
if not okHX then warn("[GTA Hub+] " .. tostring(errHX)) pcall(function() ActiveWindow:MakeNotify({Title = "GTA Hub+", Text = "erro: " .. tostring(errHX):sub(1, 80), Time = 6}) end) end
end)


-- ================================================================
-- BOTÃO FLUTUANTE ABRIR / FECHAR (arrastável)
-- ================================================================
do
    local parentGui = (type(gethui) == "function" and select(2, pcall(gethui))) or CoreGui
    if typeof(parentGui) ~= "Instance" then parentGui = CoreGui end
    local old = parentGui:FindFirstChild("GTAHub_OpenButton"); if old then old:Destroy() end
    local sg = Instance.new("ScreenGui"); sg.Name = "GTAHub_OpenButton"; sg.ResetOnSpawn = false; sg.DisplayOrder = 1000; sg.IgnoreGuiInset = true
    pcall(function() sg.Parent = parentGui end)
    local b = Instance.new("TextButton"); b.Name = "Toggle"; b.Size = UDim2.new(0, 52, 0, 52); b.Position = UDim2.new(0, 14, 0.5, -26)
    b.BackgroundColor3 = Color3.fromRGB(8, 8, 10); b.BorderSizePixel = 0; b.Text = ""; b.TextColor3 = Color3.fromRGB(255, 60, 60)
    b.Font = Enum.Font.GothamBold; b.TextSize = 11; b.Parent = sg
    Instance.new("UICorner", b).CornerRadius = UDim.new(1, 0)
    local st = Instance.new("UIStroke", b); st.Color = Color3.fromRGB(255, 60, 60); st.Thickness = 2
    local sharBox = GTA_MakeSharingan(b); sharBox.Size = UDim2.new(1, -6, 1, -6)
    local function refresh()
        local g = Hub.MainGui
        local open = (g and g.Enabled) and true or false
        st.Color = open and Color3.fromRGB(255, 60, 60) or Color3.fromRGB(110, 110, 120)
        sharBox.Rotation = open and 0 or 45
    end
    local dragging, dragStart, startPos, moved
    b.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            dragging = true; moved = false; dragStart = i.Position; startPos = b.Position
        end
    end)
    UserInputService.InputChanged:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
            local d = i.Position - dragStart
            if d.Magnitude > 6 then moved = true end
            if moved then b.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y) end
        end
    end)
    UserInputService.InputEnded:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then
            dragging = false
            if not moved then
                local g = Hub.MainGui or resolveMainGui()
                if g then g.Enabled = not g.Enabled end
                refresh()
            end
        end
    end)
    task.defer(refresh)
end
